// ===== 自定义CSS注入（顺序：widget → bubble → page，页面美化在最后，层叠优先级最高） =====
let bubbleStyleEl = document.createElement('style');
bubbleStyleEl.id = 'custom-bubble-css';
document.head.appendChild(bubbleStyleEl);
let pageStyleEl = document.createElement('style');
pageStyleEl.id = 'custom-page-css';
