/* === 自定义美化提权：选择器加 #phoneScreen 前缀提升特异性、声明补 !important，
   确保用户自定义的页面/气泡美化能压过日间主题(.theme-light 前缀+!important)，编辑框仍保留原文 === */
function _boostDecls(decls) {
  var out = [], buf = '', depth = 0, q = null;
  for (var i = 0; i < decls.length; i++) {
    var c = decls[i];
    if (q) { buf += c; if (c === q && decls[i-1] !== '\\') q = null; continue; }
    if (c === '"' || c === "'") { q = c; buf += c; continue; }
    if (c === '(') depth++;
    if (c === ')') depth = Math.max(0, depth - 1);
    if (c === ';' && depth === 0) { out.push(buf); buf = ''; continue; }
    buf += c;
  }
  if (buf.trim()) out.push(buf);
  return out.map(function (d) {
    var t = d.trim();
    if (!t) return '';
    if (/!important/i.test(t)) return t;
    var ci = t.indexOf(':');
    if (ci < 0) return t;
    var prop = t.slice(0, ci).trim(), val = t.slice(ci + 1).trim();
    if (!prop || !val) return t;
    return prop + ': ' + val + ' !important';
  }).join('; ');
}
function _boostSelectors(selText, anc) {
  return selText.split(',').map(function (x) {
    var t = x.trim();
    if (!t) return '';
    if (/^(html|body|:root)\b/i.test(t)) return t;
    if (/^@/.test(t)) return t;
    return anc + ' ' + t;
  }).join(', ');
}
function boostCustomCss(css, anc) {
  anc = anc || '#phoneScreen';
  css = String(css == null ? '' : css);
  var out = '', i = 0, n = css.length;
  while (i < n) {
    if (css.substr(i, 2) === '/*') { var ec = css.indexOf('*/', i + 2); ec = ec < 0 ? n : ec + 2; out += css.slice(i, ec); i = ec; continue; }
    var ob = css.indexOf('{', i);
    if (ob < 0) { out += css.slice(i); break; }
    var head = css.slice(i, ob), headTrim = head.trim();
    var depth = 0, j = ob, qc = null;
    for (; j < n; j++) {
      var ch = css[j];
      if (qc) { if (ch === qc && css[j-1] !== '\\') qc = null; continue; }
      if (ch === '"' || ch === "'") { qc = ch; continue; }
      if (ch === '{') depth++;
      else if (ch === '}') { depth--; if (depth === 0) { j++; break; } }
    }
    var inner = css.slice(ob + 1, j - 1);
    if (/^@(?:-[a-z]+-)?keyframes/i.test(headTrim)) {
      out += head + '{' + inner + '}';
    } else if (/^@(media|supports|layer)/i.test(headTrim)) {
      out += head + '{' + boostCustomCss(inner, anc) + '}';
    } else {
      out += _boostSelectors(head, anc) + ' { ' + _boostDecls(inner) + ' }';
    }
    i = j;
  }
  return out;
}

function applyCustomCss() {
  var pageCss = config.settings.pageCss || '';
  var bubbleCss = config.settings.bubbleCss || '';
  /* 如果config中没有CSS（可能IndexedDB尚未加载），从localStorage备用键读取 */
  if (!pageCss) { try { pageCss = localStorage.getItem('mochi_custom_page_css') || ''; } catch(e) {} }
  if (!bubbleCss) { try { bubbleCss = localStorage.getItem('mochi_custom_bubble_css') || ''; } catch(e) {} }
  try { pageStyleEl.textContent = boostCustomCss(pageCss); } catch (e) { pageStyleEl.textContent = pageCss; }
  try { bubbleStyleEl.textContent = boostCustomCss(bubbleCss); } catch (e) { bubbleStyleEl.textContent = bubbleCss; }
  try { moveCustomCssToEnd(); } catch (e) {}
}
applyCustomCss();

// ===== 紧急CSS重置（键盘快捷键，CSS卡死时可用） =====
// 连按3次 R 键 或 Ctrl+Shift+R 重置自定义CSS
(function() {
  var rPressCount = 0;
  var rPressTimer = null;
  document.addEventListener('keydown', function(e) {
    // Ctrl+Shift+R 重置
    if (e.ctrlKey && e.shiftKey && (e.key === 'R' || e.key === 'r')) {
      e.preventDefault();
      emergencyResetCss();
      return;
    }
    // 连按3次R重置
    if (!e.ctrlKey && !e.shiftKey && !e.altKey && (e.key === 'R' || e.key === 'r')) {
      rPressCount++;
      clearTimeout(rPressTimer);
      rPressTimer = setTimeout(function() { rPressCount = 0; }, 1500);
      if (rPressCount >= 3) {
        rPressCount = 0;
        emergencyResetCss();
      }
    }
  });
})();

function emergencyResetCss() {
  // 清除自定义CSS
  config.settings.pageCss = '';
  config.settings.bubbleCss = '';
  try { localStorage.removeItem('mochi_custom_page_css'); } catch(e) {}
  try { localStorage.removeItem('mochi_custom_bubble_css'); } catch(e) {}
  Store.set('config', config);
  // 立即清空style元素
  if (pageStyleEl) pageStyleEl.textContent = '';
  if (bubbleStyleEl) bubbleStyleEl.textContent = '';
  // 移除可能被CSS创建的遮罩层
  document.querySelectorAll('*').forEach(function(el) {
    if (el.style && el.style.position === 'fixed' && el.style.zIndex > 9999) {
      if (el.id !== 'custom-page-css' && el.id !== 'custom-bubble-css' && el.id !== 'custom-widget-css') {
        el.remove();
      }
    }
  });
  // 强制恢复关键元素的可交互性
  var phoneScreen = document.querySelector('.phone-screen');
  if (phoneScreen) {
    phoneScreen.style.pointerEvents = 'auto';
    phoneScreen.style.overflow = '';
  }
  // 显示提示
  alert('已紧急重置自定义CSS！\n\n页面UI已恢复默认样式。\n连按3次R或按Ctrl+Shift+R可随时重置。');
}

