// ===== 桌面分页滑动 =====
var _homeCurrentPage = 0;
var _homeTouchStartX = 0;
var _homeTouchStartY = 0;
var _homeTouchActive = false;

function homeGoToPage(page) {
  _homeCurrentPage = page;
  var track = document.getElementById('homePagesTrack');
  if (track) track.style.transform = 'translateX(-' + (page * 50) + '%)';
  var dots = document.querySelectorAll('.page-dot');
  dots.forEach(function(d, i) {
    if (i === page) d.classList.add('active');
    else d.classList.remove('active');
  });
}
window.homeGoToPage = homeGoToPage;

(function() {
  var wrap = document.getElementById('homePagesWrap');
  if (!wrap) return;

  wrap.addEventListener('touchstart', function(e) {
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    if (e.touches.length !== 1) return;
    _homeTouchStartX = e.touches[0].clientX;
    _homeTouchStartY = e.touches[0].clientY;
    _homeTouchActive = true;
  }, { passive: true });

  wrap.addEventListener('touchmove', function(e) {
    if (!_homeTouchActive || e.touches.length !== 1) return;
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    var dx = e.touches[0].clientX - _homeTouchStartX;
    var dy = e.touches[0].clientY - _homeTouchStartY;
    // 只在水平滑动明显大于垂直滑动时阻止默认行为
    if (Math.abs(dx) > Math.abs(dy) && Math.abs(dx) > 10) {
      e.preventDefault();
    }
  }, { passive: false });

  wrap.addEventListener('touchend', function(e) {
    if (!_homeTouchActive) return;
    _homeTouchActive = false;
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    var dx = (e.changedTouches[0] || {}).clientX - _homeTouchStartX;
    var dy = (e.changedTouches[0] || {}).clientY - _homeTouchStartY;
    if (Math.abs(dx) < 40 || Math.abs(dx) < Math.abs(dy)) return;
    if (dx < 0 && _homeCurrentPage < 1) {
      homeGoToPage(_homeCurrentPage + 1);
    } else if (dx > 0 && _homeCurrentPage > 0) {
      homeGoToPage(_homeCurrentPage - 1);
    }
  }, { passive: true });

  // 鼠标拖拽支持（桌面端测试）
  var mouseDown = false;
  var mouseStartX = 0;
  wrap.addEventListener('mousedown', function(e) {
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    mouseDown = true;
    mouseStartX = e.clientX;
  });
  wrap.addEventListener('mouseup', function(e) {
    if (!mouseDown) return;
    mouseDown = false;
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    var dx = e.clientX - mouseStartX;
    if (Math.abs(dx) < 50) return;
    if (dx < 0 && _homeCurrentPage < 1) {
      homeGoToPage(_homeCurrentPage + 1);
    } else if (dx > 0 && _homeCurrentPage > 0) {
      homeGoToPage(_homeCurrentPage - 1);
    }
  });
  wrap.addEventListener('mouseleave', function() { mouseDown = false; });
})();

// ===== 桌面空白处长按进入编辑模式（类 iOS）=====
(function() {
  var wrap = document.getElementById('homePagesWrap');
  if (!wrap) return;
  var _bgPressTimer = null;
  var _bgPressX = 0;
  var _bgPressY = 0;

  wrap.addEventListener('touchstart', function(e) {
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
    if (e.touches.length !== 1) return;
    // 长按空白区域（非APP图标、非小组件）才进入编辑模式
    if (e.target.closest('.app-item') || e.target.closest('.home-widget') || e.target.closest('.page-dots') || e.target.closest('.dock') || e.target.closest('.hv2-cell')) return;
    _bgPressX = e.touches[0].clientX;
    _bgPressY = e.touches[0].clientY;
    clearTimeout(_bgPressTimer);
    _bgPressTimer = setTimeout(function() {
      if (typeof enterAppEditMode === 'function') enterAppEditMode();
    }, 550);
  }, { passive: true });

  wrap.addEventListener('touchmove', function(e) {
    if (!_bgPressTimer || e.touches.length !== 1) return;
    var dx = Math.abs(e.touches[0].clientX - _bgPressX);
    var dy = Math.abs(e.touches[0].clientY - _bgPressY);
    if (dx > 10 || dy > 10) {
      clearTimeout(_bgPressTimer);
      _bgPressTimer = null;
    }
  }, { passive: true });

  wrap.addEventListener('touchend', function() {
    clearTimeout(_bgPressTimer);
    _bgPressTimer = null;
  }, { passive: true });
})();

