var APPS_PER_PAGE = 28; // 4 列 × 7 行内容区（Dock 栏占 4×8 的第 8 行），每个 APP 占 1×1
var _appEditMode = false;
var _appDragData = null;
var _appLongPressTimer = null;
var _appLongPressStartX = 0;
var _appLongPressStartY = 0;
var _appSuppressClick = false;

/* ===== APP 图标自定义系统 ===== */
var _appIconOverrides = {};  // { appId: { icon: 'text', bg: '#fff', image: 'data:...' } }

function loadAppIconOverrides() {
  /* localStorage 优先，缺失/超配额时回退 IndexedDB */
  var v = loadUiState('app_icon_overrides');
  _appIconOverrides = (v && typeof v === 'object') ? v : {};
}

/* IndexedDB 加载完成后补充：localStorage 可能因配额不足丢失图标图片，IndexedDB 更完整 */
function loadAppIconOverridesFromIDB() {
  try {
    var idbData = null;
    try { idbData = Store.get('app_icon_overrides'); } catch(e) { idbData = null; }
    if (idbData && typeof idbData === 'object' && Object.keys(idbData).length) {
      _appIconOverrides = idbData;
      try { renderHomeScreen(); renderDock(); } catch(e) {}
      console.debug('loadAppIconOverridesFromIDB: restored', Object.keys(idbData).length, 'overrides');
    }
  } catch(e) { console.warn('loadAppIconOverridesFromIDB error:', e); }
}

function saveAppIconOverrides() {
  /* localStorage + IndexedDB 双写：含真实图标图片(base64)超过 localStorage 配额时由 IndexedDB 兜底，不再静默丢失 */
  saveUiState('app_icon_overrides', _appIconOverrides || {});
}

function getAppIconDef(id) {
  var def = getAppDef(id);
  if (!def) {
    /* Dock 专用应用（wechat/settings） */
    for (var i = 0; i < DOCKABLE_APPS.length; i++) {
      if (DOCKABLE_APPS[i].id === id) { def = DOCKABLE_APPS[i]; break; }
    }
  }
  if (!def) return null;
  var override = _appIconOverrides[id];
  if (override) {
    return {
      id: def.id,
      icon: override.icon !== undefined ? override.icon : def.icon,
      name: override.name || def.name,
      bg: override.bg || def.bg,
      image: override.image || null
    };
  }
  return { id: def.id, icon: def.icon, name: def.name, bg: def.bg, image: null };
}

function renderAppIconHtml(appId) {
  var def = getAppIconDef(appId);
  if (!def) return '';
  if (def.image) {
    return '<div class="app-icon" style="background:' + (def.bg || '#fff') + '"><img src="' + def.image + '" alt="' + (def.name || '') + '"/></div>';
  }
  var iconStr = def.icon || '';
  if (iconStr.indexOf('<svg') === 0) {
    return '<div class="app-icon" style="background:' + def.bg + '">' + iconStr + '</div>';
  }
  return '<div class="app-icon" style="background:' + def.bg + '"><span>' + iconStr + '</span></div>';
}

function renderDockIconHtml(appId) {
  var def = getAppIconDef(appId);
  if (!def) return '';
  var badgeHtml = (appId === 'wechat') ? '<span class="app-badge" id="dockWechatBadge" style="display:none">0</span>' : '';
  if (def.image) {
    return '<div class="dock-icon" style="background:' + (def.bg || '#fff') + '"><img src="' + def.image + '" alt="' + (def.name || '') + '"/>' + badgeHtml + '</div>';
  }
  var iconStr = def.icon || '';
  if (iconStr.indexOf('<svg') === 0) {
    return '<div class="dock-icon" style="background:' + def.bg + '">' + iconStr + badgeHtml + '</div>';
  }
  return '<div class="dock-icon" style="background:' + def.bg + '"><span>' + iconStr + '</span>' + badgeHtml + '</div>';
}

/* 设置页面入口：打开APP图标自定义列表 */
function openAppIconListModal() {
  var overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'appIconListModal';
  overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;z-index:99999';
  /* 收集所有可自定义的APP */
  var allApps = [];
  APP_DEFINITIONS.forEach(function(a) { allApps.push(a); });
  /* Dock 专用应用 */
  for (var i = 0; i < DOCKABLE_APPS.length; i++) {
    var da = DOCKABLE_APPS[i];
    if (da.id === 'wechat' || da.id === 'settings') {
      allApps.push(da);
    }
  }
  var appListHtml = allApps.map(function(a) {
    var def = getAppIconDef(a.id);
    if (!def) return '';
    var customized = _appIconOverrides[a.id];
    var tag = customized ? '<span style="font-size:10px;color:#F5A0B8;margin-left:4px">已自定义</span>' : '';
    var iconHtml = def.image
      ? '<img src="' + def.image + '" style="width:100%;height:100%;object-fit:cover" alt=""/>'
      : '<span>' + (def.icon || '') + '</span>';
    return '<div class="settings-item" onclick="document.getElementById(\'appIconListModal\').remove();openAppIconCustomizer(\'' + a.id + '\')">'
      + '<div class="settings-icon" style="width:36px;height:36px;border-radius:8px;background:' + (def.bg || '#fff') + ';overflow:hidden;display:grid;place-items:center;font-size:16px;font-weight:700;color:#888">' + iconHtml + '</div>'
      + '<div class="settings-label">' + (def.name || a.name) + tag + '</div>'
      + '<div class="settings-arrow"></div>'
      + '</div>';
  }).join('');

  overlay.innerHTML =
    '<div class="modal-content" style="max-width:340px;max-height:80vh;display:flex;flex-direction:column">'
    + '<div class="modal-header"><span>自定义APP图标</span><div class="modal-close" onclick="document.getElementById(\'appIconListModal\').remove()">×</div></div>'
    + '<div style="padding:12px 0;overflow-y:auto;flex:1">'
    + '<div style="font-size:12px;color:#8E8E93;padding:0 16px 8px">选择要自定义的APP，可修改图标文字、上传图片、改背景色和名称</div>'
    + '<div class="settings-group" style="margin:0">' + appListHtml + '</div>'
    + '</div></div>';
  document.body.appendChild(overlay);
}

function openAppIconCustomizer(appId) {
  var def = getAppIconDef(appId);
  if (!def) return;
  var override = _appIconOverrides[appId] || {};
  var overlay = document.createElement('div');
  overlay.className = 'modal-overlay';
  overlay.id = 'appIconCustomizer';
  overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;z-index:99999';
  overlay.innerHTML =
    '<div class="modal-content" style="max-width:320px;padding:20px">' +
    '<div class="modal-header"><span>自定义「' + def.name + '」图标</span><div class="modal-close" onclick="document.getElementById(\'appIconCustomizer\').remove()">×</div></div>' +
    '<div style="padding:16px 0">' +
    '<div style="display:flex;gap:12px;align-items:center;margin-bottom:16px">' +
    '<div style="width:52px;height:52px;border-radius:12px;display:grid;place-items:center;font-size:22px;font-weight:700;color:#888;background:' + (def.bg || '#fff') + ';border:1px solid rgba(0,0,0,.06);overflow:hidden;flex-shrink:0" id="iconPreview">' +
    (def.image ? '<img src="' + def.image + '" style="width:100%;height:100%;object-fit:cover" alt=""/>' : '<span>' + (def.icon || '') + '</span>') +
    '</div>' +
    '<div style="flex:1"><div style="font-size:13px;color:#8E8E93;margin-bottom:4px">实时预览</div>' +
    '<div style="font-size:12px;color:#aea">' + (override.name || def.name) + '</div></div>' +
    '</div>' +
    '<div class="form-group"><label class="form-label">APP名称</label>' +
    '<input class="form-input" id="iconNameInput" placeholder="如：微信、约稿" value="' + ((override.name || def.name || '').replace(/"/g, '&quot;')) + '" maxlength="6">' +
    '<div class="form-hint">留空则保持原名，最多6个字</div></div>' +
    '<div class="form-group"><label class="form-label">图标文字</label>' +
    '<input class="form-input" id="iconTextInput" placeholder="如：线、同、稿" value="' + (def.image ? '' : (override.icon || def.icon || '').replace(/"/g, '&quot;')) + '" maxlength="4">' +
    '<div class="form-hint">留空则保持原文字，1-4个字符</div></div>' +
    '<div class="form-group"><label class="form-label">上传图片</label>' +
    '<button class="btn-secondary" style="width:100%" onclick="document.getElementById(\'iconFileInput\').click()">📷 选择图片</button>' +
    '<input type="file" id="iconFileInput" accept="image/*" style="display:none">' +
    '<div class="form-hint">上传后图片将替代文字图标（上限3MB）</div></div>' +
    '<div class="form-group"><label class="form-label">背景色</label>' +
    '<input class="form-input" id="iconBgInput" placeholder="#ffffff" value="' + (override.bg || def.bg || '#ffffff') + '" maxlength="20">' +
    '<div class="form-hint">支持十六进制如 #FF6B9D 或渐变</div></div>' +
    '<div style="display:flex;gap:8px;margin-top:12px">' +
    '<button class="btn-secondary" style="flex:1" onclick="resetAppIcon(\'' + appId + '\')">恢复默认</button>' +
    '<button class="btn-primary" style="flex:1" onclick="applyAppIcon(\'' + appId + '\')">应用</button>' +
    '</div></div></div>';
  document.body.appendChild(overlay);

  /* 实时预览：文字变化时更新预览 */
  var textInput = overlay.querySelector('#iconTextInput');
  var bgInput = overlay.querySelector('#iconBgInput');
  var nameInput = overlay.querySelector('#iconNameInput');
  var preview = overlay.querySelector('#iconPreview');
  var previewName = overlay.querySelector('.modal-content div[style*="flex:1"] div:last-child');

  function updatePreview() {
    if (!preview.dataset.tempImage) {
      var newText = textInput.value.trim() || def.icon || '';
      preview.innerHTML = '<span>' + newText + '</span>';
    }
    var newBg = bgInput.value.trim() || def.bg || '#fff';
    preview.style.background = newBg;
    if (previewName && nameInput.value.trim()) {
      previewName.textContent = nameInput.value.trim();
    } else if (previewName) {
      previewName.textContent = def.name;
    }
  }
  textInput.addEventListener('input', updatePreview);
  bgInput.addEventListener('input', updatePreview);
  nameInput.addEventListener('input', updatePreview);

  /* 文件上传处理 */
  var fileInput = overlay.querySelector('#iconFileInput');
  fileInput.addEventListener('change', function(e) {
    var file = e.target.files && e.target.files[0];
    if (!file) return;
    if (file.size > 3 * 1024 * 1024) { showToast('图片不能超过3MB'); return; }
    var reader = new FileReader();
    reader.onload = function(ev) {
      /* 压缩为小尺寸缩略图，避免 localStorage 配额溢出 */
      var img = new Image();
      img.onload = function() {
        var canvas = document.createElement('canvas');
        var sz = 80; /* APP图标只需要小缩略图 */
        canvas.width = sz; canvas.height = sz;
        var ctx = canvas.getContext('2d');
        /* 裁剪为正方形 */
        var minSide = Math.min(img.width, img.height);
        var sx = (img.width - minSide) / 2;
        var sy = (img.height - minSide) / 2;
        ctx.drawImage(img, sx, sy, minSide, minSide, 0, 0, sz, sz);
        var compressed = canvas.toDataURL('image/jpeg', 0.75);
        preview.innerHTML = '<img src="' + compressed + '" style="width:100%;height:100%;object-fit:cover" alt=""/>';
        preview.dataset.tempImage = compressed;
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  });
}

function applyAppIcon(appId) {
  var overlay = document.getElementById('appIconCustomizer');
  if (!overlay) return;
  var textInput = overlay.querySelector('#iconTextInput');
  var bgInput = overlay.querySelector('#iconBgInput');
  var nameInput = overlay.querySelector('#iconNameInput');
  var preview = overlay.querySelector('#iconPreview');
  var tempImage = preview ? preview.dataset.tempImage : null;

  var override = _appIconOverrides[appId] || {};
  if (tempImage) {
    override.image = tempImage;
  } else {
    delete override.image;
    if (textInput && textInput.value.trim()) override.icon = textInput.value.trim();
    else delete override.icon;
  }
  if (nameInput && nameInput.value.trim()) override.name = nameInput.value.trim();
  else delete override.name;
  if (bgInput && bgInput.value.trim()) override.bg = bgInput.value.trim();

  _appIconOverrides[appId] = override;
  saveAppIconOverrides();
  overlay.remove();

  /* 重新渲染 */
  renderHomeScreen();
  renderDock();
  showToast('图标已更新');
}

function resetAppIcon(appId) {
  delete _appIconOverrides[appId];
  saveAppIconOverrides();
  var overlay = document.getElementById('appIconCustomizer');
  if (overlay) overlay.remove();
  renderHomeScreen();
  renderDock();
  showToast('已恢复默认图标');
}

function getAppLayout() {
  var validIds = APP_DEFINITIONS.map(function(a) { return a.id; });
  try {
    var saved = readUiStateRaw('app_layout');
    if (saved) {
      var layout = JSON.parse(saved);
      // 过滤无效ID（变为空位），保留有效ID
      var result = [];
      for (var i = 0; i < layout.length; i++) {
        if (layout[i] && validIds.indexOf(layout[i]) >= 0) {
          result.push(layout[i]);
        } else {
          result.push(null);
        }
      }
      // 补齐缺失的APP：追加到末尾空位，不插入中间空位（放哪里就是哪里，不自动前移）
      APP_DEFINITIONS.forEach(function(a) {
        if (result.indexOf(a.id) < 0) {
          var emptyIdx = -1;
          for (var k = result.length - 1; k >= 0; k--) { if (!result[k]) { emptyIdx = k; break; } }
          if (emptyIdx >= 0) {
            result[emptyIdx] = a.id;
          } else {
            result.push(a.id);
          }
        }
      });
      // 确保总位置数是 APPS_PER_PAGE 的整数倍（两页）
      while (result.length < APPS_PER_PAGE * 2) result.push(null);
      while (result.length > APPS_PER_PAGE * 2) {
        var last = result.pop();
        if (last) {
          var ei = result.indexOf(null);
          if (ei >= 0) result[ei] = last;
        }
      }
      return result;
    }
    // 兼容旧数据：把 mochi_app_order 迁移为 mochi_app_layout
    var oldOrder = localStorage.getItem('mochi_app_order');
    if (oldOrder) {
      var order = JSON.parse(oldOrder);
      var filtered = order.filter(function(id) { return validIds.indexOf(id) >= 0; });
      APP_DEFINITIONS.forEach(function(a) {
        if (filtered.indexOf(a.id) < 0) filtered.push(a.id);
      });
      var migrated = filtered.slice();
      while (migrated.length < APPS_PER_PAGE * 2) migrated.push(null);
      saveAppLayout(migrated);
      return migrated;
    }
  } catch(e) {}
  // 默认布局：按截图排版（4列×7行/页）
  // 第一页：时钟(4×2)+天气(4×1)组件占据前两行半，APP 绕开两个 2×2 照片组件位
  //   r3: 角 坛 [照片]   r4: 线 网 [照片]   r5: [照片] 图 购   r6: [照片] 界 忆
  // 第二页：食 稿 同 N
  var defaultLayout = [];
  for (var di = 0; di < APPS_PER_PAGE * 2; di++) defaultLayout.push(null);
  defaultLayout[12] = 'charmanager';  // 第一页 r3c1：角
  defaultLayout[13] = 'social';       // 第一页 r3c2：坛
  defaultLayout[16] = 'offline';      // 第一页 r4c1：线
  defaultLayout[17] = 'relation';     // 第一页 r4c2：网
  defaultLayout[22] = 'map';          // 第一页 r5c3：图
  defaultLayout[23] = 'shop';         // 第一页 r5c4：购
  defaultLayout[26] = 'world';        // 第一页 r6c3：界
  defaultLayout[27] = 'memory';       // 第一页 r6c4：忆
  defaultLayout[28] = 'food';         // 第二页 r0c1：食
  defaultLayout[29] = 'commission';   // 第二页 r0c2：稿
  defaultLayout[30] = 'doujin';       // 第二页 r0c3：同
  defaultLayout[31] = 'npc';          // 第二页 r0c4：N
  defaultLayout[32] = 'phonecheck';   // 查（默认在 Dock 栏，桌面留空；移出 Dock 后落在第二页）
  defaultLayout[33] = 'netease';      // 第二页 r1c2：网易云
  defaultLayout[34] = 'phone';        // 第二页 r1c3：电
  defaultLayout[35] = 'novelgame';    // 第二页 r1c4：文游
  // 兜底（根治换装等图标在默认布局丢失）：清掉无效占位，并把所有有效但没摆上的 APP 补进空位/末尾，
  // 这样无论默认布局还是以后新增 APP，都不会因为布局表漏写而从桌面消失
  for (var _di = 0; _di < defaultLayout.length; _di++) {
    if (defaultLayout[_di] && validIds.indexOf(defaultLayout[_di]) < 0) defaultLayout[_di] = null;
  }
  APP_DEFINITIONS.forEach(function (a) {
    if (defaultLayout.indexOf(a.id) < 0) {
      var _ei = -1;
      for (var _k = defaultLayout.length - 1; _k >= 0; _k--) { if (!defaultLayout[_k]) { _ei = _k; break; } }
      if (_ei >= 0) defaultLayout[_ei] = a.id; else defaultLayout.push(a.id);
    }
  });
  return defaultLayout;
}

function saveAppLayout(layout) {
  saveUiState('app_layout', layout);
}

// ===== 后台生成追踪 + 小红点通知系统（持久化版） =====
var bgGenState = {};  // { appId: { generating: bool, completed: bool, label: string, data: any, startTime: number } }
var _bgGenResumers = {};  // appId -> 回前台自动重跑函数（不持久化，仅当前运行时有效）
var _bgGenPersistKey = 'bg_gen_state_v2';

/* 从 localStorage 恢复状态（页面加载时调用） */
function bgGenRestore() {
  try {
    var saved = localStorage.getItem(_bgGenPersistKey);
    if (saved) {
      var parsed = JSON.parse(saved);
      if (parsed && typeof parsed === 'object') {
        bgGenState = parsed;
      }
    }
  } catch(e) {}
  var now = Date.now();
  var changed = false;
  /* 清理旧版查手机缓存键（旧格式 phonecheck_<app> 不含角色id，会与新版 phonecheck_<角色>_<app> 并存空转） */
  for (var _oldK in bgGenState) {
    if (_oldK.indexOf('phonecheck_') === 0 && _oldK.split('_').length === 2) { try { delete bgGenState[_oldK]; changed = true; } catch (e) {} }
  }
  for (var k in bgGenState) {
    if (bgGenState[k] && bgGenState[k].generating && bgGenState[k].startTime) {
      if (now - bgGenState[k].startTime > 10 * 60 * 1000) {
        bgGenState[k].generating = false;
        bgGenState[k].completed = false;
        changed = true;
      }
    }
  }
  if (changed) bgGenPersist();
}

/* 持久化状态到 localStorage */
function bgGenPersist() {
  try {
    localStorage.setItem(_bgGenPersistKey, JSON.stringify(bgGenState));
  } catch(e) {}
}

function bgGenStart(appId, label, onResume) {
  bgGenState[appId] = { generating: true, completed: false, label: label || '', data: null, startTime: Date.now(), heartbeat: Date.now() };
  if (typeof onResume === 'function') { try { _bgGenResumers[appId] = onResume; } catch (e) {} }
  bgGenPersist();
  bgGenUpdateIcons();
}

/* 心跳：只要页面 JS 还在运行（哪怕生成较慢），就持续刷新 heartbeat；
   手机浏览器切后台/锁屏冻结 JS 后心跳停更，回前台据此判断任务是否被掐断。只更新内存，不频繁写存储。 */
setInterval(function () {
  var now = Date.now();
  for (var k in bgGenState) { if (bgGenState[k] && bgGenState[k].generating) bgGenState[k].heartbeat = now; }
}, 5000);

/* 回前台恢复：心跳过期(JS曾被冻结)的生成任务，有重跑器就自动重新生成，否则复位为失败让用户点重试 */
function ruaResumeBgGenerations() {
  var now = Date.now();
  for (var appId in bgGenState) {
    var st = bgGenState[appId];
    if (!st || !st.generating) continue;
    var hb = st.heartbeat || st.startTime || 0;
    if (now - hb < 15000) continue; // 心跳新鲜=仍在正常生成（与生成快慢无关），不动它
    var resumer = _bgGenResumers[appId];
    if (typeof resumer === 'function') {
      console.warn('[后台保活] 检测到「' + (st.label || appId) + '」在后台被中断，自动重新生成');
      bgGenFail(appId); // 先复位旧的“生成中”状态，resumer 内部会重新 bgGenStart
      try { resumer(); } catch (e) { console.warn('[后台保活] 自动重跑失败', e); bgGenFail(appId); }
    } else {
      bgGenFail(appId);
    }
  }
}
if (typeof window !== 'undefined') window.ruaResumeBgGenerations = ruaResumeBgGenerations;

function bgGenComplete(appId, data) {
  if (!bgGenState[appId]) bgGenState[appId] = {};
  bgGenState[appId].generating = false;
  bgGenState[appId].completed = true;
  bgGenState[appId].data = data || null;
  bgGenState[appId].startTime = 0;
  var label = bgGenState[appId].label || '内容';
  if (typeof _showToast === 'function') {
    _showToast(label + '生成完毕！点击查看');
  }
  /* 发送通知 */
  if (typeof showNotification === 'function') {
    /* 统一品牌解析：内置APP取emoji，MCP自定义APP取用户上传的真实图片图标 */
    var _brand = (typeof resolveAppBrand === 'function') ? resolveAppBrand(appId) : { icon: '✨', bg: '#576B95', iconUrl: '' };
    showNotification({
      appId: appId,
      icon: _brand.icon,
      iconUrl: _brand.iconUrl || '',
      iconBg: _brand.bg,
      title: label + '已生成',
      body: '点击查看',
      tag: 'rua-appgen-' + appId,
      onTap: (function(_id){ return function() { if (typeof openApp === 'function') openApp(_id); }; })(appId)
    });
  }
  bgGenPersist();
  bgGenUpdateIcons();
}

function bgGenFail(appId) {
  if (!bgGenState[appId]) bgGenState[appId] = {};
  bgGenState[appId].generating = false;
  bgGenState[appId].completed = false;
  bgGenState[appId].startTime = 0;
  bgGenPersist();
  bgGenUpdateIcons();
}

function bgGenClear(appId) {
  if (bgGenState[appId]) {
    bgGenState[appId].completed = false;
    bgGenState[appId].data = null;
  }
  bgGenPersist();
  bgGenUpdateIcons();
}

function bgGenIsGenerating(appId) {
  return !!(bgGenState[appId] && bgGenState[appId].generating);
}

function bgGenHasNotification(appId) {
  return !!(bgGenState[appId] && bgGenState[appId].completed);
}

/* 页面加载时恢复持久化状态 */
bgGenRestore();
/* 恢复后更新图标显示 */
if (typeof bgGenUpdateIcons === 'function') {
  setTimeout(function() { bgGenUpdateIcons(); }, 100);
}

function bgGenUpdateIcons() {
  /* 桂面 APP 图标：红点挂在 .app-item 上，避免被 .app-icon 的 overflow:hidden 裁剪 */
  document.querySelectorAll('.app-item[data-app-id]').forEach(function(item) {
    var aid = item.dataset.appId;
    var oldDot = item.querySelector('.app-icon-red-dot, .app-icon-gen-indicator');
    if (oldDot) oldDot.remove();
    if (bgGenState[aid] && bgGenState[aid].generating) {
      var genDot = document.createElement('div');
      genDot.className = 'app-icon-gen-indicator';
      item.appendChild(genDot);
    } else if (bgGenState[aid] && bgGenState[aid].completed) {
      var redDot = document.createElement('div');
      redDot.className = 'app-icon-red-dot';
      item.appendChild(redDot);
    }
  });
  /* Dock 栏图标：红点挂在 .dock-item 上 */
  document.querySelectorAll('.dock-item[data-app-id]').forEach(function(item) {
    var aid = item.dataset.appId;
    var oldDot = item.querySelector('.app-icon-red-dot, .app-icon-gen-indicator');
    if (oldDot) oldDot.remove();
    if (bgGenState[aid] && bgGenState[aid].generating) {
      var genDot = document.createElement('div');
      genDot.className = 'app-icon-gen-indicator';
      item.appendChild(genDot);
    } else if (bgGenState[aid] && bgGenState[aid].completed) {
      var redDot = document.createElement('div');
      redDot.className = 'app-icon-red-dot';
      item.appendChild(redDot);
    }
  });
}

function getAppDef(id) {
  for (var i = 0; i < APP_DEFINITIONS.length; i++) {
    if (APP_DEFINITIONS[i].id === id) return APP_DEFINITIONS[i];
  }
  return null;
}

// ===== 主屏幕统一网格（每页 4 列 × 7 行内容区，Dock 栏占 4×8 的第 8 行）=====
// 原则：应用固定在用户摆放的绝对槽位，绝不自动前移补缺（放哪里就是哪里）；
// 小组件按顺序填入剩余空格，可以填进应用之间的空位（比如 2×2 空位放 2×2 组件）
var HOME_GRID_ROWS = 7;
var HOME_GRID_COLS = 4;

// 在给定应用布局下，按顺序为一页小组件计算网格位置（行优先扫描第一个放得下的 w×h 空位）
// 返回 { placements: {id:{col,row,w,h}}, overflow: [放不下的组件id], grid: 7×4 占用表 }
function placeWidgets(page, orderedIds, layoutOpt) {
  var layout = layoutOpt || getAppLayout();
  var start = page === 'p2' ? APPS_PER_PAGE : 0;
  var grid = [];
  var r, c, dr, dc;
  for (r = 0; r < HOME_GRID_ROWS; r++) grid.push([false, false, false, false]);
  for (var i = start; i < start + APPS_PER_PAGE; i++) {
    if (layout[i]) grid[Math.floor((i - start) / HOME_GRID_COLS)][(i - start) % HOME_GRID_COLS] = true;
  }
  var savedPositions = getWidgetPositions(page);
  var placements = {};
  var overflow = [];
  (orderedIds || []).forEach(function(id) {
    var def = getWidgetDef(id);
    if (!def) return;
    var s = widgetSpanOf(def);
    var pos = null;
    /* 优先使用保存的显式位置（拖拽后保存的） */
    var saved = savedPositions[id];
    if (saved) {
      var okSaved = true;
      for (dr = 0; dr < s.h && okSaved; dr++) {
        for (dc = 0; dc < s.w && okSaved; dc++) {
          var rr = saved.row + dr, cc = saved.col + dc;
          if (rr < 0 || rr >= HOME_GRID_ROWS || cc < 0 || cc >= HOME_GRID_COLS || grid[rr][cc]) okSaved = false;
        }
      }
      if (okSaved) pos = { col: saved.col, row: saved.row };
    }
    /* 没有显式位置或位置冲突：自动从底部向上扫描 */
    if (!pos) {
      for (r = HOME_GRID_ROWS - s.h; r >= 0 && !pos; r--) {
        for (c = 0; c + s.w <= HOME_GRID_COLS && !pos; c++) {
          var ok = true;
          for (dr = 0; dr < s.h && ok; dr++) {
            for (dc = 0; dc < s.w && ok; dc++) {
              if (grid[r + dr][c + dc]) ok = false;
            }
          }
          if (ok) pos = { col: c, row: r };
        }
      }
    }
    if (pos) {
      for (dr = 0; dr < s.h; dr++) for (dc = 0; dc < s.w; dc++) grid[pos.row + dr][pos.col + dc] = true;
      placements[id] = { col: pos.col, row: pos.row, w: s.w, h: s.h };
    } else {
      overflow.push(id);
    }
  });
  return { placements: placements, overflow: overflow, grid: grid };
}

// 校验：在给定应用布局下，一页的组件序列是否全部放得下（不会溢出压到 Dock 栏）
function homePlacementFits(page, widgetIds, layoutOpt) {
  return placeWidgets(page, widgetIds, layoutOpt).overflow.length === 0;
}

/* ============================================================================
 * HV2 · 主屏幕固定版式（2026 重构）
 * ----------------------------------------------------------------------------
 * 版式：每页 4 列 × 6 行固定网格，页面结构（含照片位置）全部写在 index.html 里，
 *       JS 只负责「往固定槽位里灌数据」：应用图标、照片、头像昵称、便签。
 * 开关：HV2_FIXED = true → 旧的小组件 / 拖拽排序 / Dock 设置全部停用；
 *       旧代码一行未删，改回 false 即可整体回退到旧版式。
 * 图片：沿用 config.widgetImages（键名 hv2-*），复用既有压缩选图能力。
 * ========================================================================== */
var HV2_FIXED = true;
var HV2_DOCK_APPS = ['wechat', 'phonecheck', 'settings', 'phone'];
var _hv2ImgKey = '';     // 当前操作的照片区
var _hv2Swiped = false;  // 翻页手势中，避免误触发点击

function hv2GetImage(key) {
  try { return (config.widgetImages && config.widgetImages[key]) || ''; } catch(e) { return ''; }
}

function hv2SetImage(key, src) {
  if (!config.widgetImages) config.widgetImages = {};
  if (src) config.widgetImages[key] = src;
  else delete config.widgetImages[key];
  try { Store.set('config', config); } catch(e) {}
  hv2Render();
}

function hv2PhotoHtml(key, label, small) {
  var src = hv2GetImage(key);
  if (src) return '<img class="hv2-photo-img" src="' + src + '" alt="">';
  return '<div class="hv2-photo-empty"><span>📷</span>' +
    (small ? '' : '<i>点击添加' + (label || '图片') + '</i>') + '</div>';
}

function hv2RenderPhotos(root) {
  root.querySelectorAll('.hv2-photobox[data-img-key]').forEach(function(el) {
    el.innerHTML = hv2PhotoHtml(el.dataset.imgKey, el.getAttribute('data-img-label'), el.hasAttribute('data-img-small'));
  });
}

/* 按 HTML 上写好的 data-slot="app1,app2,…" 往固定槽位灌应用图标 */
function hv2RenderApps(root) {
  root.querySelectorAll('.hv2-apps[data-slot]').forEach(function(box) {
    var html = '';
    (box.getAttribute('data-slot') || '').split(',').forEach(function(id) {
      id = (id || '').trim();
      if (!id) return;
      var def = (typeof getAppIconDef === 'function') ? getAppIconDef(id) : null;
      if (!def) return;
      html += '<div class="app-item" data-app-id="' + id + '">' + renderAppIconHtml(id) +
        '<span class="app-name">' + def.name + '</span></div>';
    });
    box.innerHTML = html;
  });
}

/* 头像 / 昵称 / 签名：名片卡（第一页）+ 头像信息组（第二页） */
function hv2FillAvatar(id, src, name) {
  var el = document.getElementById(id);
  if (!el) return;
  if (src) { el.style.backgroundImage = 'url(' + src + ')'; el.textContent = ''; }
  else { el.style.backgroundImage = ''; el.textContent = (name || '我').charAt(0); }
}

function hv2SetText(id, txt) {
  var el = document.getElementById(id);
  if (el) el.textContent = txt;
}

function hv2RenderProfile() {
  var u = (typeof config !== 'undefined' && config.user) ? config.user : {};
  var name = '';
  try { name = (typeof userCallName === 'function') ? userCallName(u) : ''; } catch(e) {}
  if (!name) name = u.name || '我';
  var bio = ((u.bio || '') + '').trim() || '这个人很懒，什么都没写';
  /* 名片卡圆形头像：优先「点一下换图片」自选的图（config.widgetImages），否则跟随设置里的头像，再否则用名字首字 */
  hv2FillAvatar('hv2CardPortrait', hv2GetImage('hv2-card-avatar') || u.avatar || '', name);
  hv2FillAvatar('hv2ProfileAvatar', u.avatar || '', name);
  hv2SetText('hv2CardName', name);
  hv2SetText('hv2CardSub', u.wxId ? ('ID: ' + u.wxId) : '点头像换图 · 点此处改昵称');
  hv2SetText('hv2ProfileName', name);
  hv2SetText('hv2ProfileBio', bio);
  try { hv2BindCardPortrait(); } catch(e) {}
}

/* 名片卡头像：点一下＝换图片（复用普通照片区的换图菜单），并拦住玻璃条上的「进设置」 */
function hv2BindCardPortrait() {
  var pa = document.getElementById('hv2CardPortrait');
  if (!pa || pa.dataset.hv2AvatarBound === '1') return;
  pa.dataset.hv2AvatarBound = '1';
  pa.addEventListener('click', function(e) {
    e.preventDefault();
    e.stopPropagation(); /* 关键：否则会冒泡到 .hv2-card-glass 的内联 onclick="openApp('settings')" */
    hv2OpenImageMenu('hv2-card-avatar');
  });
}

/* 桌面便签 */
function hv2RenderNote() {
  var t = '';
  try { t = (config.settings && config.settings.hv2Note) || ''; } catch(e) {}
  hv2SetText('hv2NoteText', t || '今天也要好好生活呀 ✿');
}

function openHv2NoteModal() {
  var input = document.getElementById('hv2NoteInput');
  if (input) { try { input.value = (config.settings && config.settings.hv2Note) || ''; } catch(e) {} }
  if (typeof openModal === 'function') openModal('hv2NoteModal');
}
window.openHv2NoteModal = openHv2NoteModal;

function saveHv2Note() {
  var input = document.getElementById('hv2NoteInput');
  if (!config.settings) config.settings = {};
  config.settings.hv2Note = ((input && input.value) || '').trim().slice(0, 30);
  try { Store.set('config', config); } catch(e) {}
  hv2RenderNote();
  if (typeof closeModal === 'function') closeModal('hv2NoteModal');
  if (typeof showToast === 'function') showToast('便签已保存 ✿');
}
window.saveHv2Note = saveHv2Note;

/* 总渲染：只往固定槽位灌数据，不动结构 */
function hv2Render() {
  var root = document.getElementById('view-home');
  if (!root) return;
  try { hv2RenderApps(root); } catch(e) { console.warn('hv2 应用渲染失败:', e); }
  try { hv2RenderPhotos(root); } catch(e) { console.warn('hv2 照片渲染失败:', e); }
  try { hv2RenderProfile(); } catch(e) { console.warn('hv2 资料渲染失败:', e); }
  try { hv2RenderNote(); } catch(e) {}
  try { if (typeof window.__mcpInjectHomeIcons === 'function') window.__mcpInjectHomeIcons(); } catch(e) {}
  try { if (typeof bgGenUpdateIcons === 'function') bgGenUpdateIcons(); } catch(e) {}
  try { if (typeof updateBadges === 'function') updateBadges(); } catch(e) {}
}
window.hv2Render = hv2Render;

/* 照片区：空白 → 直接选图；已有图 → 换图 / 预览 / 移除 */
function hv2PickImage(key) {
  if (typeof pickWidgetImage !== 'function') return;
  pickWidgetImage(function(src) {
    hv2SetImage(key, src);
    if (typeof showToast === 'function') showToast(key === 'hv2-card-avatar' ? '头像已更新 ✿' : '照片已更新 ✿');
  });
}

function hv2OpenImageMenu(key) {
  if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
  _hv2ImgKey = key;
  if (!hv2GetImage(key)) { hv2PickImage(key); return; }
  var title = document.querySelector('#hv2ImageModal .modal-title');
  if (title) title.textContent = (key === 'hv2-card-avatar') ? '这个头像' : '这张照片';
  if (typeof openModal === 'function') openModal('hv2ImageModal');
}
window.hv2OpenImageMenu = hv2OpenImageMenu;

function hv2ImageAction(action) {
  var key = _hv2ImgKey;
  if (typeof closeModal === 'function') closeModal('hv2ImageModal');
  if (!key) return;
  if (action === 'change') { hv2PickImage(key); return; }
  if (action === 'remove') {
    hv2SetImage(key, '');
    if (typeof showToast === 'function') showToast('已移除这张照片');
    return;
  }
  if (action === 'preview') {
    var img = document.getElementById('hv2PreviewImg');
    if (img) img.src = hv2GetImage(key) || '';
    if (typeof openModal === 'function') openModal('hv2PreviewModal');
  }
}
window.hv2ImageAction = hv2ImageAction;

/* 事件绑定：点开应用 / 点照片换图 / 翻页滑动不误触 */
function initHomeV2Events() {
  if (!HV2_FIXED) return;
  var wrap = document.getElementById('homePagesWrap');
  if (!wrap || wrap.dataset.hv2Bound === '1') return;
  wrap.dataset.hv2Bound = '1';

  var sx = 0, sy = 0;
  wrap.addEventListener('touchstart', function(e) {
    if (e.touches.length !== 1) return;
    _hv2Swiped = false;
    sx = e.touches[0].clientX; sy = e.touches[0].clientY;
  }, { passive: true });
  wrap.addEventListener('touchmove', function(e) {
    if (e.touches.length !== 1) return;
    var t = e.touches[0];
    if (Math.abs(t.clientX - sx) > 10 || Math.abs(t.clientY - sy) > 10) _hv2Swiped = true;
  }, { passive: true });

  wrap.addEventListener('click', function(e) {
    if (_hv2Swiped) { _hv2Swiped = false; return; }
    if (typeof _appSuppressClick !== 'undefined' && _appSuppressClick) { _appSuppressClick = false; return; }
    if (typeof _appEditMode !== 'undefined' && _appEditMode) return;

    var box = e.target.closest('.hv2-photobox[data-img-key]');
    if (box) { e.preventDefault(); e.stopPropagation(); hv2OpenImageMenu(box.dataset.imgKey); return; }

    var app = e.target.closest('.app-item[data-app-id]');
    if (app) {
      e.preventDefault(); e.stopPropagation();
      if (typeof openApp === 'function') openApp(app.dataset.appId);
    }
  });

  hv2Render();
}
window.initHomeV2Events = initHomeV2Events;

// 渲染主屏幕：统一网格内混排小组件与应用（全部显式网格坐标，互不重排）
function renderHomeScreen() {
  /* HV2 固定版式：页面结构写死在 index.html，这里只负责往固定槽位灌数据 */
  if (HV2_FIXED) { hv2Render(); return; }
  var pages = ['p1', 'p2'];
  var widgetData = getHomeWidgetsData();
  var layout = getAppLayout();
  /* 获取 Dock 栏应用列表，主屏幕不重复显示 Dock 中的应用 */
  var dockAppIds = (typeof getDockApps === 'function') ? getDockApps() : [];
  pages.forEach(function(page) {
    var area = document.querySelector('.home-widget-area[data-page="' + page + '"]');
    if (!area) return;
    area.innerHTML = '';
    var start = page === 'p2' ? APPS_PER_PAGE : 0;
    /* 过滤布局：跳过 Dock 栏已有的应用（避免重复显示） */
    var filteredLayout = [];
    for (var li = 0; li < layout.length; li++) {
      var lid = layout[li];
      if (lid === 'npc') { filteredLayout.push(null); continue; } /* 独立NPC已下线，桌面不显示 */
      if (lid && dockAppIds.indexOf(lid) !== -1) {
        filteredLayout.push(null); /* Dock 应用在主屏幕留空 */
      } else {
        filteredLayout.push(lid);
      }
    }
    var placed = placeWidgets(page, widgetData[page] || [], filteredLayout);
    // 小组件（按放置结果显式定位）
    (widgetData[page] || []).forEach(function(id) {
      var def = getWidgetDef(id);
      var p = placed.placements[id];
      if (!def || !p) return; // 放不下的组件不渲染（正常不可达：添加/拖放前均已校验）
      var el = document.createElement('div');
      el.className = 'home-widget' + (def.cls ? ' ' + def.cls : '') + (def.span ? ' ' + def.span : '');
      el.dataset.widgetId = id;
      el.style.gridColumn = (p.col + 1) + ' / span ' + p.w;
      el.style.gridRow = (p.row + 1) + ' / span ' + p.h;
      if (def.tap) el.setAttribute('onclick', def.tap);
      var extraBtns = '<div class="widget-remove-btn" data-widget-id="' + id + '">−</div>';
      /* 所有可能显示图片的小组件：编辑模式下显示换图按钮 */
      var canChangeImg = (def.cls && def.cls.indexOf('photo-cell-widget') >= 0) || (def.custom && !def.textOnly) || (def.cls && def.cls.indexOf('photo-widget') >= 0) || (def.cls && def.cls.indexOf('polaroid-widget') >= 0) || (def.cls && def.cls.indexOf('filmstrip-widget') >= 0) || (def.cls && def.cls.indexOf('photo-round-widget') >= 0) || (def.cls && def.cls.indexOf('photo-graypink-widget') >= 0);
      if (canChangeImg) {
        extraBtns += '<div class="widget-changeimg-btn" data-widget-id="' + id + '">🖼️</div>';
      }
      el.innerHTML = def.render() + extraBtns;
      // 自定义小组件：背景 + 作用域 CSS（毛玻璃可选项）
      if (def.custom) {
        if (def.frosted) {
          el.classList.add('cw-glass');
          el.style.background = (def.bg && def.bg !== 'transparent') ? def.bg : 'rgba(255,255,255,0.35)';
        } else {
          el.style.background = def.bg || 'transparent';
        }
        injectCustomWidgetCss(el, def);
      }
      area.appendChild(el);
      if (def.after) { try { def.after(el); } catch(e) {} }
    });
    // 应用（固定在用户摆放的绝对槽位）
    for (var i = start; i < start + APPS_PER_PAGE; i++) {
      var appId = filteredLayout[i];
      if (!appId) continue;
      var appDef = getAppDef(appId);
      if (!appDef) continue;
      var rel = i - start;
      var item = document.createElement('div');
      item.className = 'app-item';
      item.dataset.appId = appDef.id;
      item.dataset.appIndex = i;
      item.style.gridColumn = String((rel % HOME_GRID_COLS) + 1);
      item.style.gridRow = String(Math.floor(rel / HOME_GRID_COLS) + 1);
      var iconDef = getAppIconDef(appDef.id);
      item.innerHTML = renderAppIconHtml(appDef.id) +
        '<span class="app-name">' + (iconDef ? iconDef.name : appDef.name) + '</span>';
      area.appendChild(item);
    }
    // 编辑模式：所有空格渲染为虚线占位（拖放目标）
    if (typeof _appEditMode !== 'undefined' && _appEditMode) {
      for (var r2 = 0; r2 < HOME_GRID_ROWS; r2++) {
        for (var c2 = 0; c2 < HOME_GRID_COLS; c2++) {
          if (placed.grid[r2][c2]) continue;
          area.appendChild(createHomeEmptySlot(page, r2, c2));
        }
      }
      area.classList.add('editing');
    } else {
      area.classList.remove('editing');
    }
    // 悬浮操作条（Dock 上方，不占用网格行）
    var pageEl = area.closest('.home-page') || area.parentNode;
    var oldBar = pageEl.querySelector('.widget-add-bar');
    if (oldBar) oldBar.parentNode.removeChild(oldBar);
    var bar = document.createElement('div');
    bar.className = 'widget-add-bar';
    var addTile = document.createElement('div');
    addTile.className = 'widget-add-tile';
    addTile.textContent = '＋ 添加小组件';
    addTile.addEventListener('click', (function(pg) {
      return function(e) {
        e.stopPropagation(); e.preventDefault();
        openWidgetGallery(pg);
      };
    })(page));
    var wallTile = document.createElement('div');
    wallTile.className = 'widget-add-tile wallpaper-tile';
    wallTile.textContent = '🖼 更换壁纸';
    wallTile.addEventListener('click', function(e) {
      e.stopPropagation(); e.preventDefault();
      openHomeWallpaperModal();
    });
    var dockTile = document.createElement('div');
    dockTile.className = 'widget-add-tile dock-tile';
    dockTile.textContent = '🚀 Dock 栏';
    dockTile.addEventListener('click', function(e) {
      e.stopPropagation(); e.preventDefault();
      openDockSettings();
    });
    bar.appendChild(addTile);
    bar.appendChild(wallTile);
    bar.appendChild(dockTile);
    pageEl.appendChild(bar);
  });
}
window.renderHomeScreen = renderHomeScreen;

// 兼容旧调用：应用网格与组件区已合并为统一网格，统一由 renderHomeScreen 渲染
function renderAppGrids() { renderHomeScreen(); }
window.renderAppGrids = renderAppGrids;

/* 渲染后刷新小红点 */
var _origRenderHomeScreen = renderHomeScreen;
renderHomeScreen = function () {
  _origRenderHomeScreen.apply(this, arguments);
  setTimeout(bgGenUpdateIcons, 50);
};
window.renderHomeScreen = renderHomeScreen;

function createHomeEmptySlot(page, row, col) {
  var slot = document.createElement('div');
  slot.className = 'app-item app-empty-slot';
  slot.dataset.appIndex = (page === 'p2' ? APPS_PER_PAGE : 0) + row * HOME_GRID_COLS + col;
  slot.style.gridColumn = String(col + 1);
  slot.style.gridRow = String(row + 1);
  slot.innerHTML =
    '<div class="app-icon" style="background:rgba(255,255,255,0.08);border:1.5px dashed rgba(200,160,180,0.45)"></div>' +
    '<span class="app-name">&nbsp;</span>';
  return slot;
}

// 旧数据一次性迁移：统一网格下放不下的组件，自动挪到另一页（之后所有操作都有校验，不会再溢出）
function migrateHomeToUnifiedGrid() {
  try {
    if (localStorage.getItem('mochi_home_grid_v2')) return;
    ['p1', 'p2'].forEach(function(pg) {
      var order = getHomeWidgets(pg);
      if (!order.length) return;
      var t = placeWidgets(pg, order);
      if (!t.overflow.length) return;
      var other = pg === 'p1' ? 'p2' : 'p1';
      t.overflow.forEach(function(id) {
        var otherOrder = getHomeWidgets(other);
        if (!homePlacementFits(other, otherOrder.concat([id]))) return;
        otherOrder.push(id);
        saveHomeWidgets(other, otherOrder);
        var cur = getHomeWidgets(pg);
        var idx = cur.indexOf(id);
        if (idx >= 0) { cur.splice(idx, 1); saveHomeWidgets(pg, cur); }
      });
    });
    localStorage.setItem('mochi_home_grid_v2', '1');
  } catch(e) {}
}

// 统一的事件处理：touch + mouse 都通过 pointer-like 逻辑（绑定在统一网格容器上）
function initAppDragSystem() {
  var grids = document.querySelectorAll('.home-widget-area');

  grids.forEach(function(grid) {
    if (!grid) return;

    // touchstart：记录位置，启动长按计时
    grid.addEventListener('touchstart', function(e) {
      if (e.touches.length !== 1) return;
      var item = e.target.closest('.app-item');
      if (!item) return;
      var t = e.touches[0];
      _appLongPressStartX = t.clientX;
      _appLongPressStartY = t.clientY;
      clearTimeout(_appLongPressTimer);
      _appLongPressTimer = setTimeout(function() {
        if (!_appEditMode) {
          enterAppEditMode();
        }
        // 进入编辑模式后立即开始拖拽
        if (_appEditMode && !_appDragData && item) {
          startAppDrag(item, _appLongPressStartX, _appLongPressStartY);
        }
      }, 500);
    }, { passive: true });

    // touchmove：更新拖拽位置
    grid.addEventListener('touchmove', function(e) {
      if (e.touches.length !== 1) return;
      var t = e.touches[0];
      // 如果还没进入编辑模式，检查是否移动了
      if (!_appEditMode && _appLongPressTimer) {
        var dx = Math.abs(t.clientX - _appLongPressStartX);
        var dy = Math.abs(t.clientY - _appLongPressStartY);
        if (dx > 8 || dy > 8) {
          clearTimeout(_appLongPressTimer);
          _appLongPressTimer = null;
        }
      }
      // 如果在拖拽中，更新位置
      if (_appDragData) {
        e.preventDefault();
        onAppDragMove(t.clientX, t.clientY);
      }
    }, { passive: false });

    // touchend：结束拖拽或打开APP
    grid.addEventListener('touchend', function(e) {
      clearTimeout(_appLongPressTimer);
      _appLongPressTimer = null;
      var item = e.target.closest('.app-item');
      if (!item) return;
      var t = (e.changedTouches[0] || {});

      if (_appDragData) {
        e.preventDefault();
        onAppDragEnd(t.clientX, t.clientY);
        _appSuppressClick = true;
        return;
      }

      if (!_appEditMode) {
        // 阻止后续的合成 click 事件穿透到 overlay 内部元素
        e.preventDefault();
        _appSuppressClick = true;
        openApp(item.dataset.appId);
      }
    }, { passive: false });

    // mousedown（桌面端）
    grid.addEventListener('mousedown', function(e) {
      if (e.button !== 0) return;
      var item = e.target.closest('.app-item');
      if (!item) return;
      _appLongPressStartX = e.clientX;
      _appLongPressStartY = e.clientY;
      clearTimeout(_appLongPressTimer);
      _appLongPressTimer = setTimeout(function() {
        if (!_appEditMode) {
          enterAppEditMode();
        }
        if (_appEditMode && !_appDragData && item) {
          startAppDrag(item, _appLongPressStartX, _appLongPressStartY);
        }
      }, 500);
    });

    // click：桌面端快速点击打开APP / 编辑模式下单击自定义图标
    grid.addEventListener('click', function(e) {
      if (_appSuppressClick) {
        _appSuppressClick = false;
        return;
      }
      var item = e.target.closest('.app-item');
      if (!item) return;
      if (_appEditMode) {
        /* 编辑模式下单击图标即可自定义 */
        if (!_appDragData) {
          openAppIconCustomizer(item.dataset.appId);
        }
        return;
      }
      openApp(item.dataset.appId);
    });
  });

  // 全局 mousemove/mouseup（桌面端拖拽）
  document.addEventListener('mousemove', function(e) {
    if (_appDragData) {
      onAppDragMove(e.clientX, e.clientY);
    }
    if (!_appEditMode && _appLongPressTimer) {
      var dx = Math.abs(e.clientX - _appLongPressStartX);
      var dy = Math.abs(e.clientY - _appLongPressStartY);
      if (dx > 8 || dy > 8) {
        clearTimeout(_appLongPressTimer);
        _appLongPressTimer = null;
      }
    }
  });

  document.addEventListener('mouseup', function(e) {
    clearTimeout(_appLongPressTimer);
    _appLongPressTimer = null;
    if (_appDragData) {
      onAppDragEnd(e.clientX, e.clientY);
      _appSuppressClick = true;
    }
  });

  // 点击空白退出编辑模式
  document.addEventListener('click', function(e) {
    if (!_appEditMode) return;
    if (_appSuppressClick) {
      _appSuppressClick = false;
      return;
    }
    if (e.target.closest('.app-item')) return;
    if (e.target.closest('.home-widget')) return;
    if (e.target.closest('.widget-add-tile')) return;
    if (e.target.closest('.widget-gallery-overlay')) return;
    exitAppEditMode();
  }, true);
}

function enterAppEditMode() {
  /* HV2 固定版式：版式不可编辑，停用长按进入编辑模式 */
  if (typeof HV2_FIXED !== 'undefined' && HV2_FIXED) return;
  if (_appEditMode) return;
  _appEditMode = true;
  /* 不重建 DOM！只添加 editing 类和占位符，保留触摸目标元素不被销毁 */
  var widgetData = getHomeWidgetsData();
  var layout = getAppLayout();
  var dockAppIds = (typeof getDockApps === 'function') ? getDockApps() : [];
  var filteredLayout = [];
  for (var li = 0; li < layout.length; li++) {
    var lid = layout[li];
    if (lid && dockAppIds.indexOf(lid) !== -1) filteredLayout.push(null);
    else filteredLayout.push(lid);
  }
  ['p1', 'p2'].forEach(function(page) {
    var area = document.querySelector('.home-widget-area[data-page="' + page + '"]');
    if (!area) return;
    area.classList.add('editing');
    /* 添加空格占位符（不清除已有元素） */
    var placed = placeWidgets(page, widgetData[page] || [], filteredLayout);
    for (var r = 0; r < HOME_GRID_ROWS; r++) {
      for (var c = 0; c < HOME_GRID_COLS; c++) {
        if (placed.grid[r][c]) continue;
        area.appendChild(createHomeEmptySlot(page, r, c));
      }
    }
    /* 添加悬浮操作条 */
    var pageEl = area.closest('.home-page') || area.parentNode;
    if (pageEl) pageEl.classList.add('editing');
    var oldBar = pageEl ? pageEl.querySelector('.widget-add-bar') : null;
    if (oldBar) oldBar.parentNode.removeChild(oldBar);
    if (pageEl) {
      var bar = document.createElement('div');
      bar.className = 'widget-add-bar';
      var addTile = document.createElement('div');
      addTile.className = 'widget-add-tile';
      addTile.textContent = '＋ 添加小组件';
      addTile.addEventListener('click', (function(pg) {
        return function(e) { e.stopPropagation(); e.preventDefault(); openWidgetGallery(pg); };
      })(page));
      var wallTile = document.createElement('div');
      wallTile.className = 'widget-add-tile wallpaper-tile';
      wallTile.textContent = '🖼 更换壁纸';
      wallTile.addEventListener('click', function(e) { e.stopPropagation(); e.preventDefault(); openHomeWallpaperModal(); });
      var dockTile = document.createElement('div');
      dockTile.className = 'widget-add-tile dock-tile';
      dockTile.textContent = '🚀 Dock 栏';
      dockTile.addEventListener('click', function(e) { e.stopPropagation(); e.preventDefault(); openDockSettings(); });
      bar.appendChild(addTile);
      bar.appendChild(wallTile);
      bar.appendChild(dockTile);
      pageEl.appendChild(bar);
    }
  });
  showAppEditHint();
}

function exitAppEditMode() {
  _appEditMode = false;
  document.querySelectorAll('.home-widget-area').forEach(function(wa) { wa.classList.remove('editing'); });
  document.querySelectorAll('.home-page').forEach(function(pg) { pg.classList.remove('editing'); });
  renderHomeScreen(); // 退出编辑后重建以移除占位符和操作条
  if (typeof closeWidgetGallery === 'function') closeWidgetGallery();
  hideAppEditHint();
}

function showAppEditHint() {
  var hint = document.getElementById('appEditHint');
  if (!hint) {
    hint = document.createElement('div');
    hint.id = 'appEditHint';
    hint.style.cssText = 'position:fixed;top:12px;left:50%;transform:translateX(-50%);background:rgba(0,0,0,0.75);color:#fff;padding:8px 20px;border-radius:20px;font-size:12px;z-index:99998;pointer-events:none;transition:opacity 0.3s';
    phoneLayer().appendChild(hint);
  }
  hint.textContent = '拖拽排序 · 点击图标可自定义图标 · 底部可添加小组件/换壁纸/设置Dock · 点击空白完成';
  hint.style.opacity = '1';
}

function hideAppEditHint() {
  var hint = document.getElementById('appEditHint');
  if (hint) hint.style.opacity = '0';
}

// ===== 拖拽核心（iOS 风格：图标实时挤位 FLIP 动画）=====
var _appLastEdgeSwitch = 0;

// 通用 FLIP：记录 elements 当前位置 → 调用 reorderFn 重排 DOM → 平滑动画到新位置
function flipAnimate(elements, skipEl) {
  var rectMap = new Map();
  elements.forEach(function(el) { rectMap.set(el, el.getBoundingClientRect()); });
  return function applyFlip() {
    elements.forEach(function(el) {
      if (el === skipEl) return;
      var oldR = rectMap.get(el);
      var newR = el.getBoundingClientRect();
      if (!oldR) return;
      var dx = oldR.left - newR.left;
      var dy = oldR.top - newR.top;
      if (!dx && !dy) return;
      el.style.animation = 'none'; // 抖动动画会覆盖内联 transform，先暂停
      el.style.transition = 'none';
      el.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
      el._flipMoved = true;
    });
    void document.body.offsetHeight; // 强制重排
    elements.forEach(function(el) {
      if (!el._flipMoved) return;
      el._flipMoved = false;
      el.style.transition = 'transform 0.26s cubic-bezier(0.3,0.7,0.4,1)';
      el.style.transform = '';
      setTimeout(function() {
        el.style.transition = '';
        el.style.animation = '';
      }, 290);
    });
  };
}

// 坐标 → 统一网格单元格 {page, col, row, area}（行距 66 = 行高58 + 间距8，几何计算不受动画影响）
function homeCellFromPoint(x, y) {
  var areas = document.querySelectorAll('.home-widget-area');
  for (var i = 0; i < areas.length; i++) {
    var a = areas[i];
    var r = a.getBoundingClientRect();
    if (r.width <= 0) continue;
    if (x >= r.left - 6 && x <= r.right + 6 && y >= r.top - 20 && y <= r.top + 7 * 66 + 20) {
      var col = Math.min(HOME_GRID_COLS - 1, Math.max(0, Math.floor((x - r.left) / (r.width / HOME_GRID_COLS))));
      var row = Math.min(HOME_GRID_ROWS - 1, Math.max(0, Math.floor((y - r.top) / 66)));
      return { page: a.dataset.page || (i === 0 ? 'p1' : 'p2'), col: col, row: row, area: a };
    }
  }
  return null;
}

function startAppDrag(item, clientX, clientY) {
  if (!_appEditMode) return;
  var rect = item.getBoundingClientRect();
  var clone = item.cloneNode(true);
  clone.classList.add('drag-clone');
  clone.style.animation = 'none';
  clone.style.width = rect.width + 'px';
  clone.style.left = rect.left + 'px';
  clone.style.top = rect.top + 'px';
  clone.style.transform = 'scale(1)';
  document.body.appendChild(clone);
  // 拾起放大效果
  void clone.offsetHeight;
  clone.style.transition = 'transform 0.18s cubic-bezier(0.3,0.7,0.4,1)';
  clone.style.transform = 'scale(1.15)';
  setTimeout(function() {
    // 仅当仍在拖拽中才取消过渡，避免覆盖落定动画
    if (clone.parentNode && _appDragData && _appDragData.clone === clone) clone.style.transition = 'none';
  }, 200);

  item.classList.add('dragging');

  // 记录两页被小组件占用的单元格（拖拽期间组件不动，应用不能落到组件格上）
  var layout = getAppLayout();
  var widgetCells = { p1: {}, p2: {} };
  ['p1', 'p2'].forEach(function(pg) {
    var t = placeWidgets(pg, getHomeWidgets(pg), layout);
    var start = pg === 'p2' ? APPS_PER_PAGE : 0;
    for (var r = 0; r < HOME_GRID_ROWS; r++) {
      for (var c = 0; c < HOME_GRID_COLS; c++) {
        if (t.grid[r][c] && !layout[start + r * HOME_GRID_COLS + c]) widgetCells[pg][r + ',' + c] = true;
      }
    }
  });

  _appDragData = {
    item: item,
    clone: clone,
    appId: item.dataset.appId,
    offsetX: clientX - rect.left,
    offsetY: clientY - rect.top,
    workLayout: layout.slice(), // 工作副本：交换/移动都先在副本上进行，落定校验通过才保存
    widgetCells: widgetCells,
    curSlot: parseInt(item.dataset.appIndex, 10) || 0,
    hoverSlotEl: null
  };
}

// 编辑模式空槽高亮：指示松手后会落到哪格
function updateDropTargetHighlight(d, cell) {
  if (d.hoverSlotEl) { d.hoverSlotEl.classList.remove('drop-target'); d.hoverSlotEl = null; }
  if (!cell) return;
  var slot = (cell.page === 'p2' ? APPS_PER_PAGE : 0) + cell.row * HOME_GRID_COLS + cell.col;
  var el = cell.area.querySelector('.app-empty-slot[data-app-index="' + slot + '"]');
  if (el) { el.classList.add('drop-target'); d.hoverSlotEl = el; }
}

// 应用拖拽：目标格为空 → 直接移动；目标格有应用 → 两者交换；其余应用绝不动（不自动前移）
function onAppDragMove(clientX, clientY) {
  if (!_appDragData) return;
  var d = _appDragData;
  d.clone.style.left = (clientX - d.offsetX) + 'px';
  d.clone.style.top = (clientY - d.offsetY) + 'px';

  var cell = homeCellFromPoint(clientX, clientY);
  if (cell) {
    var start = cell.page === 'p2' ? APPS_PER_PAGE : 0;
    var slot = start + cell.row * HOME_GRID_COLS + cell.col;
    if (slot !== d.curSlot) {
      var fromSlot = d.workLayout.indexOf(d.appId);
      if (fromSlot >= 0) {
        var partnerId = d.workLayout[slot] || null;
        d.workLayout[fromSlot] = partnerId;
        d.workLayout[slot] = d.appId;
        d.curSlot = slot;
        // DOM 预览：拖拽原位元素移到新格（跨页则换容器）
        if (d.item.parentNode !== cell.area) cell.area.appendChild(d.item);
        d.item.style.gridColumn = String(cell.col + 1);
        d.item.style.gridRow = String(cell.row + 1);
        d.item.dataset.appIndex = slot;
        // 被交换的伙伴平滑移到拖拽者让出的格子
        if (partnerId) {
          var fromPage = fromSlot < APPS_PER_PAGE ? 'p1' : 'p2';
          var fromArea = document.querySelector('.home-widget-area[data-page="' + fromPage + '"]');
          var partnerEl = cell.area.querySelector('.app-item[data-app-id="' + partnerId + '"]');
          if (partnerEl && fromArea) {
            var oldRect = partnerEl.getBoundingClientRect();
            if (partnerEl.parentNode !== fromArea) fromArea.appendChild(partnerEl);
            var frel = fromSlot - (fromPage === 'p2' ? APPS_PER_PAGE : 0);
            partnerEl.style.gridColumn = String((frel % HOME_GRID_COLS) + 1);
            partnerEl.style.gridRow = String(Math.floor(frel / HOME_GRID_COLS) + 1);
            partnerEl.dataset.appIndex = fromSlot;
            var newRect = partnerEl.getBoundingClientRect();
            var dx = oldRect.left - newRect.left, dy = oldRect.top - newRect.top;
            if (dx || dy) {
              partnerEl.style.animation = 'none';
              partnerEl.style.transition = 'none';
              partnerEl.style.transform = 'translate(' + dx + 'px,' + dy + 'px)';
              void partnerEl.offsetHeight;
              partnerEl.style.transition = 'transform 0.24s cubic-bezier(0.3,0.7,0.4,1)';
              partnerEl.style.transform = '';
              (function(el) { setTimeout(function() { el.style.transition = ''; el.style.animation = ''; }, 280); })(partnerEl);
            }
          }
        }
        updateDropTargetHighlight(d, cell);
      }
    }
  }

  // 拖到边缘停留切换页面（带冷却，避免来回抖动）
  var wrap = document.getElementById('homePagesWrap');
  if (wrap) {
    var now = Date.now();
    var wrapRect = wrap.getBoundingClientRect();
    if (now - _appLastEdgeSwitch > 750) {
      if (clientX > wrapRect.right - 30 && _homeCurrentPage < 1) {
        _appLastEdgeSwitch = now;
        homeGoToPage(1);
      } else if (clientX < wrapRect.left + 30 && _homeCurrentPage > 0) {
        _appLastEdgeSwitch = now;
        homeGoToPage(0);
      }
    }
  }
}

function onAppDragEnd(clientX, clientY) {
  if (!_appDragData) return;
  var d = _appDragData;
  _appDragData = null;

  // 落定动画：克隆体飞回目标槽位
  var targetRect = d.item.getBoundingClientRect();
  d.clone.style.transition = 'left 0.22s cubic-bezier(0.3,0.7,0.4,1), top 0.22s cubic-bezier(0.3,0.7,0.4,1), transform 0.22s, opacity 0.22s';
  d.clone.style.left = targetRect.left + 'px';
  d.clone.style.top = targetRect.top + 'px';
  d.clone.style.transform = 'scale(1)';

  setTimeout(function() {
    if (d.clone && d.clone.parentNode) d.clone.parentNode.removeChild(d.clone);
    // 直接保存新布局，小组件会自动重新排列到剩余空位
    saveAppLayout(d.workLayout);
    // 检查是否有小组件因空间不足而溢出，温和提示但不阻止
    var _overflowP1 = placeWidgets('p1', getHomeWidgets('p1'), d.workLayout).overflow;
    var _overflowP2 = placeWidgets('p2', getHomeWidgets('p2'), d.workLayout).overflow;
    var _totalOverflow = _overflowP1.length + _overflowP2.length;
    if (_totalOverflow > 0 && typeof showToast === 'function') {
      showToast('有' + _totalOverflow + '个小组件空间不足已隐藏，可在编辑模式调整');
    }
    if (d.hoverSlotEl) d.hoverSlotEl.classList.remove('drop-target');
    d.item.classList.remove('dragging');
    renderHomeScreen(); // 干净重建，清除残留内联样式
  }, 230);
}

window.renderAppGrids = renderAppGrids;
window.exitAppEditMode = exitAppEditMode;

