function getWidgetDef(id) {
  /* 支持实例ID：id 可能是 'photos__1234567890_123'，取 '__' 前的基础ID查找定义 */
  var baseId = id.indexOf('__') >= 0 ? id.split('__')[0] : id;
  for (var i = 0; i < WIDGET_DEFINITIONS.length; i++) {
    if (WIDGET_DEFINITIONS[i].id === baseId) return WIDGET_DEFINITIONS[i];
  }
  /* 尝试完整ID（自定义组件可能没有 __ 后缀） */
  for (var i = 0; i < WIDGET_DEFINITIONS.length; i++) {
    if (WIDGET_DEFINITIONS[i].id === id) return WIDGET_DEFINITIONS[i];
  }
  return null;
}

// 分页存储：{ p1: [...], p2: [...] }，兼容旧数组格式（全部归入 p1）
function getHomeWidgetsData() {
  /* 默认组件排版（配合默认APP布局）：
     时钟 4×2 在 r0，天气 4×1 在 r2，两个 2×2 照片组件分别在 r3c3（右）和 r5c1（左下） */
  var defaults = {
    p1: ['clock', 'weather', 'photos__def_a', 'photos__def_b'],
    p2: [],
    _positions: {
      p1: {
        'clock': { col: 0, row: 0 },
        'weather': { col: 0, row: 2 },
        'photos__def_a': { col: 2, row: 3 },
        'photos__def_b': { col: 0, row: 5 }
      },
      p2: {}
    }
  };
  var valid = function(id) { return !!getWidgetDef(id); };
  try {
    var saved = readUiStateRaw('home_widgets');
    if (saved) {
      var data = JSON.parse(saved);
      if (Array.isArray(data)) {
        return { p1: data.filter(valid), p2: [], _positions: { p1: {}, p2: {} } };
      }
      if (data && typeof data === 'object') {
        if (!data._positions) data._positions = { p1: {}, p2: {} };
        if (!data._positions.p1) data._positions.p1 = {};
        if (!data._positions.p2) data._positions.p2 = {};
        return {
          p1: Array.isArray(data.p1) ? data.p1.filter(valid) : [],
          p2: Array.isArray(data.p2) ? data.p2.filter(valid) : [],
          _positions: data._positions
        };
      }
    }
  } catch(e) {}
  return defaults;
}

function getWidgetPositions(page) {
  var data = getHomeWidgetsData();
  if (data._positions && data._positions[page]) return data._positions[page];
  return {};
}

function saveWidgetPositions(page, positions) {
  var data = getHomeWidgetsData();
  if (!data._positions) data._positions = { p1: {}, p2: {} };
  data._positions[page] = positions;
  saveHomeWidgetsData(data);
}

function saveWidgetPosition(page, id, col, row) {
  var data = getHomeWidgetsData();
  if (!data._positions) data._positions = { p1: {}, p2: {} };
  if (!data._positions[page]) data._positions[page] = {};
  data._positions[page][id] = { col: col, row: row };
  saveHomeWidgetsData(data);
}

function saveHomeWidgetsData(data) {
  saveUiState('home_widgets', data);
}

function getHomeWidgets(page) {
  return getHomeWidgetsData()[page || 'p1'] || [];
}

function saveHomeWidgets(page, order) {
  // 兼容旧调用 saveHomeWidgets(order)
  if (Array.isArray(page)) { order = page; page = 'p1'; }
  var data = getHomeWidgetsData();
  data[page || 'p1'] = order;
  saveHomeWidgetsData(data);
}

// 查找小组件所在页，返回 'p1'/'p2' 或 null
function findWidgetPage(id) {
  var data = getHomeWidgetsData();
  if (data.p1.indexOf(id) >= 0) return 'p1';
  if (data.p2.indexOf(id) >= 0) return 'p2';
  return null;
}

// 解析组件跨度 {w, h}
function widgetSpanOf(def) {
  var s = { w: 4, h: 1 };
  if (!def || !def.span) return s;
  var w = def.span.match(/w(\d)/), h = def.span.match(/h(\d)/);
  if (w) s.w = parseInt(w[1], 10);
  if (h) s.h = parseInt(h[1], 10);
  return s;
}

// 统一网格下，组件渲染与应用渲染合并为 renderHomeScreen（保留旧函数名作为入口）
function renderHomeWidgets() { renderHomeScreen(); }
window.renderHomeWidgets = renderHomeWidgets;

function removeHomeWidget(id) {
  var page = findWidgetPage(id);
  if (!page) return;
  var order = getHomeWidgets(page);
  var i = order.indexOf(id);
  if (i < 0) return;
  order.splice(i, 1);
  saveHomeWidgets(page, order);
  /* 清除该组件的保存位置 */
  var positions = getWidgetPositions(page);
  delete positions[id];
  saveWidgetPositions(page, positions);
  renderHomeScreen();
  if (typeof showToast === 'function') showToast('已移除，可从「＋ 添加小组件」恢复');
}

function addHomeWidget(id, page) {
  /* 允许反复添加同一小组件：每次添加生成唯一实例ID */
  var instanceId = id + '__' + Date.now() + '_' + Math.floor(Math.random() * 1000);
  page = page || 'p1';
  var order = getHomeWidgets(page);
  // 统一网格真实占用校验：组件会填进应用之间的空位（例如 2×2 空位可放 2×2 组件），
  // 只有整页 4×7 真的排不下时才拒绝；当前页排不下会自动试另一页
  if (!homePlacementFits(page, order.concat([instanceId]))) {
    var other = page === 'p2' ? 'p1' : 'p2';
    var otherOrder = getHomeWidgets(other);
    if (homePlacementFits(other, otherOrder.concat([instanceId]))) {
      otherOrder.push(instanceId);
      saveHomeWidgets(other, otherOrder);
      renderHomeScreen();
      if (typeof homeGoToPage === 'function') homeGoToPage(other === 'p2' ? 1 : 0);
      if (typeof showToast === 'function') showToast('这页放不下，已加到' + (other === 'p2' ? '第二页' : '第一页') + ' ✿');
      return;
    }
    if (typeof showToast === 'function') showToast('两页都放不下啦，先挪走一些应用或组件');
    return;
  }
  order.push(instanceId);
  saveHomeWidgets(page, order);
  renderHomeScreen();
  if (typeof showToast === 'function') showToast('已添加小组件 ✿');
}

