// ===== 天气缓存回填（widget 重渲染后恢复显示）=====
function applyWeatherCacheToWidget() {
  var w = window._weatherCache;
  if (!w) return;
  var iconEl = document.getElementById('weatherIcon');
  var tempEl = document.getElementById('weatherTemp');
  var descEl = document.getElementById('weatherDesc');
  var cityEl = document.getElementById('weatherCity');
  if (iconEl) iconEl.textContent = w.icon || '🌤️';
  if (tempEl) tempEl.textContent = (w.temp !== undefined ? w.temp : '--') + '°';
  if (descEl) descEl.textContent = (w.desc || '') + (w.feelsLike ? ' · 体感' + w.feelsLike : '');
  if (cityEl) cityEl.textContent = w.city || '';
}

// ===== 照片 Widget 渲染（1×1 / 2×2 / 2×3 全幅单张照片，支持 per-widget 自定义图片）=====
function fillPhotoCell(body, widgetId) {
  /* 优先使用 per-widget 自定义图片 */
  if (widgetId && config.widgetImages && config.widgetImages[widgetId]) {
    body.innerHTML = '<img src="' + config.widgetImages[widgetId] + '" alt="">';
  } else {
    var photos = [];
    try { photos = config.photos || []; } catch(e) {}
    var latest = null;
    for (var i = photos.length - 1; i >= 0; i--) {
      if (photos[i].src) { latest = photos[i]; break; }
    }
    if (latest) {
      body.innerHTML = '<img src="' + latest.src + '" alt="">';
    } else {
      body.innerHTML = '<div class="photo-cell-empty">' +
        '<div class="photo-cell-empty-icon">📸</div><span>点击添加</span></div>';
    }
  }
  /* 不再设置 onclick 属性，改由 area click handler 集中处理，避免干扰拖拽 */
}

/* 给小组件设置自定义图片（支持所有类型小组件） */
function setWidgetImage(widgetId, src) {
  if (!config.widgetImages) config.widgetImages = {};
  config.widgetImages[widgetId] = src;
  Store.set('config', config);
  /* 刷新所有照片类小组件 */
  renderHomePhotoWidget();
  if (typeof renderPolaroidWidget === 'function') renderPolaroidWidget();
  if (typeof renderFilmstripWidget === 'function') renderFilmstripWidget();
  if (typeof renderPhotoRoundWidget === 'function') renderPhotoRoundWidget();
  if (typeof renderGrayPinkWidget === 'function') renderGrayPinkWidget();
  /* 刷新自定义/其他类型小组件：直接设置背景图 */
  var wEl = document.querySelector('.home-widget[data-widget-id="' + widgetId + '"]');
  if (wEl) {
    var def = getWidgetDef(widgetId);
    if (def && def.cls && def.cls.indexOf('photo-cell-widget') >= 0) {
      /* 照片类已经由 renderHomePhotoWidget 处理 */
    } else if (def && def.custom) {
      /* 自定义小组件：优先更新照片区域，没有照片区域才更新背景图 */
      var zone = wEl.querySelector('.cw-photo-zone[data-pz-idx="0"]') || wEl.querySelector('.cw-photo-zone');
      if (zone) {
        var pzIdx0 = parseInt(zone.dataset.pzIdx, 10) || 0;
        zone.innerHTML = '<img src="' + src + '" style="width:100%;height:100%;object-fit:cover" alt="">';
        zone.classList.add('has-photo');
        if (!config.widgetImages) config.widgetImages = {};
        config.widgetImages[widgetId + '_pz_' + pzIdx0] = src;
        Store.set('config', config);
      } else {
        /* 更新 .custom-widget-body 内的 <img alt=""> 标签 */
        var bodyImg = wEl.querySelector('.custom-widget-body > img');
        if (bodyImg) {
          bodyImg.src = src;
        } else {
          /* 没有 img 标签：创建一个 */
          var cbody = wEl.querySelector('.custom-widget-body');
          if (cbody) {
            var newImg = document.createElement('img');
            newImg.src = src;
            newImg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0';
            cbody.insertBefore(newImg, cbody.firstChild);
          } else {
            wEl.style.background = 'url("' + src + '") center/cover no-repeat';
          }
        }
        /* 同步更新自定义小组件存储的 imageUrl，使下次渲染也生效 */
        var cwList = config.settings.customWidgets || [];
        for (var cwi = 0; cwi < cwList.length; cwi++) {
          if (cwList[cwi].id === widgetId) {
            cwList[cwi].imageUrl = src;
            break;
          }
        }
        Store.set('config', config);
      }
    } else if (def && def.cls && def.cls.indexOf('photo-widget') >= 0) {
      /* 角色速联等：在 body 内放一张图 */
      var body = wEl.querySelector('.custom-widget-body') || wEl.querySelector('.photo-widget');
      if (body) body.style.background = 'url("' + src + '") center/cover no-repeat';
    }
  }
}

/* 清除照片小组件的自定义图片（恢复默认显示最新照片） */
function clearWidgetImage(widgetId) {
  if (config.widgetImages) {
    delete config.widgetImages[widgetId];
    /* 清除所有照片区域的照片 */
    for (var i = 0; i < 3; i++) {
      delete config.widgetImages[widgetId + '_pz_' + i];
    }
  }
  Store.set('config', config);
  renderHomePhotoWidget();
  /* 清除自定义设计图组件的所有照片区域 */
  var wEl = document.querySelector('.home-widget[data-widget-id="' + widgetId + '"]');
  if (wEl) {
    var zones = wEl.querySelectorAll('.cw-photo-zone');
    for (var zi = 0; zi < zones.length; zi++) {
      zones[zi].innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.15);color:rgba(255,255,255,0.5);font-size:20px">📷</div>';
      zones[zi].classList.remove('has-photo');
    }
  }
}

/* 点击照片小组件直接上传图片（非编辑模式下也可用），支持多图组件指定位置 */
/* iOS Safari 兼容选图：input 必须挂到 DOM 才能稳定弹出选择器并回调；先压缩避免超大原图撑爆存储；可重复选；失败有提示 */
function pickWidgetImage(onDataUrl, maxDim, quality) {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.setAttribute('aria-hidden', 'true');
  input.style.cssText = 'position:fixed;left:-9999px;top:-9999px;opacity:0;width:1px;height:1px';
  function cleanup() { try { if (input && input.parentNode) input.parentNode.removeChild(input); } catch(e) {} }
  function rawFallback(file, done) {
    var r = new FileReader();
    r.onload = function() { done(r.result); };
    r.onerror = function() { done(null); };
    r.readAsDataURL(file);
  }
  document.body.appendChild(input);
  input.onchange = function(ev) {
    var file = ev.target.files && ev.target.files[0];
    if (!file) { cleanup(); return; }
    if (typeof showToast === 'function') showToast('正在处理图片…');
    function done(dataUrl) {
      cleanup();
      if (dataUrl) onDataUrl(dataUrl);
      else if (typeof showToast === 'function') showToast('图片读取失败，请换一张试试');
    }
    try {
      compressImageToDataURL(file, maxDim || 1280, quality || 0.82, function(dataUrl) {
        if (dataUrl) done(dataUrl);
        else rawFallback(file, done);
      });
    } catch(err) { rawFallback(file, done); }
  };
  setTimeout(cleanup, 60000);
  input.click();
}
function tapPhotoWidgetUpload(widgetId, photoIdx) {
  /* 编辑模式下不拦截（交给编辑的换图按钮） */
  if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
  pickWidgetImage(function(src) {
    if (photoIdx !== undefined && photoIdx !== null) setWidgetImageAt(widgetId, photoIdx, src);
    else setWidgetImage(widgetId, src);
    if (typeof showToast === 'function') showToast('照片已上传 ✿');
  });
}

/* 多图组件：设置指定位置的照片 */
function setWidgetImageAt(widgetId, idx, src) {
  if (!config.widgetImages) config.widgetImages = {};
  var key = widgetId + '_multi';
  var arr = config.widgetImages[key] || [];
  /* 从现有照片填充数组 */
  var photos = [];
  try { photos = config.photos || []; } catch(e) {}
  var existingImgs = [];
  for (var j = photos.length - 1; j >= 0; j--) {
    if (photos[j].src) existingImgs.push(photos[j].src);
  }
  /* 合并：先自定义多图，再补最新照片 */
  var merged = [];
  for (var i = 0; i < 6; i++) {
    if (arr[i]) merged.push(arr[i]);
    else if (existingImgs.length > 0) merged.push(existingImgs.shift());
    else merged.push(null);
  }
  merged[idx] = src;
  config.widgetImages[key] = merged;
  Store.set('config', config);
  if (typeof renderFilmstripWidget === 'function') renderFilmstripWidget();
}

function renderHomePhotoWidget(widgetEl) {
  if (widgetEl) {
    var body = widgetEl.querySelector ? widgetEl.querySelector('.photo-cell-body') : null;
    var wid = widgetEl.dataset ? widgetEl.dataset.widgetId : '';
    if (body) fillPhotoCell(body, wid);
    return;
  }
  // 无参数调用：刷新所有页面的照片小组件（传入每个组件的 widgetId）
  var bodies = document.querySelectorAll('.home-widget-area .photo-cell-body');
  for (var i = 0; i < bodies.length; i++) {
    var wid = '';
    var parent = bodies[i].closest('[data-widget-id]');
    if (parent) wid = parent.dataset.widgetId;
    fillPhotoCell(bodies[i], wid);
  }
}
window.renderHomePhotoWidget = renderHomePhotoWidget;

/* ===== 拍立得小组件 ===== */
function renderPolaroidWidget(widgetEl) {
  if (!widgetEl) {
    var all = document.querySelectorAll('.home-widget.polaroid-widget');
    for (var i = 0; i < all.length; i++) renderPolaroidWidget(all[i]);
    return;
  }
  var wid = widgetEl.dataset ? widgetEl.dataset.widgetId : '';
  var wrap = widgetEl.querySelector('.polaroid-img-wrap');
  var caption = widgetEl.querySelector('.polaroid-caption');
  if (!wrap) return;
  var customImg = (wid && config.widgetImages && config.widgetImages[wid]) ? config.widgetImages[wid] : null;
  if (customImg) {
    wrap.innerHTML = '<img src="' + customImg + '" alt="">';
    if (caption) caption.textContent = '';
  } else {
    /* 尝试用最新照片 */
    var photos = [];
    try { photos = config.photos || []; } catch(e) {}
    var latest = null;
    for (var j = photos.length - 1; j >= 0; j--) {
      if (photos[j].src) { latest = photos[j]; break; }
    }
    if (latest) {
      wrap.innerHTML = '<img src="' + latest.src + '" alt="">';
      if (caption) caption.textContent = '';
    } else {
      wrap.innerHTML = '<div class="polaroid-empty"><div class="polaroid-empty-icon">📷</div><span>点击添加</span></div>';
    }
  }
  /* 不再设置 onclick，由 area click handler 集中处理 */
}

/* ===== 胶片风小组件 ===== */
function renderFilmstripWidget(widgetEl) {
  if (!widgetEl) {
    var all = document.querySelectorAll('.home-widget.filmstrip-widget');
    for (var i = 0; i < all.length; i++) renderFilmstripWidget(all[i]);
    return;
  }
  var wid = widgetEl.dataset ? widgetEl.dataset.widgetId : '';
  var body = widgetEl.querySelector('.filmstrip-body');
  if (!body) return;
  var isWide = widgetEl.className.indexOf('w4') >= 0;
  var photoCount = isWide ? 4 : 2;
  /* 收集图片：per-widget 多图自定义 + 单图自定义 + 最新照片 */
  var multiKey = wid + '_multi';
  var multiImgs = (config.widgetImages && config.widgetImages[multiKey]) ? config.widgetImages[multiKey] : [];
  var imgs = [];
  for (var mi = 0; mi < photoCount; mi++) {
    if (multiImgs[mi]) imgs.push(multiImgs[mi]);
    else imgs.push(null);
  }
  /* 补充：如果多图没填满，用单图自定义 + 最新照片 */
  var singleImg = (wid && config.widgetImages && config.widgetImages[wid]) ? config.widgetImages[wid] : null;
  var photos = [];
  try { photos = config.photos || []; } catch(e) {}
  var existingImgs = [];
  for (var j = photos.length - 1; j >= 0; j--) {
    if (photos[j].src) existingImgs.push(photos[j].src);
  }
  if (singleImg) existingImgs.unshift(singleImg);
  var fillIdx = 0;
  for (var fi = 0; fi < photoCount; fi++) {
    if (!imgs[fi] && fillIdx < existingImgs.length) {
      imgs[fi] = existingImgs[fillIdx++];
    }
  }
  var hasAny = imgs.some(function(x) { return !!x; });
  var html = '';
  html += '<div class="filmstrip-perf">';
  for (var k = 0; k < (isWide ? 8 : 4); k++) html += '<div class="filmstrip-perf-hole"></div>';
  html += '</div>';
  html += '<div class="filmstrip-photos">';
  if (!hasAny) {
    html += '<div class="filmstrip-empty" style="flex:1"><div class="filmstrip-empty-icon">🎞️</div><span>点击添加照片</span></div>';
  } else {
    for (var m = 0; m < photoCount; m++) {
      if (imgs[m]) {
        html += '<div class="filmstrip-photo" data-photo-idx="' + m + '"><img src="' + imgs[m] + '" alt=""></div>';
      } else {
        html += '<div class="filmstrip-photo" data-photo-idx="' + m + '"><span class="filmstrip-photo-empty">+</span></div>';
      }
    }
  }
  html += '</div>';
  html += '<div class="filmstrip-perf">';
  for (var k2 = 0; k2 < (isWide ? 8 : 4); k2++) html += '<div class="filmstrip-perf-hole"></div>';
  html += '</div>';
  body.innerHTML = html;
  /* 不再设置 widget 级 onclick，由 area click handler 根据点击位置判断 */
}

