// v112 根治“清空后旧聊天复发”：多账号下 char.chatHistory 与账号桶 acc.chats[cid] 是【同一数组引用】，
// 打开私聊时 config.chatHistory 也指向它。必须【原地】清空(length=0)，绝不能用 =[] 赋新数组——那只会改指针、
// 留下装着旧消息的账号桶，等下次重新挂载(prepareUserPeer/mountAccount)把旧桶接回来，旧记录就“复活”。
function clearPrivateThreadInPlace(optIdx) {
  var _idx = (typeof optIdx === 'number') ? optIdx : currentCharIdx;
  var ch = (config.characters || [])[_idx];
  if (ch) {
    if (!Array.isArray(ch.chatHistory)) ch.chatHistory = [];
    ch.chatHistory.length = 0;                 // 原地清空账号线上桶（acc.chats[cid] 同引用，一并清空）
    config.chatHistory = ch.chatHistory;       // 指回同一个被清空的桶，杜绝多数组
    if (Array.isArray(ch.offlineChatHistory)) ch.offlineChatHistory.length = 0; // 账号线下桶同理原地清
    else ch.offlineChatHistory = [];
    // 兜底：直接定位当前账号的线上/线下桶原地清空，防止某些路径下 ch 指针尚未挂载到账号桶而漏清
    try {
      var _acc = (typeof waCurrentAccount === 'function') ? waCurrentAccount() : null;
      if (_acc) {
        var _k = String(ch.id);
        if (_acc.chats && Array.isArray(_acc.chats[_k])) _acc.chats[_k].length = 0;
        if (_acc.offlineChats && Array.isArray(_acc.offlineChats[_k])) _acc.offlineChats[_k].length = 0;
      }
    } catch (e) {}
  } else {
    if (Array.isArray(config.chatHistory)) config.chatHistory.length = 0;
    else config.chatHistory = [];
  }
}

function clearChatFromInfo() {
  if (!confirm('确定要清空聊天记录吗？\n\n将同时清除该角色的线上和线下聊天记录，以及所有记忆（包括手动保存的记忆）。此操作不可恢复。')) return;
  resetChatPagination();
  if (!config.summarizedUpTo) config.summarizedUpTo = {};
  // 群聊模式下清空群聊记录
  if (isGroupChatMode && _currentGroupIdx >= 0) {
    config.chatHistory = [];
    if (config.groupChats && config.groupChats[_currentGroupIdx]) {
      config.groupChats[_currentGroupIdx].messages = [];
    }
    /* 重置群聊总结标记 */
    delete config.summarizedUpTo['group_' + _currentGroupIdx];
    Store.set('config', config);
    showToast('已清空聊天记录');
    renderMessages();
    goBack('view-chat');
    return;
  }
  // 多人线下模式下清空多人线下记录
  if (isGroupOfflineMode && _currentGroupOfflineIdx >= 0) {
    config.chatHistory = [];
    if (config.groupOfflineChats && config.groupOfflineChats[_currentGroupOfflineIdx]) {
      config.groupOfflineChats[_currentGroupOfflineIdx].messages = [];
    }
    var _clGoPref = 'goff_' + _currentGroupOfflineIdx + '_char_';
    Object.keys(config.summarizedUpTo || {}).forEach(function (k) { if (k.indexOf(_clGoPref) === 0) delete config.summarizedUpTo[k]; });
    Store.set('config', config);
    showToast('已清空聊天记录');
    renderMessages();
    goBack('view-offline');
    return;
  }
  // NPC聊天模式下只清空NPC聊天，不清空角色记录
  if (isNpcChatMode && currentNpcChatIdx >= 0) {
    config.chatHistory = [];
    if (config.npcChats && config.npcChats[currentNpcChatIdx]) {
      config.npcChats[currentNpcChatIdx].messages = [];
      /* 同时清空NPC记忆 */
      config.npcChats[currentNpcChatIdx].memories = [];
    }
    /* 重置NPC总结标记 */
    delete config.summarizedUpTo['npc_' + currentNpcChatIdx + '_online'];
    Store.set('config', config);
    showToast('已清空聊天记录和记忆');
    renderMessages();
    return;
  }
  // v112 原地清空账号聊天桶（不能 =[] 断引用，否则重新挂载旧桶复发）
  clearPrivateThreadInPlace();
  if (config.characters && config.characters[currentCharIdx]) {
    // 同时清除该角色的记忆
    config.characters[currentCharIdx].memories = [];
  }
  // 清除共享记忆
  config.memories = [];
  /* 重置该角色的总结标记 */
  delete config.summarizedUpTo['char_' + currentCharIdx + '_online'];
  delete config.summarizedUpTo['char_' + currentCharIdx + '_offline'];
  /* 重置该角色所在群聊的总结标记 */
  (config.groupChats || []).forEach(function(g, gi) {
    if (g && (g.members || []).some(function(m) {
      return m.memberId === ('char_' + currentCharIdx) || (m.type === 'char' && String(m.charIdx) === String(currentCharIdx));
    })) {
      delete config.summarizedUpTo['group_' + gi + '_char_' + currentCharIdx];
    }
  });
  Store.set('config', config);
  showToast('已清空聊天记录和记忆');
  renderMessages();
  updateHeartBtn();
  if (typeof renderMemories === 'function') renderMemories();
}

// ===== 聊天壁纸（线上/线下分开存储） =====
function openChatWallpaper() {
  document.getElementById('wallpaperFileInput').click();
}

function handleWallpaperSelect(event) {
  const file = event.target.files[0];
  if (!file) return;
  event.target.value = '';
  const reader = new FileReader();
  reader.onload = function(e) {
    const dataUrl = e.target.result;
    const isOffline = (typeof currentChatMode !== 'undefined' && currentChatMode === 'offline');
    if (!config.characters) config.characters = [];
    if (config.characters[currentCharIdx]) {
      if (isOffline) {
        config.characters[currentCharIdx].offlineChatWallpaper = dataUrl;
      } else {
        config.characters[currentCharIdx].chatWallpaper = dataUrl;
      }
    }
    Store.set('config', config);
    applyChatWallpaper();
    showToast((isOffline ? '线下' : '线上') + '聊天背景已设置');
  };
  reader.readAsDataURL(file);
}

function applyOfflineWallpaperToView(chatView) {
  if (!chatView) return;
  const isOffline = (typeof currentChatMode !== 'undefined' && currentChatMode === 'offline');
  const char = config.characters && config.characters[currentCharIdx];
  // 单人线下角色专属壁纸优先，其次全局线下壁纸；都没有则回落到默认淡黄（由CSS !important兜底）
  const perChar = (isOffline && char) ? (char.offlineChatWallpaper || '') : '';
  const globalWp = (config.settings && config.settings.offlineWallpaper) || '';
  const use = perChar || globalWp || '';
  if (use) chatView.style.setProperty('--offline-wp-img', 'url("' + String(use).replace(/"/g, '') + '")');
  else chatView.style.removeProperty('--offline-wp-img');
}
function applyChatWallpaper() {
  const chatView = document.querySelector('.chat-view');
  if (!chatView) return;
  const char = config.characters && config.characters[currentCharIdx];
  const isOffline = (typeof currentChatMode !== 'undefined' && currentChatMode === 'offline');
  if (isOffline) {
    // 线下：清掉可能残留的内联背景，统一走 --offline-wp-img 变量（CSS !important 保证不被日间白底盖住）
    chatView.style.backgroundImage = ''; chatView.style.backgroundSize = '';
    chatView.style.backgroundPosition = ''; chatView.style.backgroundAttachment = '';
    applyOfflineWallpaperToView(chatView);
    return;
  }
  const wp = char ? (char.chatWallpaper || '') : '';
  if (wp) {
    // 内联带 !important：日间 .theme-light .chat-view 有 !important 白底，普通内联会被它盖掉导致“日间壁纸不显示”
    chatView.style.setProperty('background-image', 'url(' + wp + ')', 'important');
    chatView.style.setProperty('background-size', 'cover', 'important');
    chatView.style.setProperty('background-position', 'center', 'important');
    chatView.style.setProperty('background-attachment', 'fixed', 'important');
    chatView.style.setProperty('background-color', 'transparent', 'important');
  } else {
    ['background-image','background-size','background-position','background-attachment','background-color'].forEach(function(k){ chatView.style.removeProperty(k); });
  }
}
/* 全局线下模式壁纸（单人/多人线下通用；单人角色专属壁纸优先于它） */
function openOfflineWallpaper() {
  var inp = document.createElement('input');
  inp.type = 'file'; inp.accept = 'image/*';
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0];
    if (!f) return;
    var rd = new FileReader();
    rd.onload = function (ev) {
      config.settings = config.settings || {};
      config.settings.offlineWallpaper = ev.target.result;
      Store.set('config', config);
      applyChatWallpaper();
      showToast('线下壁纸已设置，进入线下剧情生效');
    };
    rd.readAsDataURL(f);
  };
  inp.click();
}
function clearOfflineWallpaper() {
  config.settings = config.settings || {};
  config.settings.offlineWallpaper = '';
  Store.set('config', config);
  applyChatWallpaper();
  showToast('已恢复默认淡黄背景');
}

function clearChatWallpaper() {
  const isOffline = (typeof currentChatMode !== 'undefined' && currentChatMode === 'offline');
  if (config.characters && config.characters[currentCharIdx]) {
    if (isOffline) {
      config.characters[currentCharIdx].offlineChatWallpaper = '';
    } else {
      config.characters[currentCharIdx].chatWallpaper = '';
    }
    Store.set('config', config);
    applyChatWallpaper();
    showToast((isOffline ? '线下' : '线上') + '聊天背景已清除');
  }
}

// ===== 头像图片选择 =====
let pickCharAvatarTarget = '';
let pendingCharAvatarImg = '';

/* 压缩图片为指定尺寸的 dataURL，避免 localStorage 配额溢出导致头像丢失 */
function compressAvatarImage(dataUrl, maxDim, quality, callback) {
  var img = new Image();
  img.onload = function() {
    var canvas = document.createElement('canvas');
    var w = img.width, h = img.height;
    if (w > h) { if (w > maxDim) { h = Math.round(h * maxDim / w); w = maxDim; } }
    else { if (h > maxDim) { w = Math.round(w * maxDim / h); h = maxDim; } }
    canvas.width = w; canvas.height = h;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0, w, h);
    try {
      callback(canvas.toDataURL('image/jpeg', quality));
    } catch(e) {
      callback(dataUrl);
    }
  };
  img.onerror = function() { callback(dataUrl); };
  img.src = dataUrl;
}

function handleAvatarSelect(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    const rawUrl = e.target.result;
    /* 压缩到 256px 以内、JPEG 0.8 质量，避免 localStorage 配额溢出 */
    compressAvatarImage(rawUrl, 256, 0.8, function(dataUrl) {
      if (pickCharAvatarTarget === 'character') {
        pendingCharAvatarImg = dataUrl;
        pendingCharAvatar = '';
        const img = document.getElementById('charAvatarImg');
        const placeholder = document.getElementById('charAvatarPlaceholder');
        const picker = document.getElementById('charAvatarPicker');
        if (img) { img.src = dataUrl; img.style.display = 'block'; }
        if (placeholder) placeholder.style.display = 'none';
        if (picker) picker.classList.add('has-image');
      } else if (pickCharAvatarTarget === 'user') {
        if (!config.user) config.user = {};
        config.user.avatar = dataUrl;
        Store.set('config', config);
        // 更新弹窗中的头像
        const img = document.getElementById('userAvatarImg');
        const placeholder = document.getElementById('userAvatarPlaceholder');
        if (img) { img.src = dataUrl; img.style.display = 'block'; }
        if (placeholder) placeholder.style.display = 'none';
        document.getElementById('userAvatarPicker').classList.add('has-image');
        renderMe();
      }
    });
  };
  reader.readAsDataURL(file);
  event.target.value = '';
}

function pickUserAvatar() {
  pickCharAvatarTarget = 'user';
  document.getElementById('avatarFileInput').click();
}

