var _userRefImages = [];
function renderUserRefPreview() {
  var box = document.getElementById('userRefPreview');
  if (!box) return;
  box.innerHTML = '';
  _userRefImages.forEach(function (src, i) {
    var d = document.createElement('div');
    d.style.cssText = 'position:relative;width:64px;height:64px;border-radius:10px;overflow:hidden';
    d.innerHTML = '<img src="' + src + '" style="width:100%;height:100%;object-fit:cover" alt="参考图"/>'
      + '<div onclick="removeUserRefImg(' + i + ')" style="position:absolute;top:2px;right:2px;width:18px;height:18px;border-radius:50%;background:rgba(0,0,0,0.55);color:#fff;font-size:12px;line-height:18px;text-align:center;cursor:pointer">×</div>';
    box.appendChild(d);
  });
}
function handleUserRefUpload(e) {
  var files = Array.prototype.slice.call(e.target.files || []);
  files.forEach(function (f) {
    if (_userRefImages.length >= 4) { showToast('最多上传4张参考图'); return; }
    if (f.size > 15 * 1024 * 1024) { showToast('单张图片请小于15MB'); return; }
    if (typeof compressImageToDataURL === 'function') {
      compressImageToDataURL(f, 768, 0.85, function (dataUrl) {
        if (_userRefImages.length < 4) { _userRefImages.push(dataUrl); renderUserRefPreview(); }
      });
    } else {
      var r = new FileReader();
      r.onload = function (ev) { if (_userRefImages.length < 4) { _userRefImages.push(ev.target.result); renderUserRefPreview(); } };
      r.readAsDataURL(f);
    }
  });
  try { e.target.value = ''; } catch (_) {}
}
function removeUserRefImg(i) { _userRefImages.splice(i, 1); renderUserRefPreview(); }
window.handleUserRefUpload = handleUserRefUpload;
window.removeUserRefImg = removeUserRefImg;

