// ===== 钱包管理 =====
let walletEditMode = '';

function openWallet() {
  navigateTo('view-wallet');
  updateWalletDisplay();
}

function updateWalletDisplay() {
  const balance = (config.user && config.user.wallet !== undefined) ? config.user.wallet : 0;
  document.getElementById('walletBalance').textContent = balance.toFixed(2);
  // 渲染交易记录
  const history = (config.user && config.user.walletHistory) || [];
  const section = document.getElementById('walletHistorySection');
  const list = document.getElementById('walletHistoryList');
  if (history.length > 0) {
    section.style.display = 'block';
    let html = '';
    history.slice(-20).reverse().forEach(h => {
      const isIncome = h.type === '充值';
      const time = new Date(h.time);
      const timeStr = (time.getMonth()+1)+'/'+time.getDate()+' '+time.getHours()+':'+String(time.getMinutes()).padStart(2,'0');
      html += `<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:0.5px solid rgba(255,255,255,0.06)">
        <div>
          <div style="color:#fff;font-size:15px">${escapeHtml(h.type)}</div>
          <div style="color:#8E8E93;font-size:12px;margin-top:2px">${timeStr}${h.to?' → '+escapeHtml(h.to):''}</div>
        </div>
        <div style="font-size:16px;font-weight:600;color:${isIncome?'#07C160':'#fff'}">${isIncome?'+':'-'}¥${h.amount.toFixed(2)}</div>
      </div>`;
    });
    list.innerHTML = html;
  } else {
    section.style.display = 'none';
  }
}

function openWalletEdit(mode) {
  walletEditMode = mode;
  document.getElementById('walletEditTitle').textContent = mode;
  const balance = (config.user && config.user.wallet !== undefined) ? config.user.wallet : 0;
  document.getElementById('walletCurrentBalance').textContent = balance.toFixed(2);
  document.getElementById('walletAmountInput').value = '';
  openModal('walletEditModal');
  setTimeout(() => document.getElementById('walletAmountInput').focus(), 100);
}

function confirmWalletEdit() {
  const amount = parseFloat(document.getElementById('walletAmountInput').value);
  if (isNaN(amount) || amount <= 0) {
    showToast('请输入有效金额');
    return;
  }
  if (!config.user) config.user = {};
  if (config.user.wallet === undefined) config.user.wallet = 0;
  if (!config.user.walletHistory) config.user.walletHistory = [];

  if (walletEditMode === '充值') {
    config.user.wallet += amount;
    config.user.walletHistory.push({ type: '充值', amount: amount, time: Date.now() });
  } else {
    if (config.user.wallet < amount) {
      showToast('余额不足');
      return;
    }
    config.user.wallet -= amount;
    config.user.walletHistory.push({ type: '提现', amount: amount, time: Date.now() });
  }
  Store.set('config', config);
  closeModal('walletEditModal');
  updateWalletDisplay();
  showToast(walletEditMode + '成功');
}

function showWalletDetails() {
  const history = (config.user && config.user.walletHistory) || [];
  if (history.length === 0) {
    showToast('暂无交易记录');
    return;
  }
  let msg = '';
  history.slice(-10).reverse().forEach(h => {
    msg += `${h.type} ¥${h.amount.toFixed(2)}\n`;
  });
  showToast(msg);
}

