/* ===== 自定义表情包标签辅助函数 ===== */
/* 判断某标签ID是否属于自定义标签 */
function isCustomPack(packId) {
  var packs = config.customStickerPacks || [];
  for (var i = 0; i < packs.length; i++) {
    if (packs[i].id === packId) return true;
  }
  return false;
}
/* 按ID获取自定义标签 */
function getCustomPackById(packId) {
  var packs = config.customStickerPacks || [];
  for (var i = 0; i < packs.length; i++) {
    if (packs[i].id === packId) return packs[i];
  }
  return null;
}
/* 生成唯一标签ID */
function generatePackId() {
  return 'pack_' + Date.now() + '_' + Math.floor(Math.random() * 10000);
}
/* 创建新标签，返回新标签对象 */
function createCustomStickerPack(name) {
  if (!config.customStickerPacks) config.customStickerPacks = [];
  var pack = { id: generatePackId(), name: name, items: [] };
  config.customStickerPacks.push(pack);
  Store.set('config', config);
  return pack;
}
/* 删除整个标签（连同表情） */
function deleteCustomStickerPack(packId) {
  if (!config.customStickerPacks) return;
  for (var i = 0; i < config.customStickerPacks.length; i++) {
    if (config.customStickerPacks[i].id === packId) {
      config.customStickerPacks.splice(i, 1);
      Store.set('config', config);
      return;
    }
  }
}
/* 往指定标签添加单个表情 */
function addStickerToPack(packId, name, url) {
  var pack = getCustomPackById(packId);
  if (!pack) return false;
  if (!pack.items) pack.items = [];
  pack.items.push({ name: name, url: url });
  Store.set('config', config);
  return true;
}

/* ===== 本地图片上传：转 base64 存储，永不错效 ===== */
/* 压缩图片为 base64 data URL，控制大小避免 localStorage 溢出 */
function compressImageToDataURL(file, maxDim, quality, callback) {
  var reader = new FileReader();
  reader.onload = function(e) {
    var img = new Image();
    img.onload = function() {
      var w = img.width, h = img.height;
      if (w > maxDim || h > maxDim) {
        if (w >= h) { h = Math.round(h * maxDim / w); w = maxDim; }
        else { w = Math.round(w * maxDim / h); h = maxDim; }
      }
      var canvas = document.createElement('canvas');
      canvas.width = w; canvas.height = h;
      var ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      var dataUrl = canvas.toDataURL('image/webp', quality);
      /* 如果 webp 不行就用 png */
      if (dataUrl.indexOf('data:image/webp') !== 0) {
        dataUrl = canvas.toDataURL('image/png');
      }
      callback(dataUrl);
    };
    img.onerror = function() { callback(null); };
    img.src = e.target.result;
  };
  reader.onerror = function() { callback(null); };
  reader.readAsDataURL(file);
}

/* 处理单个本地图片上传 */
function handleStickerFileUpload(input) {
  var file = input.files && input.files[0];
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) { showToast('图片不能超过5MB'); input.value = ''; return; }
  var nameEl = _findById('customStickerName');
  var stickerName = nameEl ? (nameEl.value || '').trim() : '';
  if (!stickerName) {
    /* 用文件名做名称 */
    stickerName = file.name.replace(/\.[^.]+$/, '').substring(0, 20);
  }
  showToast('正在处理图片...');
  compressImageToDataURL(file, 200, 0.8, function(dataUrl) {
    if (!dataUrl) { showToast('图片处理失败'); input.value = ''; return; }
    var targetPackId = _currentManagePackId;
    if (!targetPackId) {
      var packs = config.customStickerPacks || [];
      if (packs.length) {
        targetPackId = packs[0].id;
      } else {
        var newPack = createCustomStickerPack('自定义');
        targetPackId = newPack.id;
        _currentManagePackId = targetPackId;
      }
    }
    addStickerToPack(targetPackId, stickerName, dataUrl);
    if (nameEl) nameEl.value = '';
    if (document.getElementById('view-sticker-mgmt') && document.getElementById('view-sticker-mgmt').classList.contains('active')) {
      renderStickerMgmtPage();
    } else {
      renderStickerMgmtView();
    }
    showToast('已添加：' + stickerName);
    input.value = '';
  });
}

/* 批量本地图片上传 */
function handleBatchStickerFileUpload(input) {
  var files = input.files;
  if (!files || !files.length) return;
  if (files.length > 50) { showToast('一次最多50张'); return; }
  var targetPackId = _currentManagePackId;
  if (!targetPackId) {
    var packs = config.customStickerPacks || [];
    if (packs.length) {
      targetPackId = packs[0].id;
    } else {
      var newPack = createCustomStickerPack('自定义');
      targetPackId = newPack.id;
      _currentManagePackId = targetPackId;
    }
  }
  var processed = 0;
  var total = files.length;
  showToast('开始导入 ' + total + ' 张图片...');
  function processNext(idx) {
    if (idx >= total) {
      if (document.getElementById('view-sticker-mgmt') && document.getElementById('view-sticker-mgmt').classList.contains('active')) {
        renderStickerMgmtPage();
      } else {
        renderStickerMgmtView();
      }
      showToast('已导入 ' + processed + ' 张表情');
      input.value = '';
      return;
    }
    var file = files[idx];
    if (file.size > 5 * 1024 * 1024) { processNext(idx + 1); return; }
    var name = file.name.replace(/\.[^.]+$/, '').substring(0, 20);
    compressImageToDataURL(file, 200, 0.8, function(dataUrl) {
      if (dataUrl) {
        addStickerToPack(targetPackId, name, dataUrl);
        processed++;
      }
      processNext(idx + 1);
    });
  }
  processNext(0);
}

/* 查找表情包：从所有包（含自定义）中按名称查找 */
/* ===== 表情图片本地缓存（IndexedDB），防止图床挂掉 ===== */
var _stickerCacheMap = {}; // { 原始URL: blobURL }

function initStickerCache() {
  return new Promise(function(resolve) {
    try {
      var req = indexedDB.open('mochi_sticker_cache', 1);
      req.onupgradeneeded = function(e) {
        var db = e.target.result;
        if (!db.objectStoreNames.contains('stickers')) {
          db.createObjectStore('stickers', { keyPath: 'url' });
        }
      };
      req.onsuccess = function(e) {
        var db = e.target.result;
        try {
          var tx = db.transaction('stickers', 'readonly');
          var store = tx.objectStore('stickers');
          var getAll = store.getAll();
          getAll.onsuccess = function() {
            var results = getAll.result || [];
            for (var i = 0; i < results.length; i++) {
              if (results[i].blob) {
                _stickerCacheMap[results[i].url] = URL.createObjectURL(results[i].blob);
              }
            }
            console.debug('[StickerCache] loaded', Object.keys(_stickerCacheMap).length, 'cached stickers');
            resolve();
          };
          getAll.onerror = function() { resolve(); };
        } catch(e) { resolve(); }
      };
      req.onerror = function() { resolve(); };
    } catch(e) { resolve(); }
  });
}

function getCachedStickerUrl(url) {
  if (!url) return null;
  return _stickerCacheMap[url] || null;
}

function cacheStickerBlob(url, blob) {
  if (!url || _stickerCacheMap[url]) return;
  try {
    var blobUrl = URL.createObjectURL(blob);
    _stickerCacheMap[url] = blobUrl;
    var req = indexedDB.open('mochi_sticker_cache', 1);
    req.onsuccess = function(e) {
      var db = e.target.result;
      try {
        var tx = db.transaction('stickers', 'readwrite');
        var store = tx.objectStore('stickers');
        store.put({ url: url, blob: blob });
      } catch(e) {}
    };
  } catch(e) {}
}

/* 图片加载成功时自动缓存（后台 fetch blob） */
function onStickerImgLoad(img) {
  var src = img.getAttribute('src') || '';
  if (!src || src.startsWith('blob:') || src.startsWith('data:')) return;
  /* 从 src 反查原始 URL（可能已被 mochiResolveSticker 替换为 blob URL，跳过） */
  if (_stickerCacheMap[src]) return; // 已缓存
  /* 后台 fetch 并缓存 */
  fetch(src).then(function(r) {
    if (!r.ok) return;
    return r.blob();
  }).then(function(blob) {
    if (blob) cacheStickerBlob(src, blob);
  }).catch(function() {});
}

/* 预加载所有表情图片到本地缓存 */
var _stickerPreloading = false;
async function preloadAllStickers() {
  if (_stickerPreloading) { showToast('正在缓存中，请稍候...'); return; }
  var allPacks = MOCHI_STICKER_PACKS.slice();
  var cps = config.customStickerPacks || [];
  for (var i = 0; i < cps.length; i++) allPacks.push(cps[i]);

  var todo = [];
  for (var i = 0; i < allPacks.length; i++) {
    var items = allPacks[i].items || [];
    for (var j = 0; j < items.length; j++) {
      if (items[j].url && !_stickerCacheMap[items[j].url]) {
        todo.push({ url: items[j].url, name: items[j].name });
      }
    }
  }

  if (!todo.length) { showToast('所有表情已缓存'); return; }

  _stickerPreloading = true;
  showToast('开始缓存 ' + todo.length + ' 个表情...');

  var success = 0, fail = 0;
  for (var i = 0; i < todo.length; i++) {
    try {
      var resp = await fetch(todo[i].url);
      if (resp.ok) {
        var blob = await resp.blob();
        cacheStickerBlob(todo[i].url, blob);
        success++;
      } else { fail++; }
    } catch(e) { fail++; }
    /* 每缓存5个更新一次提示 */
    if ((i + 1) % 5 === 0) {
      console.debug('[StickerCache] progress:', i + 1 + '/' + todo.length);
    }
  }

  _stickerPreloading = false;
  if (fail === 0) {
    showToast('缓存完成：' + success + ' 个表情');
  } else {
    showToast('缓存完成：成功' + success + ' 失败' + fail + '（失败的可能是图床暂时不可用）');
  }
  /* 刷新面板和管理页 */
  try { renderStickerPanel(); } catch(e) {}
  try { renderStickerMgmtPage(); } catch(e) {}
}

/* 表情图片加载失败时的降级处理：替换为文字占位 */
function onStickerImgError(img) {
  var name = img.getAttribute('alt') || img.getAttribute('data-name') || '表情';
  var parent = img.parentElement;
  if (!parent) return;
  parent.innerHTML = '<div class="mc-sticker-emoji">🖼️</div>';
  var label = parent.querySelector('.mc-sticker-label');
  if (!label) {
    label = document.createElement('div');
    label.className = 'mc-sticker-label';
    parent.appendChild(label);
  }
  label.textContent = name;
}
/* 表情图片加载失败时的降级处理（面板/管理页用，保持名称不变） */
function onStickerPanelImgError(img) {
  var name = img.getAttribute('alt') || img.getAttribute('data-name') || '';
  var parent = img.parentElement;
  if (!parent) return;
  var nameEl = parent.querySelector('.mc-sticker-item-name');
  var nameText = nameEl ? nameEl.textContent : name;
  parent.innerHTML = '<div class="mc-sticker-item-emoji">🖼️</div>' + (nameEl ? '<span class="mc-sticker-item-name">' + nameText + '</span>' : '');
}

function mochiResolveSticker(name) {
  name = String(name || '').trim();
  if (!name) return null;
  var allPacks = MOCHI_STICKER_PACKS.slice();
  var cps = config.customStickerPacks || [];
  for (var cp = 0; cp < cps.length; cp++) { allPacks.push(cps[cp]); }
  for (var i = 0; i < allPacks.length; i++) {
    var items = allPacks[i].items || [];
    for (var j = 0; j < items.length; j++) {
      if (items[j].name === name) {
        var hit = items[j];
        var cached = getCachedStickerUrl(hit.url);
        if (cached) {
          return { name: hit.name, url: cached, emoji: hit.emoji, _origUrl: hit.url };
        }
        return hit;
      }
    }
  }
  return null;
}

/* 渲染表情包管理界面（面板内简易视图，扁平化展示所有自定义标签表情） */
function renderStickerMgmtView() {
  var panel = document.getElementById('stickerPanel');
  if (!panel) return;
  /* 扁平化所有自定义标签的表情用于展示 */
  var items = [];
  var _packs = config.customStickerPacks || [];
  for (var pi = 0; pi < _packs.length; pi++) {
    var _pkItems = _packs[pi].items || [];
    for (var pj = 0; pj < _pkItems.length; pj++) {
      items.push({ name: _pkItems[pj].name, url: _pkItems[pj].url });
    }
  }
  var html = '<div class="mc-sticker-back-bar">';
  html += '<div class="mc-sticker-back" id="stickerBackBtn">← 返回表情包</div>';
  html += '<div class="mc-sticker-tab-close" id="stickerMgmtCloseBtn" title="关闭">✕</div>';
  html += '</div>';
  html += '<div class="mc-sticker-mgmt-view">';
  html += '<div class="mc-sticker-mgmt-title">自定义表情包</div>';
  html += '<div class="mc-sticker-mgmt-desc">支持URL或上传本地图片（本地图片永不丢失）</div>';
  html += '<input class="mc-sticker-mgmt-input" id="customStickerName" type="text" placeholder="名称" maxlength="20" />';
  html += '<input class="mc-sticker-mgmt-input" id="customStickerUrl" type="text" placeholder="图片URL（https://...）" />';
  html += '<div style="display:flex;gap:6px;margin-top:2px;">';
  html += '<button class="mc-sticker-mgmt-btn" id="addCustomStickerBtn" type="button" style="flex:1;">添加URL</button>';
  html += '<button class="mc-sticker-mgmt-btn" type="button" onclick="document.getElementById(\'stickerFileInput\').click()" style="flex:1;background:#2C2C2E;border:0.5px solid #3A3A3C;">上传图片</button>';
  html += '</div>';
  html += '<input type="file" id="stickerFileInput" accept="image/*" style="display:none;" onchange="handleStickerFileUpload(this)" />';
  html += '<div style="font-size:11px;color:#999;margin-top:10px;">批量添加（每行：名称：URL）：</div>';
  html += '<textarea class="mc-sticker-mgmt-input" id="batchStickerInput" rows="6" placeholder="扭捏：https://example.com/1.png&#10;得意：https://example.com/2.png" style="margin-top:2px;resize:none;"></textarea>';
  html += '<div style="display:flex;gap:6px;margin-top:2px;">';
  html += '<button class="mc-sticker-mgmt-btn" id="batchAddStickerBtn" type="button" style="flex:1;">批量导入URL</button>';
  html += '<button class="mc-sticker-mgmt-btn" type="button" onclick="document.getElementById(\'batchStickerFileInput\').click()" style="flex:1;background:#2C2C2E;border:0.5px solid #3A3A3C;">批量上传图片</button>';
  html += '</div>';
  html += '<input type="file" id="batchStickerFileInput" accept="image/*" multiple style="display:none;" onchange="handleBatchStickerFileUpload(this)" />';
  html += '<div style="font-size:11px;color:#999;margin-top:8px;margin-bottom:4px;">已有自定义表情包：</div>';
  if (!items.length) {
    html += '<div class="mc-sticker-empty-mgmt">暂无自定义表情包</div>';
  } else {
    html += '<div class="mc-sticker-mgmt-list">';
    for (var i = 0; i < items.length; i++) {
      html += '<div class="mc-sticker-mgmt-item">';
      html += '<img src="' + escapeHtml(items[i].url) + '" alt="' + escapeHtml(items[i].name) + '" loading="lazy" onerror="this.style.opacity=0.3" />';
      html += '<span class="mc-mgmt-name">' + escapeHtml(items[i].name) + '</span>';
      html += '<button class="mc-mgmt-del" data-rename-sticker="' + i + '" type="button" title="重命名" style="background:#07C160;font-size:10px;top:auto;bottom:-4px;">✎</button>';
      html += '<button class="mc-mgmt-del" data-del-sticker="' + i + '" type="button">×</button>';
      html += '</div>';
    }
    html += '</div>';
  }
  html += '</div>';
  panel.innerHTML = html;
  /* 绑定事件 */
  var backBtn = document.getElementById('stickerBackBtn');
  if (backBtn) backBtn.addEventListener('click', function() {
    mochiStickerManageMode = false;
    renderStickerPanel();
  });
  var mgmtCloseBtn = document.getElementById('stickerMgmtCloseBtn');
  if (mgmtCloseBtn) mgmtCloseBtn.addEventListener('click', function() {
    mochiStickerManageMode = false;
    closeStickerPanel();
    var input = document.getElementById('chatInput');
    if (input) input.focus();
  });
  var addBtn = _findById('addCustomStickerBtn');
  if (addBtn) addBtn.addEventListener('click', addCustomSticker);
  var batchBtn = _findById('batchAddStickerBtn');
  if (batchBtn) batchBtn.addEventListener('click', batchAddStickers);
  panel.querySelectorAll('[data-del-sticker]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var flatIdx = parseInt(btn.getAttribute('data-del-sticker'));
      /* 在所有自定义标签中找到对应的表情并删除 */
      var packs = config.customStickerPacks || [];
      var counter = 0;
      for (var pi = 0; pi < packs.length; pi++) {
        var pkItems = packs[pi].items || [];
        if (flatIdx < counter + pkItems.length) {
          var realIdx = flatIdx - counter;
          pkItems.splice(realIdx, 1);
          Store.set('config', config);
          renderStickerMgmtView();
          showToast('已删除。');
          return;
        }
        counter += pkItems.length;
      }
    });
  });
  panel.querySelectorAll('[data-rename-sticker]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var flatIdx = parseInt(btn.getAttribute('data-rename-sticker'));
      /* 在所有自定义标签中找到对应的表情并重命名 */
      var packs = config.customStickerPacks || [];
      var counter = 0;
      for (var pi = 0; pi < packs.length; pi++) {
        var pkItems = packs[pi].items || [];
        if (flatIdx < counter + pkItems.length) {
          var realIdx = flatIdx - counter;
          var oldName = pkItems[realIdx].name || '';
          var newName = prompt('输入新的表情名称：', oldName);
          if (newName === null) return;
          newName = newName.trim();
          if (!newName) { showToast('名称不能为空'); return; }
          if (newName.length > 20) newName = newName.substring(0, 20);
          pkItems[realIdx].name = newName;
          Store.set('config', config);
          renderStickerMgmtView();
          try { renderStickerPanel(); } catch(e) {}
          showToast('已重命名为：' + newName);
          return;
        }
        counter += pkItems.length;
      }
    });
  });
}

/* 渲染表情包面板 */
function renderStickerPanel() {
  var panel = document.getElementById('stickerPanel');
  if (!panel) return;
  var allPacks = MOCHI_STICKER_PACKS.slice();
  /* 自定义标签页：每个自定义标签独立显示为一个tab */
  var customPacks = config.customStickerPacks || [];
  for (var cp = 0; cp < customPacks.length; cp++) {
    allPacks.push(customPacks[cp]);
  }
  var tabsHtml = '<div class="mc-sticker-tabs">';
  for (var i = 0; i < allPacks.length; i++) {
    var p = allPacks[i];
    tabsHtml += '<button class="mc-sticker-tab' + (p.id === mochiStickerActiveTab ? ' active' : '') + '" data-sticker-tab="' + escapeHtml(p.id) + '" type="button">' + escapeHtml(p.name) + '</button>';
  }
  /* 管理按钮（设置图标）—跳转到独立管理页面 */
  tabsHtml += '<div class="mc-sticker-tab-mgmt" id="stickerMgmtBtn" title="表情管理">⚙</div>';
  /* 关闭按钮 */
  tabsHtml += '<div class="mc-sticker-tab-close" id="stickerCloseBtn" title="关闭">✕</div>';
  tabsHtml += '</div>';
  var activePack = null;
  for (var j = 0; j < allPacks.length; j++) {
    if (allPacks[j].id === mochiStickerActiveTab) { activePack = allPacks[j]; break; }
  }
  if (!activePack && allPacks.length) activePack = allPacks[0];
  var gridHtml = '<div class="mc-sticker-grid">';
  if (activePack && activePack.items && activePack.items.length > 0) {
    for (var k = 0; k < activePack.items.length; k++) {
      var item = activePack.items[k];
      gridHtml += '<div class="mc-sticker-item" data-sticker-name="' + escapeHtml(item.name) + '">';
      if (item.url) {
        var _imgUrl = getCachedStickerUrl(item.url) || item.url;
        gridHtml += '<img src="' + escapeHtml(_imgUrl) + '" alt="' + escapeHtml(item.name) + '" loading="lazy" onerror="onStickerPanelImgError(this)" onload="onStickerImgLoad(this)" />';
      } else {
        gridHtml += '<div class="mc-sticker-item-emoji">' + (item.emoji || '❓') + '</div>';
      }
      gridHtml += '<span class="mc-sticker-item-name">' + escapeHtml(item.name) + '</span></div>';
    }
  } else if (activePack && !activePack.items.length) {
    /* 表情包为空时显示上传引导 */
    gridHtml += '<div style="grid-column:1/-1;text-align:center;padding:30px 10px;">';
    gridHtml += '<div style="font-size:48px;margin-bottom:8px;">📭</div>';
    gridHtml += '<div style="font-size:14px;color:#8E8E93;margin-bottom:4px;">还没有表情</div>';
    gridHtml += '<div style="font-size:12px;color:#8E8E93;margin-bottom:12px;">点击右上角 ⚙ 上传表情图片</div>';
    gridHtml += '<div class="mc-sticker-add-item" id="stickerAddBtn" style="margin:0 auto;">';
    gridHtml += '<div class="mc-sticker-add-box">+</div>';
    gridHtml += '<span class="mc-sticker-item-name">添加表情</span></div>';
    gridHtml += '</div>';
  }
  /* 自定义标签页：显示添加按钮—跳转到独立管理页面 */
  if (activePack && isCustomPack(activePack.id)) {
    gridHtml += '<div class="mc-sticker-add-item" id="stickerAddBtn-2">';
    gridHtml += '<div class="mc-sticker-add-box">+</div>';
    gridHtml += '<span class="mc-sticker-item-name">添加</span></div>';
  }
  gridHtml += '</div>';
  panel.innerHTML = tabsHtml + gridHtml;
  /* 绑定标签切换 */
  panel.querySelectorAll('[data-sticker-tab]').forEach(function(btn) {
    btn.addEventListener('click', function(e) {
      e.stopPropagation();
      mochiStickerActiveTab = btn.getAttribute('data-sticker-tab');
      renderStickerPanel();
    });
  });
  /* 绑定管理按钮—跳转到独立管理页面（显示标签列表） */
  var mgmtBtn = document.getElementById('stickerMgmtBtn');
  if (mgmtBtn) mgmtBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    _currentManagePackId = null;
    closeStickerPanel();
    navigateTo('view-sticker-mgmt');
    renderStickerMgmtPage();
  });
  /* 绑定关闭按钮 */
  var closeBtn = document.getElementById('stickerCloseBtn');
  if (closeBtn) closeBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    closeStickerPanel();
    var input = document.getElementById('chatInput');
    if (input) input.focus();
  });
  /* 绑定添加按钮—跳转到独立管理页面（定位到当前标签） */
  var addBtn = _findById('stickerAddBtn');
  if (addBtn) addBtn.addEventListener('click', function(e) {
    e.stopPropagation();
    if (activePack && isCustomPack(activePack.id)) {
      _currentManagePackId = activePack.id;
    }
    closeStickerPanel();
    navigateTo('view-sticker-mgmt');
    renderStickerMgmtPage();
  });
  /* 绑定表情点击发送 */
  panel.querySelectorAll('[data-sticker-name]').forEach(function(el) {
    el.addEventListener('click', function(e) {
      e.stopPropagation();
      var name = el.getAttribute('data-sticker-name');
      sendSticker(name);
    });
  });
}

function toggleStickerPanel() {
  var panel = document.getElementById('stickerPanel');
  if (!panel) return;
  closeChatPlusMenu();
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
    panel.style.display = 'none';
    var input = document.getElementById('chatInput');
    if (input) input.focus();
  } else {
    /* 面板定位在输入栏上方 */
    var inputBar = document.getElementById('chatInputBar');
    if (inputBar) {
      panel.style.bottom = inputBar.offsetHeight + 'px';
    }
    mochiStickerManageMode = false;
    renderStickerPanel();
    panel.classList.add('open');
    panel.style.display = 'flex';
  }
}

function closeStickerPanel() {
  var panel = document.getElementById('stickerPanel');
  if (panel) {
    panel.classList.remove('open');
    panel.style.display = 'none';
  }
  mochiStickerManageMode = false;
}

/* 点击外部关闭表情包面板 */
document.addEventListener('click', function(e) {
  var panel = document.getElementById('stickerPanel');
  if (!panel || !panel.classList.contains('open')) return;
  /* 如果点击不在面板内，且不是表情包按钮，则关闭 */
  if (!panel.contains(e.target) && !e.target.closest('.wx-sticker-btn')) {
    closeStickerPanel();
  }
});

/* 发送表情包（以"表情包-名称"格式发送，AI也能理解） */
function sendSticker(name) {
  var text = '表情包-' + name;
  config.chatHistory.push({ role: 'user', content: text, time: Date.now() });
  syncCharHistory();
  Store.set('config', config);
  renderMessages();
  scrollChatToBottom();
  closeStickerPanel();
  /* 返回文字输入 */
  var input = document.getElementById('chatInput');
  if (input) { input.focus(); }
  /* 不自动回复：发送后等用户点回复键 */
  showManualReplyBtn();
}

/* 兼容旧调用 */
function closeEmojiPanel() { closeStickerPanel(); }

/* ===== 独立表情管理页面（从微信"我"进入，支持多标签管理） ===== */
function renderStickerMgmtPage() {
  var el = document.getElementById('stickerMgmtScroll');
  if (!el) return;
  if (!config.customStickerPacks) config.customStickerPacks = [];
  var html = '<div style="padding:16px 14px 40px;">';
  /* 我的表情包预览（内置）—已清空，仅显示提示 */
  var hasBuiltin = false;
  for (var bi = 0; bi < MOCHI_STICKER_PACKS.length; bi++) {
    if (MOCHI_STICKER_PACKS[bi].items && MOCHI_STICKER_PACKS[bi].items.length) { hasBuiltin = true; break; }
  }
  if (hasBuiltin) {
    html += '<div style="margin-bottom:20px;">';
    html += '<div style="font-size:15px;font-weight:600;color:#fff;margin-bottom:10px;">我的表情</div>';
    html += '<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;">';
    for (var i = 0; i < MOCHI_STICKER_PACKS.length; i++) {
      var pack = MOCHI_STICKER_PACKS[i];
      if (pack.items && pack.items.length) {
        html += '<div style="text-align:center;">';
        var _previewUrl = getCachedStickerUrl(pack.items[0].url || '') || pack.items[0].url || '';
        html += '<img src="' + escapeHtml(_previewUrl) + '" style="width:56px;height:56px;object-fit:contain;border-radius:8px;background:#2C2C2E;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'"  alt=""/><div style="width:56px;height:56px;display:none;align-items:center;justify-content:center;font-size:24px;background:#2C2C2E;border-radius:8px;">🖼️</div>';
        html += '<div style="font-size:10px;color:#8E8E93;margin-top:3px;">' + escapeHtml(pack.name) + '</div>';
        html += '</div>';
      }
    }
    html += '</div></div>';
    /* 一键缓存所有表情 */
    html += '<div style="background:#2C2C2E;border-radius:10px;padding:12px 14px;margin-bottom:16px;">';
    html += '<div style="font-size:13px;color:#fff;font-weight:500;margin-bottom:4px;">本地缓存表情</div>';
    html += '<div style="font-size:11px;color:#8E8E93;margin-bottom:8px;line-height:1.5;">将所有表情图片下载到本地，即使图床挂掉也能正常显示</div>';
    html += '<button type="button" onclick="preloadAllStickers()" style="padding:8px 16px;border:none;border-radius:8px;background:#07C160;color:#fff;font-size:13px;cursor:pointer;font-family:inherit;">一键缓存全部表情</button>';
    html += '</div>';
  } else {
    html += '<div style="background:#2C2C2E;border-radius:10px;padding:16px 14px;margin-bottom:16px;text-align:center;">';
    html += '<div style="font-size:32px;margin-bottom:8px;">表情包</div>';
    html += '<div style="font-size:14px;color:#fff;font-weight:500;margin-bottom:4px;">上传你的表情图片</div>';
    html += '<div style="font-size:12px;color:#8E8E93;line-height:1.6;">支持单张/批量上传本地图片，图片会转为本地数据存储，永不丢失</div>';
    html += '</div>';
  }
  /* 自定义表情标签管理 */
  html += '<div style="border-top:0.5px solid #3A3A3C;padding-top:16px;">';
  if (_currentManagePackId) {
    /* === 标签详情视图 === */
    var curPack = getCustomPackById(_currentManagePackId);
    if (!curPack) {
      /* 标签不存在，返回列表 */
      _currentManagePackId = null;
      renderStickerMgmtPage();
      return;
    }
    html += '<div style="margin-bottom:14px;">';
    html += '<span style="color:#07C160;font-size:14px;cursor:pointer;" onclick="backToPackList()">← 返回标签列表</span>';
    html += '</div>';
    html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">';
    html += '<div style="font-size:15px;font-weight:600;color:#fff;">' + escapeHtml(curPack.name) + '</div>';
    html += '<button type="button" onclick="renameStickerPack(\'' + escapeHtml(curPack.id) + '\')" title="重命名标签" style="border:none;border-radius:6px;background:#2C2C2E;color:#07C160;font-size:12px;cursor:pointer;padding:3px 8px;font-family:inherit;">✎ 重命名</button>';
    html += '</div>';
    html += '<div style="font-size:12px;color:#8E8E93;margin-bottom:12px;">共 ' + (curPack.items ? curPack.items.length : 0) + ' 个表情</div>';
    /* 添加单个表情 */
    html += '<div style="font-size:13px;color:#8E8E93;margin-bottom:4px;">添加表情</div>';
    html += '<input class="mc-sticker-mgmt-input" id="customStickerName-2" type="text" placeholder="名称" maxlength="20" />';
    html += '<input class="mc-sticker-mgmt-input" id="customStickerUrl-2" type="text" placeholder="图片URL（https://...）" />';
    html += '<div style="display:flex;gap:6px;margin-top:2px;">';
    html += '<button class="mc-sticker-mgmt-btn" id="addCustomStickerBtn-2" type="button" onclick="addCustomSticker()" style="flex:1;">添加URL</button>';
    html += '<button class="mc-sticker-mgmt-btn" type="button" onclick="document.getElementById(\'stickerFileInput-2\').click()" style="flex:1;background:#2C2C2E;border:0.5px solid #3A3A3C;">上传本地图片</button>';
    html += '</div>';
    html += '<input type="file" id="stickerFileInput-2" accept="image/*" style="display:none;" onchange="handleStickerFileUpload(this)" />';
    /* 批量添加 */
    html += '<div style="font-size:11px;color:#999;margin-top:12px;margin-bottom:4px;">批量添加（每行：名称：URL）：</div>';
    html += '<textarea class="mc-sticker-mgmt-input" id="batchStickerInput-2" rows="6" placeholder="扭捏：https://example.com/1.png&#10;得意：https://example.com/2.png" style="margin-top:2px;resize:none;"></textarea>';
    html += '<button class="mc-sticker-mgmt-btn" id="batchAddStickerBtn-2" type="button" onclick="batchAddStickers()" style="margin-top:2px;">批量导入URL</button>';
    html += '<button class="mc-sticker-mgmt-btn" type="button" onclick="document.getElementById(\'batchStickerFileInput-2\').click()" style="margin-top:2px;background:#2C2C2E;border:0.5px solid #3A3A3C;">批量上传本地图片</button>';
    html += '<input type="file" id="batchStickerFileInput-2" accept="image/*" multiple style="display:none;" onchange="handleBatchStickerFileUpload(this)" />';
    /* 已有表情列表 */
    html += '<div style="font-size:13px;color:#8E8E93;margin-top:16px;margin-bottom:8px;">已有表情：</div>';
    var items = curPack.items || [];
    if (!items.length) {
      html += '<div style="text-align:center;padding:20px 0;font-size:13px;color:#8E8E93;">暂无表情，快添加吧</div>';
    } else {
      html += '<div style="display:grid;grid-template-columns:repeat(auto-fill, minmax(72px, 1fr));gap:8px;">';
      for (var j = 0; j < items.length; j++) {
        var s = items[j];
        html += '<div style="position:relative;text-align:center;">';
        html += '<img src="' + escapeHtml(s.url) + '" alt="' + escapeHtml(s.name) + '" loading="lazy" style="width:56px;height:56px;object-fit:contain;border-radius:6px;background:#2C2C2E;" onerror="this.style.display=\'none\';this.parentElement.querySelector(\'span\').style.marginTop=\'0\'" />';
        html += '<span style="font-size:10px;color:#8E8E93;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(s.name) + '</span>';
        html += '<button type="button" onclick="renameSticker(\'' + escapeHtml(curPack.id) + '\',' + j + ')" title="重命名" style="position:absolute;top:-4px;left:-4px;width:18px;height:18px;border:none;border-radius:50%;background:#07C160;color:#fff;font-size:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;">✎</button>';
        html += '<button type="button" onclick="deleteCustomSticker(\'' + escapeHtml(curPack.id) + '\',' + j + ')" title="删除" style="position:absolute;top:-4px;right:-4px;width:18px;height:18px;border:none;border-radius:50%;background:#FA5151;color:#fff;font-size:11px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;">×</button>';
        html += '</div>';
      }
      html += '</div>';
    }
    /* 删除整个标签 */
    html += '<div style="margin-top:24px;text-align:center;">';
    html += '<button type="button" onclick="deleteStickerPackById(\'' + escapeHtml(curPack.id) + '\')" style="padding:8px 20px;border:none;border-radius:8px;background:#FA5151;color:#fff;font-size:13px;cursor:pointer;">删除此标签</button>';
    html += '</div>';
  } else {
    /* === 标签列表视图 === */
    html += '<div style="font-size:15px;font-weight:600;color:#fff;margin-bottom:6px;">自定义表情标签</div>';
    html += '<div style="font-size:12px;color:#8E8E93;margin-bottom:12px;">创建多个标签分类管理你的表情包</div>';
    /* 新建标签 */
    html += '<div style="display:flex;gap:6px;margin-bottom:16px;">';
    html += '<input class="mc-sticker-mgmt-input" id="newPackNameInput" type="text" placeholder="输入标签名称（如：搞怪、可爱）" maxlength="12" style="flex:1;margin-bottom:0;" />';
    html += '<button class="mc-sticker-mgmt-btn" type="button" onclick="createStickerPackFromInput()" style="margin-bottom:0;white-space:nowrap;">新建标签</button>';
    html += '</div>';
    /* 标签列表 */
    var packs = config.customStickerPacks;
    if (!packs.length) {
      html += '<div style="text-align:center;padding:30px 0;font-size:13px;color:#8E8E93;">暂无自定义标签，点击上方新建</div>';
    } else {
      for (var k = 0; k < packs.length; k++) {
        var pk = packs[k];
        var pkItems = pk.items || [];
        html += '<div onclick="enterStickerPack(\'' + escapeHtml(pk.id) + '\')" style="background:#2C2C2E;border-radius:10px;padding:12px;margin-bottom:10px;cursor:pointer;display:flex;align-items:center;gap:10px;">';
        /* 预览图 */
        if (pkItems.length) {
          html += '<img src="' + escapeHtml(pkItems[0].url || '') + '" style="width:44px;height:44px;object-fit:contain;border-radius:6px;background:#3A3A3C;flex-shrink:0;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'"  alt=""/><div style="width:44px;height:44px;display:none;align-items:center;justify-content:center;font-size:20px;background:#3A3A3C;border-radius:6px;flex-shrink:0;">🖼️</div>';
        } else {
          html += '<div style="width:44px;height:44px;border-radius:6px;background:#3A3A3C;flex-shrink:0;"></div>';
        }
        html += '<div style="flex:1;min-width:0;">';
        html += '<div style="font-size:14px;color:#fff;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(pk.name) + '</div>';
        html += '<div style="font-size:11px;color:#8E8E93;margin-top:2px;">' + pkItems.length + ' 个表情</div>';
        html += '</div>';
        html += '<button type="button" onclick="event.stopPropagation();renameStickerPack(\'' + escapeHtml(pk.id) + '\')" title="重命名标签" style="border:none;border-radius:6px;background:#3A3A3C;color:#07C160;font-size:12px;cursor:pointer;padding:4px 8px;flex-shrink:0;font-family:inherit;">✎</button>';
        html += '<div style="color:#8E8E93;font-size:18px;flex-shrink:0;">&rsaquo;</div>';
        html += '</div>';
      }
    }
  }
  html += '</div>';
  html += '</div>';
  el.innerHTML = html;
}

/* 进入指定标签的管理详情 */
function enterStickerPack(packId) {
  _currentManagePackId = packId;
  renderStickerMgmtPage();
}

/* 返回标签列表 */
function backToPackList() {
  _currentManagePackId = null;
  renderStickerMgmtPage();
}

/* 从输入框创建新标签 */
function createStickerPackFromInput() {
  var input = document.getElementById('newPackNameInput');
  if (!input) return;
  var name = (input.value || '').trim();
  if (!name) { showToast('请输入标签名称。'); return; }
  /* 检查重名 */
  var existing = config.customStickerPacks || [];
  for (var i = 0; i < existing.length; i++) {
    if (existing[i].name === name) { showToast('标签名已存在，请换一个。'); return; }
  }
  var newPack = createCustomStickerPack(name);
  _currentManagePackId = newPack.id;
  renderStickerMgmtPage();
  showToast('已创建标签：' + name);
}

/* 删除整个标签（连同表情） */
function deleteStickerPackById(packId) {
  var pack = getCustomPackById(packId);
  if (!pack) return;
  var count = (pack.items || []).length;
  if (!confirm('确定删除标签「' + pack.name + '」' + (count ? '及其 ' + count + ' 个表情' : '') + '？此操作不可撤销。')) return;
  deleteCustomStickerPack(packId);
  _currentManagePackId = null;
  Store.set('config', config);
  renderStickerMgmtPage();
  showToast('已删除标签。');
}

/* 从指定标签删除单个表情 */
function deleteCustomSticker(packId, idx) {
  var pack = getCustomPackById(packId);
  if (!pack || !pack.items) return;
  if (idx < 0 || idx >= pack.items.length) return;
  pack.items.splice(idx, 1);
  Store.set('config', config);
  renderStickerMgmtPage();
  showToast('已删除。');
}

/* ===== 自定义表情包管理（往当前标签添加） ===== */
/* 重命名单个表情 */
function renameSticker(packId, idx) {
  var pack = getCustomPackById(packId);
  if (!pack || !pack.items) return;
  if (idx < 0 || idx >= pack.items.length) return;
  var oldName = pack.items[idx].name || '';
  var newName = prompt('输入新的表情名称：', oldName);
  if (newName === null) return;
  newName = newName.trim();
  if (!newName) { showToast('名称不能为空'); return; }
  if (newName.length > 20) newName = newName.substring(0, 20);
  pack.items[idx].name = newName;
  Store.set('config', config);
  renderStickerMgmtPage();
  try { renderStickerPanel(); } catch(e) {}
  showToast('已重命名为：' + newName);
}

/* 重命名表情标签（整个包） */
function renameStickerPack(packId) {
  var pack = getCustomPackById(packId);
  if (!pack) return;
  var oldName = pack.name || '';
  var newName = prompt('输入新的标签名称：', oldName);
  if (newName === null) return;
  newName = newName.trim();
  if (!newName) { showToast('名称不能为空'); return; }
  if (newName.length > 12) newName = newName.substring(0, 12);
  /* 检查重名 */
  var existing = config.customStickerPacks || [];
  for (var i = 0; i < existing.length; i++) {
    if (existing[i].id !== packId && existing[i].name === newName) {
      showToast('标签名已存在，请换一个。');
      return;
    }
  }
  pack.name = newName;
  Store.set('config', config);
  renderStickerMgmtPage();
  try { renderStickerPanel(); } catch(e) {}
  showToast('已重命名标签为：' + newName);
}

/* ===== 自定义表情包管理（往当前标签添加） ===== */
function addCustomSticker() {
  var nameEl = _findById('customStickerName');
  var urlEl = _findById('customStickerUrl');
  if (!nameEl || !urlEl) return;
  var name = (nameEl.value || '').trim();
  var url = (urlEl.value || '').trim();
  if (!name || !url) { showToast('请填写名称和URL。'); return; }
  /* 确定目标标签：优先使用当前管理标签，否则取第一个自定义标签 */
  var targetPackId = _currentManagePackId;
  if (!targetPackId) {
    var packs = config.customStickerPacks || [];
    if (packs.length) {
      targetPackId = packs[0].id;
    } else {
      var newPack = createCustomStickerPack('自定义');
      targetPackId = newPack.id;
      _currentManagePackId = targetPackId;
    }
  }
  addStickerToPack(targetPackId, name, url);
  nameEl.value = '';
  urlEl.value = '';
  /* 根据当前所在页面刷新对应视图 */
  if (document.getElementById('view-sticker-mgmt') && document.getElementById('view-sticker-mgmt').classList.contains('active')) {
    renderStickerMgmtPage();
  } else {
    renderStickerMgmtView();
  }
  showToast('已添加：' + name);
}

function batchAddStickers() {
  var ta = _findById('batchStickerInput');
  if (!ta) return;
  var text = (ta.value || '').trim();
  if (!text) { showToast('请输入批量内容。'); return; }
  /* 确定目标标签 */
  var targetPackId = _currentManagePackId;
  if (!targetPackId) {
    var packs = config.customStickerPacks || [];
    if (packs.length) {
      targetPackId = packs[0].id;
    } else {
      var newPack = createCustomStickerPack('自定义');
      targetPackId = newPack.id;
      _currentManagePackId = targetPackId;
    }
  }
  var lines = text.split('\n');
  var count = 0;
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    if (!line) continue;
    /* 支持：| 、 ：（中文冒号）、:（英文冒号）作为分隔符 */
    var sep = -1;
    var seps = ['|', '：', ':'];
    for (var s = 0; s < seps.length; s++) {
      var idx = line.indexOf(seps[s]);
      if (idx > 0 && (sep < 0 || idx < sep)) sep = idx;
    }
    if (sep > 0) {
      var n = line.substring(0, sep).trim();
      var u = line.substring(sep + 1).trim();
      if (n && u) {
        addStickerToPack(targetPackId, n, u);
        count++;
      }
    }
  }
  ta.value = '';
  /* 根据当前所在页面刷新对应视图 */
  if (document.getElementById('view-sticker-mgmt') && document.getElementById('view-sticker-mgmt').classList.contains('active')) {
    renderStickerMgmtPage();
  } else {
    renderStickerMgmtView();
  }
  showToast('已导入 ' + count + ' 个表情。');
}

// ===== 图片预览 =====
function previewImage(src) {
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:absolute;inset:0;background:rgba(0,0,0,0.9);z-index:300;display:flex;align-items:center;justify-content:center;border-radius:42px;cursor:pointer';
  overlay.onclick = () => overlay.remove();
  const img = document.createElement('img');
  img.src = src;
  img.style.cssText = 'max-width:90%;max-height:90%;border-radius:8px';
  overlay.appendChild(img);
  document.querySelector('.phone-screen').appendChild(overlay);
}

// ===== 红包详情 =====
function openRedPacketDetail(el) {
  showToast('红包已发送');
}

// ===== 发送图片 =====
function sendImage() {
  closeChatPlusMenu();
  document.getElementById('imageFileInput').click();
}

// ===== 自然对话换头像检测 =====
// 用户发图片（普通image类型）+ 说换情头相关的话 → AI自然回复 → 检测AI是否同意 → 同意则自动换头像
// 这是基于自然对话的，没有专门的按钮或消息类型
/* 检测AI回复中的 [accept_money] 或 [return_money] 标记，处理红包/转账的收款或退回 */
function checkMoneyActionFromReply(aiReply, optCharIdx) {
  try {
    if (!aiReply) return;
    var charIdx = (typeof optCharIdx === 'number') ? optCharIdx : currentCharIdx;
    var char = config.characters && config.characters[charIdx];
    if (!char) return;
    var charName = (char.alias || char.nickname || char.name || '对方');
    var acceptMatch = aiReply.match(/\[accept_money\]/i);
    var returnMatch = aiReply.match(/\[return_money\]/i);
    if (!acceptMatch && !returnMatch) return;
    var isAccept = !!acceptMatch;
    var hist = config.chatHistory || [];
    for (var i = hist.length - 1; i >= 0; i--) {
      var msg = hist[i];
      if (msg.role !== 'user') continue;
      if (msg.type !== 'redpacket' && msg.type !== 'transfer') continue;
      try {
        var data = JSON.parse((msg.content || '').replace(/\[(redpacket|transfer)\]/, ''));
        if (data.status && data.status !== 'pending') continue;
        var amount = data.amount || 0;
        var moneyType = msg.type === 'redpacket' ? '红包' : '转账';
        if (isAccept) {
          data.status = 'accepted';
          msg.content = '[' + msg.type + ']' + JSON.stringify(data);
          hist.push({ role: 'assistant', content: '[receipt]' + JSON.stringify({ type: msg.type, amount: amount, from: charName }), time: Date.now(), type: 'receipt' });
        } else {
          data.status = 'returned';
          msg.content = '[' + msg.type + ']' + JSON.stringify(data);
          if (!config.user) config.user = { wallet: 0 };
          if (config.user.wallet === undefined) config.user.wallet = 0;
          config.user.wallet += amount;
          if (!config.user.walletHistory) config.user.walletHistory = [];
          config.user.walletHistory.push({ type: '退回' + moneyType, amount: amount, time: Date.now(), from: charName });
          hist.push({ role: 'assistant', content: '[return_money]' + JSON.stringify({ type: msg.type, amount: amount, from: charName }), time: Date.now(), type: 'return_money' });
        }
        syncCharHistory();
        Store.set('config', config);
        break;
      } catch(e) { continue; }
    }
  } catch(e) { console.warn('[checkMoneyAction] error:', e); }
}

/* 从AI回复文本中移除 [accept_money] 和 [return_money] 标记（不显示给用户） */
function stripMoneyActionTag(text) {
  if (!text) return text;
  return text.replace(/\s*\[(accept_money|return_money)\]\s*/gi, '').trim();
}

/* 检测AI回复中的 [nickname:新网名] 标记，自动更新角色微信网名 */
function checkNicknameChangeFromReply(aiReply, optCharIdx) {
  try {
    if (!aiReply) return;
    var charIdx = (typeof optCharIdx === 'number') ? optCharIdx : currentCharIdx;
    var char = config.characters && config.characters[charIdx];
    if (!char) return;
    // 匹配 [nickname:xxx] 或 [nickname：xxx]
    var m = aiReply.match(/\[nickname[:\uff1a]\s*([^\]]+?)\s*\]/i);
    if (!m) return;
    var newNick = (m[1] || '').trim();
    if (!newNick || newNick.length > 30) return; // 网名不超过30字
    var oldNick = char.nickname || char.name || '';
    if (newNick === oldNick) return; // 没变化
    // 更新网名
    char.nickname = newNick;
    // 角色态下对方若是“用户人设镜像”，其微信网名要落到真实用户账号（镜像本身不持久化）
    if (char._waMirror && char._mirrorOf !== undefined) {
      try { var _mirU = (typeof waFindUserAcc === 'function') ? waFindUserAcc(char._mirrorOf) : null; if (_mirU) _mirU.wxName = newNick; } catch (me) {}
    }
    // 同步到 config.role
    if (config.role) config.role.nickname = newNick;
    Store.set('config', config);
    // 更新聊天标题
    if (typeof currentCharIdx === 'number' && charIdx === currentCharIdx) {
      var _t = document.getElementById('chatTitle');
      if (_t) _t.textContent = char.alias || newNick;
    }
    // 刷新聊天列表
    if (typeof renderChatList === 'function') renderChatList();
    if (typeof renderChatInfo === 'function') renderChatInfo();
    showToast((char.alias || char.nickname || char.name) + ' 更换了网名：' + newNick);
  } catch(e) {
    console.warn('[checkNicknameChange] error:', e);
  }
}

/* 从AI回复文本中移除 [nickname:xxx] 标记（不显示给用户） */
function stripNicknameTag(text) {
  if (!text) return text;
  return text.replace(/\s*\[nickname[:\uff1a]\s*[^\]]+?\s*\]\s*/gi, '').trim();
}

/* 判断一行去掉改名/金钱/无效表情包等标记后是否没有任何可见内容（有效表情包算有内容） */
function isEmptyMarkerLine(rawLine) {
  try {
    var t = String(rawLine == null ? '' : rawLine);
    t = t.replace(/\s*\[nickname[:\uff1a]\s*[^\]]*?\s*\]/gi, ' ');
    t = t.replace(/\s*\[moneyaction[:\uff1a]?[^\]]*\]\s*/gi, ' ');
    var hasValid = false;
    t = t.replace(/表情包-([^\s<，。！？、,.!?；;：:"“”‘’\[\]【】()（）]+)/g, function(m, nm) {
      if (typeof mochiResolveSticker === 'function' && mochiResolveSticker(nm.trim())) { hasValid = true; return '表情'; }
      return '';
    });
    t = t.replace(/表情包-[^\n]*/g, '');
    t = t.replace(/<\/?(thinking|miyavoice)>/gi, '');
    if (hasValid) return false;
    return t.replace(/\s/g, '').length === 0;
  } catch(e) { return false; }
}

function checkAvatarChangeFromConversation(aiReply, optCharIdx) {
  try {
    var charIdx = (typeof optCharIdx === 'number') ? optCharIdx : currentCharIdx;
    var hist = config.chatHistory || [];

    // 1. 从最新AI回复往前找：最近的用户图片消息
    var lastUserImageIdx = -1;
    var lastUserImageSrc = '';
    for (var i = hist.length - 1; i >= 0; i--) {
      var m = hist[i];
      if (m.role === 'user' && (m.type === 'image' || m.type === 'couple-avatar')) {
        lastUserImageIdx = i;
        lastUserImageSrc = (m.content || '').replace('[couple-avatar]', '').replace('[image]', '');
        break;
      }
    }
    if (lastUserImageIdx < 0) return; // 没有用户发的图片

    // 2. 检查图片消息前后是否有"换情头/换头像"相关文字
    // 向前看2条消息，向后看2条消息
    var nearbyText = '';
    for (var j = Math.max(0, lastUserImageIdx - 2); j <= Math.min(hist.length - 1, lastUserImageIdx + 2); j++) {
      if (j === lastUserImageIdx) continue;
      var mj = hist[j];
      if (mj.role === 'user') {
        nearbyText += ' ' + ((mj.content || '').replace(/\[[^\]]+\]/g, '').trim());
      }
    }
    // 如果用户没有提到换头像/情头相关，不触发
    // 关键词同时检查用户文字和AI回复文字
    var avatarKeywords = ['换头像', '换情头', '情头', '情侣头像', '头像换', '头像改成', '换个头像', '换一张', '用这个', '这张当', '当头像', '头像', '换上', 'cp头', '情头换', '换换', '新头像', '换一下头像'];
    var hasAvatarIntent = false;
    for (var k = 0; k < avatarKeywords.length; k++) {
      if (nearbyText.indexOf(avatarKeywords[k]) >= 0 || (aiReply || '').indexOf(avatarKeywords[k]) >= 0) {
        hasAvatarIntent = true;
        break;
      }
    }
    if (!hasAvatarIntent) return;

    // 3. 检查是否已经应用过（防止重复）
    for (var l = lastUserImageIdx + 1; l < hist.length; l++) {
      var ml = hist[l];
      if (ml.role === 'system' && ml.content && ml.content.indexOf('已更换头像') >= 0) return;
    }

    // 4. 检测AI回复中的拒绝
    var replyText = (aiReply || '').replace(THINK_CLOSED_RE, '')
                     .replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '')
                     .replace(/<inner_voice[^>]*>[\s\S]*?<\/inner_voice>/gi, '')
                     .trim();
    var rejectPhrases = ['不要换', '别换', '不想换', '不愿意', '不太想换', '还是别', '还是算了', '不太愿意', '拒绝', '算了吧', '不好看', '不喜欢', '不用了'];
    for (var r = 0; r < rejectPhrases.length; r++) {
      if (replyText.indexOf(rejectPhrases[r]) >= 0) return; // 拒绝，不换
    }

    // 5. 检测AI同意
    var agreePhrases = [
      '换好了', '换了', '已经换', '我换', '换上', '换啦', '换咯', '换喽',
      '换好啦', '换好了呀', '换好了哦', '换好了呢',
      '我换好了', '已经换好', '换上了', '换上啦', '已经换上',
      '已换', '换好了哟',
      '好呀', '好哒', '可以换', '换吧', '没问题', '行啊', '好啊', '当然', '同意',
      '可以啊', '可以呀', '当然可以', '当然行',
      '那就换', '答应', '好嘞', '可以哦',
      '好的', '好哦',
      '当然换', '好换', '没意见', '当然没问题',
      '可以', '行吧', '行行', '嗯好', '嗯嗯好', '好呀换', '那就用这个', '用这张', '就用这个',
      '换吧换吧', '好呀那就换', '换呗', '行呀', '可以呢', '好呀可以'
    ];
    var isAgreed = false;
    for (var p = 0; p < agreePhrases.length; p++) {
      if (replyText.indexOf(agreePhrases[p]) >= 0) { isAgreed = true; break; }
    }

    // 6. 同意 → 应用头像
    if (isAgreed && lastUserImageSrc) {
      var char = config.characters ? config.characters[charIdx] : null;
      if (char) {
        char.avatar = lastUserImageSrc;
        char.avatarBg = char.avatarBg || '#576B95';
      }
      if (!isGroupChatMode && config.role) {
        config.role.avatar = lastUserImageSrc;
      }
      // 记录已更换，防止重复触发
      config.chatHistory.push({ role: 'system', content: '[系统记录]已更换头像为' + ((config.user && config.user.name) || '用户') + '发送的图片', time: Date.now(), type: 'system-log' });
      Store.set('config', config);

      // 刷新标题栏头像
      if (!isGroupChatMode) {
        var titleAvatar = document.getElementById('chatTitleAvatar');
        if (titleAvatar) {
          titleAvatar.innerHTML = '<img src="' + lastUserImageSrc + '" style="width:100%;height:100%;object-fit:cover" alt="">';
        }
      }
      if (typeof renderChatList === 'function') renderChatList();
      if (typeof renderMessages === 'function') renderMessages();
      showToast('💕 头像已更换');
    }
  } catch(e) {
    console.error('checkAvatarChangeFromConversation error:', e);
  }
}

function handleImageSelect(event) {
  const file = event.target.files[0];
  event.target.value = '';
  if (file) handleImageUpload(file);
}

function handleImageUpload(file) {
  if (!file || !file.type.startsWith('image/')) return;
  var reader = new FileReader();
  reader.onload = function(e) {
    var dataUrl = e.target.result;
    // 压缩图片：限制最大边长1024px，JPEG质量0.8，避免data URL过大导致API请求缓慢
    compressImageForVision(dataUrl, 1024, 0.8, function(compressedUrl) {
      config.chatHistory.push({
        role: 'user',
        content: '[image]' + compressedUrl,
        time: Date.now(),
        type: 'image'
      });
      syncCharHistory();
      Store.set('config', config);
      renderMessages();
      scrollChatToBottom();
      // 不自动回复：等用户点回复键
      showManualReplyBtn();
    });
  };
  reader.readAsDataURL(file);
}

// ===== 用户主动 AI 生图并发送 =====
var _userGenLastUrl = '';
function openUserGenImageModal() {
  try {
    _userGenLastUrl = '';
    var inp = document.getElementById('userGenImagePrompt');
    if (inp) inp.value = '';
    var st = document.getElementById('userGenImageStatus');
    if (st) { st.textContent = ''; st.style.color = '#8E8E93'; }
    var pv = document.getElementById('userGenImagePreview');
    if (pv) pv.style.display = 'none';
    var genBtn = document.getElementById('userGenImageGenBtn');
    var sendBtn = document.getElementById('userGenImageSendBtn');
    if (sendBtn) sendBtn.disabled = true;
    if (genBtn) genBtn.disabled = false;
    closeChatPlusMenu && closeChatPlusMenu();
    openModal('userGenImageModal');
    setTimeout(function () { if (inp) inp.focus(); }, 120);
  } catch (e) { console.warn('openUserGenImageModal', e); }
}
function userGenImageGenerate() {
  var inp = document.getElementById('userGenImagePrompt');
  var st = document.getElementById('userGenImageStatus');
  var genBtn = document.getElementById('userGenImageGenBtn');
  var sendBtn = document.getElementById('userGenImageSendBtn');
  var desc = inp ? inp.value.trim() : '';
  if (!desc) { if (st) { st.textContent = '请先描述想要的画面'; st.style.color = '#FA5151'; } return; }
  if (typeof window.mochiUserGenImage !== 'function') { if (st) { st.textContent = '生图模块未加载'; st.style.color = '#FA5151'; } return; }
  if (st) { st.textContent = '正在生成，请稍候…'; st.style.color = '#8E8E93'; }
  if (genBtn) genBtn.disabled = true;
  if (sendBtn) sendBtn.disabled = true;
  window.mochiUserGenImage(desc).then(function (r) {
    if (genBtn) genBtn.disabled = false;
    if (!r || !r.ok) { if (st) { st.textContent = '生成失败：' + ((r && r.err) || '未知错误'); st.style.color = '#FA5151'; } return; }
    _userGenLastUrl = r.url;
    var pv = document.getElementById('userGenImagePreview');
    var img = document.getElementById('userGenImagePreviewImg');
    if (img) img.src = r.url;
    if (pv) pv.style.display = 'block';
    if (st) { st.textContent = '生成完成，可点「发送」或重新生成'; st.style.color = '#07C160'; }
    if (sendBtn) sendBtn.disabled = false;
  }).catch(function (e) {
    if (genBtn) genBtn.disabled = false;
    if (st) { st.textContent = '生成异常：' + (e && e.message ? e.message : e); st.style.color = '#FA5151'; }
  });
}
function userGenImageSend() {
  if (!_userGenLastUrl) { showToast('请先生成图片'); return; }
  try {
    config.chatHistory.push({ role: 'user', content: '[image]' + _userGenLastUrl, time: Date.now(), type: 'image' });
    syncCharHistory();
    Store.set('config', config);
    renderMessages();
    scrollChatToBottom();
    closeModal('userGenImageModal');
    showManualReplyBtn();
  } catch (e) { console.warn('userGenImageSend', e); showToast('发送失败'); }
}
window.openUserGenImageModal = openUserGenImageModal;
window.userGenImageGenerate = userGenImageGenerate;
window.userGenImageSend = userGenImageSend;

