// ===== 红包功能 =====
function openRedPacket() {
  closeChatPlusMenu();
  document.getElementById('redPacketAmount').value = '';
  document.getElementById('redPacketMessage').value = '';
  document.getElementById('redPacketPreview').textContent = '0.00';
  navigateTo('view-redpacket');
}

function updateRedPacketPreview() {
  const amount = parseFloat(document.getElementById('redPacketAmount').value) || 0;
  document.getElementById('redPacketPreview').textContent = amount.toFixed(2);
}

function sendRedPacket() {
  const amount = parseFloat(document.getElementById('redPacketAmount').value);
  if (isNaN(amount) || amount <= 0) {
    showToast('请输入有效金额');
    return;
  }
  if (!config.user) config.user = { wallet: 0 };
  if (config.user.wallet === undefined) config.user.wallet = 0;
  if (config.user.wallet < amount) {
    showToast('余额不足，请先充值');
    return;
  }

  const message = document.getElementById('redPacketMessage').value || '恭喜发财，大吉大利';

  // 扣款
  config.user.wallet -= amount;
  if (!config.user.walletHistory) config.user.walletHistory = [];
  config.user.walletHistory.push({ type: '发红包', amount: amount, time: Date.now(), to: config.role.name });

  // 发送红包消息（不自动添加收款确认，等待AI决定收或退）
  const redPacketData = { amount: amount, message: message, opened: false, status: 'pending' };
  config.chatHistory.push({ role: 'user', content: '[redpacket]' + JSON.stringify(redPacketData), time: Date.now(), type: 'redpacket' });
  syncCharHistory();
  Store.set('config', config);

  goBack('view-chat');
  renderMessages();
  scrollChatToBottom();

  // 不自动回复：等用户点回复键
  showManualReplyBtn();
  showToast('红包已发送');
}

