  document.getElementById('settingsPageCss').textContent = config.settings.pageCss ? '已自定义' : '默认';
  document.getElementById('settingsBubbleCss').textContent = config.settings.bubbleCss ? '已自定义' : '默认';
  /* 壁纸状态（设置 → 自定义外观：更换壁纸 / 锁屏壁纸） */
