// ===== 线下设置（小熊奶油风） =====
function openOfflineSettings() {
  var overlay = document.getElementById('offlineSettingsOverlay');
  if (!overlay) return;
  // 初始化字数范围
  var wc = config.settings.offlineWordCount || '100-300';
  var parts = wc.split('-');
  document.getElementById('offlineSetWordMin').value = parts[0] || '100';
  document.getElementById('offlineSetWordMax').value = parts[1] || '300';
  // 初始化角色人称
  var charPerson = config.settings.offlineCharPerson || 'third';
  var charTags = document.querySelectorAll('#offlineCharPersonTags .offline-style-tag');
  charTags.forEach(function(tag) {
    tag.classList.toggle('active', tag.getAttribute('data-person') === charPerson);
  });
  // 初始化用户人称
  var userPerson = config.settings.offlineUserPerson || 'second';
  var userTags = document.querySelectorAll('#offlineUserPersonTags .offline-style-tag');
  userTags.forEach(function(tag) {
    tag.classList.toggle('active', tag.getAttribute('data-person') === userPerson);
  });
  // 初始化文风选择
  var currentStyle = config.settings.offlineWritingStyle || '温柔细腻';
  var tags = document.querySelectorAll('#offlineStyleTags .offline-style-tag');
  tags.forEach(function(tag) {
    tag.classList.toggle('active', tag.getAttribute('data-style') === currentStyle);
  });
  // 渲染自定义文风列表
  renderCustomStyleList(currentStyle);
  // 初始化自定义文风补充
  document.getElementById('offlineSetCustomStyle').value = config.settings.offlineCustomStyle || '';
  overlay.classList.add('show');
}

function closeOfflineSettings() {
  var overlay = document.getElementById('offlineSettingsOverlay');
  if (overlay) overlay.classList.remove('show');
}

function selectOfflineStyle(tagEl) {
  var tags = document.querySelectorAll('#offlineStyleTags .offline-style-tag');
  tags.forEach(function(t) { t.classList.remove('active'); });
  tagEl.classList.add('active');
  // 同时取消自定义文风的选中
  var customItems = document.querySelectorAll('#customStyleList .custom-style-item');
  customItems.forEach(function(item) { item.classList.remove('active'); });
}

function selectOfflinePerson(type, tagEl) {
  var containerId = type === 'char' ? '#offlineCharPersonTags' : '#offlineUserPersonTags';
  var tags = document.querySelectorAll(containerId + ' .offline-style-tag');
  tags.forEach(function(t) { t.classList.remove('active'); });
  tagEl.classList.add('active');
}

// ===== 自定义文风CRUD =====
var editingStyleId = null;

function renderCustomStyleList(currentStyle) {
  var container = document.getElementById('customStyleList');
  if (!container) return;
  var styles = config.settings.offlineWritingStyles || [];
  if (styles.length === 0) {
    container.innerHTML = '';
    return;
  }
  var html = '';
  styles.forEach(function(s) {
    var isActive = s.title === currentStyle;
    html += '<div class="custom-style-item' + (isActive ? ' active' : '') + '" onclick="selectCustomStyle(\'' + s.id + '\')">';
    html += '<span>' + escapeHtml(s.title) + '</span>';
    html += '<div class="custom-style-item-actions">';
    html += '<span onclick="event.stopPropagation();editCustomStyle(\'' + s.id + '\')">✏️</span>';
    html += '<span onclick="event.stopPropagation();deleteCustomStyle(\'' + s.id + '\')">🗑️</span>';
    html += '</div></div>';
  });
  container.innerHTML = html;
}

function selectCustomStyle(id) {
  var styles = config.settings.offlineWritingStyles || [];
  var style = styles.find(function(s) { return s.id === id; });
  if (!style) return;
  // 取消预设文风选中
  var tags = document.querySelectorAll('#offlineStyleTags .offline-style-tag');
  tags.forEach(function(t) { t.classList.remove('active'); });
  // 选中自定义文风
  var items = document.querySelectorAll('#customStyleList .custom-style-item');
  items.forEach(function(item) { item.classList.remove('active'); });
  // 标记当前选中的自定义文风
  var targetItem = Array.from(items).find(function(item) {
    return item.getAttribute('onclick') && item.getAttribute('onclick').indexOf(id) >= 0;
  });
  if (targetItem) targetItem.classList.add('active');
  // 暂存选中的自定义文风ID
  window._selectedCustomStyleId = id;
}

function openEditWritingStyle(id) {
  editingStyleId = id || null;
  var overlay = document.getElementById('writingStyleEditOverlay');
  if (!overlay) return;
  if (id) {
    var styles = config.settings.offlineWritingStyles || [];
    var style = styles.find(function(s) { return s.id === id; });
    if (style) {
      document.getElementById('writingStyleEditTitle').textContent = '✏️ 编辑文风';
      document.getElementById('writingStyleTitleInput').value = style.title;
      document.getElementById('writingStyleContentInput').value = style.content;
    }
  } else {
    document.getElementById('writingStyleEditTitle').textContent = '✒️ 新建文风';
    document.getElementById('writingStyleTitleInput').value = '';
    document.getElementById('writingStyleContentInput').value = '';
  }
  overlay.classList.add('show');
}

function closeEditWritingStyle() {
  var overlay = document.getElementById('writingStyleEditOverlay');
  if (overlay) overlay.classList.remove('show');
  editingStyleId = null;
}

function saveWritingStyle() {
  var title = document.getElementById('writingStyleTitleInput').value.trim();
  var content = document.getElementById('writingStyleContentInput').value.trim();
  if (!title) { showToast('请输入文风标题'); return; }
  if (!content) { showToast('请输入文风指令'); return; }
  
  if (!config.settings.offlineWritingStyles) config.settings.offlineWritingStyles = [];
  
  if (editingStyleId) {
    // 编辑现有文风
    var idx = config.settings.offlineWritingStyles.findIndex(function(s) { return s.id === editingStyleId; });
    if (idx >= 0) {
      config.settings.offlineWritingStyles[idx].title = title;
      config.settings.offlineWritingStyles[idx].content = content;
    }
  } else {
    // 新建文风
    config.settings.offlineWritingStyles.push({
      id: 'ws_' + Date.now() + '_' + Math.random().toString(36).slice(2,7),
      title: title,
      content: content
    });
  }
  
  Store.set('config', config);
  closeEditWritingStyle();
  // 刷新自定义文风列表
  var currentStyle = config.settings.offlineWritingStyle || '温柔细腻';
  renderCustomStyleList(currentStyle);
  showToast('文风已保存');
}

function deleteCustomStyle(id) {
  if (!confirm('确定删除这个文风吗？')) return;
  if (!config.settings.offlineWritingStyles) return;
  config.settings.offlineWritingStyles = config.settings.offlineWritingStyles.filter(function(s) { return s.id !== id; });
  // 如果当前选中的文风被删除，重置为默认
  if (window._selectedCustomStyleId === id) {
    window._selectedCustomStyleId = null;
  }
  Store.set('config', config);
  var currentStyle = config.settings.offlineWritingStyle || '温柔细腻';
  renderCustomStyleList(currentStyle);
  showToast('文风已删除');
}

function editCustomStyle(id) {
  openEditWritingStyle(id);
}

function saveOfflineSettings() {
  // 保存字数范围
  var minVal = parseInt(document.getElementById('offlineSetWordMin').value, 10);
  var maxVal = parseInt(document.getElementById('offlineSetWordMax').value, 10);
  if (isNaN(minVal) || minVal < 10) minVal = 10;
  if (isNaN(maxVal) || maxVal < minVal) maxVal = minVal + 100;
  config.settings.offlineWordCount = minVal + '-' + maxVal;
  // 保存角色人称
  var charActiveTag = document.querySelector('#offlineCharPersonTags .offline-style-tag.active');
  config.settings.offlineCharPerson = charActiveTag ? charActiveTag.getAttribute('data-person') : 'third';
  // 保存用户人称
  var userActiveTag = document.querySelector('#offlineUserPersonTags .offline-style-tag.active');
  config.settings.offlineUserPerson = userActiveTag ? userActiveTag.getAttribute('data-person') : 'second';
  // 保存文风（优先自定义文风）
  if (window._selectedCustomStyleId) {
    var styles = config.settings.offlineWritingStyles || [];
    var customStyle = styles.find(function(s) { return s.id === window._selectedCustomStyleId; });
    if (customStyle) {
      config.settings.offlineWritingStyle = customStyle.title;
      config.settings.offlineWritingStyleContent = customStyle.content;
    }
    window._selectedCustomStyleId = null;
  } else {
    var activeTag = document.querySelector('#offlineStyleTags .offline-style-tag.active');
    config.settings.offlineWritingStyle = activeTag ? activeTag.getAttribute('data-style') : '温柔细腻';
    config.settings.offlineWritingStyleContent = '';
  }
  // 保存自定义文风补充
  config.settings.offlineCustomStyle = document.getElementById('offlineSetCustomStyle').value.trim();
  Store.set('config', config);
  closeOfflineSettings();
  showToast('🐻 设置已保存');
}

// ===== API预设管理 =====
function genId() { return 'p_' + Date.now() + '_' + Math.random().toString(36).slice(2,7); }

function renderPresetTabs() {
  const container = document.getElementById('presetTabs');
  let html = '';
  config.presets.forEach(p => {
    const active = p.id === config.activePresetId ? ' active' : '';
    html += `<div class="preset-tab${active}" onclick="selectPreset('${p.id}')">${escapeHtml(p.name)}<span class="del" onclick="event.stopPropagation(); deletePreset('${p.id}')">×</span></div>`;
  });
  html += `<div class="preset-add" onclick="newPreset()">+ 新建预设</div>`;
  container.innerHTML = html;
}

function selectPreset(id) {
  const preset = config.presets.find(p => p.id === id);
  if (!preset) return;
  config.activePresetId = id;
  config.api = { baseUrl: preset.baseUrl, apiKey: preset.apiKey, model: preset.model };
  Store.set('config', config);
  document.getElementById('apiBaseUrl').value = preset.baseUrl;
  document.getElementById('apiKey').value = preset.apiKey;
  document.getElementById('apiModel').value = preset.model;
  renderPresetTabs();
  renderModelList(getVendorPresetModels(preset.baseUrl), preset.model);
  showToast('已切换到预设: ' + preset.name);
}

function newPreset() {
  const baseUrl = document.getElementById('apiBaseUrl').value.trim();
  const apiKey = document.getElementById('apiKey').value.trim();
  const model = document.getElementById('apiModel').value.trim();
  if (!baseUrl || !apiKey) {
    showToast('请先填写地址和密钥');
    return;
  }
  document.getElementById('presetName').focus();
  showToast('填写预设名称后点击保存');
}

function saveAsPreset() {
  const name = document.getElementById('presetName').value.trim();
  const baseUrl = document.getElementById('apiBaseUrl').value.trim();
  const apiKey = document.getElementById('apiKey').value.trim();
  const model = document.getElementById('apiModel').value.trim();
  if (!name) { showToast('请输入预设名称'); return; }
  if (!baseUrl || !apiKey) { showToast('请填写地址和密钥'); return; }

  const preset = { id: genId(), name, baseUrl, apiKey, model };
  config.presets.push(preset);
  config.activePresetId = preset.id;
  Store.set('config', config);
  document.getElementById('presetName').value = '';
  renderPresetTabs();
  showToast('预设「' + name + '」已保存');
}

function deletePreset(id) {
  const preset = config.presets.find(p => p.id === id);
  if (!preset) return;
  config.presets = config.presets.filter(p => p.id !== id);
  if (config.activePresetId === id) config.activePresetId = null;
  Store.set('config', config);
  renderPresetTabs();
  showToast('已删除预设: ' + preset.name);
}

// ===== 拉取模型列表 =====
// ===== 厂商常用模型预设（/models 接口列举不全时兜底；模型ID以MiniMax官方文档2026-08为准）=====
var VENDOR_PRESET_MODELS = {
  minimax: [
    'MiniMax-M3', 'MiniMax-M2.7', 'MiniMax-M2.7-highspeed',
    'MiniMax-M2.5', 'MiniMax-M2.5-highspeed',
    'MiniMax-M2.1', 'MiniMax-M2.1-highspeed', 'MiniMax-M2'
  ]
};
var VENDOR_MODEL_DESC = {
  'MiniMax-M3': '最新旗舰 · 100万上下文',
  'MiniMax-M2.7': '旗舰 · 深度思考',
  'MiniMax-M2.7-highspeed': '旗舰高速版',
  'MiniMax-M2.5': '高性能 · 高性价比',
  'MiniMax-M2.5-highspeed': '高性能高速版',
  'MiniMax-M2.1': '强编程能力',
  'MiniMax-M2.1-highspeed': '编程高速版',
  'MiniMax-M2': '编码 / Agent工作流'
};
function getVendorPresetModels(baseUrl) {
  var u = String(baseUrl || '').toLowerCase();
  if (u.indexOf('minimax') >= 0) return VENDOR_PRESET_MODELS.minimax.slice();
  return [];
}
function mergeVendorModels(baseUrl, online) {
  var presets = getVendorPresetModels(baseUrl);
  var seen = {};
  var out = [];
  presets.forEach(function(m) { if (!seen[m]) { seen[m] = 1; out.push(m); } });
  (online || []).forEach(function(m) { if (!seen[m]) { seen[m] = 1; out.push(m); } });
  return out;
}

async function fetchModels() {
  const baseUrl = document.getElementById('apiBaseUrl').value.trim().replace(/\/+$/, '');
  const apiKey = document.getElementById('apiKey').value.trim();
  if (!baseUrl || !apiKey) {
    showToast('请先填写地址和密钥');
    return;
  }

  const btn = document.getElementById('fetchModelsBtn');
  const list = document.getElementById('modelList');
  btn.textContent = '拉取中...';
  btn.disabled = true;
  list.innerHTML = '<div class="model-empty">正在拉取模型列表...</div>';

  try {
    const res = await fetch(baseUrl + '/models', {
      headers: { 'Authorization': 'Bearer ' + apiKey }
    });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    const models = (data.data || data.models || data || []).map(m => m.id || m.name || m).filter(Boolean);
    if (models.length === 0) throw new Error('未找到模型');
    var _merged = mergeVendorModels(baseUrl, models);
    renderModelList(_merged, document.getElementById('apiModel').value.trim());
    showToast('找到 ' + _merged.length + ' 个模型');
  } catch(err) {
    list.innerHTML = '<div class="model-empty">拉取失败: ' + escapeHtml(err.message) + '<br>可手动输入模型名称</div>';
    showToast('拉取失败，可手动输入');
  } finally {
    btn.textContent = '拉取模型列表';
    btn.disabled = false;
  }
}

function renderModelList(models, selectedModel) {
  const list = document.getElementById('modelList');
  if (!models || models.length === 0) {
    list.innerHTML = '<div class="model-empty">点击「拉取模型列表」获取可用模型</div>';
    return;
  }
  let html = '';
  models.forEach(m => {
    const selected = m === selectedModel ? ' selected' : '';
    const check = m === selectedModel ? '<span class="check">✓</span>' : '';
    const desc = VENDOR_MODEL_DESC[m] ? '<span style="font-size:11px;color:#8e8e93;margin-left:8px;font-weight:normal">' + VENDOR_MODEL_DESC[m] + '</span>' : '';
    html += `<div class="model-item${selected}" data-model="${escapeHtml(m)}" onclick="selectModel('${escapeHtml(m)}')">${escapeHtml(m)}${desc}${check}</div>`;
  });
  list.innerHTML = html;
}

function selectModel(model) {
  document.getElementById('apiModel').value = model;
  document.querySelectorAll('.model-item').forEach(el => {
    var isSel = (el.getAttribute('data-model') || el.textContent.replace('✓','').trim()) === model;
    el.classList.toggle('selected', isSel);
    const check = el.querySelector('.check');
    if (check) check.remove();
    if (isSel) {
      el.classList.add('selected');
      const c = document.createElement('span');
      c.className = 'check';
      c.textContent = '✓';
      el.appendChild(c);
    }
  });
  updateVisionStatus();
}

