async function testImageApi() {
  var result = document.getElementById('imgApiTestResult');
  /* 先用弹窗里尚未保存的值试，方便用户边填边测 */
  var testCfg = {
    baseUrl: document.getElementById('imgApiBaseUrl').value.trim().replace(/\/+$/, ''),
    apiKey: document.getElementById('imgApiKey').value.trim(),
    model: document.getElementById('imgApiModel').value.trim()
  };
  if (!testCfg.baseUrl || !testCfg.apiKey || !testCfg.model) {
    if (result) result.innerHTML = '<div style="color:#e08a2e;font-size:12px">请先填完接口地址、Key 和模型再测试</div>';
    return;
  }
  if (result) result.innerHTML = '<div style="color:#7E728A;font-size:12px">正在测试生成，可能需要 10-30 秒...</div>';
  try {
    var url = testCfg.baseUrl + '/images/generations';
    var res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + testCfg.apiKey },
      body: JSON.stringify({ model: testCfg.model, prompt: '一只可爱的粉色麻薯小熊，奶油风，柔和光线，日系插画', n: 1, size: '1024x1024' })
    });
    if (!res.ok) {
      var errText = await res.text();
      throw new Error('HTTP ' + res.status + '：' + errText.substring(0, 100));
    }
    var data = await res.json();
    var item = data && data.data && data.data[0];
    var imgUrl = item ? (item.url || (item.b64_json ? 'data:image/png;base64,' + item.b64_json : '')) : '';
    if (!imgUrl) throw new Error('接口返回为空，请检查模型是否支持图片生成');
    if (result) {
      result.innerHTML = '<div style="color:#3d9b6c;font-size:12px;margin-bottom:6px">✅ 测试成功！记得点「应用配置」保存</div>'
        + '<img src="' + imgUrl + '" style="width:100%;border-radius:12px" alt="">';
    }
  } catch (e) {
    if (result) result.innerHTML = '<div style="color:#d45d79;font-size:12px">❌ 测试失败：' + escapeHtml(e && e.message ? e.message : '未知错误') + '</div>';
  }
}

// ===== 温度设置 =====
// ===== 语音合成 API 配置 =====

function openVoiceApiModal() {
  if (!config.ttsApi) config.ttsApi = { engine: 'browser', apiKey: '', groupId: '', region: 'cn', model: 'speech-2.8-hd', voices: [], selectedVoice: '' };
  /* 填充MiniMax表单 */
  var mmKey = document.getElementById('ttsApiKey');
  if (mmKey) mmKey.value = config.ttsApi.apiKey || '';
  var mmGid = document.getElementById('ttsGroupId');
  if (mmGid) mmGid.value = config.ttsApi.groupId || '';
  var modelSel = document.getElementById('ttsModel');
  if (modelSel) modelSel.value = config.ttsApi.model || 'speech-2.8-hd';
  /* 填充ElevenLabs表单 */
  var elKey = document.getElementById('elevenlabsApiKey');
  if (elKey) elKey.value = config.ttsApi.elevenlabsApiKey || '';
  var elModel = document.getElementById('elevenlabsModel');
  if (elModel) elModel.value = config.ttsApi.elevenlabsModel || 'eleven_multilingual_v2';
  var elStab = document.getElementById('elevenlabsStability');
  if (elStab) { elStab.value = config.ttsApi.elevenlabsStability !== undefined ? config.ttsApi.elevenlabsStability : 0.5; elStab.nextElementSibling.textContent = parseFloat(elStab.value).toFixed(2); }
  var elSim = document.getElementById('elevenlabsSimilarity');
  if (elSim) { elSim.value = config.ttsApi.elevenlabsSimilarity !== undefined ? config.ttsApi.elevenlabsSimilarity : 0.75; elSim.nextElementSibling.textContent = parseFloat(elSim.value).toFixed(2); }
  var elStyle = document.getElementById('elevenlabsStyle');
  if (elStyle) { elStyle.value = config.ttsApi.elevenlabsStyle !== undefined ? config.ttsApi.elevenlabsStyle : 0; elStyle.nextElementSibling.textContent = parseFloat(elStyle.value).toFixed(2); }
  var elBoost = document.getElementById('elevenlabsSpeakerBoostToggle');
  if (elBoost) elBoost.classList.toggle('on', config.ttsApi.elevenlabsSpeakerBoost !== false);
  /* 引擎切换状态 */
  switchVoiceEngine(config.ttsApi.engine || 'browser');
  /* 区域切换状态 */
  switchTtsRegion(config.ttsApi.region || 'cn');
  /* 渲染已保存的音色列表 */
  renderTtsVoiceList();
  renderElevenLabsVoiceList();
  var result = document.getElementById('ttsTestResult');
  if (result) result.innerHTML = '';
  var elResult = document.getElementById('elevenlabsTestResult');
  if (elResult) elResult.innerHTML = '';
  openModal('voiceApiModal');
}

function switchVoiceEngine(engine) {
  var isMinimax = engine === 'minimax';
  var isElevenlabs = engine === 'elevenlabs';
  var isBrowser = !isMinimax && !isElevenlabs;
  var mmArea = document.getElementById('minimaxConfigArea');
  var elArea = document.getElementById('elevenlabsConfigArea');
  if (mmArea) mmArea.style.display = isMinimax ? 'block' : 'none';
  if (elArea) elArea.style.display = isElevenlabs ? 'block' : 'none';
  /* 按钮样式 */
  var btnBrowser = document.getElementById('engineBtnBrowser');
  var btnMinimax = document.getElementById('engineBtnMinimax');
  var btnElevenlabs = document.getElementById('engineBtnElevenlabs');
  if (btnBrowser) {
    btnBrowser.style.borderColor = isBrowser ? '#07C160' : '#48484A';
    btnBrowser.style.background = isBrowser ? 'rgba(7,193,96,0.1)' : '#1C1C1E';
    btnBrowser.style.color = isBrowser ? '#07C160' : '#8E8E93';
  }
  if (btnMinimax) {
    btnMinimax.style.borderColor = isMinimax ? '#07C160' : '#48484A';
    btnMinimax.style.background = isMinimax ? 'rgba(7,193,96,0.1)' : '#1C1C1E';
    btnMinimax.style.color = isMinimax ? '#07C160' : '#8E8E93';
  }
  if (btnElevenlabs) {
    btnElevenlabs.style.borderColor = isElevenlabs ? '#07C160' : '#48484A';
    btnElevenlabs.style.background = isElevenlabs ? 'rgba(7,193,96,0.1)' : '#1C1C1E';
    btnElevenlabs.style.color = isElevenlabs ? '#07C160' : '#8E8E93';
  }
}

function switchTtsRegion(region) {
  var isCN = region === 'cn';
  var btnCN = document.getElementById('regionBtnCN');
  var btnIntl = document.getElementById('regionBtnIntl');
  if (btnCN) {
    btnCN.style.borderColor = isCN ? '#07C160' : '#48484A';
    btnCN.style.background = isCN ? 'rgba(7,193,96,0.1)' : '#1C1C1E';
    btnCN.style.color = isCN ? '#07C160' : '#8E8E93';
  }
  if (btnIntl) {
    btnIntl.style.borderColor = !isCN ? '#07C160' : '#48484A';
    btnIntl.style.background = !isCN ? 'rgba(7,193,96,0.1)' : '#1C1C1E';
    btnIntl.style.color = !isCN ? '#07C160' : '#8E8E93';
  }
}

/* 获取MiniMax API基础URL */
function getTtsBaseUrl() {
  var region = (config.ttsApi && config.ttsApi.region) || 'cn';
  return region === 'intl' ? 'https://api.minimax.io/v1' : 'https://api.minimaxi.com/v1';
}

/* 拉取音色列表 */
async function fetchTtsVoices() {
  var apiKey = document.getElementById('ttsApiKey').value.trim();
  if (!apiKey) { showToast('请先填写API Key'); return; }
  var region = config.ttsApi.region || 'cn';
  var groupId = document.getElementById('ttsGroupId').value.trim();
  var baseUrl = region === 'intl' ? 'https://api.minimax.io/v1' : 'https://api.minimaxi.com/v1';
  var url = baseUrl + '/get_voice';
  if (region === 'cn' && groupId) url += '?GroupId=' + groupId;

  var listEl = document.getElementById('ttsVoiceList');
  if (listEl) listEl.innerHTML = '<div style="padding:16px;text-align:center;color:#8E8E93;font-size:13px">正在拉取音色列表...</div>';

  try {
    var res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
      body: JSON.stringify({ voice_type: 'all' })
    });
    if (!res.ok) {
      var errText = await res.text();
      throw new Error('HTTP ' + res.status + ': ' + errText.substring(0, 200));
    }
    var data = await res.json();
    /* 构建内置音色的中文名映射，用于替换API返回的英文voice_id */
    var builtinMap = {};
    getDefaultTtsVoices().forEach(function(v) {
      builtinMap[v.voice_id] = { name: v.name, desc: v.desc };
    });
    /* 解析音色列表：优先用内置中文名，其次用API返回的name，最后用voice_id */
    var voices = [];
    if (data && data.system_voice) {
      (data.system_voice || []).forEach(function(v) {
        var bm = builtinMap[v.voice_id];
        voices.push({ voice_id: v.voice_id, name: (bm && bm.name) || v.name || v.voice_id, type: 'system', desc: (bm && bm.desc) || v.description || '' });
      });
    }
    if (data && data.voice_cloning) {
      (data.voice_cloning || []).forEach(function(v) {
        var bm = builtinMap[v.voice_id];
        voices.push({ voice_id: v.voice_id, name: (bm && bm.name) || v.name || v.voice_id, type: 'cloned', desc: (bm && bm.desc) || '克隆音色' });
      });
    }
    if (data && data.voice_generation) {
      (data.voice_generation || []).forEach(function(v) {
        var bm = builtinMap[v.voice_id];
        voices.push({ voice_id: v.voice_id, name: (bm && bm.name) || v.name || v.voice_id, type: 'generated', desc: (bm && bm.desc) || v.description || '' });
      });
    }
    /* 如果返回格式不同，尝试直接读取数组 */
    if (voices.length === 0 && Array.isArray(data)) {
      data.forEach(function(v) {
        var bm = builtinMap[v.voice_id || v.id || v];
        voices.push({ voice_id: v.voice_id || v.id || v, name: (bm && bm.name) || v.name || v.voice_id || v.id || v, type: v.type || 'system', desc: (bm && bm.desc) || v.description || '' });
      });
    }
    /* 如果还是没有，使用内置音色列表 */
    if (voices.length === 0) {
      voices = getDefaultTtsVoices();
    }
    if (!config.ttsApi) config.ttsApi = {};
    /* 保留自定义音色，不被拉取覆盖 */
    var customVoices = config.ttsApi.customVoices || [];
    /* 合并：拉取的系统音色 + 保留的自定义音色 */
    config.ttsApi.voices = voices.concat(customVoices);
    renderTtsVoiceList();
    showToast('成功拉取 ' + voices.length + ' 个音色' + (customVoices.length > 0 ? '（含' + customVoices.length + '个自定义）' : ''));
  } catch(err) {
    /* 拉取失败时显示内置音色列表 */
    var fallbackVoices = getDefaultTtsVoices();
    if (!config.ttsApi) config.ttsApi = {};
    /* 保留自定义音色 */
    var customVoices = config.ttsApi.customVoices || [];
    config.ttsApi.voices = fallbackVoices.concat(customVoices);
    renderTtsVoiceList();
    if (listEl) {
      listEl.innerHTML = '<div style="padding:12px;color:#FF9500;font-size:12px;margin-bottom:8px">拉取失败(' + escapeHtml(err.message) + ')，已显示内置音色列表供选择</div>' + listEl.innerHTML;
    }
    showToast('拉取失败，已显示内置音色');
  }
}

