/* 渲染音色列表 */
function renderTtsVoiceList() {
  var listEl = document.getElementById('ttsVoiceList');
  if (!listEl) return;
  var voices = (config.ttsApi && config.ttsApi.voices) || [];
  var selected = (config.ttsApi && config.ttsApi.selectedVoice) || '';
  /* 修复已存储的英文音色名：如果name等于voice_id（英文ID），尝试用内置中文名替换 */
  var builtinMap = {};
  getDefaultTtsVoices().forEach(function(v) {
    builtinMap[v.voice_id] = { name: v.name, desc: v.desc };
  });
  voices.forEach(function(v) {
    var bm = builtinMap[v.voice_id];
    if (bm) {
      if (!v.name || v.name === v.voice_id) v.name = bm.name;
      if (!v.desc || v.desc === '') v.desc = bm.desc;
    }
  });
  if (voices.length === 0) {
    listEl.innerHTML = '<div style="padding:16px;text-align:center;color:#8E8E93;font-size:13px">填写API Key后点击「拉取音色」获取可用音色列表</div>';
    return;
  }
  /* 按类型分组 */
  var groups = {};
  voices.forEach(function(v) {
    var type = v.type || 'system';
    if (!groups[type]) groups[type] = [];
    groups[type].push(v);
  });
  var typeNames = { system: '系统音色', cloned: '克隆音色', generated: '生成音色', custom: '自定义音色' };
  var html = '';
  Object.keys(groups).forEach(function(type) {
    html += '<div style="padding:6px 12px;font-size:11px;color:#8E8E93;font-weight:600">' + (typeNames[type] || type) + '</div>';
    groups[type].forEach(function(v) {
      var isSelected = v.voice_id === selected;
      html += '<div class="tts-voice-item' + (isSelected ? ' selected' : '') + '" onclick="selectTtsVoice(\'' + escapeHtml(v.voice_id) + '\')" style="padding:10px 12px;border-radius:8px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;' + (isSelected ? 'background:rgba(7,193,96,0.12);' : '') + '">';
      html += '<div style="flex:1"><div style="font-size:13px;color:#fff">' + escapeHtml(v.name || v.voice_id) + '</div>';
      if (v.desc) html += '<div style="font-size:11px;color:#8E8E93;margin-top:2px">' + escapeHtml(v.desc) + '</div>';
      html += '</div>';
      if (isSelected) html += '<span style="color:#07C160;font-size:16px;margin-right:6px">✓</span>';
      /* 自定义音色显示删除按钮 */
      if (type === 'custom') {
        html += '<button onclick="event.stopPropagation();removeCustomTtsVoice(\'' + escapeHtml(v.voice_id) + '\')" style="width:24px;height:24px;border-radius:6px;border:none;background:rgba(255,59,48,0.15);color:#FF3B30;font-size:12px;cursor:pointer;flex-shrink:0">×</button>';
      }
      html += '</div>';
    });
  });
  listEl.innerHTML = html;
}

function selectTtsVoice(voiceId) {
  if (!config.ttsApi) config.ttsApi = {};
  config.ttsApi.selectedVoice = voiceId;
  renderTtsVoiceList();
  Store.set('config', config);
}

/* 添加自定义音色 */
function addCustomTtsVoice() {
  var idInput = document.getElementById('customVoiceIdInput');
  var nameInput = document.getElementById('customVoiceNameInput');
  if (!idInput) return;
  var voiceId = idInput.value.trim();
  if (!voiceId) { showToast('请输入Voice ID'); return; }
  if (!config.ttsApi) config.ttsApi = {};
  if (!config.ttsApi.voices) config.ttsApi.voices = [];
  /* 去重：检查是否已存在相同voice_id的自定义音色 */
  var existing = config.ttsApi.voices.find(function(v) { return v.voice_id === voiceId; });
  if (existing) { showToast('该音色ID已存在于列表中'); return; }
  var name = nameInput ? nameInput.value.trim() : '';
  config.ttsApi.voices.push({ voice_id: voiceId, name: name || voiceId, type: 'custom', desc: '自定义音色' });
  /* 同步保存自定义音色到独立字段，确保刷新和拉取后不丢失 */
  if (!config.ttsApi.customVoices) config.ttsApi.customVoices = [];
  var alreadySaved = config.ttsApi.customVoices.find(function(v) { return v.voice_id === voiceId; });
  if (!alreadySaved) {
    config.ttsApi.customVoices.push({ voice_id: voiceId, name: name || voiceId, type: 'custom', desc: '自定义音色' });
  }
  Store.set('config', config);
  /* 清空输入框 */
  idInput.value = '';
  if (nameInput) nameInput.value = '';
  renderTtsVoiceList();
  showToast('已添加自定义音色: ' + voiceId);
}

/* 删除自定义音色 */
function removeCustomTtsVoice(voiceId) {
  if (!config.ttsApi || !config.ttsApi.voices) return;
  config.ttsApi.voices = config.ttsApi.voices.filter(function(v) { return !(v.voice_id === voiceId && v.type === 'custom'); });
  if (config.ttsApi.customVoices) {
    config.ttsApi.customVoices = config.ttsApi.customVoices.filter(function(v) { return v.voice_id !== voiceId; });
  }
  /* 如果删除的是当前选中的音色，清空选中 */
  if (config.ttsApi.selectedVoice === voiceId) {
    config.ttsApi.selectedVoice = '';
  }
  Store.set('config', config);
  renderTtsVoiceList();
  showToast('已删除自定义音色');
}

/* 应用TTS配置 */
function applyTtsApiConfig() {
  if (!config.ttsApi) config.ttsApi = {};
  var btnMinimax = document.getElementById('engineBtnMinimax');
  var btnElevenlabs = document.getElementById('engineBtnElevenlabs');
  var isMinimax = btnMinimax && btnMinimax.style.borderColor === 'rgb(7, 193, 96)';
  var isElevenlabs = btnElevenlabs && btnElevenlabs.style.borderColor === 'rgb(7, 193, 96)';
  config.ttsApi.engine = isElevenlabs ? 'elevenlabs' : (isMinimax ? 'minimax' : 'browser');
  /* MiniMax配置 */
  var mmKey = document.getElementById('ttsApiKey');
  config.ttsApi.apiKey = mmKey ? mmKey.value.trim() : '';
  var mmGid = document.getElementById('ttsGroupId');
  config.ttsApi.groupId = mmGid ? mmGid.value.trim() : '';
  var modelSel = document.getElementById('ttsModel');
  config.ttsApi.model = modelSel ? modelSel.value : 'speech-2.8-hd';
  /* 区域 */
  var regionBtnCN = document.getElementById('regionBtnCN');
  config.ttsApi.region = (regionBtnCN && regionBtnCN.style.borderColor === 'rgb(7, 193, 96)') ? 'cn' : 'intl';
  /* ElevenLabs配置 */
  var elKey = document.getElementById('elevenlabsApiKey');
  config.ttsApi.elevenlabsApiKey = elKey ? elKey.value.trim() : '';
  var elModel = document.getElementById('elevenlabsModel');
  config.ttsApi.elevenlabsModel = elModel ? elModel.value : 'eleven_multilingual_v2';
  var elStab = document.getElementById('elevenlabsStability');
  config.ttsApi.elevenlabsStability = elStab ? parseFloat(elStab.value) : 0.5;
  var elSim = document.getElementById('elevenlabsSimilarity');
  config.ttsApi.elevenlabsSimilarity = elSim ? parseFloat(elSim.value) : 0.75;
  var elStyle = document.getElementById('elevenlabsStyle');
  config.ttsApi.elevenlabsStyle = elStyle ? parseFloat(elStyle.value) : 0;
  var elBoost = document.getElementById('elevenlabsSpeakerBoostToggle');
  config.ttsApi.elevenlabsSpeakerBoost = elBoost ? elBoost.classList.contains('on') : true;
  Store.set('config', config);
  updateSettingsView();
  closeModal('voiceApiModal');
  showToast('语音合成 API 配置已保存');
}

/* 测试TTS合成 */
async function testTtsVoice() {
  var apiKey = document.getElementById('ttsApiKey').value.trim();
  if (!apiKey) { showToast('请先填写API Key'); return; }
  var result = document.getElementById('ttsTestResult');
  if (result) result.innerHTML = '<div style="color:#7E728A;font-size:12px">正在合成语音...</div>';

  var region = config.ttsApi.region || 'cn';
  var groupId = document.getElementById('ttsGroupId').value.trim();
  var modelSel = document.getElementById('ttsModel');
  var model = modelSel ? modelSel.value : 'speech-2.8-hd';
  var voiceId = (config.ttsApi && config.ttsApi.selectedVoice) || 'female-shaonv';
  var baseUrl = region === 'intl' ? 'https://api.minimax.io/v1' : 'https://api.minimaxi.com/v1';
  var url = baseUrl + '/t2a_v2';
  if (region === 'cn' && groupId) url += '?GroupId=' + groupId;

  try {
    var res = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
      body: JSON.stringify({
        model: model,
        text: '你好呀，我是语音合成测试。今天天气真好，我们出去走走吧！',
        stream: false,
        voice_setting: {
          voice_id: voiceId,
          speed: 1.0,
          vol: 1.0,
          pitch: 0,
          emotion: 'happy'
        },
        audio_setting: {
          sample_rate: 32000,
          bitrate: 128000,
          format: 'mp3',
          channel: 1
        }
      })
    });
    if (!res.ok) {
      var errText = await res.text();
      throw new Error('HTTP ' + res.status + ': ' + errText.substring(0, 200));
    }
    var data = await res.json();
    if (data.base_resp && data.base_resp.status_code !== 0) {
      throw new Error('API错误(' + data.base_resp.status_code + '): ' + data.base_resp.status_msg);
    }
    if (!data.data || !data.data.audio) {
      throw new Error('返回数据中没有音频内容');
    }
    /* hex转base64再播放 */
    var hexAudio = data.data.audio;
    var audioBlob = hexToBlob(hexAudio, 'audio/mp3');
    var audioUrl = URL.createObjectURL(audioBlob);
    var audio = new Audio(audioUrl);
    audio.play();
    if (result) {
      var duration = data.extra_info ? (data.extra_info.audio_length / 1000).toFixed(1) : '?';
      var chars = data.extra_info ? data.extra_info.usage_characters : '?';
      result.innerHTML = '<div style="color:#3d9b6c;font-size:12px">✅ 合成成功！时长' + duration + '秒，消耗' + chars + '字符。正在播放...</div>';
    }
  } catch(err) {
    if (result) result.innerHTML = '<div style="color:#d45d79;font-size:12px">❌ 测试失败：' + escapeHtml(err && err.message ? err.message : '未知错误') + '</div>';
  }
}

/* hex转Blob */
function hexToBlob(hex, mimeType) {
  var bytes = new Uint8Array(hex.length / 2);
  for (var i = 0; i < hex.length; i += 2) {
    bytes[i / 2] = parseInt(hex.substr(i, 2), 16);
  }
  return new Blob([bytes], { type: mimeType });
}

/* 调用MiniMax TTS合成语音（供播放函数调用） */
async function synthesizeWithMiniMax(text, charIdx) {
  var tts = config.ttsApi;
  if (!tts || !tts.apiKey) throw new Error('未配置MiniMax API Key');
  var char = config.characters && config.characters[charIdx];
  var vs = ensureCharVoiceSettings(char || {});
  /* 情绪：空值=自动，模型根据每条文本内容自行选择 */
  var emotion = vs.emotion || '';
  /* 口语化文本处理（插入 MiniMax 停顿标记） */
  var processedText = applyVoiceRealism(text, vs, true);
  var baseUrl = getTtsBaseUrl();
  var url = baseUrl + '/t2a_v2';
  if (tts.region === 'cn' && tts.groupId) url += '?GroupId=' + tts.groupId;

  /* 音色混合校验：2-4个音色且权重合计100才生效 */
  var mix = (vs.mix || []).filter(function(m) { return m && m.voiceId && (parseInt(m.weight, 10) || 0) > 0; });
  var mixSum = mix.reduce(function(s, m) { return s + (parseInt(m.weight, 10) || 0); }, 0);
  var useMix = mix.length >= 2 && mix.length <= 4 && mixSum === 100;

  /* 优先使用角色独立音色，其次全局音色；混合音色生效时 voice_id 置空 */
  /* 确保 speed 是合法浮点数，防止继承旧 rate 导致加速 */
  var _safeSpeed = parseFloat(vs.speed);
  if (isNaN(_safeSpeed) || _safeSpeed <= 0) _safeSpeed = 1.0;
  _safeSpeed = Math.max(0.5, Math.min(2.0, _safeSpeed));
  var voiceSetting = {
    voice_id: useMix ? '' : (vs.voiceId || tts.selectedVoice || 'female-shaonv'),
    speed: _safeSpeed,
    vol: parseFloat(vs.vol) || 1.0,
    pitch: Math.max(-12, Math.min(12, Math.round(vs.pitch)))
  };
  if (emotion) voiceSetting.emotion = emotion;

  var reqBody = {
    model: tts.model || 'speech-2.8-hd',
    text: processedText,
    stream: false,
    voice_setting: voiceSetting,
    audio_setting: {
      sample_rate: 32000,
      bitrate: 128000,
      format: 'mp3',
      channel: 1
    }
  };
  if (useMix) {
    reqBody.timbre_weights = mix.map(function(m) { return { voice_id: m.voiceId, weight: parseInt(m.weight, 10) || 0 }; });
  }
  /* 声音微调：仅在有非零值或音效时发送 */
  var md = vs.modify || {};
  var voiceModify = {};
  if (md.pitch) voiceModify.pitch = Math.round(md.pitch);
  if (md.intensity) voiceModify.intensity = Math.round(md.intensity);
  if (md.timbre) voiceModify.timbre = Math.round(md.timbre);
  if (md.soundEffects) voiceModify.sound_effects = md.soundEffects;
  if (Object.keys(voiceModify).length > 0) reqBody.voice_modify = voiceModify;

  var res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + tts.apiKey },
    body: JSON.stringify(reqBody)
  });
  if (!res.ok) {
    var errText = await res.text();
    throw new Error('HTTP ' + res.status + ': ' + errText.substring(0, 200));
  }
  var data = await res.json();
  if (data.base_resp && data.base_resp.status_code !== 0) {
    throw new Error('API错误(' + data.base_resp.status_code + '): ' + data.base_resp.status_msg);
  }
  if (!data.data || !data.data.audio) {
    throw new Error('返回数据中没有音频内容');
  }
  var hexAudio = data.data.audio;
  return hexToBlob(hexAudio, 'audio/mp3');
}

/* ===== ElevenLabs TTS ===== */

/* 调用ElevenLabs TTS合成语音（供播放函数调用） */
async function synthesizeWithElevenLabs(text, charIdx) {
  var tts = config.ttsApi;
  if (!tts || !tts.elevenlabsApiKey) throw new Error('未配置ElevenLabs API Key');
  var char = config.characters && config.characters[charIdx];
  var vs = ensureCharVoiceSettings(char || {});
  /* 口语化文本处理 */
  var processedText = applyVoiceRealism(text, vs, false);
  /* 音色ID：优先角色独立音色，其次全局选中音色，最后默认音色 */
  var voiceId = vs.elevenlabsVoiceId || tts.elevenlabsSelectedVoice || '21m00Tcm4TlvDq8ikWAM';
  /* 语音参数：优先角色级覆盖，其次全局默认 */
  var stability = vs.elevenlabsStability !== undefined ? vs.elevenlabsStability : (tts.elevenlabsStability !== undefined ? tts.elevenlabsStability : 0.5);
  var similarity = vs.elevenlabsSimilarity !== undefined ? vs.elevenlabsSimilarity : (tts.elevenlabsSimilarity !== undefined ? tts.elevenlabsSimilarity : 0.75);
  var style = vs.elevenlabsStyle !== undefined ? vs.elevenlabsStyle : (tts.elevenlabsStyle !== undefined ? tts.elevenlabsStyle : 0);
  var useSpeakerBoost = vs.elevenlabsSpeakerBoost !== undefined ? vs.elevenlabsSpeakerBoost : (tts.elevenlabsSpeakerBoost !== false);
  var model = tts.elevenlabsModel || 'eleven_multilingual_v2';

  var url = 'https://api.elevenlabs.io/v1/text-to-speech/' + encodeURIComponent(voiceId);
  var res = await fetch(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'xi-api-key': tts.elevenlabsApiKey,
      'Accept': 'audio/mpeg'
    },
    body: JSON.stringify({
      text: processedText,
      model_id: model,
      voice_settings: {
        stability: Math.max(0, Math.min(1, parseFloat(stability))),
        similarity_boost: Math.max(0, Math.min(1, parseFloat(similarity))),
        style: Math.max(0, Math.min(1, parseFloat(style))),
        use_speaker_boost: !!useSpeakerBoost
      }
    })
  });
  if (!res.ok) {
    var errText = await res.text();
    throw new Error('HTTP ' + res.status + ': ' + errText.substring(0, 200));
  }
  /* ElevenLabs返回的是二进制音频，不是JSON */
  var blob = await res.blob();
  if (!blob || blob.size === 0) throw new Error('返回数据中没有音频内容');
  return blob;
}

/* 获取角色生效的TTS引擎（角色级覆盖优先，其次全局） */
function getCharTtsEngine(charIdx) {
  var char = config.characters && config.characters[charIdx];
  var vs = char ? ensureCharVoiceSettings(char) : {};
  var tts = config.ttsApi || {};
  /* 角色级引擎覆盖 */
  if (vs.engine === 'browser') return 'browser';
  if (vs.engine === 'minimax' && tts.apiKey) return 'minimax';
  if (vs.engine === 'elevenlabs' && tts.elevenlabsApiKey) return 'elevenlabs';
  /* 跟随全局 */
  if (tts.engine === 'minimax' && tts.apiKey) return 'minimax';
  if (tts.engine === 'elevenlabs' && tts.elevenlabsApiKey) return 'elevenlabs';
  return 'browser';
}

/* 判断指定角色是否使用云端TTS */
function isCloudTtsActiveForChar(charIdx) {
  var engine = getCharTtsEngine(charIdx);
  return engine === 'minimax' || engine === 'elevenlabs';
}

/* 云端TTS统一调度：根据角色级引擎路由 */
async function synthesizeCloudTts(text, charIdx) {
  var engine = getCharTtsEngine(charIdx);
  if (engine === 'elevenlabs') {
    return await synthesizeWithElevenLabs(text, charIdx);
  } else {
    return await synthesizeWithMiniMax(text, charIdx);
  }
}

/* 判断是否启用了云端TTS（全局级别，用于设置页状态显示） */
function isCloudTtsActive() {
  var tts = config.ttsApi;
  if (!tts) return false;
  if (tts.engine === 'minimax' && tts.apiKey) return true;
  if (tts.engine === 'elevenlabs' && tts.elevenlabsApiKey) return true;
  return false;
}

