// ===== Dock 栏系统（主屏幕 4×8 的第 8 行：2-4 个 APP，栏内平均排列）=====
// 可放进 Dock 的应用 = 微信/设置 + 桌面网格里的全部应用
var DOCKABLE_APPS = [
  { id: 'wechat',   icon: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#777" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 10a2 2 0 0 1-2 2H6.828a2 2 0 0 0-1.414.586l-2.202 2.202A.71.71 0 0 1 2 14.286V4a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/><path d="M20 9a2 2 0 0 1 2 2v10.286a.71.71 0 0 1-1.212.502l-2.202-2.202A2 2 0 0 0 17.172 19H10a2 2 0 0 1-2-2v-1"/></svg>', name: '微信', bg: '#FFFFFF' },
  { id: 'settings', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#777" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9.671 4.136a2.34 2.34 0 0 1 4.659 0 2.34 2.34 0 0 0 3.319 1.915 2.34 2.34 0 0 1 2.33 4.033 2.34 2.34 0 0 0 0 3.831 2.34 2.34 0 0 1-2.33 4.033 2.34 2.34 0 0 0-3.319 1.915 2.34 2.34 0 0 1-4.659 0 2.34 2.34 0 0 0-3.32-1.915 2.34 2.34 0 0 1-2.33-4.033 2.34 2.34 0 0 0 0-3.831A2.34 2.34 0 0 1 6.35 6.051a2.34 2.34 0 0 0 3.319-1.915"/><circle cx="12" cy="12" r="3"/></svg>', name: '设置', bg: '#FFFFFF' }
].concat(APP_DEFINITIONS);

function getDockableDef(id) {
  for (var i = 0; i < DOCKABLE_APPS.length; i++) {
    if (DOCKABLE_APPS[i].id === id) return DOCKABLE_APPS[i];
  }
  return null;
}

function getDockApps() {
  /* HV2 固定版式：Dock 写死 4 个应用，不再读取用户自定义 */
  if (typeof HV2_FIXED !== 'undefined' && HV2_FIXED) return HV2_DOCK_APPS.slice();
  var fallback = ['wechat', 'phonecheck', 'settings'];
  var saved = null;
  try { saved = config.settings.dockApps; } catch(e) {}
  if (!Array.isArray(saved) || !saved.length) {
    try { saved = JSON.parse(localStorage.getItem('mochi_dock_apps') || 'null'); } catch(e2) { saved = null; }
  }
  if (!Array.isArray(saved) || !saved.length) saved = fallback;
  // 校验：最多 4 个、去重、必须是存在的应用
  var valid = [];
  saved.forEach(function(id) {
    if (valid.length < 4 && valid.indexOf(id) < 0 && getDockableDef(id)) valid.push(id);
  });
  // 兜底：至少 2 个
  for (var i = 0; i < fallback.length && valid.length < 2; i++) {
    if (valid.indexOf(fallback[i]) < 0 && getDockableDef(fallback[i])) valid.push(fallback[i]);
  }
  return valid;
}

function renderDock() {
  var dock = document.getElementById('homeDock');
  if (!dock) return;
  dock.innerHTML = '';
  getDockApps().forEach(function(id) {
    var def = getAppIconDef(id);
    if (!def) return;
    var item = document.createElement('div');
    item.className = 'dock-item';
    item.dataset.appId = id;
    /* 用事件监听替代 onclick 属性，支持编辑模式下单击自定义图标 */
    item.addEventListener('click', function(e) {
      var appId = this.dataset.appId;
      if (typeof _appEditMode !== 'undefined' && _appEditMode) {
        openAppIconCustomizer(appId);
        return;
      }
      openApp(appId);
    });
    item.innerHTML = renderDockIconHtml(id) +
      '<span class="dock-name">' + def.name + '</span>';
    dock.appendChild(item);
  });
  if (typeof updateBadges === 'function') updateBadges();
  setTimeout(bgGenUpdateIcons, 50);
}

var _dockSelection = [];
function openDockSettings() {
  /* HV2 固定版式：Dock 已固定为 微信 / 查手机 / 设置 / 电话 */
  if (typeof HV2_FIXED !== 'undefined' && HV2_FIXED) {
    if (typeof showToast === 'function') showToast('Dock 栏已固定：微信 / 查手机 / 设置 / 电话');
    return;
  }
  _dockSelection = getDockApps();
  renderDockAppList();
  openModal('dockSettingsModal');
}
function renderDockAppList() {
  var box = document.getElementById('dockAppList');
  if (!box) return;
  var html = '';
  DOCKABLE_APPS.forEach(function(def) {
    var pos = _dockSelection.indexOf(def.id);
    html += '<div class="dock-app-item' + (pos >= 0 ? ' selected' : '') + '" onclick="toggleDockApp(\'' + def.id + '\')">' +
      '<div class="dock-app-item-icon" style="background:' + def.bg + '">' + def.icon +
      (pos >= 0 ? '<span class="dock-order-badge">' + (pos + 1) + '</span>' : '') + '</div>' +
      '<div class="dock-app-item-name">' + def.name + '</div>' +
      '<div class="dock-app-check">✓</div></div>';
  });
  box.innerHTML = html;
}
function toggleDockApp(id) {
  var idx = _dockSelection.indexOf(id);
  if (idx >= 0) {
    if (_dockSelection.length <= 2) { showToast('Dock 栏至少保留 2 个应用'); return; }
    _dockSelection.splice(idx, 1);
  } else {
    if (_dockSelection.length >= 4) { showToast('Dock 栏最多放 4 个应用'); return; }
    _dockSelection.push(id);
  }
  renderDockAppList();
}
function saveDockSelection() {
  if (_dockSelection.length < 2 || _dockSelection.length > 4) { showToast('请选择 2 - 4 个应用'); return; }
  config.settings.dockApps = _dockSelection.slice();
  Store.set('config', config);
  try { localStorage.setItem('mochi_dock_apps', JSON.stringify(_dockSelection)); } catch(e) {}
  renderDock();
  closeModal('dockSettingsModal');
  if (typeof updateSettingsView === 'function') updateSettingsView();
  showToast('Dock 栏已更新 ✿');
}

// ===== 用户自定义小组件（自己设计 HTML/CSS，出现在添加小组件画廊）=====
var CW_SIZE_OPTIONS = ['w1 h1', 'w2 h1', 'w2 h2', 'w4 h1', 'w4 h2', 'w2 h3'];

function getCustomWidgets() {
  try {
    var list = config.settings.customWidgets;
    return Array.isArray(list) ? list : [];
  } catch(e) { return []; }
}
function saveCustomWidgets(list) {
  config.settings.customWidgets = list;
  Store.set('config', config);
}
function widgetSpanLabel(span) {
  var w = (span || '').match(/w(\d)/), h = (span || '').match(/h(\d)/);
  return (w ? w[1] : '2') + '×' + (h ? h[1] : '2');
}
function customWidgetDef(w) {
  /* 纯文案组件：不显示图片和照片区域 */
  var isTextOnly = w.textOnly;
  var showImg = !isTextOnly && w.imageUrl;
  /* 层级：z0=背景图 → z1=照片区域 → z2=抠图层 → z3=HTML/文案 */
  var imgHtml = showImg ? '<img src="' + w.imageUrl + '" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0" alt="">' : '';
  /* 多照片区域：支持最多3个，向后兼容旧的单区域格式 */
  var pzList = [];
  if (w.photoZones && w.photoZones.length) {
    pzList = w.photoZones;
  } else if (w.photoZone && w.photoZoneStyle) {
    var pzOld = w.photoZoneStyle;
    var matchOld = function(prop) { var m = pzOld.match(new RegExp(prop + '\\s*:\\s*([\\d.]+)')); return m ? parseFloat(m[1]) : 0; };
    pzList = [{ left: matchOld('left') || 0, top: matchOld('top') || 0, width: matchOld('width') || 100, height: matchOld('height') || 100, radius: (function(){ var rm = pzOld.match(/border-radius\s*:\s*(\d+)/); return rm ? parseInt(rm[1],10) : 0; })() }];
  }
  var photoZoneHtml = '';
  if (!isTextOnly && pzList.length > 0) {
    for (var pzi = 0; pzi < pzList.length; pzi++) {
      photoZoneHtml += '<div class="cw-photo-zone" data-pz-idx="' + pzi + '" onclick="event.stopPropagation();cwDesignPhotoUpload(\'' + w.id + '\',' + pzi + ')" style="position:absolute;z-index:1;cursor:pointer"></div>';
    }
  }
  var cutoutHtml = (!isTextOnly && w.cutoutUrl) ? '<img src="' + w.cutoutUrl + '" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2;pointer-events:none" alt="">' : '';
  var contentHtml = (w.html || w.text) ? '<div style="position:relative;z-index:3">' + (w.text || w.html) + '</div>' : '';
  var descSuffix = isTextOnly ? ' · 文案' : (pzList.length > 0 ? ' · 可放照片(' + pzList.length + ')' : '');
  var def = {
    id: w.id, name: w.name || '自定义组件', icon: w.icon || '✨',
    desc: '自己设计的小组件 · 占 ' + widgetSpanLabel(w.span) + ' 格' + descSuffix,
    bg: (!w.bg || w.bg === 'linear-gradient(135deg,#E8C5D0,#D4B5C5)') ? 'transparent' : w.bg,
    frosted: !!w.frosted,
    cls: 'custom-widget', span: w.span || 'w2 h2',
    custom: true, customCss: w.css || '', textOnly: isTextOnly,
    render: function() { return '<div class="custom-widget-body">' + imgHtml + photoZoneHtml + cutoutHtml + contentHtml + '</div>'; }
  };
  if (!isTextOnly && pzList.length > 0) {
    def.after = function(el) {
      var zones = el.querySelectorAll('.cw-photo-zone');
      for (var zi = 0; zi < zones.length; zi++) {
        var zone = zones[zi];
        var pzIdx = parseInt(zone.dataset.pzIdx, 10) || 0;
        var pzData = pzList[pzIdx];
        if (!pzData) continue;
        var pzStyle = 'position:absolute;z-index:1;cursor:pointer;left:' + (pzData.left || 0) + '%;top:' + (pzData.top || 0) + '%;width:' + (pzData.width || 100) + '%;height:' + (pzData.height || 100) + '%';
        if (pzData.radius) pzStyle += ';border-radius:' + pzData.radius + 'px';
        zone.style.cssText = pzStyle + ';overflow:hidden';
        /* Check for stored photo (key: widgetId_pz_idx) */
        var photoKey = w.id + '_pz_' + pzIdx;
        var photoSrc = (config.widgetImages && config.widgetImages[photoKey]) ? config.widgetImages[photoKey] : null;
        /* 向后兼容：如果新的key没有，但旧的单区域key有且idx=0，用旧的 */
        if (!photoSrc && pzIdx === 0 && config.widgetImages && config.widgetImages[w.id]) {
          photoSrc = config.widgetImages[w.id];
        }
        if (photoSrc) {
          zone.innerHTML = '<img src="' + photoSrc + '" style="width:100%;height:100%;object-fit:cover" alt="">';
          zone.classList.add('has-photo');
        } else {
          zone.innerHTML = '<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.15);color:rgba(255,255,255,0.5);font-size:20px">📷</div>';
        }
      }
    };
  }
  return def;
}
// 把用户保存的自定义小组件注册进小组件定义表（先清旧再注册，可重复调用）
function registerCustomWidgets() {
  for (var i = WIDGET_DEFINITIONS.length - 1; i >= 0; i--) {
    if (WIDGET_DEFINITIONS[i].custom) WIDGET_DEFINITIONS.splice(i, 1);
  }
  getCustomWidgets().forEach(function(w) {
    if (w && w.id) WIDGET_DEFINITIONS.push(customWidgetDef(w));
  });
}

// 设计图小组件照片上传
function cwDesignPhotoUpload(widgetId, pzIdx) {
  if (typeof _appEditMode !== 'undefined' && _appEditMode) return;
  if (typeof pzIdx === 'undefined') pzIdx = 0;
  pickWidgetImage(function(src) {
    if (!config.widgetImages) config.widgetImages = {};
    var photoKey = widgetId + '_pz_' + pzIdx;
    config.widgetImages[photoKey] = src;
    /* 同时清理旧的单区域 key 以避免冲突 */
    if (pzIdx === 0 && config.widgetImages[widgetId]) {
      delete config.widgetImages[widgetId];
    }
    Store.set('config', config);
    var zones = document.querySelectorAll('.home-widget[data-widget-id="' + widgetId + '"] .cw-photo-zone');
    for (var i = 0; i < zones.length; i++) {
      var zone = zones[i];
      var zIdx = parseInt(zone.dataset.pzIdx, 10) || 0;
      if (zIdx !== pzIdx) continue;
      zone.innerHTML = '<img src="' + src + '" style="width:100%;height:100%;object-fit:cover" alt="">';
      zone.classList.add('has-photo');
    }
    if (typeof showToast === 'function') showToast('照片已上传到区域 ' + (pzIdx + 1) + ' ✿');
  });
}
window.cwDesignPhotoUpload = cwDesignPhotoUpload;

/* 更新自定义小组件的背景图（不影响照片区域） */
function setCustomWidgetBgImage(widgetId, src) {
  /* 1. 更新 DOM 中的 <img alt=""> 标签 */
  var wEls = document.querySelectorAll('.home-widget[data-widget-id="' + widgetId + '"]');
  for (var wi = 0; wi < wEls.length; wi++) {
    var body = wEls[wi].querySelector('.custom-widget-body');
    if (!body) continue;
    var bgImg = body.querySelector('img[style*="z-index:0"]') || body.querySelector('img');
    if (bgImg) {
      bgImg.src = src;
    } else {
      var newImg = document.createElement('img');
      newImg.src = src;
      newImg.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0';
      body.insertBefore(newImg, body.firstChild);
    }
  }
  /* 2. 同步更新存储的 imageUrl，使下次渲染生效 */
  var cwList = config.settings.customWidgets || [];
  for (var ci = 0; ci < cwList.length; ci++) {
    if (cwList[ci].id === widgetId) {
      cwList[ci].imageUrl = src;
      break;
    }
  }
  Store.set('config', config);
}
window.setCustomWidgetBgImage = setCustomWidgetBgImage;
// 注入作用域 CSS：所有选择器自动加上该组件实例的限定，避免影响其它组件
function injectCustomWidgetCss(el, def) {
  if (!def || !def.customCss) return;
  var scope = '[data-widget-id="' + el.dataset.widgetId + '"]';
  var out = [];
  def.customCss.split('}').forEach(function(rule) {
    var r = rule.trim();
    if (!r) return;
    var brace = r.indexOf('{');
    if (brace < 0) return;
    var sels = r.substring(0, brace).split(',').map(function(s) {
      s = s.trim();
      return s ? scope + ' ' + s : '';
    }).filter(Boolean).join(',');
    if (sels) out.push(sels + '{' + r.substring(brace + 1) + '}');
  });
  if (!out.length) return;
  var style = document.createElement('style');
  style.textContent = out.join('\n');
  el.appendChild(style);
}

// ----- 管理弹窗 -----
function openCustomWidgetManager() {
  renderCustomWidgetList();
  openModal('customWidgetModal');
}
function renderCustomWidgetList() {
  var box = document.getElementById('customWidgetList');
  if (!box) return;
  var list = getCustomWidgets();
  if (!list.length) {
    box.innerHTML = '<div class="cw-empty">🧩 还没有自定义小组件<br>点击下方「新建小组件」开始设计</div>';
    return;
  }
  var html = '';
  list.forEach(function(w) {
    html += '<div class="cw-list-item">' +
      '<div class="cw-list-icon" style="background:' + (w.bg || '#F5D0A9') + '">' + (w.icon || '✨') + '</div>' +
      '<div style="flex:1;min-width:0"><div class="cw-list-name">' + escapeHtml(w.name || '未命名') + '</div>' +
      '<div class="cw-list-desc">占 ' + widgetSpanLabel(w.span) + ' 格' + (findWidgetPage(w.id) ? ' · 已在主屏幕' : '') + '</div></div>' +
      '<div class="cw-mini-btn cw-edit-btn" onclick="openCustomWidgetEditor(\'' + w.id + '\')">编辑</div>' +
      '<div class="cw-mini-btn cw-del-btn" onclick="deleteCustomWidget(\'' + w.id + '\')">删除</div></div>';
  });
  box.innerHTML = html;
}

// ----- 编辑弹窗 -----
var _cwEditSpan = 'w2 h2';
function openCustomWidgetEditor(id) {
  var w = null;
  var list = getCustomWidgets();
  if (id) {
    for (var i = 0; i < list.length; i++) { if (list[i].id === id) { w = list[i]; break; } }
  }
  document.getElementById('cwEditId').value = w ? w.id : '';
  document.getElementById('customWidgetEditTitle').textContent = w ? '编辑小组件' : '新建小组件';
  document.getElementById('cwNameInput').value = w ? (w.name || '') : '';
  document.getElementById('cwIconInput').value = w ? (w.icon || '') : '';
  document.getElementById('cwBgInput').value = w ? (w.bg || '') : '';
  document.getElementById('cwFrostedInput').checked = w ? !!w.frosted : false;
  document.getElementById('cwImageUrlInput').value = w ? (w.imageUrl || '') : '';
  document.getElementById('cwCutoutUrlInput').value = w ? (w.cutoutUrl || '') : '';
  document.getElementById('cwHtmlInput').value = w ? (w.html || '') : '';
  document.getElementById('cwCssInput').value = w ? (w.css || '') : '';
  document.getElementById('cwTextInput').value = w ? (w.text || '') : '';
  _cwEditSpan = w ? (w.span || 'w2 h2') : 'w2 h2';
  // 加载照片区域设置（支持多区域 + 向后兼容旧格式）
  _cwPhotoZones = [];
  if (w && w.photoZones && w.photoZones.length) {
    _cwPhotoZones = w.photoZones.map(function(z) {
      return { left: z.left || 0, top: z.top || 0, width: z.width || 50, height: z.height || 50, radius: z.radius || 0 };
    });
  } else if (w && w.photoZone && w.photoZoneStyle) {
    /* 兼容旧格式：单个 photoZoneStyle 字符串 */
    var pzOld = w.photoZoneStyle;
    var matchOld = function(prop) { var m = pzOld.match(new RegExp(prop + '\\s*:\\s*([\\d.]+)')); return m ? parseFloat(m[1]) : 0; };
    _cwPhotoZones = [{ left: matchOld('left') || 0, top: matchOld('top') || 0, width: matchOld('width') || 100, height: matchOld('height') || 100, radius: (function(){ var rm = pzOld.match(/border-radius\s*:\s*(\d+)/); return rm ? parseInt(rm[1],10) : 0; })() }];
  }
  cwUpdatePzInfo();
  // 默认显示第一个标签
  cwSwitchTab('file');
  renderCwSizeGrid();
  updateCustomWidgetPreview();
  openModal('customWidgetEditModal');
}
function cwUploadImage() {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = function(ev) {
    var file = ev.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function() {
      document.getElementById('cwImageUrlInput').value = reader.result;
      updateCustomWidgetPreview();
    };
    reader.readAsDataURL(file);
  };
  input.click();
}
function cwUploadFile() {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = '.html,.htm,.txt,.css';
  input.onchange = function(ev) {
    var file = ev.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function() {
      var content = reader.result || '';
      var name = (file.name || '').toLowerCase();
      if (name.endsWith('.css')) {
        document.getElementById('cwCssInput').value = content;
      } else {
        document.getElementById('cwHtmlInput').value = content;
      }
      updateCustomWidgetPreview();
      showToast('文件「' + file.name + '」已导入');
    };
    reader.readAsText(file);
  };
  input.click();
}

// ===== 智能抠图功能 =====
var _cutoutOriginalImage = null;
var _cutoutHistory = [];
var _cutoutCanvas = null;
var _cutoutCtx = null;
var _cutoutTarget = 'image';

function cwUploadImageWithCutout() {
  var input = document.createElement('input');
  input.type = 'file';
  input.accept = 'image/*';
  input.onchange = function(ev) {
    var file = ev.target.files[0];
    if (!file) return;
    var reader = new FileReader();
    reader.onload = function() {
      var img = new Image();
      img.onload = function() {
        _cutoutOriginalImage = img;
        _cutoutTarget = 'image';
        openCutoutModal(img);
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  };
  input.click();
}

/* 智能抠图：点击图片空白处自动去除背景 */

/**
 * 智能抠图：点击图片中的空白区域，自动 flood fill 去除相似颜色背景
 */
function cutoutSmartRemove(clickX, clickY) {
  if (!_cutoutCtx || !_cutoutCanvas) return;
  var procEl = document.getElementById('cutoutProcessing');
  if (procEl) procEl.style.display = 'block';
  _cutoutCanvas.style.opacity = '0.3';

  saveCutoutHistory();

  setTimeout(function() {
    try {
      var w = _cutoutCanvas.width;
      var h = _cutoutCanvas.height;
      var imageData = _cutoutCtx.getImageData(0, 0, w, h);
      var data = imageData.data;

      var idx = (clickY * w + clickX) * 4;
      var bgR = data[idx];
      var bgG = data[idx + 1];
      var bgB = data[idx + 2];
      var tol = parseInt(document.getElementById('cutoutTolerance').value, 10) || 40;

      var visited = new Uint8Array(w * h);
      var queue = [clickY * w + clickX];
      visited[clickY * w + clickX] = 1;

      function isBg(px) {
        var r = data[px * 4], g = data[px * 4 + 1], b = data[px * 4 + 2];
        var dr = r - bgR, dg = g - bgG, db = b - bgB;
        var dist = Math.sqrt(dr * dr + dg * dg + db * db);
        return dist < tol;
      }

      var head = 0;
      while (head < queue.length) {
        var curIdx = queue[head++];
        var px = curIdx % w;
        var py = Math.floor(curIdx / w);

        if (!isBg(curIdx)) continue;

        data[curIdx * 4 + 3] = 0;

        if (px > 0 && !visited[curIdx - 1]) { visited[curIdx - 1] = 1; queue.push(curIdx - 1); }
        if (px < w - 1 && !visited[curIdx + 1]) { visited[curIdx + 1] = 1; queue.push(curIdx + 1); }
        if (py > 0 && !visited[curIdx - w]) { visited[curIdx - w] = 1; queue.push(curIdx - w); }
        if (py < h - 1 && !visited[curIdx + w]) { visited[curIdx + w] = 1; queue.push(curIdx + w); }
      }

      /* 边缘羽化 */
      for (var y = 1; y < h - 1; y++) {
        for (var x = 1; x < w - 1; x++) {
          var i = y * w + x;
          if (data[i * 4 + 3] === 255) {
            var hasTransparent =
              data[(i - 1) * 4 + 3] === 0 ||
              data[(i + 1) * 4 + 3] === 0 ||
              data[(i - w) * 4 + 3] === 0 ||
              data[(i + w) * 4 + 3] === 0;
            if (hasTransparent) {
              data[i * 4 + 3] = 180;
            }
          }
        }
      }

      _cutoutCtx.putImageData(imageData, 0, 0);
      if (procEl) procEl.style.display = 'none';
      _cutoutCanvas.style.opacity = '1';
      if (typeof showToast === 'function') showToast('已去除背景，可继续点击其他区域');
    } catch(e) {
      console.error('cutoutSmartRemove error:', e);
      if (procEl) procEl.style.display = 'none';
      _cutoutCanvas.style.opacity = '1';
      if (typeof showToast === 'function') showToast('抠图失败，请重试');
    }
  }, 50);
}

function openCutoutModal(img) {
  openModal('cutoutModal');
  _cutoutCanvas = document.getElementById('cutoutCanvas');
  _cutoutCtx = _cutoutCanvas.getContext('2d');

  var maxW = 320;
  var scale = Math.min(1, maxW / img.width);
  var w = Math.round(img.width * scale);
  var h = Math.round(img.height * scale);
  _cutoutCanvas.width = w;
  _cutoutCanvas.height = h;
  _cutoutCtx.drawImage(img, 0, 0, w, h);

  _cutoutHistory = [];
  saveCutoutHistory();

  _cutoutCanvas.style.width = w + 'px';
  _cutoutCanvas.style.height = h + 'px';

  var procEl = document.getElementById('cutoutProcessing');
  if (procEl) procEl.style.display = 'none';

  /* 点击空白区域自动抠图 */
  _cutoutCanvas.onmousedown = function(e) {
    var pos = cutoutGetPos(e);
    cutoutSmartRemove(Math.round(pos.x), Math.round(pos.y));
  };
  _cutoutCanvas.ontouchstart = function(e) {
    e.preventDefault();
    var pos = cutoutGetPos(e.touches[0]);
    cutoutSmartRemove(Math.round(pos.x), Math.round(pos.y));
  };
}

function cutoutGetPos(e) {
  var rect = _cutoutCanvas.getBoundingClientRect();
  var scaleX = _cutoutCanvas.width / rect.width;
  var scaleY = _cutoutCanvas.height / rect.height;
  return {
    x: (e.clientX - rect.left) * scaleX,
    y: (e.clientY - rect.top) * scaleY
  };
}

function saveCutoutHistory() {
  try {
    var data = _cutoutCtx.getImageData(0, 0, _cutoutCanvas.width, _cutoutCanvas.height);
    _cutoutHistory.push(data);
    if (_cutoutHistory.length > 20) _cutoutHistory.shift();
  } catch(e) {}
}

function cutoutReset() {
  if (!_cutoutOriginalImage || !_cutoutCtx) return;
  _cutoutCtx.clearRect(0, 0, _cutoutCanvas.width, _cutoutCanvas.height);
  _cutoutCtx.drawImage(_cutoutOriginalImage, 0, 0, _cutoutCanvas.width, _cutoutCanvas.height);
  _cutoutHistory = [];
  saveCutoutHistory();
}

function cutoutUndo() {
  if (_cutoutHistory.length <= 1) return;
  _cutoutHistory.pop();
  var prev = _cutoutHistory[_cutoutHistory.length - 1];
  _cutoutCtx.putImageData(prev, 0, 0);
}

function cutoutConfirm() {
  if (!_cutoutCanvas) return;
  var dataUrl = _cutoutCanvas.toDataURL('image/png');
  if (_cutoutTarget === 'image') {
    document.getElementById('cwCutoutUrlInput').value = dataUrl;
    /* 抠图后不再自动把原图填进背景图层 z0：否则抠掉的背景又会被原图白底盖回来，
       导致「抠图了却透不出壁纸」。留空 z0，让抠图透明处直接透出壁纸。
       若需要给组件配一张底图，请用「📷 上传」单独设置背景图。 */
  }
  updateCustomWidgetPreview();
  closeModal('cutoutModal');
  showToast('抠图完成 ✿');
}

// ===== 三模块切换 =====
function cwSwitchTab(tab) {
  ['file', 'image', 'text'].forEach(function(t) {
    var content = document.getElementById('cwTab' + t.charAt(0).toUpperCase() + t.slice(1));
    var btn = document.querySelector('.cw-tab-btn[data-tab="' + t + '"]');
    if (content) content.style.display = (t === tab) ? 'block' : 'none';
    if (btn) {
      if (t === tab) { btn.classList.add('active'); btn.style.background = ''; btn.style.color = ''; }
      else { btn.classList.remove('active'); btn.style.background = '#F5F5F5'; btn.style.color = '#8E8E93'; }
    }
  });
  updateCustomWidgetPreview();
}

/* 照片区域：点击预览空白处自动放置，和抠图一样的方式，最多3个 */
var CW_PZ_DEFAULT_SIZE = 50; /* 默认照片区域宽高百分比 */
var CW_PZ_MAX = 3; /* 最多照片区域数量 */
var _cwPhotoZones = []; /* 编辑中的照片区域数组 [{left,top,width,height,radius}] */

function cwUpdatePzInfo() {
  var n = _cwPhotoZones.length;
  var info = document.getElementById('cwPzInfo');
  if (!info) return;
  if (n === 0) {
    info.textContent = '未设置照片区域（0/' + CW_PZ_MAX + '）';
    return;
  }
  var parts = [];
  for (var i = 0; i < n; i++) {
    var z = _cwPhotoZones[i];
    parts.push('#' + (i + 1) + ' 左' + z.left + '% 上' + z.top + '% ' + z.width + '×' + z.height + '%');
  }
  info.textContent = '照片区域（' + n + '/' + CW_PZ_MAX + '）：' + parts.join('，');
}

function cwPlacePhotoZoneAt(clickX, clickY) {
  /* 以点击点为中心，放置默认大小的照片区域 */
  var size = CW_PZ_DEFAULT_SIZE;
  var left = Math.max(0, Math.round(clickX - size / 2));
  var top = Math.max(0, Math.round(clickY - size / 2));
  left = Math.min(left, 100 - size);
  top = Math.min(top, 100 - size);
  var zone = { left: left, top: top, width: size, height: size, radius: 0 };

  if (_cwPhotoZones.length >= CW_PZ_MAX) {
    /* 已满3个：替换最后一个 */
    _cwPhotoZones[CW_PZ_MAX - 1] = zone;
    showToast('照片区域已满3个，已替换最后一个 ✿');
  } else {
    _cwPhotoZones.push(zone);
    showToast('照片区域 ' + _cwPhotoZones.length + '/' + CW_PZ_MAX + ' 已放置 ✿');
  }
  cwUpdatePzInfo();
  updateCustomWidgetPreview();
}

function cwClearPhotoZone() {
  _cwPhotoZones = [];
  cwUpdatePzInfo();
  updateCustomWidgetPreview();
}
var CW_MAX_WIDTH = 4;
var CW_MAX_HEIGHT = 3;

function renderCwSizeGrid() {
  var curW = 2, curH = 2;
  var m = (_cwEditSpan || '').match(/w(\d)/);
  var m2 = (_cwEditSpan || '').match(/h(\d)/);
  if (m) curW = parseInt(m[1], 10);
  if (m2) curH = parseInt(m2[1], 10);
  curW = Math.max(1, Math.min(CW_MAX_WIDTH, curW));
  curH = Math.max(1, Math.min(CW_MAX_HEIGHT, curH));

  var wGrid = document.getElementById('cwWidthGrid');
  var hGrid = document.getElementById('cwHeightGrid');
  if (wGrid) {
    wGrid.innerHTML = '';
    for (var w = 1; w <= CW_MAX_WIDTH; w++) {
      var opt = document.createElement('div');
      opt.className = 'cw-size-opt' + (w === curW ? ' active' : '');
      opt.textContent = w + '格';
      opt.dataset.w = w;
      opt.onclick = function() {
        var selW = parseInt(this.dataset.w, 10);
        var selH = parseInt((_cwEditSpan.match(/h(\d)/) || [])[1] || 2, 10);
        _cwEditSpan = 'w' + selW + ' h' + selH;
        renderCwSizeGrid();
        updateCustomWidgetPreview();
      };
      wGrid.appendChild(opt);
    }
  }
  if (hGrid) {
    hGrid.innerHTML = '';
    for (var h = 1; h <= CW_MAX_HEIGHT; h++) {
      var opt2 = document.createElement('div');
      opt2.className = 'cw-size-opt' + (h === curH ? ' active' : '');
      opt2.textContent = h + '格';
      opt2.dataset.h = h;
      opt2.onclick = function() {
        var selH = parseInt(this.dataset.h, 10);
        var selW = parseInt((_cwEditSpan.match(/w(\d)/) || [])[1] || 2, 10);
        _cwEditSpan = 'w' + selW + ' h' + selH;
        renderCwSizeGrid();
        updateCustomWidgetPreview();
      };
      hGrid.appendChild(opt2);
    }
  }
  var label = document.getElementById('cwSizeLabel');
  if (label) label.textContent = curW + ' × ' + curH + ' 格';
}
function updateCustomWidgetPreview() {
  var box = document.getElementById('cwPreviewBox');
  if (!box) return;
  var frosted = document.getElementById('cwFrostedInput') && document.getElementById('cwFrostedInput').checked;
  var bg = document.getElementById('cwBgInput').value.trim();
  if (frosted) { if (!bg || bg === 'transparent') bg = 'rgba(255,255,255,0.35)'; }
  else { bg = bg || 'transparent'; }
  var glassCls = frosted ? ' cw-glass' : '';
  var html = document.getElementById('cwHtmlInput').value;
  var css = document.getElementById('cwCssInput').value;
  var text = document.getElementById('cwTextInput') ? document.getElementById('cwTextInput').value : '';
  var imgUrl = document.getElementById('cwImageUrlInput').value.trim();
  var cutoutUrl = document.getElementById('cwCutoutUrlInput') ? document.getElementById('cwCutoutUrlInput').value.trim() : '';
  var s = widgetSpanOf({ span: _cwEditSpan });

  /* 层级：z0=背景图 → z1=照片区域 → z2=抠图层 → z3=HTML/文案 */
  var imgHtml = imgUrl ? '<img src="' + imgUrl + '" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:0" alt="">' : '';
  var photoZoneHtml = '';
  for (var pi = 0; pi < _cwPhotoZones.length; pi++) {
    var pz = _cwPhotoZones[pi];
    photoZoneHtml += '<div class="cw-pz-preview" data-pz-idx="' + pi + '" style="position:absolute;z-index:1;left:' + pz.left + '%;top:' + pz.top + '%;width:' + pz.width + '%;height:' + pz.height + '%;border-radius:' + (pz.radius || 0) + 'px;overflow:hidden;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.15);color:rgba(255,255,255,0.5);font-size:16px;cursor:pointer">📷' + (pi + 1) + '</div>';
  }
  var cutoutHtml = cutoutUrl ? '<img src="' + cutoutUrl + '" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:2;pointer-events:none" alt="">' : '';
  var contentHtml = (html || text) ? '<div style="position:relative;z-index:3">' + (text || html) + '</div>' : '';

  box.innerHTML = '<div class="home-widget custom-widget' + glassCls + ' ' + _cwEditSpan + '" style="background:' + bg +
    ';width:' + (s.w * 25) + '%;height:' + (s.h * 58 + (s.h - 1) * 8) + 'px;cursor:crosshair">' +
    '<div class="custom-widget-body">' + imgHtml + photoZoneHtml + cutoutHtml + contentHtml + '</div></div>';

  /* 点击预览空白处自动放置照片区域；点击已有区域可删除单个 */
  var widgetEl = box.querySelector('.home-widget');
  if (widgetEl) {
    widgetEl.onmousedown = function(e) {
      var existingZone = e.target.closest('.cw-pz-preview');
      if (existingZone) {
        /* 点击已有照片区域：删除该区域 */
        var idx = parseInt(existingZone.dataset.pzIdx, 10);
        if (!isNaN(idx) && idx < _cwPhotoZones.length) {
          _cwPhotoZones.splice(idx, 1);
          cwUpdatePzInfo();
          updateCustomWidgetPreview();
          showToast('已删除照片区域 #' + (idx + 1));
        }
        return;
      }
      var rect = widgetEl.getBoundingClientRect();
      var x = (e.clientX - rect.left) / rect.width * 100;
      var y = (e.clientY - rect.top) / rect.height * 100;
      cwPlacePhotoZoneAt(x, y);
    };
    widgetEl.ontouchstart = function(e) {
      var existingZone = e.target.closest('.cw-pz-preview');
      if (existingZone) {
        e.preventDefault();
        var idx = parseInt(existingZone.dataset.pzIdx, 10);
        if (!isNaN(idx) && idx < _cwPhotoZones.length) {
          _cwPhotoZones.splice(idx, 1);
          cwUpdatePzInfo();
          updateCustomWidgetPreview();
          showToast('已删除照片区域 #' + (idx + 1));
        }
        return;
      }
      e.preventDefault();
      var rect = widgetEl.getBoundingClientRect();
      var t = e.touches[0];
      var x = (t.clientX - rect.left) / rect.width * 100;
      var y = (t.clientY - rect.top) / rect.height * 100;
      cwPlacePhotoZoneAt(x, y);
    };
  }

  var old = document.getElementById('cw-preview-css');
  if (old) old.remove();
  if (css.trim()) {
    var style = document.createElement('style');
    style.id = 'cw-preview-css';
    style.textContent = '#cwPreviewBox ' + css.split('}').join('} #cwPreviewBox ');
    document.head.appendChild(style);
  }
}
function saveCustomWidgetFromEditor() {
  var id = document.getElementById('cwEditId').value;
  var name = document.getElementById('cwNameInput').value.trim();
  var icon = document.getElementById('cwIconInput').value.trim() || '✨';
  var frosted = document.getElementById('cwFrostedInput') && document.getElementById('cwFrostedInput').checked;
  var bg = document.getElementById('cwBgInput').value.trim() || 'transparent';
  var html = document.getElementById('cwHtmlInput').value;
  var css = document.getElementById('cwCssInput').value;
  var text = document.getElementById('cwTextInput').value;
  var imageUrl = document.getElementById('cwImageUrlInput').value.trim();
  var cutoutUrl = document.getElementById('cwCutoutUrlInput').value.trim();
  if (!name) { showToast('请给小组件起个名字'); return; }
  if (!html.trim() && !text.trim() && !imageUrl && !cutoutUrl) { showToast('请填写内容、上传图片或文案'); return; }

  // 构建照片区域数据（支持多区域）
  var photoZones = _cwPhotoZones.map(function(z) {
    return { left: z.left, top: z.top, width: z.width, height: z.height, radius: z.radius || 0 };
  });
  var hasPhotoZone = photoZones.length > 0;

  var isTextOnly = text.trim() && !imageUrl && !cutoutUrl;
  var widgetData = {
    id: id || ('cw_' + Date.now()),
    name: name, icon: icon, bg: bg, frosted: frosted, span: _cwEditSpan,
    html: html, css: css, text: text,
    imageUrl: imageUrl, cutoutUrl: cutoutUrl,
    photoZone: hasPhotoZone, photoZones: photoZones,
    textOnly: isTextOnly
  };

  var list = getCustomWidgets();
  if (id) {
    var found = false;
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === id) { list[i] = widgetData; found = true; break; }
    }
    if (!found) list.push(widgetData);
  } else {
    list.push(widgetData);
  }
  saveCustomWidgets(list);
  registerCustomWidgets();
  renderHomeWidgets();
  closeModal('customWidgetEditModal');
  renderCustomWidgetList();
  if (typeof updateSettingsView === 'function') updateSettingsView();
  showToast('小组件已保存，去「＋ 添加小组件」放到主屏幕吧 ✿');
}
function deleteCustomWidget(id) {
  var list = getCustomWidgets();
  var idx = -1;
  for (var i = 0; i < list.length; i++) { if (list[i].id === id) { idx = i; break; } }
  if (idx < 0) return;
  if (!confirm('删除小组件「' + (list[idx].name || '') + '」？\n主屏幕上的该组件也会一并移除。')) return;
  list.splice(idx, 1);
  saveCustomWidgets(list);
  // 从各页小组件列表移除
  var data = getHomeWidgetsData();
  ['p1', 'p2'].forEach(function(p) {
    var wi = data[p].indexOf(id);
    if (wi >= 0) data[p].splice(wi, 1);
  });
  saveHomeWidgetsData(data);
  registerCustomWidgets();
  renderHomeWidgets();
  renderCustomWidgetList();
  if (typeof updateSettingsView === 'function') updateSettingsView();
  showToast('已删除');
}

// ===== 清理之前上传的设计图小组件（必须在 Store 就绪后执行）=====
function cleanupDesignWidgets() {
  /* 安全检查：如果 config 是空默认配置（无角色、无用户名），说明 IndexedDB 尚未加载，不执行任何写入 */
  if ((!config.characters || config.characters.length === 0) && (!config.user || !config.user.name) && (!config.presets || config.presets.length === 0)) {
    console.warn('cleanupDesignWidgets: config appears empty, skipping to prevent data overwrite');
    return;
  }
  /* 只运行一次 */
  if (localStorage.getItem('mochi_design_cleaned')) return;
  localStorage.setItem('mochi_design_cleaned', '1');

  var existing = getCustomWidgets();
  var hasDesign = false;
  for (var i = 0; i < existing.length; i++) {
    if (existing[i].id && existing[i].id.indexOf('design_') === 0) { hasDesign = true; break; }
  }
  if (!hasDesign) return;

  var kept = [];
  for (var i = 0; i < existing.length; i++) {
    if (existing[i].id && existing[i].id.indexOf('design_') === 0) continue;
    kept.push(existing[i]);
  }
  saveCustomWidgets(kept);
  /* 直接操作 localStorage 原始数据，不经过 getHomeWidgetsData 的 valid 过滤 */
  try {
    var raw = readUiStateRaw('home_widgets');
    if (raw) {
      var data = JSON.parse(raw);
      if (Array.isArray(data)) {
        data = data.filter(function(id) { return !id || id.indexOf('design_') !== 0; });
        data = { p1: data, p2: [] };
      } else if (data && typeof data === 'object') {
        ['p1', 'p2'].forEach(function(p) {
          if (Array.isArray(data[p])) {
            data[p] = data[p].filter(function(id) { return !id || id.indexOf('design_') !== 0; });
          }
        });
      }
      saveUiState('home_widgets', data);
    }
  } catch(e) { console.warn('cleanup home widgets error:', e); }
}
/* 必须等 IndexedDB 加载完成后才执行，否则可能用空配置覆盖真实数据 */
onStoreReady(function() {
  try { cleanupDesignWidgets(); } catch(e) { console.warn('cleanupDesignWidgets error:', e); }
});

/* ===== 主屏幕默认排版 v2 一次性迁移 =====
   旧存档没有组件显式位置，自动摆放会把时钟/天气放反、照片组件溢出丢失。
   迁移：APP 写入新默认槽位；组件写入新默认列表+位置；已上传的照片按顺序保留到新组件实例。
   已有显式位置的存档（自己拖好的）不动。 */
function migrateHomeLayoutV2() {
  try {
    if (localStorage.getItem('mochi_home_layout_v2')) return;
    var rawW = null;
    try { rawW = JSON.parse(readUiStateRaw('home_widgets') || 'null'); } catch(e) {}
    var hasPositions = !!(rawW && !Array.isArray(rawW) && rawW._positions && rawW._positions.p1 && Object.keys(rawW._positions.p1).length > 0);
    if (!hasPositions) {
      /* 1. 收集旧照片组件实例，按顺序把图片迁到新实例 */
      var oldIds = [];
      if (Array.isArray(rawW)) oldIds = rawW;
      else if (rawW && Array.isArray(rawW.p1)) oldIds = rawW.p1;
      var oldPhotoIds = oldIds.filter(function(id) { return id && id.split('__')[0] === 'photos'; });
      var newPhotoIds = ['photos__def_a', 'photos__def_b'];
      if (config.widgetImages) {
        for (var i = 0; i < oldPhotoIds.length && i < newPhotoIds.length; i++) {
          var img = config.widgetImages[oldPhotoIds[i]];
          if (img && !config.widgetImages[newPhotoIds[i]]) {
            config.widgetImages[newPhotoIds[i]] = img;
          }
        }
        Store.set('config', config);
      }
      /* 2. 写入新默认组件列表 + 显式位置 */
      var newData = {
        p1: ['clock', 'weather', 'photos__def_a', 'photos__def_b'],
        p2: [],
        _positions: {
          p1: {
            'clock': { col: 0, row: 0 },
            'weather': { col: 0, row: 2 },
            'photos__def_a': { col: 2, row: 3 },
            'photos__def_b': { col: 0, row: 5 }
          },
          p2: {}
        }
      };
      saveUiState('home_widgets', newData);
      /* 3. 写入新默认 APP 布局 */
      var layout = [];
      for (var di = 0; di < APPS_PER_PAGE * 2; di++) layout.push(null);
      layout[12] = 'charmanager'; layout[13] = 'social';
      layout[16] = 'offline'; layout[17] = 'relation';
      layout[22] = 'map'; layout[23] = 'shop';
      layout[26] = 'world'; layout[27] = 'memory';
      layout[28] = 'food'; layout[29] = 'commission';
      layout[30] = 'doujin'; layout[31] = 'npc';
      layout[32] = 'phonecheck';
      saveAppLayout(layout);
    }
    localStorage.setItem('mochi_home_layout_v2', '1');
  } catch(e) { console.warn('migrateHomeLayoutV2 error:', e); }
}
onStoreReady(function() {
  try {
    migrateHomeLayoutV2();
    if (typeof renderHomeScreen === 'function') renderHomeScreen();
  } catch(e) { console.warn('migrateHomeLayoutV2 run error:', e); }
});

// 初始化：注册自定义小组件 + 渲染 Dock 栏（try 保护，避免影响后续初始化代码）
