try { renderDock(); } catch(e) { console.warn('renderDock error:', e); }

// ===== 主屏幕壁纸 =====
var HOME_WALLPAPER_PRESETS = [
  { name: '樱花粉', css: 'linear-gradient(175deg,#FFF5F8 0%,#FFF0F5 35%,#FDF0F5 70%,#FFF5F8 100%)' },
  { name: '薄雾蓝', css: 'linear-gradient(175deg,#EFF5FB 0%,#E3EEF8 50%,#EDF3FA 100%)' },
  { name: '抹茶绿', css: 'linear-gradient(175deg,#F1F8EF 0%,#E5F1E3 50%,#EDF5EA 100%)' },
  { name: '薰衣草', css: 'linear-gradient(175deg,#F4F0FB 0%,#EAE3F6 50%,#F1ECF9 100%)' },
  { name: '蜜桃橙', css: 'linear-gradient(175deg,#FFF5EB 0%,#FDEBDA 50%,#FDF1E4 100%)' },
  { name: '静谧夜', css: 'linear-gradient(175deg,#3A3A4C 0%,#2B2B3A 55%,#232330 100%)' }
];

/* 统一入口：type = 'home'（桌面壁纸）| 'lock'（锁屏壁纸）
   设置 → 自定义外观 的两个入口都走这里；旧的 openHomeWallpaperModal() 调用点保持不变 */
function openWallpaperModal(type) {
  _wpCurrentType = (type === 'lock') ? 'lock' : 'home';
  wpSyncTabs();
  wpSyncTitle();
  renderWallpaperPresets();
  openModal('homeWallpaperModal');
}

function wpSyncTabs() {
  var th = document.getElementById('wpTabHome');
  var tl = document.getElementById('wpTabLock');
  if (th) th.className = 'wp-tab' + (_wpCurrentType === 'home' ? ' active' : '');
  if (tl) tl.className = 'wp-tab' + (_wpCurrentType === 'lock' ? ' active' : '');
}

function wpSyncTitle() {
  var title = document.getElementById('homeWallpaperModalTitle');
  if (title) title.textContent = (_wpCurrentType === 'lock') ? '更换锁屏壁纸' : '更换壁纸';
}

function openHomeWallpaperModal() { openWallpaperModal('home'); }
function openLockWallpaperModal() { openWallpaperModal('lock'); }
window.openHomeWallpaperModal = openHomeWallpaperModal;
window.openLockWallpaperModal = openLockWallpaperModal;

function applyHomeWallpaper() {
  var ps = document.querySelector('.phone-screen');
  if (!ps) return;
  var wp = config.settings.homeWallpaper;
  if (!wp || !wp.value) {
    ps.style.background = '';
    return;
  }
  if (wp.type === 'image') {
    ps.style.background = 'url(' + wp.value + ') center/cover no-repeat';
  } else {
    ps.style.background = wp.value;
  }
}
window.applyHomeWallpaper = applyHomeWallpaper;
applyHomeWallpaper();

// ===== 壁纸类型切换（桌面/锁屏） =====
var _wpCurrentType = 'home'; /* 'home' or 'lock' */

function wpSwitchType(type) {
  _wpCurrentType = (type === 'lock') ? 'lock' : 'home';
  wpSyncTabs();
  wpSyncTitle();
  renderWallpaperPresets();
}

/* 重写 renderWallpaperPresets 支持桌面/锁屏 */
function renderWallpaperPresets() {
  var grid = document.getElementById('wallpaperPresetGrid');
  if (!grid) return;
  var wpKey = _wpCurrentType === 'lock' ? 'lockWallpaper' : 'homeWallpaper';
  var cur = (config.settings[wpKey] && config.settings[wpKey].value) || '';
  var html = '';
  HOME_WALLPAPER_PRESETS.forEach(function(p, i) {
    html += '<div class="wallpaper-preset' + (cur === p.css ? ' active' : '') +
      '" style="background:' + p.css + '" onclick="setWallpaperPreset(' + i + ')">' +
      '<div class="wp-name">' + p.name + '</div></div>';
  });
  if (config.settings[wpKey] && config.settings[wpKey].type === 'image') {
    html += '<div class="wallpaper-preset active" style="background:url(' + config.settings[wpKey].value + ') center/cover">' +
      '<div class="wp-name">自定义</div></div>';
  }
  grid.innerHTML = html;
  renderWallpaperPreview();
}

/* 弹窗内实时预览：设置页是不透明实心底（#view-settings 背景 #FAF3EE），
   改完壁纸必须退回主屏才看得见，所以在弹窗里给一条即时反馈。
   未自定义时直接镜像真实目标的背景，避免和 CSS 默认值漂移。 */
function renderWallpaperPreview() {
  var box = document.getElementById('wpPreview');
  if (!box) return;
  var wpKey = _wpCurrentType === 'lock' ? 'lockWallpaper' : 'homeWallpaper';
  var wp = config.settings[wpKey];
  var followsHome = false;
  if (_wpCurrentType === 'lock' && (!wp || !wp.value)) {
    /* 与 applyLockWallpaper 同一规则：锁屏未自定义时跟随桌面壁纸。
       注意 #lockscreen 的内联背景此时可能还是启动时的深色兜底，不能直接照抄 DOM。 */
    var hwp = config.settings.homeWallpaper;
    if (hwp && hwp.value) { wp = hwp; followsHome = true; }
  }
  if (wp && wp.value) {
    box.style.background = (wp.type === 'image')
      ? 'url(' + wp.value + ') center/cover no-repeat'
      : wp.value;
  } else {
    /* 未自定义：逐条镜像真实目标的计算样式（#wpPreview 自己不能带 transform/其它装饰，
       直接拼 background 简写会被浏览器判为非法而整条丢弃，所以用长写属性逐条赋值）。 */
    var target = (_wpCurrentType === 'lock')
      ? document.getElementById('lockscreen')
      : document.querySelector('.phone-screen');
    if (target) {
      var cs = window.getComputedStyle(target);
      box.style.background = '';
      box.style.backgroundImage = cs.backgroundImage;
      box.style.backgroundColor = cs.backgroundColor;
      box.style.backgroundRepeat = cs.backgroundRepeat;
      box.style.backgroundSize = cs.backgroundSize;
      box.style.backgroundPosition = cs.backgroundPosition;
      box.style.backgroundOrigin = cs.backgroundOrigin;
      box.style.backgroundClip = cs.backgroundClip;
    } else {
      box.style.background = '';
      box.style.backgroundColor = '#FFF5F8';
    }
  }
  var label = document.getElementById('wpPreviewLabel');
  if (label) {
    if (_wpCurrentType === 'lock') {
      label.textContent = followsHome ? '锁屏预览 · 跟随桌面壁纸' : '锁屏预览';
    } else {
      label.textContent = '桌面预览';
    }
  }
}

/* 设置页「更换壁纸 / 锁屏壁纸」右侧状态文案 */
function updateWallpaperSettingLabels() {
  [['settingsHomeWallpaper', 'homeWallpaper'], ['settingsLockWallpaper', 'lockWallpaper']].forEach(function(pair) {
    var el = document.getElementById(pair[0]);
    if (!el) return;
    var wp = config.settings[pair[1]];
    if (!wp || !wp.value) { el.textContent = '默认'; return; }
    if (wp.type === 'image') { el.textContent = '自定义图片'; return; }
    var name = '';
    for (var i = 0; i < HOME_WALLPAPER_PRESETS.length; i++) {
      if (HOME_WALLPAPER_PRESETS[i].css === wp.value) { name = HOME_WALLPAPER_PRESETS[i].name; break; }
    }
    el.textContent = name || '已自定义';
  });
}
window.updateWallpaperSettingLabels = updateWallpaperSettingLabels;

function setWallpaperPreset(idx) {
  var p = HOME_WALLPAPER_PRESETS[idx];
  if (!p) return;
  var wpKey = _wpCurrentType === 'lock' ? 'lockWallpaper' : 'homeWallpaper';
  config.settings[wpKey] = { type: 'gradient', value: p.css };
  Store.set('config', config);
  if (_wpCurrentType === 'home') applyHomeWallpaper();
  else applyLockWallpaper();
  renderWallpaperPresets();
  updateWallpaperSettingLabels();
  showToast((_wpCurrentType === 'lock' ? '锁屏' : '桌面') + '壁纸已更换 · ' + p.name);
}

/* 重写 handleHomeWallpaperSelect 支持桌面/锁屏 */
function handleHomeWallpaperSelect(event) {
  var file = event.target.files[0];
  if (!file) return;
  event.target.value = '';
  var wpKey = _wpCurrentType === 'lock' ? 'lockWallpaper' : 'homeWallpaper';
  var reader = new FileReader();
  reader.onload = function(e) {
    var img = new Image();
    img.onload = function() {
      var scale = Math.min(1, 720 / img.width);
      var dataUrl = e.target.result;
      try {
        var canvas = document.createElement('canvas');
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
        dataUrl = canvas.toDataURL('image/jpeg', 0.85);
      } catch(err) {}
      config.settings[wpKey] = { type: 'image', value: dataUrl };
      Store.set('config', config);
      if (_wpCurrentType === 'home') applyHomeWallpaper();
      else applyLockWallpaper();
      renderWallpaperPresets();
      updateWallpaperSettingLabels();
      showToast((_wpCurrentType === 'lock' ? '锁屏' : '桌面') + '壁纸已更换');
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

/* 重写 resetHomeWallpaper */
function resetHomeWallpaper() {
  var wpKey = _wpCurrentType === 'lock' ? 'lockWallpaper' : 'homeWallpaper';
  config.settings[wpKey] = null;
  Store.set('config', config);
  if (_wpCurrentType === 'home') applyHomeWallpaper();
  else applyLockWallpaper();
  renderWallpaperPresets();
  updateWallpaperSettingLabels();
  showToast((_wpCurrentType === 'lock' ? '锁屏' : '桌面') + '壁纸已恢复默认');
}

function setHomeWallpaperPreset(idx) { _wpCurrentType = 'home'; setWallpaperPreset(idx); }

// ===== 锁屏壁纸 =====
function applyLockWallpaper() {
  var ls = document.getElementById('lockscreen');
  if (!ls) return;
  var wp = config.settings.lockWallpaper;
  if (!wp || !wp.value) {
    /* 默认使用桌面壁纸或深色渐变 */
    var hwp = config.settings.homeWallpaper;
    if (hwp && hwp.value) {
      ls.style.background = (hwp.type === 'image') ? 'url(' + hwp.value + ') center/cover no-repeat' : hwp.value;
    } else {
      ls.style.background = 'linear-gradient(180deg,#1a1a2e 0%,#16213e 50%,#0f3460 100%)';
    }
    return;
  }
  if (wp.type === 'image') {
    ls.style.background = 'url(' + wp.value + ') center/cover no-repeat';
  } else {
    ls.style.background = wp.value;
  }
}

// ===== 锁屏密码 =====
function saveLockPassword() {
  var input = document.getElementById('lockPasswordSetInput');
  var pwd = input.value.trim();
  if (!pwd || pwd.length !== 4 || !/^\d{4}$/.test(pwd)) {
    showToast('请输入4位数字密码');
    return;
  }
  if (!config.settings.lock) config.settings.lock = {};
  config.settings.lock.password = pwd;
  Store.set('config', config);
  updateLockPasswordStatus();
  closeModal('lockPasswordModal');
  showToast('锁屏密码已设置');
}

function clearLockPassword() {
  if (!config.settings.lock) config.settings.lock = {};
  config.settings.lock.password = '';
  Store.set('config', config);
  updateLockPasswordStatus();
  closeModal('lockPasswordModal');
  showToast('锁屏密码已清除，滑动直接解锁');
}

function updateLockPasswordStatus() {
  var el = document.getElementById('settingsLockPassword');
  if (el) el.textContent = (config.settings.lock && config.settings.lock.password) ? '已设置' : '未设置';
}

// ===== 锁屏显示/隐藏 =====
var _lockInputBuffer = '';

function lockNow() {
  goHome();
  setTimeout(showLockscreen, 100);
}

function showLockscreen() {
  var ls = document.getElementById('lockscreen');
  if (!ls) return;
  applyLockWallpaper();
  updateLockClock();
  ls.classList.add('show');
  ls.classList.remove('unlocking');
  /* 设置密码输入模式 */
  var hasPwd = config.settings.lock && config.settings.lock.password;
  var pad = document.getElementById('lockPasswordPad');
  var slideText = document.getElementById('lockSlideText');
  if (hasPwd) {
    pad.style.display = 'flex';
    slideText.style.display = 'none';
    _lockInputBuffer = '';
    updateLockPasswordDots();
  } else {
    pad.style.display = 'none';
    slideText.style.display = 'block';
  }
  /* 渲染锁屏通知 */
  renderLockscreenNotifications();
}

function hideLockscreen() {
  var ls = document.getElementById('lockscreen');
  if (!ls) return;
  ls.classList.add('unlocking');
  setTimeout(function() {
    ls.classList.remove('show', 'unlocking');
  }, 400);
}

function updateLockClock() {
  var clockEl = document.getElementById('lockClock');
  var dateEl = document.getElementById('lockDate');
  if (!clockEl) return;
  var d = new Date();
  var hh = String(d.getHours()).padStart(2, '0');
  var mm = String(d.getMinutes()).padStart(2, '0');
  clockEl.textContent = hh + ':' + mm;
  if (dateEl) {
    var weekdays = ['星期日','星期一','星期二','星期三','星期四','星期五','星期六'];
    dateEl.textContent = (d.getMonth() + 1) + '月' + d.getDate() + '日 ' + weekdays[d.getDay()];
  }
}

/* 锁屏密码输入 */
function lockInputDigit(d) {
  if (_lockInputBuffer.length >= 4) return;
  _lockInputBuffer += d;
  updateLockPasswordDots();
  if (_lockInputBuffer.length === 4) {
    setTimeout(function() {
      var pwd = config.settings.lock && config.settings.lock.password;
      if (_lockInputBuffer === pwd) {
        hideLockscreen();
      } else {
        showToast('密码错误');
        _lockInputBuffer = '';
        updateLockPasswordDots();
      }
    }, 200);
  }
}

function lockDeleteDigit() {
  _lockInputBuffer = _lockInputBuffer.slice(0, -1);
  updateLockPasswordDots();
}

function updateLockPasswordDots() {
  var dotsEl = document.getElementById('lockPasswordDots');
  if (!dotsEl) return;
  var html = '';
  for (var i = 0; i < 4; i++) {
    html += '<div class="lock-password-dot' + (i < _lockInputBuffer.length ? ' filled' : '') + '"></div>';
  }
  dotsEl.innerHTML = html;
}

/* 锁屏滑动解锁（触摸/鼠标拖拽向上） */
(function() {
  var lockEl = null;
  var startY = 0;
  var isDragging = false;
  document.addEventListener('DOMContentLoaded', function() {
    lockEl = document.getElementById('lockscreen');
    if (!lockEl) return;
    function onStart(e) {
      if (!lockEl.classList.contains('show')) return;
      var hasPwd = config.settings.lock && config.settings.lock.password;
      if (hasPwd) return; /* 有密码时不用滑动 */
      var touch = e.touches ? e.touches[0] : e;
      startY = touch.clientY;
      isDragging = true;
    }
    function onMove(e) {
      if (!isDragging) return;
      var touch = e.touches ? e.touches[0] : e;
      var dy = startY - touch.clientY;
      if (dy > 0) {
        lockEl.style.transform = 'translateY(-' + (dy * 0.5) + 'px)';
        lockEl.style.opacity = String(Math.max(0.2, 1 - dy / 400));
      }
    }
    function onEnd(e) {
      if (!isDragging) return;
      isDragging = false;
      var touch = e.changedTouches ? e.changedTouches[0] : e;
      var dy = startY - touch.clientY;
      lockEl.style.transform = '';
      lockEl.style.opacity = '';
      if (dy > 100) {
        hideLockscreen();
      }
    }
    lockEl.addEventListener('touchstart', onStart, { passive: true });
    lockEl.addEventListener('touchmove', onMove, { passive: true });
    lockEl.addEventListener('touchend', onEnd);
    lockEl.addEventListener('mousedown', onStart);
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onEnd);
  });
})();

// ===== 通知系统 (iPhone风格) =====
var _notifIdCounter = 0;
var _activeNotifications = []; /* 锁屏上的通知列表 */
var NOTIF_AUTO_DISMISS_MS = 5000; /* 非锁屏时通知自动消失时间 */

/* ============================================================
 * 统一通知辅助：图标归一化 / 通知权限 / APP品牌解析 / 后台系统通知
 * ============================================================ */
/* 把通知图标归一化为可放进 .notification-icon 的 HTML：已是<img>直接用；data:/http 图片包成 img；否则按 emoji/文字 */
function _notifIconInner(icon, fallback) {
  var sx = (icon === 0 || icon) ? String(icon) : '';
  if (!sx) return fallback || '\uD83D\uDD14';
  if (sx.indexOf('<img') === 0) return sx;
  if (sx.indexOf('<svg') === 0) return sx;
  if (sx.indexOf('data:image') === 0 || sx.indexOf('http://') === 0 || sx.indexOf('https://') === 0) {
    return '<img src="' + sx + '" style="width:100%;height:100%;object-fit:cover;border-radius:inherit" alt="">';
  }
  return escapeHtml(sx);
}
/* 请求浏览器通知权限（已授权/被拒直接返回，不重复打扰） */
function ensureNotifPermission() {
  try {
    if (!('Notification' in window)) return Promise.resolve('unsupported');
    if (Notification.permission === 'granted') return Promise.resolve('granted');
    if (Notification.permission === 'denied') return Promise.resolve('denied');
    return Notification.requestPermission();
  } catch (e) { return Promise.resolve('error'); }
}
/* 按 appId 解析通知品牌（图标/底色/名称），覆盖内置 APP 与 MCP 自定义 APP 上传的真实图标 */
function resolveAppBrand(appId) {
  try {
    if (typeof appId === 'string' && appId.indexOf('mcp:') === 0) {
      var mid = appId.slice(4), mlist = (typeof config !== 'undefined' && config && config.mcpServers) || [];
      for (var mi = 0; mi < mlist.length; mi++) {
        if (mlist[mi].id === mid) {
          return { icon: mlist[mi].iconImage || mlist[mi].icon || '\uD83D\uDD27', bg: '#ffffff', name: mlist[mi].name || '应用', iconUrl: mlist[mi].iconImage || '' };
        }
      }
    }
    var def = (typeof getAppDef === 'function') ? getAppDef(appId) : null;
    if (def) return { icon: def.icon || '\u2728', bg: def.bg || '#576B95', name: def.name || def.label || '', iconUrl: def.iconImage || '' };
  } catch (e) {}
  return { icon: '\u2728', bg: '#576B95', name: '应用', iconUrl: '' };
}
/* 页面切后台/失焦时补发一条浏览器系统通知（前台时应用内横幅已可见，不重复弹）；带真实图标，点击回焦并跳转 */
function _maybeSystemNotification(opts) {
  try {
    if (!('Notification' in window) || Notification.permission !== 'granted') return;
    var inBg = document.hidden || (typeof document.hasFocus === 'function' && !document.hasFocus());
    if (!inBg) return;
    var title = opts.title || '通知';
    var body = opts.body || '';
    var iconUrl = opts.iconUrl || '';
    if (!iconUrl && typeof opts.icon === 'string' && (opts.icon.indexOf('data:image') === 0 || opts.icon.indexOf('http') === 0)) iconUrl = opts.icon;
    var nopt = {
      body: body,
      tag: opts.tag || ('rua-' + (opts.appId || 'app')),
      renotify: true,
      icon: iconUrl || '/icon-192.png',
      badge: '/favicon-32x32.png',
      data: { appId: opts.appId || '', url: location.href }
    };
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.ready.then(function(reg) {
        return reg.showNotification(title, nopt);
      }).catch(function(err) {
        console.warn('[通知] Service Worker 系统通知失败:', err);
      });
    }
  } catch (e) {}
}

function showNotification(opts) {
  /* opts: { appId, icon, iconBg, title, body, onTap } */
  opts = opts || {};
  var id = ++_notifIdCounter;
  var isLocked = document.getElementById('lockscreen').classList.contains('show');

  if (isLocked) {
    /* 锁屏模式：添加到锁屏通知列表 */
    _activeNotifications.push({
      id: id,
      appId: opts.appId || '',
      icon: opts.icon || '🔔',
      iconBg: opts.iconBg || '#8E8E93',
      title: opts.title || '通知',
      body: opts.body || '',
      time: Date.now(),
      onTap: opts.onTap || null
    });
    renderLockscreenNotifications();
  } else {
    /* 非锁屏：显示顶部弹窗通知 */
    var stack = document.getElementById('notificationStack');
    if (!stack) return;
    var card = document.createElement('div');
    card.className = 'notification-card';
    card.dataset.notifId = id;
    var timeStr = formatNotifTime(Date.now());
    card.innerHTML =
      '<div class="notification-icon" style="background:' + (opts.iconBg || '#8E8E93') + '">' + _notifIconInner(opts.icon, '🔔') + '</div>' +
      '<div class="notification-content">' +
      '<div class="notification-title">' + escapeHtml(opts.title || '通知') + '</div>' +
      '<div class="notification-body">' + escapeHtml(opts.body || '') + '</div>' +
      '</div>' +
      '<div class="notification-time">' + timeStr + '</div>';
    card.onclick = function() {
      if (typeof opts.onTap === 'function') {
        removeNotificationCard(card);
        opts.onTap();
      }
    };
    /* 下滑消失 */
    var sY = 0, dragging = false;
    card.addEventListener('touchstart', function(e) { sY = e.touches[0].clientY; dragging = true; }, { passive: true });
    card.addEventListener('touchmove', function(e) {
      if (!dragging) return;
      var dy = e.touches[0].clientY - sY;
      if (dy < 0) { card.style.transform = 'translateY(' + dy + 'px)'; card.style.opacity = String(Math.max(0.2, 1 + dy / 200)); }
    }, { passive: true });
    card.addEventListener('touchend', function(e) {
      if (!dragging) return;
      dragging = false;
      var dy = (e.changedTouches[0].clientY - sY);
      card.style.transform = ''; card.style.opacity = '';
      if (dy < -50) removeNotificationCard(card);
    });
    stack.appendChild(card);
    /* 自动消失 */
    setTimeout(function() {
      if (card.parentNode) removeNotificationCard(card);
    }, NOTIF_AUTO_DISMISS_MS);
  }
  /* 切后台/失焦时补发浏览器系统通知 */
  _maybeSystemNotification(opts);
  return id;
}

function removeNotificationCard(card) {
  if (!card || !card.parentNode) return;
  card.classList.add('removing');
  setTimeout(function() { if (card.parentNode) card.remove(); }, 300);
}

function renderLockscreenNotifications() {
  var box = document.getElementById('lockNotifications');
  if (!box) return;
  if (_activeNotifications.length === 0) {
    box.innerHTML = '';
    return;
  }
  var html = '';
  /* 只显示最近10条 */
  var notifs = _activeNotifications.slice(-10);
  notifs.forEach(function(n) {
    var timeStr = formatNotifTime(n.time);
    html += '<div class="notification-card lockscreen-notif" onclick="tapLockNotification(' + n.id + ')">' +
      '<div class="notification-icon" style="background:' + n.iconBg + '">' + _notifIconInner(n.icon, '🔔') + '</div>' +
      '<div class="notification-content">' +
      '<div class="notification-title">' + escapeHtml(n.title) + '</div>' +
      '<div class="notification-body">' + escapeHtml(n.body) + '</div>' +
      '</div>' +
      '<div class="notification-time" style="color:rgba(255,255,255,0.6)">' + timeStr + '</div>' +
      '</div>';
  });
  box.innerHTML = html;
}

function tapLockNotification(id) {
  var notif = _activeNotifications.find(function(n) { return n.id === id; });
  if (!notif) return;
  /* 从列表中移除 */
  _activeNotifications = _activeNotifications.filter(function(n) { return n.id !== id; });
  renderLockscreenNotifications();
  /* 解锁并执行回调 */
  hideLockscreen();
  if (typeof notif.onTap === 'function') {
    setTimeout(notif.onTap, 500);
  }
}

function formatNotifTime(ts) {
  var d = new Date(ts);
  var now = new Date();
  var diff = now - ts;
  if (diff < 60000) return '现在';
  if (diff < 3600000) return Math.floor(diff / 60000) + '分钟前';
  var hh = String(d.getHours()).padStart(2, '0');
  var mm = String(d.getMinutes()).padStart(2, '0');
  return hh + ':' + mm;
}

/* 清除所有锁屏通知（解锁时调用） */
function clearLockNotifications() {
  _activeNotifications = [];
  var box = document.getElementById('lockNotifications');
  if (box) box.innerHTML = '';
}

/* 更新锁屏时钟定时器 */
setInterval(function() {
  if (document.getElementById('lockscreen') && document.getElementById('lockscreen').classList.contains('show')) {
    updateLockClock();
  }
}, 1000);

/* 初始化 */
updateLockPasswordStatus();

/* ===== 自动锁屏 ===== */
var _autoLockTimer = null;
var _userInteracting = false;
var _lastUserAction = 0; /* 用户最后操作的时间戳 */

/* 自动锁屏时间选项（秒） */
var AUTO_LOCK_OPTIONS = [
  { seconds: 15,  label: '15秒' },
  { seconds: 30,  label: '30秒' },
  { seconds: 60,  label: '1分钟' },
  { seconds: 120, label: '2分钟' },
  { seconds: 300, label: '5分钟' },
  { seconds: 600, label: '10分钟' },
  { seconds: 0,   label: '关闭' }
];

/* 格式化自动锁屏时间显示 */
function formatAutoLockLabel(seconds) {
  if (!seconds || seconds === 0) return '关闭';
  if (seconds < 60) return seconds + '秒';
  if (seconds % 60 === 0) return (seconds / 60) + '分钟';
  return (seconds / 60).toFixed(1) + '分钟';
}

/* 渲染自动锁屏选项列表 */
function renderAutoLockOptions() {
  var container = document.getElementById('autoLockOptions');
  if (!container) return;
  var current = (typeof config !== 'undefined' && config.settings) ? (config.settings.autoLockTimeout ?? 60) : 60;
  container.innerHTML = AUTO_LOCK_OPTIONS.map(function(opt) {
    var isActive = current === opt.seconds;
    return '<div onclick="setAutoLockTimeout(' + opt.seconds + ')" style="padding:14px 16px;border-radius:10px;display:flex;align-items:center;justify-content:space-between;cursor:pointer;background:' + (isActive ? 'rgba(245,160,184,0.15)' : 'rgba(255,255,255,0.04)') + '">'
      + '<span style="font-size:14px;color:' + (isActive ? '#F5A0B8' : '#E8E0E8') + '">' + opt.label + '</span>'
      + (isActive ? '<span style="color:#F5A0B8;font-size:16px">✓</span>' : '')
      + '</div>';
  }).join('');
}

/* 设置自动锁屏时间并保存 */
function setAutoLockTimeout(seconds) {
  if (typeof config !== 'undefined' && config.settings) {
    config.settings.autoLockTimeout = seconds;
    Store.set('config', config);
  }
  closeModal('autoLockModal');
  showToast(seconds === 0 ? '已关闭自动锁屏' : '已设置为' + formatAutoLockLabel(seconds) + '自动锁屏');
  if (typeof updateSettingsView === 'function') updateSettingsView();
  /* 重置计时器使新设置立即生效 */
  resetAutoLockTimer();
}

function resetAutoLockTimer() {
  _userInteracting = true; /* 标记用户已交互 */
  _lastUserAction = Date.now(); /* 记录操作时间戳 */
  if (_autoLockTimer) clearTimeout(_autoLockTimer);
  /* 自动锁屏关闭（0秒）时不计时 */
  var autoLockSec = (typeof config !== 'undefined' && config.settings) ? (config.settings.autoLockTimeout ?? 60) : 60;
  if (!autoLockSec || autoLockSec <= 0) return;
  /* 只有不在通话中、不在锁屏中才计时 */
  var ls = document.getElementById('lockscreen');
  if (ls && ls.classList.contains('show')) return;
  if (typeof callState !== 'undefined' && callState.active) return;
  var autoLockMs = autoLockSec * 1000;
  _autoLockTimer = setTimeout(function() {
    /* 竞态保护：如果距离用户最后操作不到3秒，说明用户刚刚操作过，推迟锁屏 */
    var elapsed = Date.now() - _lastUserAction;
    if (elapsed < 3000) {
      console.debug('[Lockscreen] 用户刚操作过(' + elapsed + 'ms前)，推迟自动锁屏');
      resetAutoLockTimer();
      return;
    }
    /* 自动锁屏 */
    if (typeof goHome === 'function') goHome();
    setTimeout(showLockscreen, 100);
  }, autoLockMs);
}

/* 监听用户操作重置计时器 */
document.addEventListener('touchstart', function() { resetAutoLockTimer(); }, { passive: true });
document.addEventListener('click', function() { resetAutoLockTimer(); }, { passive: true });
document.addEventListener('keydown', function() { resetAutoLockTimer(); }, { passive: true });

/* 页面加载后启动自动锁屏计时 */
resetAutoLockTimer();

/* ===== 启动时显示锁屏 ===== */
/* 延迟显示锁屏，确保config和壁纸已加载。
   但如果用户已经开始操作（如打开微信、点击加号），则跳过启动锁屏，只靠自动锁屏。 */
var _startupLockShown = false;
function _showStartupLockscreen() {
  if (_startupLockShown) return;
  _startupLockShown = true;
  /* 如果用户已经开始交互，不弹启动锁屏 */
  if (_userInteracting) {
    console.debug('[Lockscreen] 用户已开始交互，跳过启动锁屏');
    return;
  }
  try {
    if (typeof applyLockWallpaper === 'function') applyLockWallpaper();
    showLockscreen();
  } catch(e) {
    console.error('startup lockscreen error:', e);
  }
}
setTimeout(_showStartupLockscreen, 300);

// ===== 数据导入导出（全量备份：localStorage + IndexedDB） =====
// 旧版只导出 config + 自定义图标，会遗漏文游存档、美化布局(小组件/Dock/CSS)、
// APP 排版、壁纸等大量独立存储的数据。现改为全量快照所有本地数据。
async function exportData() {
  /* 先把节流窗口内尚未落盘的 config 强制写入，确保导出的 IndexedDB 快照与内存完全一致，不丢最后改动 */
  try { if (typeof _flushConfigPersist === 'function') await _flushConfigPersist(); } catch (e) {}
  // 1. 快照全部 localStorage（含 mochi_config、mochi_app_layout、mochi_home_widgets、
  //    mochi_dock_apps、mochi_custom_page_css、mochi_custom_bubble_css、mochi_app_icon_overrides、
  //    novelgame_* 文游存档/脚本、pc_data_* 角色数据、bg_gen_state_v2、amapKey 等）
  const lsSnapshot = {};
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k) lsSnapshot[k] = localStorage.getItem(k);
    }
  } catch(e) {}

  // 2. 快照全部 IndexedDB kv_store 条目（大数据如图片/壁纸/聊天记录等可能仅存于此）
  let _rawIdb = [];
  try { _rawIdb = await _idbGetAll(); } catch(e) { _rawIdb = []; }
  /* 清洗无法序列化的单条，避免一条坏数据导致整包导出失败、进而丢掉全部 IndexedDB 图片 */
  const idbSnapshot = [];
  _rawIdb.forEach(function(rec) { try { JSON.stringify(rec); idbSnapshot.push(rec); } catch(e) {} });

  // 3. 组装备份对象：保留顶层 config / appIconOverrides 字段以兼容旧版导入逻辑
  const exportObj = Object.assign({}, config, {
    __backup__: 'rua-phone',
    __version__: 2,
    __exportedAt__: new Date().toISOString(),
    appIconOverrides: _appIconOverrides || {},
    localStorageData: lsSnapshot,
    indexedDBData: idbSnapshot
  });

  let data;
  try {
    data = JSON.stringify(exportObj, null, 2);
  } catch(e) {
    // 若 IndexedDB 中含不可序列化内容，退化为只含 localStorage + config 的精简版
    try {
      data = JSON.stringify(Object.assign({}, config, {
        __backup__: 'rua-phone', __version__: 2,
        appIconOverrides: _appIconOverrides || {},
        localStorageData: lsSnapshot,
        indexedDBData: idbSnapshot
      }), null, 2);
    } catch(e2) {
      showToast('导出失败：数据含不可序列化内容');
      return;
    }
  }

  const date = new Date().toISOString().slice(0,10);
  const filename = 'rua小手机-backup-' + date + '.json';
  // APK / Capacitor 模式：优先用系统分享
  if (window.AndroidFileSaver) {
    window.AndroidFileSaver.saveTextFile(filename, data, 'application/json');
    showToast('数据已导出到下载文件夹（含全部本地数据）');
    return;
  }
  // WebView / 移动端：用系统分享面板（可保存到文件/发送到其他应用）
  if (navigator.share && navigator.canShare) {
    const file = new File([data], filename, { type: 'application/json' });
    if (navigator.canShare({ files: [file] })) {
      try {
        await navigator.share({ files: [file], title: 'rua数据备份' });
        showToast('已导出（请选择保存位置）');
        return;
      } catch (e) {
        // 用户取消或分享失败，继续走兜底
      }
    }
  }
  // 兜底：复制到剪贴板
  try {
    await navigator.clipboard.writeText(data);
    showToast('数据已复制到剪贴板（请自行保存为文件）');
    return;
  } catch (e) {}
  // 浏览器模式：Blob 下载
  const blob = new Blob([data], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('数据已导出（含全部本地数据）');
}

function importData(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    let data;
    try { data = JSON.parse(e.target.result); }
    catch(err) { showToast('导入失败: ' + err.message); event.target.value = ''; return; }

    if (!data || typeof data !== 'object') {
      showToast('文件格式不正确'); event.target.value = ''; return;
    }
    const isV2 = (data.__backup__ === 'rua-phone') || data.localStorageData || data.indexedDBData;
    if (!isV2 && (!data.api || !data.role)) {
      showToast('文件格式不正确'); event.target.value = ''; return;
    }

    // 1) 先清空全部旧本地数据，避免新旧混杂、旧数据占满 localStorage 配额导致恢复失败
    let legacyConfig = null;
    let finalConfig = null; // 导入后真正应生效的 config，用于内存对齐，防止被旧内存 config 覆盖
    const _BACKUP_GARBAGE = ['__backup__','__version__','__exportedAt__','localStorageData','indexedDBData','appIconOverrides'];
    if (!data.localStorageData && !data.indexedDBData) {
      legacyConfig = Object.assign({}, defaultConfig, data);
      legacyConfig.settings = Object.assign({}, defaultConfig.settings, data.settings || {});
      legacyConfig.role = Object.assign({}, defaultConfig.role, data.role || {});
      legacyConfig.api = Object.assign({}, defaultConfig.api, data.api || {});
    }
    /* 导入一开始就取消任何排队中的旧 config 节流落盘，防止其在清空/恢复期间把旧数据写回 */
    try { if (typeof _abortConfigPersist === 'function') _abortConfigPersist(); } catch(e) {}
    Promise.resolve()
      .then(function() { return _idbClearAll(); })
      .then(function() {
        try { localStorage.clear(); } catch(e) {}
        if (typeof _stickerCacheMap !== 'undefined') {
          for (var _ck in _stickerCacheMap) { try { URL.revokeObjectURL(_stickerCacheMap[_ck]); } catch(e) {} }
          _stickerCacheMap = {};
        }
        var tasks = [];
        // 2) 恢复 localStorage：单条超配额写不进时转存 IndexedDB（大容量），保证大字段(含图片)不丢
        if (data.localStorageData && typeof data.localStorageData === 'object') {
          for (const lk in data.localStorageData) {
            const lv = data.localStorageData[lk];
            let lsOk = false;
            try { localStorage.setItem(lk, lv); lsOk = true; } catch(e) { lsOk = false; }
            if (!lsOk) {
              var baseKey = lk.indexOf('mochi_') === 0 ? lk.substring(6) : lk;
              var parsed = lv;
              try { parsed = JSON.parse(lv); } catch(e) { parsed = lv; }
              tasks.push(_idbSet(baseKey, parsed).catch(function() {}));
            }
          }
        }
        // 3) 恢复 IndexedDB 全量（聊天记录、config、小组件/图标大图等）
        if (Array.isArray(data.indexedDBData)) {
          data.indexedDBData.forEach(function(rec) {
            if (rec && rec.key !== undefined) tasks.push(_idbSet(rec.key, rec.value).catch(function() {}));
            if (rec && rec.key === 'config' && rec.value && typeof rec.value === 'object') finalConfig = rec.value;
          });
        }
        // 4a) 旧版备份：顶层 config 落库
        if (legacyConfig) {
          tasks.push(_idbSet('config', legacyConfig).catch(function() {}));
          try { localStorage.setItem('mochi_config', JSON.stringify(legacyConfig)); } catch(e) {}
          if (data.appIconOverrides && typeof data.appIconOverrides === 'object') {
            tasks.push(_idbSet('app_icon_overrides', data.appIconOverrides).catch(function() {}));
          }
        } else {
          // 4b) v2 退化兜底：若 config 因配额没写进 localStorage，用顶层 config 主体补一份到 IndexedDB
          let cfgInLs = null;
          try { cfgInLs = localStorage.getItem('mochi_config'); } catch(e) {}
          if (!cfgInLs && (data.characters || data.api || data.role)) {
            var topCfg = Object.assign({}, defaultConfig, data);
            _BACKUP_GARBAGE.forEach(function(g){ delete topCfg[g]; }); // 不把备份包装字段写进 config，避免体积膨胀/自包含
            topCfg.settings = Object.assign({}, defaultConfig.settings, data.settings || {});
            if (data.role) topCfg.role = Object.assign({}, defaultConfig.role, data.role);
            if (data.api) topCfg.api = Object.assign({}, defaultConfig.api, data.api);
            tasks.push(_idbSet('config', topCfg).catch(function() {}));
            finalConfig = topCfg;
          }
        }
        return Promise.all(tasks);
      })
      .then(function() { return _deleteStickerCacheDB(); })
      .then(function() {
        /* ★关键：导入只写了存储，全局内存 config 仍是导入前的旧/空对象。若不立即对齐，
           刷新前这 700ms 内任何定时器/渲染触发 Store.set('config', 旧config)，经节流落盘会
           反向覆盖刚导入的完整数据，刷新后角色/人设/壁纸/组件全空。这里取消挂起写入、把内存
           与全局 config 对齐到导入结果、补跑迁移并强制落盘，确保刷新读到的就是导入的数据。 */
        try { if (typeof _abortConfigPersist === 'function') _abortConfigPersist(); } catch (e) {}
        if (finalConfig && typeof finalConfig === 'object') {
          try {
            _memStore['config'] = finalConfig;
            config = finalConfig;
            if (!config.settings) config.settings = Object.assign({}, (typeof defaultConfig!=='undefined'&&defaultConfig.settings)||{});
            try { if (typeof waMigrate === 'function') waMigrate(); } catch (e) {}
            return Promise.resolve(_idbSet('config', config)).then(function () {
              if (typeof _flushConfigPersist === 'function') { try { return _flushConfigPersist(); } catch (e) {} }
            });
          } catch (e) { console.warn('导入内存对齐失败:', e); }
        }
      })
      .then(function() {
        showToast('数据导入成功，正在刷新…');
        setTimeout(function() { location.reload(); }, 700);
      })
      .catch(function(err) {
        console.error('导入恢复异常:', err);
        showToast('数据导入成功，正在刷新…');
        setTimeout(function() { location.reload(); }, 700);
      });
  };
  reader.readAsText(file);
}

// ===== 清空所有本机数据（更新版本时替代“清空浏览器数据”）=====
/* 恢复最近一次自动安全快照（config_safety_snapshot，由 Store.set 自动维护） */
async function restoreSafetySnapshot() {
  try {
    var snap = await _idbGet('config_safety_snapshot');
    if (!snap) { showToast('暂无可恢复的自动备份'); return; }
    var when = snap._snapshotAt ? new Date(snap._snapshotAt).toLocaleString() : '最近';
    if (!confirm('找到一份 ' + when + ' 的自动备份。\n恢复将用它覆盖当前数据并刷新页面，确定恢复吗？')) return;
    try { delete snap._snapshotAt; } catch(e) {}
    try { Object.keys(config).forEach(function(k){ delete config[k]; }); Object.assign(config, snap); } catch(e) { config = snap; }
    await Store.set('config', config);
    showToast('已恢复自动备份，正在刷新…');
    setTimeout(function(){ location.reload(); }, 700);
  } catch(e) { showToast('恢复失败：' + (e.message || e)); }
}

function clearAllData() {
  if (!confirm('将清空本机的全部数据（设置、角色、联系人、聊天记录、桌面小组件与图片、自定义图标/组件、缓存等）。\n\n为防误删，点“确定”后会【先自动下载一份完整备份文件】，再执行清空。确定继续吗？')) return;
  if (!confirm('再次确认：真的要清空全部数据吗？\n（清空开始前会先自动导出一份备份到你的下载目录）')) return;
  /* 真正清空前先自动留底：导出一份完整备份，导出成功/失败都继续清空，不阻塞 */
  var _doClear = function() {
  try { if (typeof _abortConfigPersist === 'function') _abortConfigPersist(); } catch(e) {}
  try { localStorage.clear(); } catch(e) {}
  try { if (typeof _memStore !== 'undefined') { for (var k in _memStore) { if (k !== '_db') delete _memStore[k]; } } } catch(e) {}
  if (typeof _stickerCacheMap !== 'undefined') {
    for (var ck in _stickerCacheMap) { try { URL.revokeObjectURL(_stickerCacheMap[ck]); } catch(e) {} }
    _stickerCacheMap = {};
  }
  var jobs = [];
  jobs.push(_idbClearAll());                              // 主数据库
  jobs.push(_deleteStickerCacheDB());                     // 表情包缓存库
  // 代码缓存 / Service Worker：一并清掉，使“应用内清空”与浏览器“清空站点数据”完全等价
  jobs.push(new Promise(function(resolve) {
    try {
      if (window.caches) { caches.keys().then(function(ns) {
        return Promise.all(ns.map(function(n) { return caches.delete(n); }));
      }).then(resolve, resolve); } else { resolve(); }
    } catch(e) { resolve(); }
  }));
  jobs.push(new Promise(function(resolve) {
    try {
      if ('serviceWorker' in navigator) { navigator.serviceWorker.getRegistrations().then(function(rs) {
        return Promise.all(rs.map(function(r) { return r.unregister(); }));
      }).then(resolve, resolve); } else { resolve(); }
    } catch(e) { resolve(); }
  }));
  Promise.all(jobs).then(function() {
    showToast('已清空全部数据，正在刷新…');
    setTimeout(function() { location.reload(); }, 500);
  });
  };
  try {
    Promise.resolve(exportData()).then(function(){ setTimeout(_doClear, 400); }, function(){ setTimeout(_doClear, 400); });
  } catch(e) { _doClear(); }
}

