/* 收集某角色参与、且有未总结新内容的“多人线下剧情”，作为长期记忆总结的来源（谁参与谁记得） */
function buildGroupOfflineTargetChats(charIdx, charName) {
  var out = [];
  (config.groupOfflineChats || []).forEach(function (goc, gi) {
    if (!goc || goc.deleted || !goc.messages || !goc.messages.length) return;
    var inGO = (goc.members || []).some(function (m) {
      return m.memberId === ('char_' + charIdx) || (m.type !== 'npc' && String(m.charIdx) === String(charIdx));
    });
    if (!inGO) return;
    var goKey = 'goff_' + gi + '_char_' + charIdx;
    var goSum = (config.summarizedUpTo && config.summarizedUpTo[(window._summaryPfx||'')+goKey]) || 0;
    var goNew = goc.messages.slice(goSum);
    if (!goNew.length) return;
    out.push({
      charName: goc.name || '多人线下', charIdx: charIdx, isGroupOffline: true, focusChar: charName,
      offlineHistory: goNew, totalOffline: goc.messages.length, fromOffline: goSum, goKey: goKey
    });
  });
  return out;
}

/* 群聊/多人线下记忆总结：严格按消息固化的发送者身份标名，绝不用当前登录账号名顶替（根治“旧账号群聊被记成新账号”） */
function groupMsgSpeakerName(msg, chat) {
  if (msg && msg.senderName) return msg.senderName;
  var sid = (msg && msg.senderId) || '';
  if (sid.indexOf('user:') === 0) { var n = (typeof waUserNameById === 'function') ? waUserNameById(sid.slice(5)) : ''; if (n) return n; }
  if (sid.indexOf('char_') === 0) { var ci = parseInt(sid.slice(5)); var c = (config.characters || [])[ci]; if (c) return c.alias || c.nickname || c.name; }
  if (sid.indexOf('npc_') === 0) { var ni = parseInt(sid.slice(4)); var nc = (config.npcChats || [])[ni]; if (nc) return nc.npcName; }
  return (chat && chat.focusChar) ? '群里其他人' : '群里某人'; // 旧数据无身份：中性称谓，绝不拿当前账号名顶替
}
window.groupMsgSpeakerName = groupMsgSpeakerName;
/* 群聊总结游标：用“消息时间戳”而非数组下标（数组被治愈拆分/前插后下标会错位→反复总结）；
   并严格按时间正序返回，根治总结不符合时间线。老版本存的是“条数”(<1e12)，一次性当作0迁移。 */
function groupSummarySlice(g, rawMark) {
  var sinceTs = (rawMark && rawMark > 1e12) ? rawMark : 0;
  var arr = (g.messages || []).filter(function (m) { return (m.time || 0) > sinceTs; });
  arr.sort(function (a, b) { var d = (a.time || 0) - (b.time || 0); return d !== 0 ? d : 0; });
  var maxTs = arr.reduce(function (mx, m) { return Math.max(mx, m.time || 0); }, sinceTs);
  return { arr: arr, maxTs: maxTs };
}
/* 群总结标记键：用群稳定 id（数组下标会因建/删群漂移而重复总结） */
function groupMarkKey(g, gi, charId) {
  var base = 'gid_' + ((g && g.id != null) ? g.id : ('idx' + gi));
  return (charId != null && charId !== '') ? (base + '_c_' + charId) : base;
}
window.groupSummarySlice = groupSummarySlice; window.groupMarkKey = groupMarkKey;
/* 选出当前私聊线程里“真人登录角色微信代发、且尚未就其提示过”的消息（按线程上记录的 _proxyNotedTs 去重） */
function pickProxyMsgs(thr) {
  if (!Array.isArray(thr)) return [];
  var noted = thr._proxyNotedTs || 0;
  return thr.filter(function (m) { return m && m._charProxy && (m.time || 0) > noted && String(m.content || '').trim(); });
}
window.waPickProxyMsgs = pickProxyMsgs;
/* 全来源统一时间线：稳定按 time 升序（缺 time 的保持原相对顺序、排最后），不改动消息本体 */
function sortMsgsByTime(arr) {
  if (!Array.isArray(arr)) return arr;
  return arr.map(function (m, i) { return { m: m, i: i }; })
    .sort(function (a, b) {
      var ta = (a.m && a.m.time) || Infinity, tb = (b.m && b.m.time) || Infinity;
      if (ta !== tb) return ta - tb; return a.i - b.i; /* 缺时间的排最后，保持时间线不被打断 */
    })
    .map(function (x) { return x.m; });
}
function chatEarliestT(chat) {
  var t = Infinity;
  (chat.history || []).forEach(function (m) { if (m && m.time) t = Math.min(t, m.time); });
  (chat.offlineHistory || []).forEach(function (m) { if (m && m.time) t = Math.min(t, m.time); });
  return t === Infinity ? 0 : t;
}
window.sortMsgsByTime = sortMsgsByTime; window.chatEarliestT = chatEarliestT;
async function summarizeMemories() {
  const api = config.api;
  if (!api.baseUrl || !api.apiKey || !api.model) {
    showToast('请先在设置中配置API');
    return;
  }
  /* === 多账号锁定：总结从发起到保存可能间隔很久（流式+人工编辑），期间切账号会导致
     “A的对话/名字被存进B”。这里在最开始就锁定发起账号，后续 名字/写入池/总结游标 全部用锁定值 === */
  window._summaryAccId = (typeof currentAccId === 'function') ? currentAccId() : '';
  window._summaryAccName = (typeof userCallName === 'function') ? userCallName() : ((config.user && (config.user.personaName || config.user.name)) || '');
  window._summaryWorldId = (typeof waActiveWorldId === 'function') ? waActiveWorldId() : 'default';
  var _pfx = 'acc::' + (window._summaryAccId || '_anon') + '::';
  window._summaryPfx = _pfx;
  if (!config.summarizedUpTo) config.summarizedUpTo = {};
  /* 跨世界按 id 找账号对象（保存时即便切了世界/账号也能写回原账号） */
  function _findAccAnyWorld(accId) {
    var hit = null;
    (config.worlds || []).forEach(function (w) { (w.users || []).forEach(function (u) { if (u.id === accId) hit = u; }); });
    return hit;
  }

  /* 记忆APP角色分区：选中某个角色时，只总结与该角色有关的记忆 */
  var targetChars = [];
  var extraText = '';      /* 跨平台互动数据文本（朋友圈、社交论坛、通话记录） */
  var extraKeys = {};      /* 跨平台数据的 summarizedUpTo 键 */
  window._memorySaveCharOverride = -1;
  window._memorySaveNpcOverride = -1;
  if (_memoryTabCharIdx >= 0) {
    var selChars = config.characters || [];
    var selChar = selChars[_memoryTabCharIdx];
    if (!selChar) { showToast('角色不存在'); return; }
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    var mKey = 'char_' + _memoryTabCharIdx;
    var mSumOnline = config.summarizedUpTo[_pfx+mKey + '_online'] || 0;
    var mSumOffline = config.summarizedUpTo[_pfx+mKey + '_offline'] || 0;
    // v85：按“发起总结时锁定的账号 id”精确取该账号的聊天桶，绝不读会随挂载漂移的 selChar.chatHistory，从根上杜绝 A 账号总结出 B 的内容
    var _mAccChats = (typeof waAccCharChats === 'function') ? waAccCharChats(selChar, window._summaryAccId) : null;
    var mOnlineAll = (_mAccChats && _mAccChats.online) || selChar.chatHistory || [];
    var mOfflineAll = (_mAccChats && _mAccChats.offline) || selChar.offlineChatHistory || [];
    var mNewOnline = mOnlineAll.slice(mSumOnline);
    var mNewOffline = mOfflineAll.slice(mSumOffline);
    /* 主条目：该角色的线上+线下对话 */
    targetChars.push({
      charName: selChar.name,
      charIdx: _memoryTabCharIdx,
      history: mNewOnline,
      offlineHistory: mNewOffline,
      totalOnline: mOnlineAll.length,
      totalOffline: mOfflineAll.length,
      fromOnline: mSumOnline,
      fromOffline: mSumOffline
    });
    /* 该角色所在的群聊：同一段群聊每个角色都可各自总结（标记按 群×角色 记录） */
    (config.groupChats || []).forEach(function(g, gi) {
      if (!g || g.deleted || !g.messages || !g.messages.length) return;
      var inGroup = (g.members || []).some(function(m) {
        return (m.charId !== undefined && String(m.charId) === String(selChar.id))
          || m.memberId === ('char_' + _memoryTabCharIdx) || (m.type === 'char' && String(m.charIdx) === String(_memoryTabCharIdx));
      });
      if (!inGroup) return;
      var gMarkKey = groupMarkKey(g, gi, selChar.id);
      var _gs = groupSummarySlice(g, config.summarizedUpTo[_pfx+gMarkKey]);
      if (_gs.arr.length === 0) return;
      targetChars.push({
        charName: (g.name || '群聊'),
        charIdx: _memoryTabCharIdx,
        isGroup: true,
        focusChar: selChar.name,
        history: _gs.arr,
        offlineHistory: [],
        totalOnline: _gs.maxTs,
        totalOffline: 0,
        fromOnline: _gs.maxTs,
        groupKey: gMarkKey
      });
    });
    /* 该角色参与的多人线下剧情也要纳入长期记忆 */
    Array.prototype.push.apply(targetChars, buildGroupOfflineTargetChats(_memoryTabCharIdx, selChar.name));
    var mTotalNew = targetChars.reduce(function(s, c) { return s + c.history.length + c.offlineHistory.length; }, 0);
    if (mTotalNew === 0) {
      showToast('「' + (selChar.alias || selChar.name) + '」没有新的对话需要总结');
      return;
    }
    window._memorySaveCharOverride = _memoryTabCharIdx;
  } else if (_memoryTabNpcIdx >= 0) {
    /* NPC分区：只总结与该NPC有关的对话 */
    var selNpcChats = config.npcChats || [];
    var selNpcChat = selNpcChats[_memoryTabNpcIdx];
    if (!selNpcChat) { showToast('NPC不存在'); return; }
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    var npcKey = 'npc_' + _memoryTabNpcIdx;
    var npcSumOnline = config.summarizedUpTo[_pfx+npcKey + '_online'] || 0;
    var npcOnlineAll = selNpcChat.messages || [];
    var npcNewOnline = npcOnlineAll.slice(npcSumOnline);
    if (npcNewOnline.length === 0) {
      showToast('「' + (selNpcChat.npcName || 'NPC') + '」没有新的对话需要总结');
      return;
    }
    /* NPC对话消息格式：{role:'user'|'other', content, time} → 统一转为 history */
    var npcHistory = npcNewOnline.map(function(m) {
      return { role: m.role === 'other' ? 'assistant' : 'user', content: m.content, time: m.time, type: m.type || 'text' };
    });
    targetChars = [{
      charName: selNpcChat.npcName || 'NPC',
      charIdx: -1,
      isNpc: true,
      history: npcHistory,
      offlineHistory: [],
      totalOnline: npcOnlineAll.length,
      totalOffline: 0,
      fromOnline: npcSumOnline,
      groupKey: npcKey + '_online'
    }];
    window._memorySaveNpcOverride = _memoryTabNpcIdx;
  } else if (isGroupChatMode && _currentGroupIdx >= 0) {
    /* 群聊：总结群聊消息 */
    var gc = (config.groupChats || [])[_currentGroupIdx];
    if (!gc || !gc.messages || gc.messages.length === 0) {
      showToast('没有新的群聊对话需要总结');
      return;
    }
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    var gKey = groupMarkKey(gc, _currentGroupIdx, null);
    var _gcs = groupSummarySlice(gc, config.summarizedUpTo[_pfx+gKey]);
    if (_gcs.arr.length === 0) { showToast('没有新的群聊对话需要总结'); return; }
    targetChars = [{
      charName: gc.name || '群聊',
      charIdx: -1,
      isGroup: true,
      history: _gcs.arr,
      offlineHistory: [],
      totalOnline: _gcs.maxTs,
      totalOffline: 0,
      fromOnline: _gcs.maxTs,
      groupKey: gKey
    }];
  } else {
    /* 全部分区：扫描所有角色、NPC和群聊，找出有新对话的 */
    const characters = config.characters || [];
    const npcChats = config.npcChats || [];
    const groupChats = config.groupChats || [];
    if (characters.length === 0 && npcChats.length === 0) { showToast('还没有聊天记录'); return; }
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    /* 扫描所有角色 */
    characters.forEach(function(char, ci) {
      if (!char) return;
      var onlineHistory = char.chatHistory || [];
      var offlineHistory = char.offlineChatHistory || [];
      // v85：全部分区也只总结“锁定账号”与该角色的聊天，按 id 精确取桶，防止挂载指针漂移导致串号
      var _allAccChats = (typeof waAccCharChats === 'function') ? waAccCharChats(char, window._summaryAccId) : null;
      if (_allAccChats) { onlineHistory = _allAccChats.online || []; offlineHistory = _allAccChats.offline || []; }
      var key = 'char_' + ci;
      var sumOnline = config.summarizedUpTo[_pfx+key + '_online'] || 0;
      var sumOffline = config.summarizedUpTo[_pfx+key + '_offline'] || 0;
      var newOnline = onlineHistory.slice(sumOnline);
      var newOffline = offlineHistory.slice(sumOffline);
      if (newOnline.length > 0 || newOffline.length > 0) {
        targetChars.push({
          charName: char.name,
          charIdx: ci,
          history: newOnline,
          offlineHistory: newOffline,
          totalOnline: onlineHistory.length,
          totalOffline: offlineHistory.length,
          fromOnline: sumOnline,
          fromOffline: sumOffline
        });
        /* 该角色参与的多人线下剧情同样纳入 */
        Array.prototype.push.apply(targetChars, buildGroupOfflineTargetChats(ci, char.name));
      }
    });
    /* 扫描所有NPC */
    npcChats.forEach(function(nc, ni) {
      if (!nc || nc.deletedFromWechat) return;
      var npcMsgs = nc.messages || [];
      var npcKey = 'npc_' + ni;
      var npcSum = config.summarizedUpTo[_pfx+npcKey + '_online'] || 0;
      var npcNew = npcMsgs.slice(npcSum);
      if (npcNew.length > 0) {
        var npcHistory = npcNew.map(function(m) {
          return { role: m.role === 'other' ? 'assistant' : 'user', content: m.content, time: m.time, type: m.type || 'text' };
        });
        targetChars.push({
          charName: nc.npcName || 'NPC',
          charIdx: -1,
          isNpc: true,
          history: npcHistory,
          offlineHistory: [],
          totalOnline: npcMsgs.length,
          totalOffline: 0,
          fromOnline: npcSum,
          groupKey: npcKey + '_online'
        });
      }
    });
    /* 扫描所有群聊 */
    groupChats.forEach(function(g, gi) {
      if (!g || g.deleted || !g.messages || !g.messages.length) return;
      var gKey = groupMarkKey(g, gi, null);
      var _gs2 = groupSummarySlice(g, config.summarizedUpTo[_pfx+gKey]);
      if (_gs2.arr.length > 0) {
        targetChars.push({
          charName: g.name || '群聊',
          charIdx: -1,
          isGroup: true,
          history: _gs2.arr,
          offlineHistory: [],
          totalOnline: _gs2.maxTs,
          totalOffline: 0,
          fromOnline: _gs2.maxTs,
          groupKey: gKey
        });
      }
    });
    /* === 跨平台互动数据收集（仅在全部分区时） === */
    /* 1. 朋友圈互动 */
    (function() {
      var moments = config.moments || [];
      var mk = 'moments';
      var mSum = config.summarizedUpTo[_pfx+mk] || 0;
      if (mSum < moments.length) {
        /* moments是unshift的（最新在前），转为时间正序后取未总结部分 */
        var mReversed = moments.slice().reverse();
        var newMoments = mReversed.slice(mSum);
        if (newMoments.length > 0) {
          extraText += '\n【微信朋友圈互动记录】\n';
          newMoments.forEach(function(m) {
            var poster = m.isMine ? '我' : (m.authorName || m.name || '某角色');
            var mtext = (m.text || '').replace(/\n/g, ' ').substring(0, 200);
            extraText += poster + '发了朋友圈：「' + mtext + '」\n';
            if (m.image) extraText += '  （附图片）\n';
            if (m.likes && m.likes.length > 0) {
              extraText += '  点赞：' + m.likes.map(function(l) { return l.name || '某人'; }).join('、') + '\n';
            }
            if (m.comments && m.comments.length > 0) {
              m.comments.forEach(function(c) {
                var cText = (c.text || '').replace(/\n/g, ' ');
                var reply = c.replyTo ? ' 回复 ' + c.replyTo : '';
                extraText += '  ' + (c.name || '某人') + reply + '评论：' + cText + '\n';
              });
            }
          });
          extraKeys[mk] = { upTo: moments.length, from: mSum };
        }
      }
    })();
    /* 2. 社交论坛互动（帖子、评论、点赞） */
    (function() {
      try {
        var userPosts = [];
        var savedUP = sfStorage.get('sf_user_posts');
        if (savedUP) { try { userPosts = JSON.parse(savedUP) || []; } catch(e) { userPosts = []; } }
        var likedPosts = [];
        var savedLP = sfStorage.get('sf_liked_posts');
        if (savedLP) { try { likedPosts = JSON.parse(savedLP) || []; } catch(e) { likedPosts = []; } }
        var commentsCache = {};
        var savedCC = sfStorage.get('sf_comments_cache');
        if (savedCC) {
          try { commentsCache = JSON.parse(savedCC) || {}; } catch(e) {}
        }
        var allForumPosts = [];
        userPosts.forEach(function(p) { allForumPosts.push({ post: p, type: '发帖' }); });
        likedPosts.forEach(function(p) { allForumPosts.push({ post: p, type: '点赞' }); });
        allForumPosts.sort(function(a, b) {
          var ta = (a.post && (a.post.time || a.post.timestamp)) || 0;
          var tb = (b.post && (b.post.time || b.post.timestamp)) || 0;
          return ta - tb;
        });
        var fk = 'sf_posts';
        var fSum = config.summarizedUpTo[_pfx+fk] || 0;
        if (fSum < allForumPosts.length) {
          var newForumData = allForumPosts.slice(fSum);
          if (newForumData.length > 0) {
            extraText += '\n【社交论坛互动记录】\n';
            newForumData.forEach(function(item) {
              var p = item.post;
              if (!p) return;
              var author = p.authorName || p.handle || '某用户';
              var content = (p.content || p.text || '').replace(/\n/g, ' ').substring(0, 200);
              if (item.type === '发帖') {
                extraText += '我在社交论坛发了帖子：「' + content + '」\n';
              } else if (item.type === '点赞') {
                extraText += '我点赞了' + author + '的帖子：「' + content + '」\n';
              }
              var pComments = commentsCache[p.id] || p.commentsList || [];
              if (pComments && pComments.length > 0) {
                pComments.slice(0, 10).forEach(function(c) {
                  var cName = c.name || c.authorName || '某人';
                  var cText = (c.text || c.content || '').replace(/\n/g, ' ');
                  extraText += '  ' + cName + '评论：' + cText + '\n';
                });
              }
            });
            extraKeys[fk] = { upTo: allForumPosts.length, from: fSum };
          }
        }
      } catch(e) { console.warn('社交论坛记忆收集失败:', e); }
    })();
    /* 3. 社交论坛私信 */
    (function() {
      try {
        var dmConversations = {};
        var savedDM = sfStorage.get('sf_dm_conversations');
        if (savedDM) { try { dmConversations = JSON.parse(savedDM) || {}; } catch(e) {} }
        var strangerDMs = [];
        var savedSDM = sfStorage.get('sf_stranger_dms');
        if (savedSDM) { try { strangerDMs = JSON.parse(savedSDM) || []; } catch(e) {} }
        var dk = 'sf_dms';
        var dSum = config.summarizedUpTo[_pfx+dk] || 0;
        var allDMs = [];
        for (var cid in dmConversations) {
          var conv = dmConversations[cid];
          if (conv && conv.messages && conv.messages.length > 0) {
            allDMs.push({ id: cid, name: cid, messages: conv.messages, isStranger: false });
          }
        }
        strangerDMs.forEach(function(s) {
          if (s.messages && s.messages.length > 0) {
            allDMs.push({ id: s.id, name: s.name || '陌生人', messages: s.messages, isStranger: true });
          }
        });
        if (dSum < allDMs.length) {
          var newDMs = allDMs.slice(dSum);
          if (newDMs.length > 0) {
            extraText += '\n【社交论坛私信记录】\n';
            newDMs.forEach(function(dm) {
              var label = dm.isStranger ? ('陌生人' + (dm.name ? '(' + dm.name + ')' : '')) : dm.name;
              extraText += '与' + label + '的私信：\n';
              dm.messages.slice(0, 20).forEach(function(m) {
                var who = m.me ? '我' : label;
                var text = (m.text || '').replace(/\n/g, ' ');
                extraText += '  ' + who + '：' + text + '\n';
              });
            });
            extraKeys[dk] = { upTo: allDMs.length, from: dSum };
          }
        }
      } catch(e) { console.warn('社交论坛私信记忆收集失败:', e); }
    })();
    /* 4. 电话通话记录 */
    (function() {
      var callLog = config.phoneCallLog || [];
      var ck = 'phone_calls';
      var cSum = config.summarizedUpTo[_pfx+ck] || 0;
      if (cSum < callLog.length) {
        var newCalls = callLog.slice(cSum);
        if (newCalls.length > 0) {
          extraText += '\n【电话通话记录】\n';
          newCalls.forEach(function(r) {
            var name = r.name || formatPhoneNumber(r.number);
            var typeText = r.type === 'incoming' ? '来电' : (r.type === 'outgoing' ? '去电' : '未接');
            extraText += '与' + name + '的' + typeText;
            if (r.durationText) extraText += '（' + r.durationText + '）';
            extraText += '\n';
            if (r.transcript && r.transcript.length > 0) {
              r.transcript.forEach(function(h) {
                var who = h.who === 'me' ? '我' : name;
                var text = (h.text || '').replace(/\n/g, ' ');
                extraText += '  ' + who + '：' + text + '\n';
              });
            }
          });
          extraKeys[ck] = { upTo: callLog.length, from: cSum };
        }
      }
    })();
    /* 5. 微信语音/视频通话记录 */
    (function() {
      var wcLog = config.wechatCallLog || [];
      var wk = 'wechat_calls';
      var wSum = config.summarizedUpTo[_pfx+wk] || 0;
      if (wSum < wcLog.length) {
        var newWCalls = wcLog.slice(wSum);
        if (newWCalls.length > 0) {
          extraText += '\n【微信语音/视频通话记录】\n';
          newWCalls.forEach(function(r) {
            var name = r.isAnon ? '匿名号码' : (r.roleName || '对方');
            var typeText = r.incoming ? (r.typeText + '·来电') : (r.typeText + '·去电');
            extraText += '与' + name + '的微信' + typeText;
            if (r.durationText) extraText += '（' + r.durationText + '）';
            extraText += '\n';
            if (r.transcript && r.transcript.length > 0) {
              r.transcript.forEach(function(h) {
                var who = h.who === 'me' ? '我' : name;
                var text = (h.text || '').replace(/\n/g, ' ');
                extraText += '  ' + who + '：' + text + '\n';
              });
            }
          });
          extraKeys[wk] = { upTo: wcLog.length, from: wSum };
        }
      }
    })();
    /* 6. 好友申请 + 关系变动（删除/拉黑/恢复等），时间戳游标，按时间线 */
    (function () {
      var rk = 'rel_events_t';
      var rSince = config.summarizedUpTo[_pfx + rk] || 0;
      var r = (typeof buildRelationEventLines === 'function') ? buildRelationEventLines(rSince, window._summaryAccId || null) : { lines: [], maxT: 0 };
      if (r.lines.length > 0) {
        extraText += '\n【好友申请与关系变动记录】\n' + r.lines.join('\n') + '\n';
        extraKeys[rk] = { upTo: Math.max(r.maxT, rSince), from: rSince };
      }
    })();
    /* 检查是否有任何新数据需要总结 */
    if (targetChars.length === 0 && extraText === '') {
      showToast('没有新的对话需要总结');
      return;
    }
    /* 全部分区：只取第一个有新对话的角色/NPC，避免多池保存冲突 */
    if (targetChars.length > 1) {
      var firstCharName = targetChars[0].charName;
      targetChars = [targetChars[0]];
      setTimeout(function() { showToast('正在总结「' + firstCharName + '」的对话，其他角色请切换分区后总结'); }, 500);
    }
    /* 设置保存覆盖：确保记忆存入正确的池 */
    if (targetChars.length > 0 && targetChars[0]) {
      if (targetChars[0].isNpc) {
        var m = targetChars[0].groupKey.match(/^npc_(\d+)_online$/);
        if (m) window._memorySaveNpcOverride = parseInt(m[1]);
      } else if (targetChars[0].isGroup) {
        /* 群聊总结：存入共享记忆池（config.memories），不设override */
        /* 不设 _memorySaveCharOverride 和 _memorySaveNpcOverride，getMemorySaveTarget 会返回 config.memories */
      } else if (targetChars[0].charIdx >= 0) {
        window._memorySaveCharOverride = targetChars[0].charIdx;
      }
    }
    /* 跨平台互动数据（朋友圈、社交论坛、通话记录）：如果只有跨平台数据没有角色对话，
       存入全局共享记忆池 config.memories，不设 override */
    if (targetChars.length === 0 && extraText) {
      /* 不设 override，getMemorySaveTarget 返回 config.memories（共享池） */
      window._memorySaveCharOverride = -1;
      window._memorySaveNpcOverride = -1;
    }
  }

  var totalNewMsgs = targetChars.reduce(function(s, c) { return s + c.history.length + c.offlineHistory.length; }, 0);
  /* 如果没有角色对话但有跨平台互动数据，计为额外消息数 */
  if (totalNewMsgs === 0 && extraText) { totalNewMsgs = 10; }

  // 显示加载状态
  const btn = document.getElementById('summarizeBtn');
  const list = document.getElementById('memoryList');
  const empty = document.getElementById('memoryEmpty');
  empty.style.display = 'none';
  list.innerHTML = `<div class="memory-loading"><div class="spinner"></div><div>AI正在总结记忆...</div></div>`;
  btn.disabled = true;
  btn.style.opacity = '0.5';

  try {
    // v88：私聊语境下“双视角双池”——一次总结同时沉淀【角色第一人称记忆】（进角色大脑、打账号标，
    // 角色因此是一颗跨账号的完整大脑）与【用户第一人称记忆】（进锁定账号）。仅当本次只涉及一个私聊角色时启用，
    // 避免多角色错存；群聊/NPC/多角色维持原单池逻辑。
    var _dualCharIdxSet = {};
    targetChars.forEach(function (tc) { if (tc && !tc.isGroup && !tc.isNpc && !tc.isGroupOffline && tc.charIdx >= 0) _dualCharIdxSet[tc.charIdx] = true; });
    var _dualCharIdxs = Object.keys(_dualCharIdxSet).map(Number);
    var _dualCharIdx = (_dualCharIdxs.length === 1) ? _dualCharIdxs[0] : -1;
    window._summaryDual = (_dualCharIdx >= 0);
    window._summaryDualCharIdx = _dualCharIdx;
    // === 全来源时间线规整：无论私聊/群聊/多人线下/NPC，喂给 AI 前每个来源内部严格按时间正序，
    // 不同会话块之间也按“最早一条发生时间”排序，保证整部手机的记忆总结沿真实时间线推进（两遍压缩共用） ===
    targetChars.forEach(function (chat) {
      chat.history = sortMsgsByTime(chat.history);
      chat.offlineHistory = sortMsgsByTime(chat.offlineHistory);
    });
    targetChars.sort(function (a, b) { return chatEarliestT(a) - chatEarliestT(b); });
    // 构建对话记录文本（只含未总结的新对话），每条消息单独截断确保所有对话都被包含
    let chatText = '';
    var CW_MEMO_MAX_MSG = 800; /* 单条消息最大字符数 */
    var CW_MEMO_MAX_TOTAL = 20000; /* 总文本最大字符数 */
    var totalMsgCount = 0; /* 统计消息条数用于动态计算记忆条数 */
    targetChars.forEach(chat => {
      // 线上微信聊天 / 群聊
      if (chat.history && chat.history.length > 0) {
        if (chat.isGroup) {
          chatText += `\n【群聊「${chat.charName}」的聊天记录（重点提取与${chat.focusChar || '相关角色'}有关的情节）】\n`;
        } else {
          chatText += `\n【与${chat.charName}的线上微信对话】\n`;
        }
        chat.history.forEach(msg => {
          if (msg.isNudge) return;
          /* 群聊消息使用发送者名字，私聊用角色名 */
          var role = chat.isGroup ? groupMsgSpeakerName(msg, chat) : (msg.role === 'user' ? '我' : chat.charName);
          var rawContent = msg.content || '';
          /* 清洗thinking和miyavoice标签 */
          rawContent = rawContent.replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '');
          /* 清洗媒体标记 */
          rawContent = rawContent.replace(/\[image\].*/g, '[图片]').replace(/\[redpacket\].*/g, '[红包]').replace(/\[repost\].*/g, '[论坛帖子]');
          /* 清洗HTML标签（线下模式消息可能包含） */
          rawContent = rawContent.replace(/<[^>]+>/g, '');
          rawContent = rawContent.trim();
          if (!rawContent) return;
          /* 单条消息截断，防止线下模式几千字把Prompt撑爆 */
          if (rawContent.length > CW_MEMO_MAX_MSG) {
            rawContent = rawContent.substring(0, CW_MEMO_MAX_MSG) + '...(后文略)';
          }
          chatText += role + '：' + (msg._charProxy ? '〔注：这条是我微信号在我本人未操作时被登录发出的〕' : '') + rawContent + '\n';
          totalMsgCount++;
        });
      }
      // 线下小说互动
      if (chat.offlineHistory && chat.offlineHistory.length > 0) {
        chatText += chat.isGroupOffline ? `\n【多人线下剧情「${chat.charName}」（${chat.focusChar}参与其中，第三人称小说式记录）】\n` : `\n【与${chat.charName}的线下互动记录】\n`;
        chat.offlineHistory.forEach(msg => {
          if (msg.isNudge) return;
          const role = chat.isGroupOffline ? (msg.senderName || groupMsgSpeakerName(msg, chat)) : (msg.role === 'user' ? '我' : chat.charName);
          var rawContent = msg.content || '';
          rawContent = rawContent.replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '');
          rawContent = rawContent.replace(/<[^>]+>/g, '');
          rawContent = rawContent.trim();
          if (!rawContent) return;
          if (rawContent.length > CW_MEMO_MAX_MSG) {
            rawContent = rawContent.substring(0, CW_MEMO_MAX_MSG) + '...(后文略)';
          }
          chatText += role + '：' + (msg._charProxy ? '〔注：这条是我微信号在我本人未操作时被登录发出的〕' : '') + rawContent + '\n';
          totalMsgCount++;
        });
      }
    });
    /* 追加跨平台互动数据（朋友圈、社交论坛、通话记录等） */
    if (extraText) {
      chatText += extraText;
      /* 跨平台数据也计入消息条数 */
      var extraLines = extraText.split('\n').filter(function(l) { return l.trim() && !l.startsWith('【') && !l.startsWith('---'); });
      totalMsgCount += extraLines.length;
    }
    /* 只有在总文本超长时才截断，但保留所有消息的概要 */
    if (chatText.length > CW_MEMO_MAX_TOTAL) {
      /* 不直接截断，而是进一步压缩单条消息长度 */
      chatText = '';
      targetChars.forEach(chat => {
        if (chat.history && chat.history.length > 0) {
          if (chat.isGroup) {
            chatText += `\n【群聊「${chat.charName}」记录】\n`;
          } else {
            chatText += `\n【与${chat.charName}的微信对话】\n`;
          }
          chat.history.forEach(msg => {
            if (msg.isNudge) return;
            var role = chat.isGroup ? groupMsgSpeakerName(msg, chat) : (msg.role === 'user' ? '我' : chat.charName);
            var rawContent = (msg.content || '').replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '').replace(/<[^>]+>/g, '').replace(/\[image\].*/g, '[图片]').replace(/\[redpacket\].*/g, '[红包]').replace(/\[repost\].*/g, '[论坛帖子]').trim();
            if (!rawContent) return;
            if (rawContent.length > 300) rawContent = rawContent.substring(0, 300) + '...';
            chatText += role + '：' + (msg._charProxy ? '〔注：这条是我微信号在我本人未操作时被登录发出的〕' : '') + rawContent + '\n';
          });
        }
        if (chat.offlineHistory && chat.offlineHistory.length > 0) {
          chatText += chat.isGroupOffline ? `\n【多人线下剧情「${chat.charName}」记录】\n` : `\n【与${chat.charName}的线下互动】\n`;
          chat.offlineHistory.forEach(msg => {
            if (msg.isNudge) return;
            var role = chat.isGroupOffline ? (msg.senderName || groupMsgSpeakerName(msg, chat)) : (msg.role === 'user' ? '我' : chat.charName);
            var rawContent = (msg.content || '').replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '').replace(/<[^>]+>/g, '').trim();
            if (!rawContent) return;
            if (rawContent.length > 300) rawContent = rawContent.substring(0, 300) + '...';
            chatText += role + '：' + (msg._charProxy ? '〔注：这条是我微信号在我本人未操作时被登录发出的〕' : '') + rawContent + '\n';
          });
        }
      });
      if (extraText) chatText += extraText;
    }

    // 收集已有记忆，告诉AI避免重复
    // 角色分区总结时只看该角色自己的记忆池；NPC分区只看该NPC自己的记忆池
    var _existingPool;
    if (window._memorySaveCharOverride >= 0) {
      var _oc = (config.characters || [])[window._memorySaveCharOverride];
      _existingPool = (_oc && _oc.memories) || [];
    } else if (window._memorySaveNpcOverride >= 0) {
      var _onc = (config.npcChats || [])[window._memorySaveNpcOverride];
      _existingPool = (_onc && _onc.memories) || [];
    } else {
      _existingPool = getActiveMemories();
    }
    var existingMemories = _existingPool.map(function(m) { return m.content; }).join('\n- ');
    /* 截断过长的已有记忆列表，避免prompt过大 */
    if (existingMemories.length > 1500) {
      existingMemories = existingMemories.substring(0, 1500) + '…';
    }
    var avoidDupPrompt = '';
    if (existingMemories) {
      avoidDupPrompt = '\n\n以下是已经保存的记忆，请不要重复提取相同内容：\n- ' + existingMemories + '\n\n请只提取上述已有记忆中没有涵盖的新内容。';
    }

    // 根据对话长度动态选择单条或多条记忆，并动态计算记忆条数
    const msgCount = totalNewMsgs;
    /* 动态计算记忆条数：每3轮对话（约6条消息）生成1条记忆，最少3条最多12条 */
    var dynamicMemoCount = Math.max(3, Math.min(12, Math.ceil(msgCount / 6)));
    /* 5条以上消息用多条模式；v89修复：私聊双池（要分“角色的记忆/我的记忆”两个编号板块）也必须用多条模板，
       否则 SINGLE 的“写成一段150-400字”会和双板块/条数指令打架，导致只吐出一两段、大量内容被漏掉 */
    const useMulti = msgCount > 5 || !!window._summaryDual;
    var ruleTemplate = useMulti ? BUILTIN_MEMORY_RULES_MULTI : BUILTIN_MEMORY_RULES_SINGLE;
    const roleName = (targetChars.length > 0 && targetChars[0]) ? targetChars[0].charName : '跨平台互动';
    // 视角归属：存进“角色/NPC本人记忆池”时必须以角色/NPC第一人称“我”书写（跨用户账号共享、属于这个角色本人）；
    // 存进“当前用户账号记忆池”（全部/群聊）时才以用户第一人称“我”书写（按账号隔离）。
    var _memViewIsEntity = (window._memorySaveCharOverride >= 0 || window._memorySaveNpcOverride >= 0);
    var _memEntityLabel = window._memorySaveNpcOverride >= 0 ? 'NPC' : '角色';
    if (_memViewIsEntity) {
      ruleTemplate = ruleTemplate.replace(/以第一人称（用户视角"我"）/g, '以第一人称（' + _memEntityLabel + '“' + roleName + '”本人视角“我”，对话里的用户是“对方/TA”，绝不能用用户视角）');
      ruleTemplate = ruleTemplate.replace(/用户视角"我"/g, _memEntityLabel + '本人视角“我”');
    }
    /* 角色分区/NPC分区总结时，强调只提取与该角色/NPC有关的内容 */
    var focusPrompt = '';
    if (window._memorySaveCharOverride >= 0) {
      var _fc = (config.characters || [])[window._memorySaveCharOverride];
      if (_fc) focusPrompt = '\n\n注意：只提取与「' + (_fc.alias || _fc.name) + '」有关的记忆，与他/她无关的情节不要记录。';
    } else if (window._memorySaveNpcOverride >= 0) {
      var _fnc = (config.npcChats || [])[window._memorySaveNpcOverride];
      if (_fnc) focusPrompt = '\n\n注意：只提取与「' + (_fnc.npcName || 'NPC') + '」有关的记忆，与他/她无关的情节不要记录。';
    }
    /* 跨平台互动数据提示 */
    if (extraText) {
      focusPrompt += '\n\n注意：对话记录中包含【微信朋友圈互动记录】【社交论坛互动记录】【社交论坛私信记录】【电话通话记录】【微信语音/视频通话记录】等跨平台互动数据。请明确标注每条记忆来自哪个平台的互动（如"在朋友圈……""在社交论坛……""打电话时……""微信语音通话时……"）。这些跨平台互动的记忆非常重要，不要遗漏。';
    }
    if (useMulti) {
      focusPrompt += '\n\n【重要】本次需要生成正好 ' + dynamicMemoCount + ' 条记忆。请确保覆盖对话中的所有重要内容，不要遗漏任何对话。不同话题/事件分成不同条目。';
    } else {
      // v89修复：单条记叙文模式（新增对话很少）不再命令“正好N条”（那会和“写成一篇记叙文”自相矛盾、只吐一两句），
      // 改为强调完整覆盖全部对话
      focusPrompt += '\n\n【重要】请把这段时间发生的所有事件、约定、情绪变化和细节都完整写进这一篇记叙文里，不要遗漏任何一段对话，不要因为篇幅而省略事件。';
    }
    /* 用户自定义“记忆总结文风要求”：保存后每次总结都按此风格撰写 */
    var _memStyle = (config.memorySummaryStyle || '').trim();
    var _memStylePrompt = _memStyle ? '\n\n【本次总结的文风/写法要求·优先级很高】\n在满足上面记忆提取要求的同时，每一条记忆的文字风格、叙述口吻、详略与修辞，都必须严格遵循下面用户指定的文风要求来写：\n""' + _memStyleSlice(_memStyle) + '""\n不要违背该文风。' : '';
    /* 用“发起总结时锁定”的账号名，而不是保存当下的账号，防止流式/编辑期间切号导致名字张冠李戴 */
    var _sumUserName = window._summaryAccName || ((typeof userCallName === 'function' ? userCallName() : ((config.user && (config.user.personaName || config.user.name)) || '')));
    /* 记录本次总结结果应写入哪类池（保存时按此锁定，不再实时取当前账号） */
    window._summarySaveKind = (window._memorySaveNpcOverride >= 0) ? 'npc' : ((window._memorySaveCharOverride >= 0) ? 'char' : 'acc');
    window._summarySaveCharIdx = (window._memorySaveCharOverride >= 0) ? window._memorySaveCharOverride : -1;
    window._summarySaveNpcIdx = (window._memorySaveNpcOverride >= 0) ? window._memorySaveNpcOverride : -1;
    var _memViewPrompt = _memViewIsEntity
      ? '\n\n【视角硬要求·最高优先级】这份记忆属于' + _memEntityLabel + '“' + roleName + '”本人，必须用' + roleName + '的第一人称“我”来写（我就是' + roleName + '），记录我和' + (_sumUserName || '这个人') + '之间发生的事、我的感受、我的打算，以及我对' + (_sumUserName || 'TA') + '的了解。' + (_sumUserName ? '提到这个人时，必须用我对TA的专属称呼：默认叫名字“' + _sumUserName + '”，若我的人设或我们的关系里有更亲昵的叫法（昵称、宝贝、老婆、老公、小名等）就用那个，生气或严肃拉开距离时就连名带姓喊全名，全文严禁出现 TA、对方、用户、他、她 等任何泛称；' : '') + '严禁把' + (_sumUserName || '用户') + '写成“我”，“我”只能是' + roleName + '。这份记忆属于我本人、会长期保留。'
      : '\n\n【视角硬要求】这份记忆属于当前用户账号本人，用“我”（用户）的第一人称记录我的经历与感受，提到角色直接写其名字、不要用TA/对方等泛称，按账号独立保存。';
    // v88 双池：私聊单一角色时，一次总结同时产出“角色本人记忆”和“用户本人记忆”两段，保存时拆分到两个池
    var _dualChar = window._summaryDual ? (config.characters || [])[_dualCharIdx] : null;
    var _dualCharName = _dualChar ? (_dualChar.alias || _dualChar.name) : roleName;
    var _dualRel = '';
    try { if (_dualChar && _dualChar.people && window._summaryAccId && _dualChar.people[window._summaryAccId]) _dualRel = _dualChar.people[window._summaryAccId].relation || ''; } catch (e) {}
    var _dualPrompt = window._summaryDual ? (
      '\n\n【输出格式·最高优先级·必须严格遵守】请分成下面两个板块输出，板块标题单独一行、原样照抄，不要输出别的标题：\n'
      + '第一板块标题为「【' + _dualCharName + '的记忆】」，其下用编号列出“' + _dualCharName + '本人第一人称”的记忆（我就是' + _dualCharName + '），记录我和' + (_sumUserName || '这个人') + '之间发生的事、我的感受与打算、我对' + (_sumUserName || 'TA') + '的了解。提到对方时必须用我对' + (_sumUserName || 'TA') + '的专属称呼：' + (_dualRel ? '我们现在的关系是“' + _dualRel + '”，' : '') + '默认叫名字“' + (_sumUserName || '') + '”，关系亲密时自然地用昵称、宝贝、老婆、老公、小名等，生气或要拉开距离时连名带姓喊全名，同一条里不要反复刷同一个称呼；全文严禁出现 TA、对方、用户、他、她 等泛称，也严禁把' + (_sumUserName || '对方') + '写成“我”。\n'
      + '第二板块标题为「【我的记忆】」，其下用编号列出当前用户账号“' + (_sumUserName || '我') + '”第一人称“我”的记忆，记录我的经历与感受，提到' + _dualCharName + '直接写名字、不要用泛称。\n'
      + '两个板块各自从 1. 开始独立编号。' + (_sumUserName ? '注意两个板块的“我”不是同一个人：第一板块的我是' + _dualCharName + '，第二板块的我是' + _sumUserName + '；上方对话记录里的“我”永远指用户账号“' + _sumUserName + '”，绝对不能写成任何其他账号的名字。' : '')
    ) : '';
    var _finalViewPrompt = window._summaryDual ? _dualPrompt : _memViewPrompt;
    const prompt = ruleTemplate.replace(/角色名/g, roleName).replace('（对话内容）', chatText) + focusPrompt + avoidDupPrompt + _memStylePrompt + _finalViewPrompt;

    const messages = [
      { role: 'system', content: '你是一个专业的记忆总结助手。你的任务是从对话记录中提取所有重要的记忆，确保每一段对话的内容都被覆盖到，不遗漏任何重要信息。严格按照要求的格式和条数输出。只提取新的、未记录过的记忆，不要与已有记忆重复。' },
      { role: 'user', content: prompt }
    ];

    /* v90修复截断：双池要写“角色+用户”两个板块各N条、多条模式每条150-350字，4000 token 中文约两千字就到顶，
       会被接口按 length 硬截断（表现为只剩一两段、第二板块缺失、结尾戛然而止）。双池/多条提升到 8000，
       且不低于用户在设置里填的 maxTokens；单条记叙文维持 4000。 */
    var _memMaxTokens = (window._summaryDual || useMulti) ? 8000 : 4000;
    try { var _cfgMT = (config.settings && config.settings.maxTokens) || 0; if (_cfgMT > _memMaxTokens) _memMaxTokens = _cfgMT; } catch (emt) {}
    /* 使用流式调用，避免长时间无响应导致超时 */
    const reply = await callApiStreamForMemory(messages, { maxTokens: _memMaxTokens, timeout: 180000 });

    // 显示总结结果供用户编辑
    document.getElementById('memorySummaryInput').value = reply.trim();
    // 记录待标记的总结位置（保存时才真正标记），同时记录起始位置用于删除记忆时回滚
    window._pendingSummarizeUpTo = {};
    window._pendingSummarizeFrom = {};
    targetChars.forEach(function(chat) {
      if (chat.isGroupOffline) {
        window._pendingSummarizeUpTo[chat.goKey] = chat.totalOffline;
        window._pendingSummarizeFrom[chat.goKey] = chat.fromOffline || 0;
      } else if (chat.isGroup) {
        window._pendingSummarizeUpTo[chat.groupKey] = chat.totalOnline;
        window._pendingSummarizeFrom[chat.groupKey] = chat.fromOnline || 0;
      } else if (chat.isNpc) {
        /* NPC：使用 npc_{idx}_online 作为标记键 */
        window._pendingSummarizeUpTo[chat.groupKey] = chat.totalOnline;
        window._pendingSummarizeFrom[chat.groupKey] = chat.fromOnline || 0;
      } else {
        var k = 'char_' + chat.charIdx;
        window._pendingSummarizeUpTo[k + '_online'] = chat.totalOnline;
        window._pendingSummarizeUpTo[k + '_offline'] = chat.totalOffline;
        window._pendingSummarizeFrom[k + '_online'] = chat.fromOnline || 0;
        window._pendingSummarizeFrom[k + '_offline'] = chat.fromOffline || 0;
      }
    });
    /* 跨平台互动数据的总结标记 */
    for (var ek in extraKeys) {
      window._pendingSummarizeUpTo[ek] = extraKeys[ek].upTo;
      window._pendingSummarizeFrom[ek] = extraKeys[ek].from;
    }
    openModal('memorySummaryModal');
    list.innerHTML = '';
    renderMemories();
  } catch(err) {
    var errMsg = err.message || '未知错误';
    console.error('记忆总结失败:', err);
    /* 友好的错误提示 */
    var userMsg = errMsg;
    if (/超时|timeout|abort/i.test(errMsg)) {
      userMsg = 'AI总结超时了。可能对话太长或模型响应慢，请尝试：1)减少对话量后重试 2)换用更快的模型';
    } else if (/网络|fetch|network|load failed/i.test(errMsg)) {
      userMsg = '网络连接失败，请检查：1)API地址是否正确 2)网络是否通畅 3)API是否支持非流式请求';
    } else if (/密钥|401|403|权限/i.test(errMsg)) {
      userMsg = 'API密钥无效或无权限，请在设置中检查API配置';
    } else if (/429|频率|超限/i.test(errMsg)) {
      userMsg = 'API请求频率超限，请等几秒后重试';
    } else if (/空内容|empty/i.test(errMsg)) {
      userMsg = 'AI返回了空内容，可能是对话太短或模型异常，请重试';
    } else if (/HTML|html/i.test(errMsg)) {
      userMsg = 'API返回了HTML页面而非JSON数据，请检查API地址是否正确（常见原因：地址缺少/v1路径、API地址错误、或被Cloudflare拦截）';
    } else if (/格式异常|format/i.test(errMsg)) {
      userMsg = 'API返回格式异常，可能当前模型不支持记忆总结功能，请尝试换一个模型';
    } else if (/无法解析|非JSON/i.test(errMsg)) {
      userMsg = 'API返回了无法解析的数据。下方显示了API实际返回的内容，请据此排查（常见原因：API地址错误、返回HTML错误页、接口不兼容）';
    } else if (/JSON|parse|unexpected/i.test(errMsg)) {
      userMsg = 'API返回了无法解析的数据，可能原因：1)当前模型不支持流式请求 2)API地址不兼容 3)接口返回了错误页面。请尝试更换模型或API地址';
    } else if (/context.*length|token.*limit|too long/i.test(errMsg)) {
      userMsg = '对话内容太长，超出了模型上下文限制，请减少对话量后重试';
    }
    showToast('总结失败: ' + userMsg, 5000);
    list.innerHTML = '<div style="padding:20px;text-align:center;color:#8E8E93;font-size:13px;line-height:1.8">' +
      '<div style="font-size:36px;margin-bottom:8px;opacity:0.3">⚠️</div>' +
      '<div>总结失败</div>' +
      '<div style="margin-top:6px;font-size:12px;color:#6B6B70;word-break:break-all;max-height:120px;overflow-y:auto">' + errMsg.substring(0, 500) + '</div>' +
      '<button class="btn-sm" style="margin-top:12px;background:#F3E3E9;color:#C97E96" onclick="summarizeMemories()">重试</button>' +
      '</div>';
    renderMemories();
  } finally {
    btn.disabled = false;
    btn.style.opacity = '1';
  }
}

function saveSummaryMemory() {
  const text = document.getElementById('memorySummaryInput').value.trim();
  if (!text) {
    showToast('记忆内容不能为空');
    return;
  }
  var _spfx = window._summaryPfx || '';
  /* 写回“发起总结时锁定”的池：角色池/NPC池跨账号共享；用户记忆必须写回发起账号，
     即便保存这一刻用户已经切到别的账号，也绝不能写进当前账号（否则A的记忆会带上B的名字） */
  var _lockedTarget = (function () {
    var kind = window._summarySaveKind;
    if (kind === 'char') { var c = (config.characters || [])[window._summarySaveCharIdx]; if (c) { if (!Array.isArray(c.memories)) c.memories = []; return c.memories; } }
    if (kind === 'npc') { var n = (config.npcChats || [])[window._summarySaveNpcIdx]; if (n) { if (!Array.isArray(n.memories)) n.memories = []; return n.memories; } }
    var acc = null;
    (config.worlds || []).forEach(function (w) { (w.users || []).forEach(function (u) { if (u.id === window._summaryAccId) acc = u; }); });
    if (acc) { if (!Array.isArray(acc.memories)) acc.memories = []; return acc.memories; }
    return getMemorySaveTarget(); /* 极端兜底：锁定账号已不存在时才用当前池 */
  })();
  var savedCount = 0;
  var skippedCount = 0;
  /* v85：保存角色记忆时，确保角色人物簿里有“锁定账号”这一页并同步其名字，关系/名字永远对得上发起总结的账号 */
  try {
    if (window._summarySaveKind === 'char' && window._summaryAccId && typeof waEnsureCharPerson === 'function') {
      var _pc = (config.characters || [])[window._summarySaveCharIdx], _pa = null;
      (config.worlds || []).forEach(function (w) { (w.users || []).forEach(function (u) { if (u.id === window._summaryAccId) _pa = u; }); });
      if (_pc && _pa) waEnsureCharPerson(_pc, _pa);
    }
  } catch (epp) {}
  /* 本次总结覆盖的情节区间（key → {from,to}），打到每条记忆上，删除记忆时用于回滚总结标记；键带账号前缀 */
  var rangesTag = null;
  if (window._pendingSummarizeUpTo) {
    rangesTag = {};
    for (var rk in window._pendingSummarizeUpTo) {
      rangesTag[_spfx + rk] = {
        from: (window._pendingSummarizeFrom && window._pendingSummarizeFrom[rk]) || 0,
        to: window._pendingSummarizeUpTo[rk]
      };
    }
  }
  var makeMem = function(content, _forceChar) {
    var mem = { content: content, time: Date.now(), source: 'ai' };
    if (rangesTag) mem._ranges = rangesTag;
    // v83：角色记忆按“发起总结时锁定的对方账号”打标，私聊时才能把“和眼前人的经历”
    // 与“和其他账号（别的人）的经历”分开，杜绝新账号被当成旧账号。
    // 双池路径会显式传 true/false（以此为准，避免角色分区 kind='char' 误伤用户段）；单池路径不传则按 kind 判断
    var _tagAsChar = (_forceChar === undefined) ? (window._summarySaveKind === 'char') : _forceChar;
    if (_tagAsChar && window._summaryAccId) {
      mem.withAccId = window._summaryAccId;
      if (window._summaryAccName) mem.withName = window._summaryAccName;
    }
    return mem;
  };
  // v88 双池：把 AI 输出拆成「角色记忆」「我的记忆」两段，分别写进角色大脑与锁定账号
  var _dualHandled = false;
  if (window._summaryDual && window._summaryDualCharIdx >= 0) {
    var _dc = (config.characters || [])[window._summaryDualCharIdx];
    var _dAcc = null;
    (config.worlds || []).forEach(function (w) { (w.users || []).forEach(function (u) { if (u.id === window._summaryAccId) _dAcc = u; }); });
    if (_dc) {
      if (!Array.isArray(_dc.memories)) _dc.memories = [];
      if (_dAcc && !Array.isArray(_dAcc.memories)) _dAcc.memories = [];
      var _cHead = text.search(/【\s*[^】\n]*的记忆\s*】/);
      var _uHead = text.search(/【\s*我的记忆\s*】/);
      if (_cHead >= 0 && _uHead >= 0 && _cHead !== _uHead) {
        var _lo = Math.min(_cHead, _uHead), _hi = Math.max(_cHead, _uHead);
        var _seg1 = text.substring(_lo, _hi), _seg2 = text.substring(_hi);
        var charSeg = (_cHead < _uHead) ? _seg1 : _seg2;
        var userSeg = (_cHead < _uHead) ? _seg2 : _seg1;
        charSeg = charSeg.replace(/^[^\n]*\n/, '').trim();
        userSeg = userSeg.replace(/^[^\n]*\n/, '').trim();
        var _pushSeg = function (seg, pool, isCharSeg) {
          if (!seg || !pool) return;
          var mm = seg.match(/^\d+\.\s/gm);
          var items = (mm && mm.length > 0)
            ? seg.split(/(?=^\d+\.\s)/m).map(function (s) { return s.replace(/^\d+\.\s*/, '').trim(); }).filter(Boolean)
            : [seg];
          items.forEach(function (item) {
            if (!item) return;
            if (!pool.some(function (m) { return isMemorySimilar(item, m.content); })) {
              pool.push(makeMem(item, isCharSeg));
              savedCount++;
            } else { skippedCount++; }
          });
        };
        _pushSeg(charSeg, _dc.memories, true);
        if (_dAcc) _pushSeg(userSeg, _dAcc.memories, false);
        try { if (_dAcc && typeof waEnsureCharPerson === 'function') waEnsureCharPerson(_dc, _dAcc); } catch (edp) {}
        _dualHandled = true;
      } else if (_cHead >= 0 || _uHead >= 0) {
        /* v90修复截断：只生成了一个板块（通常是 max_tokens 到顶、第二板块没来得及输出）。
           只把已生成的那个板块存进它该去的池，绝不能把角色段落误存成用户记忆；并标记不完整以提示重试。 */
        var _pushSegOne = function (seg, pool, isCharSeg) {
          if (!seg || !pool) return 0;
          seg = seg.replace(/^[^\n]*\n/, '').trim();
          var mm = seg.match(/^\d+\.\s/gm), n = 0;
          var items = (mm && mm.length > 0)
            ? seg.split(/(?=^\d+\.\s)/m).map(function (s) { return s.replace(/^\d+\.\s*/, '').trim(); }).filter(Boolean)
            : [seg];
          items.forEach(function (item) {
            if (!item) return;
            if (!pool.some(function (m) { return isMemorySimilar(item, m.content); })) { pool.push(makeMem(item, isCharSeg)); savedCount++; n++; }
            else { skippedCount++; }
          });
          return n;
        };
        var _onlyChar = (_cHead >= 0 && _uHead < 0);
        var _onlySeg = text.substring(_onlyChar ? _cHead : _uHead);
        if (_onlyChar) _pushSegOne(_onlySeg, _dc.memories, true);
        else if (_dAcc) _pushSegOne(_onlySeg, _dAcc.memories, false);
        try { if (_dAcc && typeof waEnsureCharPerson === 'function') waEnsureCharPerson(_dc, _dAcc); } catch (edp2) {}
        _dualHandled = true;
        window._summaryIncomplete = true; // 缺一个板块，保存后提示用户可重新总结补全
      }
    }
  }
  if (!_dualHandled) {
  // 检查是否多条（编号开头）
  const multiMatch = text.match(/^\d+\.\s/gm);
  if (multiMatch && multiMatch.length > 1) {
    // 拆分多条
    const items = text.split(/(?=^\d+\.\s)/m).map(s => s.replace(/^\d+\.\s*/, '').trim()).filter(s => s);
    items.forEach(item => {
      // 只在锁定的目标池内查重，避免不同账号/角色之间互相误判
      var _dup = _lockedTarget.some(function (m) { return isMemorySimilar(item, m.content); });
      if (!_dup) {
        _lockedTarget.push(makeMem(item));
        savedCount++;
      } else {
        skippedCount++;
      }
    });
  } else {
    // 单条记忆也要在目标池内检查重复
    if (!_lockedTarget.some(function (m) { return isMemorySimilar(text, m.content); })) {
      _lockedTarget.push(makeMem(text));
      savedCount++;
    } else {
      skippedCount++;
    }
  }
  } // end !_dualHandled
  // 标记已总结的消息位置，防止下次重复总结。
  // 关键：只要本次确实成功跑过总结（pending 存在），即使新记忆被去重、savedCount=0 也必须推进游标，
  // 否则同一批群消息会因“没产出新记忆”而被一次次重复总结。取消总结时 pending 已被清空，不会误推进。
  if (window._pendingSummarizeUpTo) {
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    for (var k in window._pendingSummarizeUpTo) {
      var _pv = window._pendingSummarizeUpTo[k];
      // 群聊是时间戳游标：只前进不回退；私聊/其他沿用原值
      var _cur = config.summarizedUpTo[_spfx + k];
      config.summarizedUpTo[_spfx + k] = (typeof _pv === 'number' && _pv > 1e12) ? Math.max(_cur || 0, _pv) : _pv;
    }
    window._pendingSummarizeUpTo = null;
    window._pendingSummarizeFrom = null;
  }
  /* 保存完成后清除角色/NPC分区覆盖与本次账号锁定 */
  window._memorySaveCharOverride = -1;
  window._memorySaveNpcOverride = -1;
  window._summarySaveKind = null; window._summarySaveCharIdx = -1; window._summarySaveNpcIdx = -1;
  window._summaryAccId = null; window._summaryAccName = ''; window._summaryPfx = '';
  window._summaryDual = false; window._summaryDualCharIdx = -1;
  Store.set('config', config);
  closeModal('memorySummaryModal');
  renderMemories();
  if (window._summaryIncomplete) {
    showToast('只生成完了一部分（另一板块被长度截断），已保存现有内容，可再点一次总结补全');
    try { window._summaryIncomplete = false; } catch (ei) {}
  } else if (savedCount > 0 && skippedCount > 0) {
    showToast('已保存' + savedCount + '条新记忆（跳过' + skippedCount + '条重复）');
  } else if (savedCount > 0) {
    showToast('已保存' + savedCount + '条记忆');
  } else {
    showToast('所有记忆均已存在，无新内容保存');
  }
}

function editMemory(idx) {
  var map = _memoryDisplayList[idx];
  if (!map) return;
  var mem = null;
  if (map.source === 'accmem') {
    var _ea = memoryAccById(map.accId);
    mem = _ea ? (_ea.memories || [])[map.memIdx] : null;
  } else if (map.source === 'global') {
    mem = (config.memories || [])[map.memIdx];
  } else if (map.source === 'npc') {
    var npc = (config.npcChats || [])[map.npcIdx];
    mem = npc && (npc.memories || [])[map.memIdx];
  } else {
    var char = (config.characters || [])[map.charIdx];
    mem = char && (char.memories || [])[map.memIdx];
  }
  if (!mem) return;
  editingMemoryIdx = idx;
  document.getElementById('memoryEditTitle').textContent = '编辑记忆';
  document.getElementById('memoryEditInput').value = mem.content;
  openModal('memoryEditModal');
}

let editingMemoryIdx = -1;

function saveMemoryEdit() {
  const text = document.getElementById('memoryEditInput').value.trim();
  if (!text) {
    showToast('记忆内容不能为空');
    return;
  }
  var map = _memoryDisplayList[editingMemoryIdx];
  if (!map) return;
  var mem = null;
  if (map.source === 'accmem') {
    var _ea = memoryAccById(map.accId);
    mem = _ea ? (_ea.memories || [])[map.memIdx] : null;
  } else if (map.source === 'global') {
    mem = (config.memories || [])[map.memIdx];
  } else if (map.source === 'npc') {
    var npc = (config.npcChats || [])[map.npcIdx];
    mem = npc && (npc.memories || [])[map.memIdx];
  } else {
    var char = (config.characters || [])[map.charIdx];
    mem = char && (char.memories || [])[map.memIdx];
  }
  if (mem) {
    mem.content = text;
    Store.set('config', config);
    closeModal('memoryEditModal');
    renderMemories();
    showToast('记忆已更新');
  }
}

function deleteMemory(idx) {
  var map = _memoryDisplayList[idx];
  if (!map) return;
  var mem = null;
  var arr = null;
  if (map.source === 'accmem') {
    var _da = memoryAccById(map.accId);
    if (_da) { if (!Array.isArray(_da.memories)) _da.memories = []; arr = _da.memories; mem = arr[map.memIdx]; }
  } else if (map.source === 'global') {
    arr = config.memories || [];
    mem = arr[map.memIdx];
  } else if (map.source === 'npc') {
    var npc = (config.npcChats || [])[map.npcIdx];
    if (npc) { arr = npc.memories || []; mem = arr[map.memIdx]; }
  } else {
    var char = (config.characters || [])[map.charIdx];
    if (char) { arr = char.memories || []; mem = arr[map.memIdx]; }
  }
  if (!mem) return;
  if (!confirm('确定要删除这条记忆吗？')) return;
  // 记录被删除的记忆内容，防止好友恢复时被重新加回
  var deletedContent = mem.content;
  if (!config.deletedMemories) config.deletedMemories = [];
  config.deletedMemories.push(deletedContent);
  // 限制已删除记忆列表大小，避免无限增长
  if (config.deletedMemories.length > 500) {
    config.deletedMemories = config.deletedMemories.slice(-500);
  }
  /* 回滚总结标记：删除记忆后，该段情节允许重新总结 */
  var rollbackRanges = mem._ranges;
  /* 如果记忆自身没有 _ranges，尝试从同一批次（相同时间戳）的记忆中借用 */
  if (!rollbackRanges && arr.length > 0) {
    var memTime = mem.time || 0;
    for (var si = 0; si < arr.length; si++) {
      if (arr[si] && arr[si]._ranges && Math.abs((arr[si].time || 0) - memTime) < 5000) {
        rollbackRanges = arr[si]._ranges;
        break;
      }
    }
  }
  /* 仍然没有 _ranges，尝试从同池中找最近的带 _ranges 的记忆 */
  if (!rollbackRanges && arr.length > 0) {
    var bestDiff = Infinity;
    for (var bi = 0; bi < arr.length; bi++) {
      if (arr[bi] && arr[bi]._ranges) {
        var diff = Math.abs((arr[bi].time || 0) - (mem.time || 0));
        if (diff < bestDiff) { bestDiff = diff; rollbackRanges = arr[bi]._ranges; }
      }
    }
  }
  if (rollbackRanges) {
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    for (var rk in rollbackRanges) {
      var rg = rollbackRanges[rk];
      if (!rg) continue;
      var cur = config.summarizedUpTo[rk] || 0;
      /* 只回滚到该情节的起点，不影响其他情节的进度 */
      if (typeof rg.from === 'number' && rg.from < cur) {
        config.summarizedUpTo[rk] = rg.from;
      }
    }
  } else if (mem.source === 'ai' || !mem.source) {
    /* AI总结的记忆但没有 _ranges（旧数据）：根据来源推断上下文，重置对应标记 */
    if (!config.summarizedUpTo) config.summarizedUpTo = {};
    if (map.source === 'char') {
      var cKey = 'char_' + map.charIdx;
      config.summarizedUpTo[cKey + '_online'] = 0;
      config.summarizedUpTo[cKey + '_offline'] = 0;
    } else if (map.source === 'npc') {
      var nKey = 'npc_' + map.npcIdx;
      config.summarizedUpTo[nKey + '_online'] = 0;
    } else if (map.source === 'global') {
      /* 全局记忆（群聊总结）：重置所有 group_ 开头的标记 */
      for (var gk in config.summarizedUpTo) {
        if (gk.indexOf('group_') === 0) {
          config.summarizedUpTo[gk] = 0;
        }
      }
    }
  }
  arr.splice(map.memIdx, 1);
  Store.set('config', config);
  renderMemories();
  showToast('记忆已删除');
}

function openManualMemoryModal() {
  document.getElementById('manualMemoryInput').value = '';
  /* 在角色分区里手动导入时，存入该角色的记忆池 */
  window._memorySaveCharOverride = (_memoryTabCharIdx >= 0) ? _memoryTabCharIdx : -1;
  /* 在NPC分区里手动导入时，存入该NPC的记忆池 */
  window._memorySaveNpcOverride = (_memoryTabNpcIdx >= 0) ? _memoryTabNpcIdx : -1;
  /* 在某用户账号分区手动导入时，存入该账号的记忆池 */
  window._memorySaveAccId = (_memoryTabAccId != null) ? _memoryTabAccId : null;
  openModal('manualMemoryModal');
  setTimeout(() => document.getElementById('manualMemoryInput').focus(), 100);
}

function saveManualMemory() {
  const text = document.getElementById('manualMemoryInput').value.trim();
  if (!text) {
    showToast('记忆内容不能为空');
    return;
  }
  var _manualTarget = getMemorySaveTarget();
  // 只在“将要写入的目标池”内查重，避免不同账号/角色之间互相误判重复
  var _dupInTarget = (_manualTarget || []).some(function (m) { return isMemorySimilar(text, m.content); });
  if (_dupInTarget) {
    showToast('该记忆在此分区已存在或高度相似');
    return;
  }
  _manualTarget.push({ content: text, time: Date.now(), source: 'manual' });
  window._memorySaveCharOverride = -1;
  window._memorySaveNpcOverride = -1;
  window._memorySaveAccId = null;
  Store.set('config', config);
  closeModal('manualMemoryModal');
  renderMemories();
  showToast('记忆已保存');
}

// ===== 消息长按编辑/删除 =====
let longPressMsgIdx = -1;
let longPressLineIdx = -1;
let longPressTimer = null;

function attachLongPress() {
  const container = document.getElementById('chatMessages');
  // 线上模式：气泡长按
  container.querySelectorAll('.msg-bubble').forEach(bubble => {
    const idx = parseInt(bubble.dataset.msgIdx);
    if (isNaN(idx)) return;
    const lineIdx = bubble.dataset.lineIdx !== undefined ? parseInt(bubble.dataset.lineIdx) : -1;
    bubble.addEventListener('touchstart', function(e) {
      longPressTimer = setTimeout(() => {
        longPressMsgIdx = idx;
        longPressLineIdx = lineIdx;
        showMsgActionMenu(e);
      }, 500);
    });
    bubble.addEventListener('touchend', function() { clearTimeout(longPressTimer); });
    bubble.addEventListener('touchmove', function() { clearTimeout(longPressTimer); });
    bubble.addEventListener('contextmenu', function(e) {
      e.preventDefault();
      longPressMsgIdx = idx;
      longPressLineIdx = lineIdx;
      showMsgActionMenu(e);
    });
  });
  // 线下模式：小说段落长按
  container.querySelectorAll('.novel-paragraph[data-msg-idx]').forEach(para => {
    const idx = parseInt(para.dataset.msgIdx);
    if (isNaN(idx)) return;
    const lineIdx = para.dataset.lineIdx !== undefined ? parseInt(para.dataset.lineIdx) : -1;
    para.addEventListener('touchstart', function(e) {
      longPressTimer = setTimeout(() => {
        longPressMsgIdx = idx;
        longPressLineIdx = lineIdx;
        showMsgActionMenu(e);
      }, 500);
    });
    para.addEventListener('touchend', function() { clearTimeout(longPressTimer); });
    para.addEventListener('touchmove', function() { clearTimeout(longPressTimer); });
    para.addEventListener('contextmenu', function(e) {
      e.preventDefault();
      longPressMsgIdx = idx;
      longPressLineIdx = lineIdx;
      showMsgActionMenu(e);
    });
  });
}

function showMsgActionMenu(e) {
  const menu = document.getElementById('msgActionMenu');
  /* 长按的是AI语音消息时，显示转文字选项 */
  const transcribeBtn = document.getElementById('msgActionTranscribe');
  if (transcribeBtn && longPressMsgIdx >= 0) {
    const msg = config.chatHistory[longPressMsgIdx];
    var isAiVoice = false;
    /* 方式1：标准 voice 类型消息 */
    if (msg && msg.type === 'voice' && msg.role === 'assistant') {
      isAiVoice = true;
    }
    /* 方式2：通过 DOM 直接判断——被长按的气泡有 msg-voice-ai 类 */
    if (!isAiVoice && e && e.target) {
      var bubble = e.target.closest && e.target.closest('.msg-bubble');
      if (bubble && bubble.classList.contains('msg-voice-ai')) isAiVoice = true;
    }
    /* 方式3：内容里包含 [语音：xxx] 标签（兼容旧数据，任意位置都匹配） */
    if (!isAiVoice && msg && msg.role === 'assistant' && msg.content) {
      if (msg.content.indexOf('[语音：') >= 0 || msg.content.indexOf('[语音:') >= 0) isAiVoice = true;
    }
    transcribeBtn.style.display = isAiVoice ? 'block' : 'none';
  } else if (transcribeBtn) {
    transcribeBtn.style.display = 'none';
  }
  /* 检测消息是否包含外语文本（非中文的非空白字符占比高时显示翻译按钮） */
  const translateBtn = document.getElementById('msgActionTranslate');
  if (translateBtn && longPressMsgIdx >= 0) {
    const msg = config.chatHistory[longPressMsgIdx];
    var showTranslate = false;
    if (msg && msg.content) {
      var rawText = String(msg.content)
        .replace(THINK_CLOSED_RE, '')
        .replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '')
        .replace(/\[[^\]]+\]/g, '')  /* 去掉 [转账：...] 等标记 */
        .replace(/表情包-[^\s<]+/g, '')
        .trim();
      if (rawText.length > 0) {
        /* 统计拉丁字母、西里尔字母、阿拉伯字母、日文假名、韩文等外文字符 */
        var foreignChars = rawText.match(/[a-zA-Z\u00C0-\u024F\u0400-\u04FF\u0600-\u06FF\u3040-\u309F\u30A0-\u30FF\uAC00-\uD7AF]/g);
        var chineseChars = rawText.match(/[\u4e00-\u9fff]/g);
        var foreignCount = foreignChars ? foreignChars.length : 0;
        var chineseCount = chineseChars ? chineseChars.length : 0;
        /* 当外文字符数 >= 3 且外文字符占比高于中文字符时显示翻译 */
        if (foreignCount >= 3 && foreignCount > chineseCount) {
          showTranslate = true;
        }
      }
    }
    translateBtn.style.display = showTranslate ? 'block' : 'none';
  } else if (translateBtn) {
    translateBtn.style.display = 'none';
  }
  const touch = e.touches ? e.touches[0] : e;
  let x = touch.clientX || e.clientX;
  let y = touch.clientY || e.clientY;
  const rect = document.querySelector('.phone-screen').getBoundingClientRect();
  x = x - rect.left;
  y = y - rect.top;
  // 确保不超出边界
  if (x > rect.width - 130) x = rect.width - 130;
  if (y > rect.height - 100) y = rect.height - 100;
  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
  /* 长按菜单挂在 .phone-screen 上（不在微信视图里面），拿不到视图的 .theme-light，
     日间下要单独补一个，否则白色界面里会弹出一块深灰菜单 */
  try { menu.classList.toggle('theme-light', (typeof isLightTheme === 'function') && isLightTheme()); } catch (e) {}
  menu.classList.add('show');
}

function hideMsgActionMenu() {
  document.getElementById('msgActionMenu').classList.remove('show');
}

// ===== 消息翻译功能（内联渲染，和转文字一样） =====
function translateMessage() {
  if (longPressMsgIdx < 0) return;
  var msg = config.chatHistory[longPressMsgIdx];
  if (!msg || !msg.content) { hideMsgActionMenu(); return; }

  /* 已有缓存的翻译且当前可见：切换隐藏 */
  if (msg.translation && msg.translationVisible) {
    msg.translationVisible = false;
    syncCharHistory();
    Store.set('config', config);
    renderMessages();
    return;
  }
  /* 已有缓存的翻译但隐藏中：切换显示 */
  if (msg.translation && !msg.translationVisible) {
    msg.translationVisible = true;
    syncCharHistory();
    Store.set('config', config);
    renderMessages();
    return;
  }

  /* 提取纯文本：去掉thinking/miyavoice标签和特殊标记 */
  var rawText = String(msg.content)
    .replace(THINK_CLOSED_RE, '')
    .replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '')
    .replace(/\[转账[：:][^\]]+\]/g, '')
    .replace(/\[红包[：:][^\]]+\]/g, '')
    .replace(/\[位置[：:][^\]]+\]/g, '')
    .replace(/\[照片[：:][^\]]+\]/g, '')
    .replace(/\[语音[：:][^\]]+\]/g, '')
    .replace(/表情包-[^\s<]+/g, '')
    .trim();

  if (!rawText) { showToast('没有可翻译的内容'); hideMsgActionMenu(); return; }

  hideMsgActionMenu();

  /* 先显示"正在翻译..."占位 */
  msg.translation = '__loading__';
  msg.translationVisible = true;
  renderMessages();

  /* 调用API翻译 */
  var charName = (config.role && config.role.name) ? config.role.name : '对方';
  var messages = [
    {
      role: 'system',
      content: '你是一个专业翻译引擎。用户会给你一段聊天消息，请将其翻译成中文。如果消息已经是中文，请原样返回。只返回翻译结果，不要添加任何解释或说明。'
    },
    {
      role: 'user',
      content: '请将以下来自"' + charName + '"的消息翻译成中文：\n\n' + rawText
    }
  ];

  callApi(messages, { temperature: 0.3, maxTokens: 1000 })
    .then(function(result) {
      var translated = String(result || '').trim();
      if (!translated) translated = '翻译结果为空';
      msg.translation = translated;
      msg.translationVisible = true;
      syncCharHistory();
      Store.set('config', config);
      renderMessages();
    })
    .catch(function(err) {
      msg.translation = '翻译失败：' + (err && err.message ? err.message : '请稍后重试');
      msg.translationVisible = true;
      msg._translationError = true;
      syncCharHistory();
      Store.set('config', config);
      renderMessages();
    });
}

function toggleTranslation(msgIdx) {
  var msg = config.chatHistory[msgIdx];
  if (!msg || !msg.translation) return;
  msg.translationVisible = !msg.translationVisible;
  syncCharHistory();
  Store.set('config', config);
  renderMessages();
}

function editMessage() {
  if (longPressMsgIdx < 0) return;
  const msg = config.chatHistory[longPressMsgIdx];
  if (!msg) { hideMsgActionMenu(); return; }
  if (msg.type === 'image' || msg.type === 'fakephoto' || msg.type === 'redpacket' || msg.type === 'transfer' || msg.type === 'repost' || msg.type === 'voice' || msg.type === 'call' || msg.type === 'order' || msg.type === 'couple-avatar') {
    showToast('该消息不支持编辑');
    hideMsgActionMenu();
    return;
  }
  hideMsgActionMenu();
  // 显示输入栏并填入消息内容（AI消息需去除thinking/miyavoice标签）
  const input = document.getElementById('chatInput');
  let editContent = msg.content;
  if (msg.role === 'assistant') {
    const parsed = parseAiResponse(msg.content);
    editContent = parsed.content || '';
  }
  input.value = editContent;
  input.dispatchEvent(new Event('input'));
  input.focus();
  // 标记为编辑模式
  input.dataset.editIdx = longPressMsgIdx;
  // 线下模式编辑AI回复：仅替换内容，不重新调用API
  if (currentChatMode === 'offline' && msg.role === 'assistant') {
    input.dataset.editOnly = '1';
    showToast('修改后发送将直接替换此条回复');
  } else {
    showToast('已载入消息，修改后发送将替换原消息');
  }
}

function deleteMessage() {
  if (longPressMsgIdx < 0) return;
  hideMsgActionMenu();
  const msg = config.chatHistory[longPressMsgIdx];
  if (!msg) return;
  
  /* 同步调整 summarizedUpTo 标记：删除消息后，标记前的消息少了一条，标记需要前移 */
  function adjustSummaryMarker(deletedIdx) {
    if (!config.summarizedUpTo) return;
    // 多人线下：该会话对应每个参与角色的 goff 标记都要前移
    if (typeof isGroupOfflineMode !== 'undefined' && isGroupOfflineMode && _currentGroupOfflineIdx >= 0) {
      var _goPref = 'goff_' + _currentGroupOfflineIdx + '_char_';
      for (var _gk in config.summarizedUpTo) {
        if (_gk.indexOf(_goPref) === 0 && config.summarizedUpTo[_gk] > deletedIdx) {
          config.summarizedUpTo[_gk] -= 1;
          if (config.summarizedUpTo[_gk] < 0) config.summarizedUpTo[_gk] = 0;
        }
      }
      return;
    }
    var mKey = null, mSub = null;
    if (isNpcChatMode && currentNpcChatIdx >= 0) {
      mKey = 'npc_' + currentNpcChatIdx; mSub = '_online';
    } else if (isGroupChatMode && _currentGroupIdx >= 0) {
      mKey = 'group_' + _currentGroupIdx; mSub = '';
    } else if (currentCharIdx >= 0) {
      mKey = 'char_' + currentCharIdx;
      /* 线下模式用 _offline 标记，线上用 _online */
      mSub = (currentChatMode === 'offline') ? '_offline' : '_online';
    }
    if (!mKey) return;
    var fullKey = mKey + mSub;
    var cur = config.summarizedUpTo[fullKey];
    if (cur !== undefined && cur > deletedIdx) {
      /* 删除的消息在标记之前，标记前移1位 */
      config.summarizedUpTo[fullKey] = cur - 1;
      if (config.summarizedUpTo[fullKey] < 0) config.summarizedUpTo[fullKey] = 0;
    }
    /* 如果是角色模式，还需要检查另一个标记（online/offline） */
    if (currentCharIdx >= 0 && mSub === '_offline') {
      var onlineKey = 'char_' + currentCharIdx + '_online';
      var curOnline = config.summarizedUpTo[onlineKey];
      if (curOnline !== undefined && curOnline > deletedIdx) {
        config.summarizedUpTo[onlineKey] = curOnline - 1;
        if (config.summarizedUpTo[onlineKey] < 0) config.summarizedUpTo[onlineKey] = 0;
      }
    } else if (currentCharIdx >= 0 && mSub === '_online') {
      var offlineKey = 'char_' + currentCharIdx + '_offline';
      var curOffline = config.summarizedUpTo[offlineKey];
      if (curOffline !== undefined && curOffline > deletedIdx) {
        config.summarizedUpTo[offlineKey] = curOffline - 1;
        if (config.summarizedUpTo[offlineKey] < 0) config.summarizedUpTo[offlineKey] = 0;
      }
    }
  }
  
  // 线下模式：始终删除整条消息（一次生成的全部内容）
  if (currentChatMode === 'offline') {
    if (!confirm('确定要删除这次生成的全部内容吗？')) return;
    adjustSummaryMarker(longPressMsgIdx);
    config.chatHistory.splice(longPressMsgIdx, 1);
    syncCharHistory();
    Store.set('config', config);
    renderMessages();
    updateHeartBtn();
    showToast('已删除整条回复');
    longPressLineIdx = -1;
    return;
  }
  
  // 线上模式：如果有行索引且消息是多行AI回复，只删除对应行
  if (longPressLineIdx >= 0 && msg.role === 'assistant') {
    const parsed = parseAiResponse(msg.content);
    const lines = parsed.content.split('\n').filter(l => l.trim());
    if (lines.length > 1 && longPressLineIdx < lines.length) {
      if (!confirm('确定要删除这条消息吗？')) return;
      lines.splice(longPressLineIdx, 1);
      // 重新组装消息内容
      let newContent = lines.join('\n');
      // 保留thinking和miyavoice标签
      if (parsed.thinking) newContent = '<thinking>' + parsed.thinking + '</thinking>\n' + newContent;
      if (parsed.miyavoice) {
        let voiceStr = '<miyavoice>\n';
        for (const [k, v] of Object.entries(parsed.miyavoice)) {
          voiceStr += k + '：' + v + '\n';
        }
        voiceStr += '</miyavoice>\n';
        newContent = voiceStr + newContent;
      }
      msg.content = newContent;
      syncCharHistory();
      Store.set('config', config);
      renderMessages();
      updateHeartBtn();
      showToast('已删除该条');
      longPressLineIdx = -1;
      return;
    }
  }
  
  // 普通删除：删除整条消息
  if (!confirm('确定要删除这条消息吗？')) return;
  adjustSummaryMarker(longPressMsgIdx);
  config.chatHistory.splice(longPressMsgIdx, 1);
  syncCharHistory();
  Store.set('config', config);
  renderMessages();
  updateHeartBtn();
  showToast('消息已删除');
  longPressLineIdx = -1;
}

// ===== 引用回复 =====
var pendingQuote = null;

function quoteMessage() {
  if (longPressMsgIdx < 0) { hideMsgActionMenu(); return; }
  var msg = config.chatHistory[longPressMsgIdx];
  hideMsgActionMenu();
  if (!msg) return;
  if (msg.role === 'system') { showToast('系统消息不支持引用'); return; }
  if (msg.type === 'redpacket' || msg.type === 'transfer' || msg.type === 'repost' || msg.type === 'call' || msg.type === 'fakephoto' || msg.type === 'order') { showToast('该消息不支持引用'); return; }
  if (msg.type === 'voice' && msg.role === 'assistant') { showToast('语音消息不支持引用'); return; }

  var name = msg.role === 'user'
    ? ((config.user && (config.user.wxName || config.user.name)) || '我')
    : (msg.senderName || (config.role && config.role.name) || '对方');
  var text = '';
  if (msg.type === 'image') {
    text = '[图片]';
  } else if (msg.type === 'couple-avatar') {
    text = '[图片]';
  } else {
    text = (msg.content || '')
      .replace(THINK_CLOSED_RE, '')
      .replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '')
      .replace(/<inner_voice[^>]*>[\s\S]*?<\/inner_voice>/gi, '')
      .replace(/\[语音[：:]([^\]]+)\]/g, '[语音]')
      .replace(/\[红包[：:]([^\]]+)\]/g, '[红包]')
      .trim();
    // 多行AI回复：只引用长按的那一行
    if (msg.role === 'assistant' && longPressLineIdx >= 0) {
      var lines = text.split('\n').filter(function(l) { return l.trim(); });
      if (longPressLineIdx < lines.length) text = lines[longPressLineIdx].trim();
    }
  }
  if (!text) { showToast('该消息不支持引用'); return; }
  if (text.length > 80) text = text.substring(0, 80) + '…';

  pendingQuote = { name: name, text: text };
  var bar = document.getElementById('quotePreviewBar');
  var barText = document.getElementById('quotePreviewText');
  if (bar && barText) {
    barText.textContent = name + '：' + text;
    bar.style.display = 'flex';
  }
  var input = document.getElementById('chatInput');
  if (input) input.focus();
}

function cancelQuote() {
  pendingQuote = null;
  var bar = document.getElementById('quotePreviewBar');
  if (bar) bar.style.display = 'none';
}

// ===== 一起听歌 / 一起看书 =====
var _sharedActivityBusy = false;
async function startSharedActivity(kind) {
  closeChatPlusMenu();
  if (isGroupChatMode || isNpcChatMode) { showToast('仅在私聊中可用'); return; }
  var api = config.api;
  if (!api.baseUrl || !api.apiKey || !api.model) { showToast('请先配置API'); return; }
  var role = config.role;
  if (!role || !role.name) return;
  if (_sharedActivityBusy) return;
  _sharedActivityBusy = true;

  var char = config.characters ? config.characters[currentCharIdx] : null;
  var kindLabel = kind === 'music' ? '一起听歌' : '一起看小说';
  // 用户发出邀请卡片
  config.chatHistory.push({ role: 'user', content: '[邀请' + kindLabel + ']', time: Date.now() });
  syncCharHistory();
  Store.set('config', config);
  renderMessages();
  scrollChatToBottom();
  showTypingIndicator();

  try {
    var mood = char ? getCharLastMood(char) : '';
    var cardFormat = kind === 'music' ? '[一起听：歌名，歌手]' : '[一起看：书名，作者]';
    var thingDesc = kind === 'music' ? '一首歌曲' : '一本小说';
    var sys = '你是' + (role.name || '对方') + '。' + (role.persona || '').substring(0, 2000) + '\n\n用户邀请你' + kindLabel + '，你欣然接受。' + (mood ? '你最近的心情：' + mood + '。' : '') + '\n\n请回复：\n1. 第一行单独输出你要分享的' + thingDesc + '卡片，格式：' + cardFormat + '（选真实存在且符合你人设/此刻心情的作品）\n2. 第二行起写1-2句口语化的短消息，像发微信一样说说你为什么选它、或此刻的感受\n3. 不要解释格式，不要加引号，不要提"邀请"两个字';
    var reply = await callApi([
      { role: 'system', content: sys },
      { role: 'user', content: '（对方接受了你的' + kindLabel + '邀请）' }
    ], { maxTokens: 200, temperature: 0.9 });
    hideTypingIndicator();
    reply = (reply || '').trim();
    if (!reply) { _sharedActivityBusy = false; return; }
    config.chatHistory.push({ role: 'assistant', content: reply, time: Date.now() });
    syncCharHistory();
    Store.set('config', config);
    renderMessages();
    scrollChatToBottom();
  } catch(e) {
    hideTypingIndicator();
    showToast('对方暂时没空，稍后再试');
  } finally {
    _sharedActivityBusy = false;
  }
}

// ===== 自动检测移动设备并启用全屏模式 =====
(function autoDetectMobile() {
  var isMobile = false;
  // UA 检测
  var ua = navigator.userAgent || '';
  if (/Mobi|Android|iPhone|iPad|iPod|Windows Phone|BlackBerry|Opera Mini|IEMobile/i.test(ua)) {
    isMobile = true;
  }
  // 触摸检测
  if (!isMobile && (navigator.maxTouchPoints > 0 || 'ontouchstart' in window)) {
    // 有触摸能力且屏幕较窄，判定为移动设备
    if (window.innerWidth <= 900) {
      isMobile = true;
    }
  }
  // matchMedia 检测
  if (!isMobile && window.matchMedia && window.matchMedia('(hover: none) and (pointer: coarse)').matches) {
    isMobile = true;
  }
  if (isMobile) {
    var frame = document.getElementById('phoneFrame');
    if (frame && !frame.classList.contains('fullscreen')) {
      frame.classList.add('fullscreen');
    }
    document.body.style.padding = '0';
    document.documentElement.style.padding = '0';
    // 动态注入全局覆盖样式，确保所有 fixed 定位的覆盖层填满屏幕
    var styleEl = document.createElement('style');
    styleEl.id = 'auto-mobile-fix';
    styleEl.textContent = [
      '.ws-overlay,.rc-overlay,.pw-overlay,.pw-action-sheet,',
      '.sf-overlay,.sf-detail-overlay,.sf-dm-detail-overlay,.sf-trend-detail-overlay,.sf-char-profile-overlay,',
      '.df-overlay,.df-detail-overlay',
      '{max-width:100vw !important;width:100% !important;}',
      '.modal-overlay{border-radius:0 !important;}'
    ].join('');
    document.head.appendChild(styleEl);
  }
})();

