/* IndexedDB 加载完成后：优先使用 IndexedDB 数据（更可靠，避免 localStorage 配额截断导致头像丢失）。
   用 onStoreReadyFirst 插队到所有启动迁移之前，先完成全局 config 注入 */
onStoreReadyFirst(function() {
  try {
    var idbConfig = _memStore['config'];
    if (idbConfig && typeof idbConfig === 'object' && !Array.isArray(idbConfig) && typeof config !== 'undefined') {
      /* IndexedDB 是权威数据源（参考图等大字段只在 IDB 完整保存）。按“保存时间戳”判断新旧，不再比数据长度 */
      var idbSaved = (idbConfig && idbConfig._savedAt) || 0;
      var lsConfigRaw = null, lsSaved = 0;
      try { lsConfigRaw = localStorage.getItem('mochi_config'); if (lsConfigRaw) { var _lsCfg = JSON.parse(lsConfigRaw); lsSaved = (_lsCfg && _lsCfg._savedAt) || 0; } } catch(e) {}
      /* IDB 不早于 LS 就采用 IDB（含两边都无时间戳的老数据）；仅当 LS 时间戳明确更新（IDB 写入失败的极端兜底）才保留 LS */
      var useIdb = !lsConfigRaw || idbSaved >= lsSaved;
      var _waPrevMemCfg = config; // 汇合前的内存/LS config
      if (useIdb) {
        config = idbConfig;
        // 双向账号合并：主体=IDB，把内存里同 id 更全字段、以及 IDB 缺失的“有内容账号”补回；空壳不并入
        try { if (typeof waMergeRicherAccounts === 'function' && _waPrevMemCfg && _waPrevMemCfg !== idbConfig) { waMergeRicherAccounts(idbConfig, _waPrevMemCfg); } } catch (e) {}
        /* ★根因修复：IndexedDB 权威 config 是异步到达的，可能晚于 world-accounts 首次迁移，
           这次整体赋值会把首次迁移生成的 worlds/账号冲掉而导致旧版用户人设(config.user)看似丢失。
           因此在权威 config 就位后必须补跑一次账号/世界迁移（迁移幂等，已迁移会自动跳过），
           并重新挂载当前账号，保证人设、联系人、聊天记录都落到正确账号上。 */
        try { if (typeof waMigrate === 'function') waMigrate(); } catch(e) { console.warn('[WA] remigrate on IDB load:', e); }
        try { if (typeof waEnsureMount === 'function') waEnsureMount(); } catch(e) {}
        /* 重新迁移新加载的 config 字段 */
        if (!config.settings) config.settings = { streaming: true, temperature: 0.8, maxTokens: 2000, pageCss: '', bubbleCss: '' };
        if (config.settings.pageCss === undefined) config.settings.pageCss = '';
        if (config.settings.bubbleCss === undefined) config.settings.bubbleCss = '';
        if (config.settings.dynamicIslandVisible === undefined) config.settings.dynamicIslandVisible = true;
        try { applyCustomCss(); } catch(e) { console.warn('applyCustomCss on IDB load:', e); }
        /* IndexedDB 备份里的主题在此时才加载，必须重新应用一次，否则刷新后内部是 light、界面却停在深色，首次点切换反而切到 dark，表现为“切换没反应” */
        try { applyTheme(); } catch(e) { console.warn('applyTheme on IDB load:', e); }
        setTimeout(function() {
          try { updateHome(); } catch(e) {}
          try { updateBadges(); } catch(e) {}
          try { renderChatList(); } catch(e) {}
          requestAnimationFrame(function() {
            try { registerCustomWidgets(); } catch(e) { console.warn('registerCustomWidgets on IDB load:', e); }
            try { renderAppGrids(); } catch(e) {}
            try { renderHomeWidgets(); } catch(e) {}
            try { if (typeof updateSettingsView === 'function') updateSettingsView(); } catch(e) {}
            try { if (typeof applyHomeWallpaper === 'function') applyHomeWallpaper(); } catch(e) {}
            try { if (typeof renderHomeScreen === 'function') renderHomeScreen(); } catch(e) {}
            try { if (typeof renderDock === 'function') renderDock(); } catch(e) {}
            try { if (typeof renderMe === 'function') renderMe(); } catch(e) {}
            try { if (typeof applyLockWallpaper === 'function') applyLockWallpaper(); } catch(e) {}
            try { if (typeof loadAppIconOverridesFromIDB === 'function') loadAppIconOverridesFromIDB(); } catch(e) {}
            console.debug('[Store] IndexedDB 数据已加载，UI 已刷新');
          });
        }, 0);
      } else {
        /* 内存/LS 时间戳更新而保留它时，IDB 里可能仍装着它缺失的“原主账号”（典型：启动竞态新建了空壳并先落盘）。
           必须把 IDB 的有内容账号/更全字段并回当前 config，再清理空壳、补迁移与重挂载，否则原人设会被空壳顶替丢失。 */
        try { if (typeof waMergeRicherAccounts === 'function') waMergeRicherAccounts(config, idbConfig); } catch (e) {}
        try { if (typeof waReconcileUserAccounts === 'function') waReconcileUserAccounts(); } catch (e) {}
        try { if (typeof waMigrate === 'function') waMigrate(); } catch (e) {}
        try { if (typeof waEnsureMount === 'function') waEnsureMount(); } catch (e) {}
        try { applyCustomCss(); } catch (e) {}
        try { applyTheme(); } catch (e) {}
        setTimeout(function () {
          try { updateHome(); } catch (e) {}
          try { updateBadges(); } catch (e) {}
          try { renderChatList(); } catch (e) {}
          requestAnimationFrame(function () {
            try { registerCustomWidgets(); } catch (e) {}
            try { renderAppGrids(); } catch (e) {}
            try { renderHomeWidgets(); } catch (e) {}
            try { if (typeof updateSettingsView === 'function') updateSettingsView(); } catch (e) {}
            try { if (typeof applyHomeWallpaper === 'function') applyHomeWallpaper(); } catch (e) {}
            try { if (typeof renderHomeScreen === 'function') renderHomeScreen(); } catch (e) {}
            try { if (typeof renderDock === 'function') renderDock(); } catch (e) {}
            try { if (typeof renderMe === 'function') renderMe(); } catch (e) {}
          });
        }, 0);
      }
    }
  } catch(e) {
    console.error('[Store] IndexedDB config 加载失败，使用现有 config:', e);
  }
});
