/* ============================================================
 * PART 4 - Storage Abstraction (uses Store if available)
 * ============================================================ */

/* 论坛按“世界 + 账号”隔离：每个世界/账号是一个独立社会，帖子/关注/点赞/收藏/私信/通知全部独立成桶 */
var sfScope = function () {
  try {
    var sn = (typeof config !== 'undefined' && config && config.waSession) || null;
    if (sn && sn.worldId) return 'sf__' + String(sn.worldId) + '__' + String(sn.kind || 'none') + '__' + String(sn.refId || '0') + '__';
  } catch (e) {}
  return 'sf__none__';
};
window.sfScope = sfScope;
var sfStorage = {
  get: function (key) {
    key = sfScope() + key;
    try {
      if (typeof Store !== 'undefined' && Store && typeof Store.get === 'function') {
        return Store.get(key, null);
      }
      return localStorage.getItem(key);
    } catch (e) { return null; }
  },
  set: function (key, val) {
    key = sfScope() + key;
    try {
      if (typeof Store !== 'undefined' && Store && typeof Store.set === 'function') {
        Store.set(key, val);
        return;
      }
      localStorage.setItem(key, val);
    } catch (e) {}
  },
  remove: function (key) {
    key = sfScope() + key;
    try {
      if (typeof Store !== 'undefined' && Store && typeof Store.del === 'function') { Store.del(key); return; }
      if (typeof Store !== 'undefined' && Store && typeof Store.remove === 'function') { Store.remove(key); return; }
      localStorage.removeItem(key);
    } catch (e) {}
  },
  /* 显式指定作用域（异步任务在发起时锁定，避免生成过程中切换账号把结果存错桶）；scope 传 null 则用当前作用域 */
  setIn: function (scope, key, val) { try { var k = (scope || sfScope()) + key; if (typeof Store !== 'undefined' && Store) { Store.set(k, val); return; } localStorage.setItem(k, val); } catch (e) {} },
  getIn: function (scope, key) { key = (scope || sfScope()) + key; try { if (typeof Store !== 'undefined' && Store) return Store.get(key, null); return localStorage.getItem(key); } catch (e) { return null; } }
};

/* ============================================================
 * PART 5 - Helper Functions
 * ============================================================ */

var sfEscapeHtml = function (str) {
  if (typeof escapeHtml === 'function') return escapeHtml(str);
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
};

var sfToast = function (msg) {
  if (typeof showToast === 'function') { showToast(msg); return; }
  if (typeof toast === 'function') { toast(msg); return; }
};

var sfEl = function (id) {
  return document.getElementById(id);
};

var sfHandle = function (name) {
  return '@' + String(name || 'anon').replace(/[\s@]+/g, '').substring(0, 12).toLowerCase();
};

var sfInitial = function (name) {
  var n = String(name || '匿').trim();
  return n ? n.charAt(0) : '?';
};

var sfFormatNum = function (n) {
  n = Number(n) || 0;
  if (n >= 10000) return (n / 10000).toFixed(1) + 'w';
  if (n >= 1000) return (n / 1000).toFixed(1) + 'k';
  return String(n);
};

var sfRandomGradient = function (seed) {
  if (typeof seed === 'number') {
    return SF_GRADIENTS[seed % SF_GRADIENTS.length];
  }
  return SF_GRADIENTS[Math.floor(Math.random() * SF_GRADIENTS.length)];
};

var sfGradientCss = function (grad) {
  if (!grad || grad.length < 2) return 'linear-gradient(135deg,#F5A0B8,#FFC7D9)';
  return 'linear-gradient(135deg,' + grad[0] + ',' + grad[1] + ')';
};

var sfAvatarGradient = function (index) {
  var colors = SF_AVATAR_COLORS[(index || 0) % SF_AVATAR_COLORS.length];
  return 'linear-gradient(135deg,' + colors[0] + ',' + colors[1] + ')';
};

/* Generate an SVG data URI avatar for fallback (no external images needed). */
var sfGetAvatarSrc = function (index, name) {
  var idx = (index || 0) % SF_AVATAR_COLORS.length;
  var colors = SF_AVATAR_COLORS[idx];
  var initial = sfInitial(name);
  var gid = 'sfag' + idx;
  var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="42" height="42">'
    + '<defs><linearGradient id="' + gid + '" x1="0" y1="0" x2="1" y2="1">'
    + '<stop offset="0" stop-color="' + colors[0] + '"/>'
    + '<stop offset="1" stop-color="' + colors[1] + '"/>'
    + '</linearGradient></defs>'
    + '<rect width="42" height="42" rx="21" fill="url(#' + gid + ')"/>'
    + '<text x="21" y="28" font-size="17" font-weight="700" fill="#fff" text-anchor="middle" font-family="sans-serif">' + initial + '</text>'
    + '</svg>';
  return 'data:image/svg+xml,' + encodeURIComponent(svg);
};

/* Resolve a role/character avatar to a usable src. */
var sfRoleAvatarSrc = function (role) {
  if (!role) return sfGetAvatarSrc(0, '?');
  if (role.avatar) return role.avatar;
  if (typeof avatarOf === 'function') return avatarOf(role.name, role.avatar);
  return sfGetAvatarSrc(0, role.name);
};

/* A cute pink mascot (inline SVG) used in empty states. */
var sfMascotSvg = function (size) {
  size = size || 96;
  return '<svg xmlns="http://www.w3.org/2000/svg" width="' + size + '" height="' + size
    + '" viewBox="0 0 96 96">'
    + '<defs><linearGradient id="fmG" x1="0" x2="1" y1="0" y2="1">'
    + '<stop stop-color="#FFE4EE"/><stop offset="1" stop-color="#FFC7D9"/></linearGradient></defs>'
    + '<ellipse cx="48" cy="74" rx="30" ry="8" fill="#FFD3DE" opacity=".6"/>'
    + '<circle cx="48" cy="50" r="26" fill="url(#fmG)" stroke="#F5A0B8" stroke-width="2"/>'
    + '<ellipse cx="33" cy="30" rx="7" ry="12" fill="#FFC4D6" stroke="#F5A0B8" stroke-width="1.5" transform="rotate(-18 33 30)"/>'
    + '<ellipse cx="63" cy="30" rx="7" ry="12" fill="#FFC4D6" stroke="#F5A0B8" stroke-width="1.5" transform="rotate(18 63 30)"/>'
    + '<circle cx="39" cy="48" r="3.2" fill="#5b3a4a"/>'
    + '<circle cx="57" cy="48" r="3.2" fill="#5b3a4a"/>'
    + '<circle cx="40.2" cy="47" r="1" fill="#fff"/><circle cx="58.2" cy="47" r="1" fill="#fff"/>'
    + '<path d="M42 58 Q48 63 54 58" stroke="#F5A0B8" stroke-width="2.4" fill="none" stroke-linecap="round"/>'
    + '<circle cx="32" cy="55" r="3.4" fill="#FFC7D9" opacity=".55"/>'
    + '<circle cx="64" cy="55" r="3.4" fill="#FFC7D9" opacity=".55"/>'
    + '</svg>';
};

