var sfFallbackPosts = function (tab, roleName, followedRolesData) {
  var isFollowing = (tab === 'following');
  var isGossip = (tab === 'gossip');
  var roles = Array.isArray(followedRolesData) ? followedRolesData : [];
  if (roles.length === 0 && roleName) {
    roles = [{ name: roleName, prompt: '', avatar: null }];
  }

  var count = isFollowing ? Math.max(6, roles.length * 2) : (6 + Math.floor(Math.random() * 3));
  var posts = [];

  /* 帖子模板按长度分组：短/中/长 */
  var allTemplates = isFollowing
    ? SF_FOLLOWING_TEMPLATES_SHORT.concat(SF_FOLLOWING_TEMPLATES_MEDIUM, SF_FOLLOWING_TEMPLATES_LONG)
    : isGossip
      ? SF_GOSSIP_TEMPLATES
      : SF_RECOMMENDED_TEMPLATES;
  var shortT = SF_FOLLOWING_TEMPLATES_SHORT;
  var medT = SF_FOLLOWING_TEMPLATES_MEDIUM;
  var longT = SF_FOLLOWING_TEMPLATES_LONG;
  var recT = SF_RECOMMENDED_TEMPLATES;
  var gosT = SF_GOSSIP_TEMPLATES;

  for (var i = 0; i < count; i++) {
    var nameIdx = (i * 3 + Math.floor(Math.random() * 5)) % SF_FALLBACK_NAMES.length;
    var author, content, roleData = null;

    if (isFollowing) {
      /* 关注页：角色自己发的帖子，轮换使用不同角色 */
      roleData = roles[i % roles.length];
      author = roleData.name || roleName || 'TA';
      /* 混合不同长度：约30%短、40%中、30%长 */
      var lenBucket = i % 10;
      if (lenBucket < 3) {
        content = shortT[Math.floor(Math.random() * shortT.length)];
      } else if (lenBucket < 7) {
        content = medT[Math.floor(Math.random() * medT.length)];
      } else {
        content = longT[Math.floor(Math.random() * longT.length)];
      }
    } else if (isGossip) {
      author = SF_FALLBACK_NAMES[nameIdx];
      content = gosT[i % gosT.length];
    } else {
      /* 推荐页：混合不同长度和类型 */
      author = SF_FALLBACK_NAMES[nameIdx];
      content = recT[i % recT.length];
    }

    var post = {
      id: tab + '-sf-fb-' + Date.now() + '-' + i,
      authorName: author,
      handle: sfHandle(author),
      verified: isFollowing ? false : (SF_VERIFIED_NAMES.indexOf(SF_FALLBACK_NAMES[nameIdx]) !== -1),
      content: content,
      time: ['刚刚', '3分钟前', '10分钟前', '半小时前', '1小时前', '6小时前', '今天'][i % 7],
      likes: Math.floor(Math.random() * 300) + 5,
      reposts: Math.floor(Math.random() * 50),
      comments: Math.floor(Math.random() * 60) + 1,
      views: Math.floor(Math.random() * 8000) + 200,
      avatarIndex: isFollowing ? 0 : (nameIdx % 8),
      imageGradient: null,
      commentsList: []
    };
    /* following posts: role-authored, use role avatar */
    if (isFollowing) {
      post.roleAuthored = true;
      post.imageGradient = null;
      if (roleData) {
        post.roleAvatar = sfRoleAvatarSrc(roleData);
      }
    }
    posts.push(post);
  }
  return posts;
};

var sfFallbackComments = function () {
  var n = 8 + Math.floor(Math.random() * 3);
  var arr = [];
  for (var i = 0; i < n; i++) {
    var idx = Math.floor(Math.random() * SF_COMMENT_AUTHORS.length);
    arr.push({
      id: 'sc-fb-' + Date.now() + '-' + i,
      authorName: SF_COMMENT_AUTHORS[idx],
      content: SF_COMMENT_TEMPLATES[Math.floor(Math.random() * SF_COMMENT_TEMPLATES.length)],
      time: ['刚刚', '2分钟前', '5分钟前', '15分钟前', '30分钟前', '1小时前'][i % 6],
      avatarIndex: idx % 8
    });
  }
  return arr;
};

/* ============================================================
 * PART 9 - AI Prompt Builders
 * (adapted from server-side generateForumPostsCore & comment gen)
 * ============================================================ */

var sfBuildPostsPrompt = function (tab, followedRoles, role, recentMessages, memories) {
  var validTabs = ['following', 'recommended', 'gossip'];
  var activeTab = validTabs.indexOf(tab) !== -1 ? tab : 'recommended';

  var roleName = role ? (role.name || '') : '';
  var rolePrompt = role ? (role.persona || role.prompt || '') : '';
  var _sfUserName = (typeof config !== 'undefined' && config.user && (config.user.personaName || config.user.name)) || '用户';
  var userLoc = (typeof getUserLocationStr === 'function') ? getUserLocationStr() : '';
  var charLoc = role ? getCharLocationStr(role) : '';

  var memStr = function (arr, n) {
    if (!arr || arr.length === 0) return '';
    return arr.slice(0, n).map(function (m) {
      return typeof m === 'string' ? m : (m.content || '');
    }).filter(Boolean).join('；');
  };

  var locHint = '';
  if (userLoc || charLoc) {
    var locParts = [];
    if (charLoc) locParts.push(roleName + '在' + charLoc);
    if (userLoc) locParts.push('用户在' + userLoc);
    locHint = '- 位置感知：' + locParts.join('，') + '。帖子中可以自然提及当地天气、美食、地点等，但不要每条都提。\n';
  }

  /* 世界观设定提示（影响所有生成内容） */
  var wvText = sfGetActiveWorldviewText();
  var wvHint = wvText ? '【世界观设定】' + wvText + '\n所有帖子内容必须符合此世界观设定。\n\n' : '';

  /* HTML交互模块提示（约30%帖子附带） */
  var htmlModuleHint = '- 约30%的帖子可以附带一个htmlModule字段，值为一段简洁的HTML代码，用于增加帖子互动性。例如：小投票（<div>投票：A还是B？<button>A</button><button>B</button></div>）、趣味问答（<div>猜猜我在哪？<details><summary>点击揭晓</summary>答案</details></div>）、可展开卡片等。HTML要简洁、自包含，不要使用<script>标签。不需要每条都有，约30%即可。\n';

  if (activeTab === 'following') {
    var roleInfos = Array.isArray(followedRoles) ? followedRoles : [];
    if (roleInfos.length === 0 && roleName) {
      roleInfos = [{ name: roleName, prompt: rolePrompt }];
    }

    var roleList = roleInfos.filter(function(r) { return r.type !== 'npc'; }).map(function (r) {
      return '- 角色名：' + (r.name || '未设定') + (r.gender ? '，性别：' + r.gender : '') + (r.prompt ? '，设定：' + String(r.prompt) : '');
    }).join('\n');

    return '当前任务：生成关注页中多个角色发布的动态帖子。每个角色至少发一条。\n注意：只为角色生成帖子，不要为NPC生成帖子（NPC的帖子由用户操控NPC时发布）。\n\n' +
      '【发帖身份铁律·最高优先级·必须严格遵守】\n' +
      '这些帖子是下面列出的各个角色以【自己本人身份】发布的公开动态：\n' +
      '- 每条帖子的 authorName 是谁，正文里的第一人称“我”就必须是谁。authorName 是哪个角色，正文就是这个角色本人在说话。\n' +
      '- 用户「' + _sfUserName + '」是浏览论坛的真人，绝不是任何帖子的作者。严禁用用户的身份、口吻、姓名或经历发帖，严禁出现“作为用户/玩家”“我（用户）”之类视角。\n' +
      '- 可以写角色和用户之间的事，但必须从角色本人视角出发，例如“今天和' + _sfUserName + '一起吃饭，很开心”；发帖的“我”永远是角色，绝不能写成“今天我和某角色吃饭”这种用户视角。\n\n' +
      wvHint +
      '帖子风格参考小红书爆款帖子，要求：\n' +
      '- 字数混合：短的50-150字、中等的150-300字、长的300-500字，三种长度都要出现\n' +
      '- 类型混合：日常记录、心情抒发、事件描述、感悟分享等多种类型都要有\n' +
      '- 口语化但有质感，像真人写的，不要AI感\n' +
      '- 可以带emoji和话题标签#\n' +
      '- 帖子之间要有明显的风格差异\n' +
      '- 约40%的帖子内容应与角色的记忆系统有关（回忆、约定、情感、日常互动等）\n' +
      '- 约60%的帖子内容应与角色的核心人设有关（性格特征、职业背景、兴趣爱好、人际关系等）\n' +
      htmlModuleHint + '\n' +
      locHint +
      '关注的角色：\n' + roleList + '\n\n' +
      (memories && memories.length > 0 ? '- 可用的记忆素材（约40%帖子可从中取材；素材里的“我”指角色本人，取材时保持角色第一人称，严禁换成用户「' + _sfUserName + '」视角）：' + memStr(memories, 8) + '\n' : '') +
      '\n请生成帖子，每个角色至少一条。帖子总数 = ' + Math.max(6, roleInfos.length * 2) + '条。\n' +
      '每条帖子的authorName必须是上述某个角色的名字，且正文必须是该角色本人第一人称，绝对不能是用户「' + _sfUserName + '」的视角。\n' +
      '返回JSON格式：{"posts":[{"authorName":"角色名","content":"帖子正文","time":"发布时间","htmlModule":"可选的HTML交互模块"}]}\n' +
      '不要有任何解释性文字，只返回JSON。';
  } else if (activeTab === 'recommended') {
    return '当前任务：生成推荐流帖子，展示虚拟世界中各种陌生网友发的帖子，话题更广泛。这些作者都是论坛陌生网友，不是用户「' + _sfUserName + '」，第一人称“我”是网友本人。\n\n' +
      wvHint +
      '帖子风格参考小红书，要求：\n' +
      '- 这是其他角色发的帖子，要包含不同角色的不同文风和性格，作者之间风格要有差异\n' +
      '- 内容类型多样化混合：逆袭/经验分享类、哲学/灵性感悟类、文学/人文科普类、社会观察类、日常吐槽/生活分享类、美食/旅行/生活方式类等，多种类型都要出现\n' +
      '- 字数混合：短的50-150字、中等的150-300字、长的300-500字，三种长度都要出现\n' +
      '- 口语化、真实感强，像真人写的，不要AI感\n' +
      '- 可以带emoji和话题标签#\n' +
      '- 不同帖子要有明显的风格差异\n' +
      htmlModuleHint + '\n' +
      '背景信息：\n' +
      locHint +
      (roleName ? '- 用户互动的角色：' + roleName + '\n' : '') +
      (memories && memories.length > 0 ? '- 可参考的记忆素材：' + memStr(memories, 5) + '\n' : '') +
      '\n作者名请从以下中选择或创作类似的中文网名：' +
      '职场小白兔、咖啡因中毒、阴暗爬行、心碎香菜、男人乱我心、呆呆小羊、深夜食堂老板、代码诗人、旅行笔记、人间观察员、哲学小鱼、月光酒馆、七里香、北城以北、南方有嘉木、春风十里、夜色温柔\n\n' +
      '请生成8条帖子，返回JSON格式：{"posts":[{"authorName":"作者名","content":"帖子正文","time":"发布时间","htmlModule":"可选的HTML交互模块"}]}\n' +
      '不要解释，只返回JSON。';
  } else {
    /* 八卦必须围绕“所有角色 + 用户”之间的关系，而不是只写当前一个角色 */
    var gRoles = (Array.isArray(followedRoles) ? followedRoles : []).filter(function (r) { return r && r.name && r.type !== 'npc'; });
    if (gRoles.length === 0 && roleName) gRoles = [{ name: roleName, prompt: rolePrompt }];
    var gNameList = gRoles.map(function (r) { return '「' + r.name + '」'; }).join('、') || '（暂无）';
    var gRoleLines = gRoles.map(function (r) {
      return '- 角色' + r.name + (r.gender ? '（' + r.gender + '）' : '') + (r.prompt ? '：' + String(r.prompt).slice(0, 120) : '');
    }).join('\n');
    var gCoverRule = '【人物覆盖·最高优先级】这个小圈子里真实存在的人是：角色 ' + gNameList + '，以及用户「' + _sfUserName + '」（真人）。\n'
      + '- 6条八卦必须分配到不同的人物组合上，确保上面每一个角色、以及用户「' + _sfUserName + '」都至少被提到一次，严禁6条全都只围着同一个角色写。\n'
      + '- 多写“谁和谁怎么了”的多人关系：两个角色之间、某个角色和用户「' + _sfUserName + '」之间、多角关系都要有；提到用户时用第三人称（如“' + _sfUserName + '最近好像和……”），发帖人仍是匿名路人，不是用户本人。\n'
      + '- 路人只知道表面传闻，不要写成全知视角，别替当事人说出私密内心独白。\n\n';
    return '当前任务：生成八卦流帖子，展示虚拟世界中的传闻、八卦、小道消息、爆料。发布者都是匿名网友或路人，不是用户「' + _sfUserName + '」。\n\n' +
      wvHint +
      gCoverRule +
      '论坛里真实存在的人物（八卦素材只能从他们之间产生）：\n' + gRoleLines + '\n- 用户（真人，被八卦的对象之一）：' + _sfUserName + '\n\n' +
      '风格要求：\n' +
      '- 八卦/爆料风格，像朋友之间传的小道消息\n' +
      '- 话题类型混合：角色关系传闻、神秘事件线索、争议话题、圈内爆料、吃瓜见闻、小道消息等多种类型都要出现\n' +
      '- 字数混合：短的50-150字、中等的150-300字、长的300-500字，三种长度都要出现\n' +
      '- 带有悬念和吃瓜感，但不恶意攻击\n' +
      '- 口语化，像朋友圈或群聊中的八卦，可以带emoji和话题标签#\n' +
      '- 不同帖子要有风格差异\n' +
      htmlModuleHint + '\n' +
      locHint +
      (memories && memories.length > 0 ? '可参考的记忆素材：' + memStr(memories, 5) + '\n' : '') +
      '\n请生成6条八卦帖子，返回JSON格式：{"posts":[{"authorName":"匿名或化名","content":"八卦内容","time":"发布时间","htmlModule":"可选的HTML交互模块"}]}\n' +
      '作者名可以是匿名昵称如"匿名瓜农"、"吃瓜路人"、"圈内人"、"小道消息"等。\n' +
      '不要解释，只返回JSON。';
  }
};

var sfGatherForumContext = function (post) {
  var ctx = { characters: [], npcs: [], memories: '', authorType: 'stranger', authorName: '' };
  try {
    if (typeof config === 'undefined') return ctx;
    
    /* Determine post author type */
    var authorName = post.authorName || '';
    ctx.authorName = authorName;
    var authorIsNpc = post.npcAuthored && post.npcId;
    var authorIsUser = post._user === true;
    var authorIsRole = post.roleAuthored === true;
    var authorIsAnonymous = post._anonymous === true;
    var authorNpc = null;
    var authorRole = null;
    
    if (authorIsAnonymous) {
      /* 匿名发帖：AI不知道发帖人是谁 */
      ctx.authorType = 'anonymous';
    } else if (authorIsNpc) {
      authorNpc = (config.npcs || []).find(function(n) { return String(n.id) === String(post.npcId); });
      ctx.authorType = 'npc';
    } else if (authorIsUser) {
      ctx.authorType = 'user';
    } else if (authorIsRole) {
      /* Character-authored post in following tab */
      authorRole = (config.characters || []).find(function(c) { return c.name === authorName && !c.deletedFromWechat; });
      ctx.authorType = authorRole ? 'character' : 'stranger';
    } else {
      /* AI-generated post by a random forum user */
      ctx.authorType = 'stranger';
    }
    
    var userName = (config.user && config.user.name) || '用户';
    
    /* Collect characters (not deleted from wechat) */
    var characters = (config.characters || []).filter(function(c) { return !c.deletedFromWechat; });
    /* 如果设置了参与角色列表，只保留在列表中的角色 */
    if (sfState.activeForumRoleIds && sfState.activeForumRoleIds.length > 0) {
      characters = characters.filter(function(c) {
        var cid = c.id || c.name;
        return sfState.activeForumRoleIds.indexOf(cid) !== -1;
      });
    }
    ctx.characters = characters.map(function(c) {
      var info = { name: c.name, persona: (c.persona || '').substring(0, 500) };
      /* Skip the author character themselves */
      if (ctx.authorType === 'character' && c.name === authorName) {
        info.relationship = '（这是发帖人本人，不需要互动）';
        return info;
      }
      /* Relationship with post author depends on author type */
      if (ctx.authorType === 'npc' && authorNpc && authorNpc.relationships) {
        var rel = (authorNpc.relationships.characters || []).find(function(r) { return r.characterName === c.name; });
        info.relationship = rel ? (rel.type || '认识') : '无直接关系';
      } else if (ctx.authorType === 'character') {
        /* Character-authored post: other characters don't necessarily know the author */
        info.relationship = '论坛上看到的帖子，发帖人是角色「' + authorName + '」';
        var userMems0 = (config.memories || []).filter(function(m) { return m.content && m.content.indexOf(c.name) >= 0; });
        info.relationshipWithUser = userMems0.length > 3 ? '与用户关系密切' : (userMems0.length > 0 ? '认识用户' : '不太熟');
      } else if (ctx.authorType === 'user') {
        /* User-authored post: infer from memories */
        var charMems = (config.memories || []).filter(function(m) { return m.content && m.content.indexOf(c.name) >= 0; });
        info.memoryCount = charMems.length;
        info.relationship = charMems.length > 3 ? '与用户关系密切' : (charMems.length > 0 ? '认识用户' : '不太熟');
      } else {
        /* AI-generated post by a stranger - character's relationship is with the USER, not the post author */
        info.relationship = '论坛上看到的帖子，发帖人是陌生人';
        /* Still include relationship with user for context */
        var userMems = (config.memories || []).filter(function(m) { return m.content && m.content.indexOf(c.name) >= 0; });
        info.relationshipWithUser = userMems.length > 3 ? '与用户关系密切' : (userMems.length > 0 ? '认识用户' : '不太熟');
      }
      /* Recent online chat */
      var recentChat = (c.chatHistory || []).slice(-5);
      if (recentChat.length > 0) {
        info.recentChat = recentChat.map(function(m) {
          var role = m.role === 'user' ? ((config.user && config.user.name) || '用户') : c.name;
          var content = (m.content || '').replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '').trim().substring(0, 50);
          return content ? role + '：' + content : '';
        }).filter(Boolean).join(' | ');
      }
      /* Recent offline chat - include more context */
      var offlineChat = (c.offlineChatHistory || []).slice(-8);
      if (offlineChat.length > 0) {
        info.recentOffline = offlineChat.map(function(m) {
          var role = m.role === 'user' ? ((config.user && config.user.name) || '用户') : c.name;
          var content = (m.content || '').replace(THINK_CLOSED_RE, '').replace(/<miyavoice>[\s\S]*?<\/miyavoice>/gi, '').trim().substring(0, 100);
          return content ? role + '：' + content : '';
        }).filter(Boolean).join(' | ');
      }
      /* Character-specific memories (including offline-related) */
      var charMemsAll = (config.memories || []).filter(function(m) {
        return m.content && m.content.indexOf(c.name) >= 0;
      });
      if (charMemsAll.length > 0) {
        info.charMemories = charMemsAll.slice(-8).map(function(m) { return m.content; }).join(' | ');
      }
      return info;
    });
    
    /* Collect NPCs (not deprecated, not the author) */
    var npcs = (config.npcs || []).filter(function(n) { return !n._deprecated; });
    /* 如果设置了参与角色列表，只保留在列表中的NPC */
    if (sfState.activeForumRoleIds && sfState.activeForumRoleIds.length > 0) {
      npcs = npcs.filter(function(n) {
        var nid = 'npc-' + n.id;
        return sfState.activeForumRoleIds.indexOf(nid) !== -1;
      });
    }
    if (authorNpc) {
      npcs = npcs.filter(function(n) { return n.id !== authorNpc.id; });
    }
    ctx.npcs = npcs.map(function(n) {
      var info = { name: n.name, persona: (n.persona || '').substring(0, 500) };
      /* Relationship depends on author type */
      if (ctx.authorType === 'npc' && authorNpc && authorNpc.relationships) {
        var rel = (authorNpc.relationships.npcs || []).find(function(r) { return r.npcId === n.id; });
        info.relationship = rel ? (rel.type || '认识') : '无直接关系';
        /* Also include NPC's relationship with user for context */
        if (n.relationships && n.relationships.user) {
          info.relationshipWithUser = n.relationships.user.type || '认识用户';
        }
      } else if (ctx.authorType === 'user') {
        if (n.relationships && n.relationships.user) {
          info.relationship = n.relationships.user.type || '认识用户';
        } else {
          info.relationship = '认识用户';
        }
        /* Include NPC's relationships with characters */
        if (n.relationships && n.relationships.characters) {
          var charRels = n.relationships.characters.map(function(r) { return r.characterName + '(' + (r.type || '认识') + ')'; });
          if (charRels.length > 0) info.characterRelationships = charRels.join('、');
        }
      } else {
        /* AI-generated post by a stranger */
        info.relationship = '论坛上看到的帖子，发帖人是陌生人';
        if (n.relationships && n.relationships.user) {
          info.relationshipWithUser = n.relationships.user.type || '认识用户';
        }
        /* Include NPC's relationships with characters for cross-interaction */
        if (n.relationships && n.relationships.characters) {
          var charRels2 = n.relationships.characters.map(function(r) { return r.characterName + '(' + (r.type || '认识') + ')'; });
          if (charRels2.length > 0) info.characterRelationships = charRels2.join('、');
        }
      }
      /* NPC recent events */
      if (n.recentEvents && n.recentEvents.length > 0) {
        info.recentActions = n.recentEvents.slice(-5).join('；');
      }
      /* NPC recent chat with user */
      var npcChat = (config.npcChats || []).find(function(c) { return c.npcId === n.id; });
      if (npcChat && npcChat.messages && npcChat.messages.length > 0) {
        var recentMsgs = npcChat.messages.slice(-3);
        info.recentChat = recentMsgs.map(function(m) {
          var role = m.role === 'user' ? ((config.user && config.user.name) || '用户') : n.name;
          var content = (m.content || '').substring(0, 40);
          return content ? role + '：' + content : '';
        }).filter(Boolean).join(' | ');
      }
      return info;
    });
    
    /* Memories - include more, prioritize recent and important */
    if (config.memories && config.memories.length > 0) {
      var sortedMems = config.memories.slice().sort(function(a, b) {
        return (b.time || 0) - (a.time || 0);
      });
      ctx.memories = sortedMems.slice(0, 25).map(function(m) { return m.content; }).join('\n');
    }
  } catch(e) {
    console.error('sfGatherForumContext error:', e);
  }
  return ctx;
};

/* ---- Post type detection (scoring-based) ---- */
var sfDetectPostType = function (content) {
  var text = String(content || '').toLowerCase();
  var scores = { help: 0, recommend: 0, emotion: 0, question: 0, share: 0, daily: 0 };
  
  /* Help: strong signals */
  var helpStrong = [/求助/, /怎么办/, /怎么处理/, /有没有人知道/, /请教/, /帮帮我/, /出个主意/, /谁会/, /怎么解决/, /在线等/, /急急/];
  var helpMed = [/请.*帮/, /谁能/, /有没有.*办法/, /怎么才能/, /遇到.*问题/, /不会弄/, /搞不定/, /不知道.*怎么办/];
  helpStrong.forEach(function(p) { if (p.test(text)) scores.help += 3; });
  helpMed.forEach(function(p) { if (p.test(text)) scores.help += 2; });
  
  /* Recommend: strong signals */
  var recStrong = [/推荐/, /安利/, /好物分享/, /宝藏.*店/, /值得去/, /打卡/, /探店/, /旅游攻略/, /旅行攻略/, /必去/, /好吃.*推荐/, /美食推荐/];
  var recMed = [/好吃/, /好玩/, /景点/, /美食/, /餐厅/, /好去处/, /周末去/, /旅行/, /旅游/, /电影.*推荐/, /书.*推荐/];
  recStrong.forEach(function(p) { if (p.test(text)) scores.recommend += 3; });
  recMed.forEach(function(p) { if (p.test(text)) scores.recommend += 1; });
  
  /* Emotion: strong signals */
  var emoStrong = [/难过/, /心碎/, /分手/, /表白/, /暗恋/, /想念/, /孤独/, /崩溃/, /emo/, /委屈/, /心疼/, /好哭/, /泪目/];
  var emoMed = [/开心/, /生气/, /郁闷/, /焦虑/, /压力/, /感动/, /幸福/, /甜蜜/, /吵架/, /和好/, /好累/, /心累/, /纠结/, /失望/];
  var emoWeak = [/喜欢/, /爱/];
  emoStrong.forEach(function(p) { if (p.test(text)) scores.emotion += 3; });
  emoMed.forEach(function(p) { if (p.test(text)) scores.emotion += 2; });
  emoWeak.forEach(function(p) { if (p.test(text)) scores.emotion += 1; });
  
  /* Question: must have question mark or strong question words */
  var qStrong = [/为什么/, /什么是/, /如何.*[?？]/, /哪里有/, /哪个好/, /什么时候/, /多少钱/, /是不是.*[?？]/, /能不能.*[?？]/, /可以吗.*[?？]/, /有没有.*[?？]/, /怎么办.*[?？]/];
  var qMed = [/[?？]$/, /[?？]\s*$/, /怎么.*[?？]/, /如何.*[?？]/, /哪.*[?？]/];
  qStrong.forEach(function(p) { if (p.test(text)) scores.question += 3; });
  qMed.forEach(function(p) { if (p.test(text)) scores.question += 2; });
  /* Lone question mark without question words = weak signal */
  if (/[?？]/.test(text) && scores.question === 0) scores.question += 1;
  
  /* Share: experience/showcase */
  var shareStrong = [/开箱/, /测评/, /对比.*评测/, /入手.*体验/, /晒单/, /分享.*体验/];
  var shareMed = [/终于.*到了/, /第一次.*体验/, /今天.*收到了/, /记录.*日常/, /日常.*分享/];
  shareStrong.forEach(function(p) { if (p.test(text)) scores.share += 3; });
  shareMed.forEach(function(p) { if (p.test(text)) scores.share += 1; });
  
  /* Find highest score */
  var maxType = 'daily';
  var maxScore = 0;
  for (var key in scores) {
    if (scores[key] > maxScore) {
      maxScore = scores[key];
      maxType = key;
    }
  }
  /* If no strong signal, check for daily patterns */
  if (maxScore === 0) return 'daily';
  return maxType;
};

var sfPostTypeLabel = function (type) {
  var labels = { help: '求助', recommend: '推荐', emotion: '情感', share: '分享', question: '提问', daily: '日常' };
  return labels[type] || '日常';
};

var sfPostTypeBadgeHtml = function (content) {
  var type = sfDetectPostType(content);
  return '<span class="sf-post-type-badge ' + type + '">' + sfPostTypeLabel(type) + '</span>';
};

var sfPostTypeInteractionGuide = function (type) {
  var guides = {
    help: '【帖子类型：求助】角色/NPC如果知道答案或有过类似经历，应该给出建议或分享经验。评论要有实质内容，不要只说"加油"。与用户关系亲密的角色可以主动转发给用户说"我帮你问问"或"我记得有个方法"。',
    recommend: '【帖子类型：推荐】角色/NPC如果感兴趣可以评论说想去、想试、或者补充自己的体验。与用户关系亲密的角色应该主动转发给用户，说"想和你一起去"或"周末带你去"之类的话。',
    emotion: '【帖子类型：情感】角色/NPC可以表达共情、安慰或分享类似感受。评论要温暖、真诚，符合角色性格。性格冷淡的角色可以只点赞不评论。',
    share: '【帖子类型：分享】角色/NPC可以评论表达看法、分享类似经历或互动调侃。觉得有意思的可以点赞。',
    question: '【帖子类型：提问】角色/NPC如果知道答案应该回答，不确定的可以追问或讨论。与用户相关的可以转发给用户征求意见。',
    daily: '【帖子类型：日常】角色/NPC如果觉得有趣可以点赞，有想法可以评论。不感兴趣的不需要互动。'
  };
  return guides[type] || guides.daily;
};

/* ---- Save forum interaction as memory (interaction chain) ---- */
var sfSaveForumMemory = function (reactions, post) {
  /* Auto-save memory feature has been removed */
  return;
};

/* ---- Trigger proactive WeChat message from character to user ---- */
var sfTriggerProactiveWechatMessage = function (reactions, post) {
  try {
    if (typeof config === 'undefined') return;
    // 角色账号登录时禁止“角色转发给用户”的自动链路写入上一个用户账号的共享聊天桶。
    if (typeof waIsCharSession === 'function' && waIsCharSession()) return;
    var postSnippet = String(post.content || '').substring(0, 50);
    var postAuthor = post.authorName || '有人';
    var postId = post.id || '';
    var postContent = String(post.content || '').substring(0, 100);
    var _forwardedNames = [];
    reactions.forEach(function(r) {
      if (!r._matchedName || r.action !== 'repost' || !r.text) return;
      var repostData = {
        postId: postId,
        author: postAuthor,
        content: postContent,
        comment: r.text
      };
      /* 角色转发给用户：AI已根据关系亲疏决定repost，这里不再用记忆条数拦截，确保真实送达 */
      var char = (config.characters || []).find(function(c) { return c.name === r._matchedName && !c.deletedFromWechat; });
      /* v90：只转发给“当前账号在当前世界里真实可见（是好友/未删除）”的角色，
         否则会出现会话列表里找不到、微信却冒出红点的“莫名红点” */
      if (char && typeof waCharVisible === 'function' && !waCharVisible(char)) char = null;
      if (char) {
        char.chatHistory = char.chatHistory || [];
        char.chatHistory.push({
          role: 'assistant',
          content: '[repost]' + JSON.stringify(repostData),
          time: Date.now(),
          type: 'repost',
          _proactive: true,
          _forumRef: postSnippet
        });
        config.unreadCount = (config.unreadCount || 0) + 1;
        _forwardedNames.push(char.alias || char.nickname || char.name);
        return;
      }
      /* NPC 转发给用户 */
      var npc = (config.npcs || []).find(function(n) { return n.name === r._matchedName && !n._deprecated; });
      if (npc) {
        if (!config.npcChats) config.npcChats = [];
        var npcChat = config.npcChats.find(function(nc) { return nc.npcId === npc.id; });
        if (npcChat) {
          npcChat.messages = npcChat.messages || [];
          npcChat.messages.push({
            role: 'other',
            content: '[repost]' + JSON.stringify(repostData),
            time: Date.now(),
            type: 'repost'
          });
          config.unreadCount = (config.unreadCount || 0) + 1;
          _forwardedNames.push(npc.name);
        }
      }
    });
    if (_forwardedNames.length === 0) return;
    Store.set('config', config);
    /* 立即刷新微信界面，让转发真实可见 */
    try { if (typeof renderChatList === 'function') renderChatList(); } catch(e) {}
    try { if (typeof updateBadges === 'function') updateBadges(); } catch(e) {}
    try {
      /* 若正在浏览转发者的聊天页，实时刷新消息 */
      var _curChar = (config.characters || [])[currentCharIdx];
      if (_curChar && _forwardedNames.indexOf(_curChar.alias || _curChar.nickname || _curChar.name) >= 0 && typeof renderMessages === 'function') renderMessages();
    } catch(e) {}
    try { if (typeof showToast === 'function') showToast(_forwardedNames[0] + ' 在论坛转发了帖子给你'); } catch(e) {}
  } catch(e) { console.warn('sfTriggerProactiveWechatMessage error:', e); }
};

var sfBuildCommentsPrompt = function (postContent, postAuthor, count, contextData) {
  var ctx = contextData || {};
  var charDesc = '';
  var npcDesc = '';
  var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';

  /* Build character descriptions with rich context */
  if (ctx.characters && ctx.characters.length > 0) {
    charDesc = ctx.characters.map(function(c, i) {
      var parts = [i + 1 + '. 角色「' + c.name + '」（身份：AI角色，不是用户「' + userName + '」，不是NPC）：' + (c.persona || '').substring(0, 500)];
      if (c.relationship) parts.push('   与发帖人关系：' + c.relationship);
      if (c.relationshipWithUser) parts.push('   与用户「' + userName + '」的关系：' + c.relationshipWithUser);
      if (c.memoryCount !== undefined) parts.push('   与用户共同记忆数：' + c.memoryCount);
      if (c.charMemories) parts.push('   相关记忆（含线下）：' + c.charMemories);
      if (c.recentChat) parts.push('   最近线上聊天：' + c.recentChat);
      if (c.recentOffline) parts.push('   最近线下互动：' + c.recentOffline);
      return parts.join('\n');
    }).join('\n');
  }

  /* Build NPC descriptions with rich context */
  if (ctx.npcs && ctx.npcs.length > 0) {
    npcDesc = ctx.npcs.map(function(n, i) {
      var parts = [(ctx.characters ? ctx.characters.length + i + 1 : i + 1) + '. NPC「' + n.name + '」（身份：NPC，不是用户「' + userName + '」，不是角色）：' + (n.persona || '').substring(0, 500)];
      if (n.relationship) parts.push('   与发帖人关系：' + n.relationship);
      if (n.relationshipWithUser) parts.push('   与用户「' + userName + '」的关系：' + n.relationshipWithUser);
      if (n.characterRelationships) parts.push('   与角色的关系：' + n.characterRelationships);
      if (n.recentActions) parts.push('   近期行为：' + n.recentActions);
      if (n.recentChat) parts.push('   最近与用户聊天：' + n.recentChat);
      return parts.join('\n');
    }).join('\n');
  }

  /* Detect post type and get interaction guide */
  var postType = sfDetectPostType(postContent);
  var typeGuide = sfPostTypeInteractionGuide(postType);

  var allDesc = charDesc + (npcDesc ? '\n' + npcDesc : '');
  var memoryText = ctx.memories ? '\n相关记忆：\n' + ctx.memories + '\n' : '';

  /* ===== 补充：所有场景通用数据（图二10项） + 发布者信息 ===== */

  // 1. 角色身份锁（批量场景）- 强化版：显式区分用户/角色/NPC
  var _idLockCharNames = (ctx.characters || []).map(function(c){ return c.name; });
  var _idLockNpcNames = (ctx.npcs || []).map(function(n){ return n.name; });
  var identityLockText = '【身份锁·最重要规则·违反将导致严重混乱】\n'
    + '以下三类身份绝对不可混淆：\n'
    + '1. 用户「' + userName + '」：是真人，不是角色，不是NPC，不会出现在reactions评论里。用户只是看帖子的人。\n'
    + '2. 角色（AI扮演的虚拟人物）：' + (_idLockCharNames.length ? _idLockCharNames.map(function(n){ return '「' + n + '」'; }).join('、') : '无') + '。每个角色都不是用户，也不是其他角色，更不是NPC。\n'
    + '3. NPC（独立虚拟人物）：' + (_idLockNpcNames.length ? _idLockNpcNames.map(function(n){ return '「' + n + '」'; }).join('、') : '无') + '。每个NPC都不是用户，也不是角色。\n'
    + '铁律：\n'
    + '- 角色和NPC是两类不同的存在，NPC不是角色，角色不是NPC。\n'
    + '- 任何角色/NPC都不能自称是用户「' + userName + '」，也不能把用户当成角色或NPC。\n'
    + '- 角色只知道自己经历过的事和公开渠道（论坛、朋友圈、群聊）的信息，不知道其他角色/NPC的私聊内容。\n'
    + '- reactions数组中的name只能是上面列出的角色名或NPC名，绝对不能是用户「' + userName + '」的名字。';

  // 2. 完整用户人设
  var userPersonaText = '';
  if (config.user) {
    var _sfUserParts = [];
    var _sfUserName = config.user.personaName || config.user.name || '';
    if (_sfUserName) _sfUserParts.push('称呼：' + _sfUserName);
    if (config.user.persona) _sfUserParts.push('人设描述：' + config.user.persona);
    if (config.user.personaRelations) _sfUserParts.push('人际关系：' + config.user.personaRelations);
    if (_sfUserParts.length > 0) {
      userPersonaText = _sfUserParts.join('\n');
    }
  }

  // 3. 世界书（关键词激活）
  var wbContextText = '';
  if (typeof getWorldBookContext === 'function') {
    var _sfWb = getWorldBookContext(postContent || '');
    if (_sfWb) wbContextText = _sfWb;
  }

  // 4. 全局NPC信息（所有NPC，不仅仅是参与互动的）
  var allNpcInfoText = '';
  if (config.npcs && config.npcs.length > 0) {
    var _sfAllNpcParts = [];
    config.npcs.forEach(function(n) {
      if (n._deprecated) return;
      // 跳过已经在npcDesc中的NPC（参与互动的），避免重复
      if (ctx.npcs && ctx.npcs.some(function(activeNpc) { return activeNpc.name === n.name; })) return;
      var npcInfo = ['【' + n.name + '】'];
      if (n.persona) npcInfo.push('人设：' + n.persona.substring(0, 200));
      if (n.relationships && n.relationships.user) {
        npcInfo.push('与用户：' + (n.relationships.user.type || '认识'));
      }
      _sfAllNpcParts.push(npcInfo.join(' | '));
    });
    if (_sfAllNpcParts.length > 0) {
      allNpcInfoText = _sfAllNpcParts.join('\n');
    }
  }

  // 5. 统一时间线
  var timelineText = '';
  if (typeof buildUnifiedTimeline === 'function' && typeof formatUnifiedTimeline === 'function') {
    var _sfTimeline = buildUnifiedTimeline(15);
    if (_sfTimeline.length > 0) {
      var _sfTlText = formatUnifiedTimeline(_sfTimeline);
      if (_sfTlText) timelineText = _sfTlText;
    }
  }

  // 6. 实时MCP数据
  var mcpText = '';
  if (typeof getMCPContext === 'function') {
    var _sfMcp = getMCPContext();
    if (_sfMcp) mcpText = _sfMcp;
  }

  // 7. 发布者信息（详细）
  var authorInfoText = '';
  if (ctx.authorType === 'npc' && config.npcs) {
    var _sfAuthorNpc = config.npcs.find(function(n) { return n.name === ctx.authorName; });
    if (_sfAuthorNpc) {
      var _sfAuthorParts = ['【发布者详细信息】'];
      _sfAuthorParts.push('姓名：' + _sfAuthorNpc.name);
      if (_sfAuthorNpc.persona) _sfAuthorParts.push('人设：' + _sfAuthorNpc.persona.substring(0, 400));
      if (_sfAuthorNpc.relationships) {
        var _sfAuthorRels = [];
        if (_sfAuthorNpc.relationships.user) {
          var ur = _sfAuthorNpc.relationships.user;
          _sfAuthorRels.push('与用户：' + (ur.type || '认识') + (ur.description ? '（' + ur.description + '）' : ''));
        }
        (_sfAuthorNpc.relationships.characters || []).forEach(function(r) {
          _sfAuthorRels.push('与' + r.characterName + '：' + r.type + (r.description ? '（' + r.description + '）' : ''));
        });
        (_sfAuthorNpc.relationships.npcs || []).forEach(function(r) {
          _sfAuthorRels.push('与' + r.npcName + '（NPC）：' + r.type);
        });
        if (_sfAuthorRels.length > 0) _sfAuthorParts.push('人际关系：\n' + _sfAuthorRels.join('\n'));
      }
      if (_sfAuthorNpc.recentEvents && _sfAuthorNpc.recentEvents.length > 0) {
        _sfAuthorParts.push('近期动态：' + _sfAuthorNpc.recentEvents.slice(-5).join('；'));
      }
      authorInfoText = _sfAuthorParts.join('\n');
    }
  } else if (ctx.authorType === 'character' && config.characters) {
    var _sfAuthorChar = config.characters.find(function(c) { return c.name === ctx.authorName; });
    if (_sfAuthorChar) {
      var _sfAuthorCharParts = ['【发布者详细信息】'];
      _sfAuthorCharParts.push('姓名：' + _sfAuthorChar.name);
      if (_sfAuthorChar.persona) _sfAuthorCharParts.push('人设：' + _sfAuthorChar.persona.substring(0, 400));
      if (_sfAuthorChar.location) _sfAuthorCharParts.push('所在城市：' + _sfAuthorChar.location);
      // 与用户的关系（从记忆推断）
      var _sfCharUserMems = (config.memories || []).filter(function(m) {
        return m.content && m.content.indexOf(_sfAuthorChar.name) >= 0;
      });
      _sfAuthorCharParts.push('与用户关系：' + (_sfCharUserMems.length > 3 ? '关系密切' : (_sfCharUserMems.length > 0 ? '认识' : '不太熟')) + '（共同记忆' + _sfCharUserMems.length + '条）');
      authorInfoText = _sfAuthorCharParts.join('\n');
    }
  } else if (ctx.authorType === 'user' && config.user) {
    var _sfAuthorUserParts = ['【发布者详细信息】'];
    _sfAuthorUserParts.push('姓名：' + userName + '（用户）');
    if (config.user.persona) _sfAuthorUserParts.push('人设：' + config.user.persona);
    if (config.user.personaRelations) _sfAuthorUserParts.push('人际关系：' + config.user.personaRelations);
    authorInfoText = _sfAuthorUserParts.join('\n');
  }

  /* Determine author context description */
  var authorContext = '';
  var authorWarning = '';
  if (ctx.authorType === 'anonymous') {
    /* 匿名帖子：AI不知道发帖人是谁，约8%概率角色会试探性猜测身份 */
    authorContext = '【重要·匿名帖子】这条帖子是匿名发布的，你不知道发帖人是谁。发帖人显示为"匿名用户"，可能是任何人。用户「' + userName + '」只是在看帖子的人。';
    authorWarning = '发帖人是匿名的，你不知道真实身份。绝对不要直接说出发帖人是谁。但在极少数情况下（约8%的概率），某个角色可以在评论中试探性地猜测一下发帖人身份，比如"楼主的说话方式让我想起一个朋友..."这种含糊的表达，但不要点破。其余情况下就当陌生人帖子对待。';
  } else if (ctx.authorType === 'user') {
    authorContext = '【重要】这条帖子的发帖人是用户「' + userName + '」，也就是你认识的人。';
    authorWarning = '发帖人就是用户「' + userName + '」本人。';
  } else if (ctx.authorType === 'npc') {
    authorContext = '【重要】这条帖子的发帖人是NPC「' + (ctx.authorName || '某NPC') + '」，不是用户「' + userName + '」。用户「' + userName + '」是看帖子的人，不是发帖的人。';
    authorWarning = '发帖人是NPC「' + (ctx.authorName || '某NPC') + '」，绝对不是用户「' + userName + '」。不要在评论里对用户说"你的帖子"或"你发的"。';
  } else if (ctx.authorType === 'character') {
    authorContext = '【重要】这条帖子的发帖人是角色「' + (ctx.authorName || '某角色') + '」，不是用户「' + userName + '」。用户「' + userName + '」是看帖子的人，不是发帖的人。';
    authorWarning = '发帖人是角色「' + (ctx.authorName || '某角色') + '」，绝对不是用户「' + userName + '」。不要在评论里说"你的帖子"或"你发的"。';
  } else {
    authorContext = '【重要】这条帖子的发帖人是论坛上的陌生人「' + (postAuthor || '匿名') + '」，不是用户「' + userName + '」，也不是你认识的任何人。用户「' + userName + '」只是在看帖子的人。';
    authorWarning = '发帖人是陌生人「' + (postAuthor || '匿名') + '」，绝对不是用户「' + userName + '」。不要在评论里说"你的帖子"或"你发的"，因为帖子不是用户发的。';
  }

  if (allDesc) {
    var activeRuleText = sfGetActiveRuleText();
    var ruleSection = activeRuleText ? '\n【论坛规则】' + activeRuleText + '\n' : '';
    /* 世界观设定注入 */
    var wvText = sfGetActiveWorldviewText();
    var wvSection = wvText ? '\n【世界观设定】' + wvText + '\n' : '';

    // 组装补充数据段
    var extraSections = [];
    extraSections.push(identityLockText);
    if (userPersonaText) extraSections.push('=== 用户人设 ===\n以下是用户的完整人设信息，各角色对用户的态度和互动方式应符合此人设：\n' + userPersonaText);
    if (authorInfoText) extraSections.push(authorInfoText);
    if (wbContextText) extraSections.push('=== 世界书 ===\n' + wbContextText);
    if (allNpcInfoText) extraSections.push('=== 其他NPC信息 ===\n以下是世界中其他NPC的简要信息（非互动参与者，仅作背景参考）：\n' + allNpcInfoText);
    if (timelineText) extraSections.push('=== 近期事件时间线 ===\n以下是近期所有互动的统一时间线，供各角色参考（各角色只知道自己经历的事，但可作为事件因果的背景）：\n' + timelineText);
    if (mcpText) extraSections.push('=== 实时信息 ===\n' + mcpText);
    var extraText = extraSections.join('\n\n');

    return '场景：论坛上有一条新帖子，角色、NPC和普通论坛用户在浏览帖子。\n\n'
      + '【身份区分·最重要】用户「' + userName + '」是真人，只在看帖子，不会自动生成评论。角色和NPC是AI虚拟人物，可以生成评论。普通论坛用户是路人网友。这三类身份绝不可混淆。\n\n' +
      '══════════════════════════════\n' +
      authorContext + '\n' +
      '══════════════════════════════\n\n' +
      typeGuide + '\n\n' +
      '帖子内容：' + String(postContent || '').slice(0, 500) + '\n\n' +
      extraText + '\n\n' +
      '以下是浏览帖子的角色和NPC（注意：这些是看帖子的人，不是发帖人）：\n' + allDesc + '\n' + memoryText + wvSection + ruleSection + '\n' +
      '══════════════════════════════\n' +
      '【两步决策机制】\n' +
      '══════════════════════════════\n\n' +
      '第一步：注意力筛选\n' +
      '请根据每个角色/NPC的人设、性格、记忆、最近互动和帖子内容，判断他们是否会对这条帖子产生兴趣。不是每个人都会对每条帖子感兴趣。判断依据：\n' +
      '- 帖子话题是否与角色的人设/兴趣/经历相关\n' +
      '- 角色与发帖人的关系（陌生人帖子关注度低，熟人帖子关注度高）\n' +
      '- 帖子内容是否触动了角色的某些记忆或情感\n' +
      '- 角色性格（外向的人更爱评论，内向的人可能只点赞）\n' +
      '- 如果帖子与角色完全不相关，该角色可以不互动\n\n' +
      '第二步：互动生成\n' +
      '对产生兴趣的角色/NPC，生成具体的互动行为：\n' +
      '- like：点赞（觉得内容不错、有趣或赞同）\n' +
      '- comment：评论（对帖子内容发表看法，像真实社交平台评论一样自然）\n' +
      '- repost：转发（觉得值得分享给用户「' + userName + '」，转发时附上想对' + userName + '说的话）\n' +
      '- 不互动：如果角色对帖子没兴趣，就不要强行互动\n\n' +
      '══════════════════════════════\n' +
      '【互动规则】\n' +
      '══════════════════════════════\n' +
      '1. 【自然互动率】不要让所有人都互动。只有对帖子内容真正感兴趣的角色/NPC才互动。可能只有1-2个人互动，也可能没人互动，这取决于帖子内容和角色匹配度。\n' +
      '2. ' + typeGuide + '\n' +
      '3. 【评论风格铁律】评论必须像真实社交平台的评论，口语化、自然、有个性。参考微博/小红书评论区风格：\n' +
      '   - 【角色多样性】评论区必须模拟真实网络生态，包含多种角色：理性的分析者、情绪化的支持者/反对者、抖机灵的、单纯的路人、偶尔出现的杠精\n' +
      '   - 可以带emoji（😂👍✨🔥等），可以用网络用语（yyds、绝了、笑死、蚌埠住了等）\n' +
      '   - 可以调侃、吐槽、赞同、追问、分享类似经历、甚至偏题聊自己的事\n' +
      '   - 评论以简短为主，一般8-40字，最多不超过60字，不要写小作文或长段落\n' +
      '   - 要符合角色性格和说话方式，不同角色评论风格要有明显差异\n' +
      '   - 不要说教，不要像AI，不要用"作为一个..."这种句式\n' +
      '   - 评论可以很短，比如"哈哈哈"、"确实"、"前排吃瓜"、"lz说得对"这种也很真实\n' +
      '   - 严禁使用"用户A"、"评论者1"这种代号，昵称要有网感\n' +
      '4. 【作者身份】' + authorWarning + '\n' +
      '5. 名字必须与上面列出的完全一致。reactions里的name只能是角色名或NPC名，绝对不能是用户「' + userName + '」的名字。\n' +
      '6. 【交叉互动】角色和NPC都应该被考虑。如果帖子是NPC发的，与该NPC有关系的角色更可能互动；如果帖子是角色发的，与该角色有关系的NPC也更可能互动。\n' +
      '7. 【回复链】评论可以回复其他人的评论，用"replyTo":"被回复者名字"标注。形成讨论氛围。有人可以反驳别人，有人可以附和，形成真实讨论。\n' +
      '8. 【主动性】与用户关系密切的角色，遇到推荐类帖子时可以选择repost，通过转发把帖子推荐给用户。但不要每条推荐帖都转发，只在真正觉得用户会喜欢的时候才转发。\n' +
      '9. 【记忆运用】角色和NPC的"相关记忆"和"最近线下互动"包含了他们与用户之间的真实经历。评论时可以自然地参考这些记忆。不要无视记忆中记录的事件。\n\n' +
      '══════════════════════════════\n' +
      '【普通论坛用户评论】\n' +
      '══════════════════════════════\n' +
      '除了角色和NPC的互动外，还需要生成普通论坛用户的评论。这些是论坛上的陌生网友，他们的评论风格多样：\n' +
      '- 有些是赞同、有些是反对、有些是调侃、有些是分享自己的经历、有些是纯灌水\n' +
      '- 评论简短为主，一般8-40字，可以很短如"哈哈哈"或"mark"，不要长篇\n' +
      '- 他们的名字应该是普通网友昵称（如"路过的猫"、"打工魂"、"甜筒不加糖"、"深夜冲浪选手"等），要有网感\n' +
      '- 不同网友的语气、立场、表达方式要有明显差异\n\n' +
      '══════════════════════════════\n' +
      '【评论总数要求】\n' +
      '══════════════════════════════\n' +
      '角色/NPC的评论 + 普通论坛用户的评论 = 总共8-10条即可，不要超过10条，避免冗长。\n' +
      '如果角色/NPC互动较少，就多生成普通网友评论补足到8-10条；每条都尽量短。\n\n' +
      '返回JSON格式：\n' +
      '{"reactions":[{"name":"角色或NPC名字","action":"like"},{"name":"角色或NPC名字","action":"comment","text":"评论内容","replyTo":"被回复者名字(可选)"},{"name":"角色或NPC名字","action":"repost","text":"想对用户说的话"}],"comments":[{"authorName":"普通网友昵称","content":"评论内容","time":"刚刚"}]}\n' +
      'reactions数组：角色和NPC的互动（点赞、评论、转发）\n' +
      'comments数组：普通论坛用户的评论（用于补足10条总评论）\n' +
      '如果没有角色/NPC互动，reactions返回空数组。只返回JSON。';
  }

  // 没有角色/NPC信息时，生成10条普通论坛用户评论
  return '请为以下帖子生成10条评论。\n\n' +
    '帖子作者：' + (postAuthor || '匿名') + '\n' +
    '帖子内容：' + String(postContent || '').slice(0, 300) + '\n\n' +
    '【评论生成铁律】：\n' +
    '1. 【角色多样性】评论区必须模拟真实网络生态，包含多种角色：理性的分析者、情绪化的支持者/反对者、抖机灵的、单纯的路人、偶尔出现的杠精\n' +
    '2. 【昵称网感】评论者的昵称必须非常生活化、有网感。严禁使用"用户A"、"评论者1"这种代号。\n' +
    '3. 【内容高度相关】所有评论都必须紧密围绕帖子内容展开。\n' +
    '4. 【语言风格】全部使用简体中文，语气要口语化。可以带emoji，可以用网络用语。\n' +
    '5. 评论可以很短，比如"哈哈哈"、"确实"、"前排吃瓜"这种也很真实\n' +
    '6. 不同网友的语气、立场、表达方式要有明显差异\n' +
    '7. 返回JSON格式：{"comments":[{"authorName":"","content":"","time":"刚刚"}]}\n' +
    '8. 只返回JSON，不要解释';
};

/* ============================================================
 * PART 10 - Open / Close
 * ============================================================ */

var openSocialForum = function (role) {
  sfState.currentRole = role || null;
  /* 未指定角色时：优先取“当前世界 + 当前账号好友”的第一个角色，保证论坛是本世界的社会，不混入别的世界角色 */
  if (!sfState.currentRole && typeof config !== 'undefined' && config.characters && config.characters.length > 0) {
    var _wid = (config.waSession && config.waSession.worldId) || 'default';
    var _sameWorld = config.characters.filter(function (ch) { return (ch.worldId || 'default') === _wid && !ch.deletedFromWechat; });
    sfState.currentRole = _sameWorld[0] || config.characters.filter(function (ch) { return (ch.worldId || 'default') === _wid; })[0] || config.characters[0];
  }

  sfState.active = true;
  sfState.currentTab = 'following';
  sfState.currentView = 'feed';
  sfState.posts = {};
  /* 世界/账号隔离：打开前先清空所有“按账号存储”的内存集合，再由下方各 load 按当前 scope 重新填充，
     否则新账号没有对应数据时会残留上一账号的帖子/点赞/收藏/关注/私信/通知（sfStorage 的 load 仅在有值时覆盖） */
  sfState.userPosts = []; sfState.likedPosts = []; sfState.savedPosts = []; sfState.followedRoles = [];
  sfState.dmConversations = {}; sfState.strangerDMs = []; sfState.notifList = [];
  sfState.commentsCache = {}; sfState.likesCache = {}; sfState.repostsCache = {}; sfState.reactionsGenerated = {};
  sfState.forumRules = []; sfState.worldviews = []; sfState.selectedRuleId = null; sfState.activeWorldviewId = null;
  sfState.userProfile = { posts: 0, followers: 0, following: 0, likes: 0, avatar: null };
  /* Load cached posts from localStorage */
  ['following', 'recommended', 'gossip'].forEach(function (t) {
    sfState.posts[t] = [];
    try {
      var saved = sfStorage.get('sf_posts_' + t);
      if (saved) {
        var parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          sfState.posts[t] = parsed;
        }
      }
    } catch (e) {}
  });
  sfState.loading = { following: false, recommended: false, gossip: false };
  sfState.notifCache = null;
  sfState.isLoading = false;
  sfState.sideMenuOpen = false;

  /* load saved profile */
  try {
    sfLoadProfileMeta();
  } catch (e) {}

  /* load saved followedRoles */
  try {
    var savedFollowed = sfStorage.get('sf_followed_roles');
    if (savedFollowed) {
      sfState.followedRoles = JSON.parse(savedFollowed) || [];
    }
  } catch (e) {}

  /* If followed is empty but we have a current role, auto-add it */
  if (sfState.followedRoles.length === 0 && sfState.currentRole) {
    sfState.followedRoles.push({
      id: sfState.currentRole.id || sfState.currentRole.name,
      name: sfState.currentRole.name,
      prompt: sfState.currentRole.persona || sfState.currentRole.prompt || '',
      gender: sfState.currentRole.gender || '',
      avatar: sfState.currentRole.avatar || sfState.currentRole.image || null
    });
    sfSaveFollowedRoles();
  }

  /* Load forum rules */
  try { sfLoadForumRules(); } catch (e) {}
  /* Load DM conversations */
  try { sfLoadDMConversations(); } catch (e) {}
  /* Load active forum roles selection */
  try { sfLoadActiveForumRoles(); } catch (e) {}
  /* Load worldviews (世界观) */
  try { sfLoadWorldviews(); } catch (e) {}
  /* Load 我发布的帖子（按当前世界/账号） */
  try { sfLoadUserPosts(); } catch (e) {}
  /* Load stranger DMs (陌生人私信) */
  try { sfLoadStrangerDMs(); } catch (e) {}
  /* Reload comments/likes/reactions cache */
  try { sfLoadCommentsCache(); } catch (e) {}

  var overlay = sfEl('socialForumOverlay');
  if (overlay) overlay.classList.add('active');

  sfRenderSideMenu();
  sfRenderNavAvatar();
  sfSwitchView('feed');
  /* 更新通知badge */
  try { sfLoadNotifications(); sfUpdateNotifBadge(); } catch(e) {}
};

var sfRenderNavAvatar = function () {
  sfLoadProfileMeta();
  var navAvatar = sfEl('sfNavAvatar');
  if (!navAvatar) return;
  var name = sfState.userProfile.displayName ||
    (typeof config !== 'undefined' && config.user && config.user.name) ||
    '体验用户';
  var avatarSrc = sfState.userProfile.avatar ||
    (typeof config !== 'undefined' && config.user && config.user.avatar) ||
    null;
  if (avatarSrc) {
    navAvatar.innerHTML = '<img src="' + sfEscapeHtml(avatarSrc) + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover" alt="" />';
  } else {
    navAvatar.innerHTML = sfEscapeHtml(sfInitial(name));
  }
};

var closeSocialForum = function () {
  sfState.active = false;
  var overlay = sfEl('socialForumOverlay');
  if (overlay) overlay.classList.remove('active');
  sfClosePostDetail();
  sfClosePostModal();
  sfCloseSideMenu();
};

/* ============================================================
 * PART 11 - View Switching
 * ============================================================ */

var sfSwitchView = function (view) {
  var normView = (view === 'home') ? 'feed' : view;
  sfState.currentView = normView;
  /* hide all views */
  document.querySelectorAll('#sfContent .sf-view').forEach(function (v) {
    v.classList.remove('active');
  });

  var viewMap = {
    feed: 'sfHomeView',
    search: 'sfSearchView',
    dm: 'sfDMView',
    notifications: 'sfNotifView',
    me: 'sfMeView'
  };
  var el = sfEl(viewMap[normView]);
  if (el) el.classList.add('active');

  /* update bottom nav */
  document.querySelectorAll('.sf-bottom-nav .sf-tab').forEach(function (t) {
    var tv = t.dataset.sfView;
    t.classList.toggle('active', tv === normView || (normView === 'me' && tv === 'me'));
  });

  /* FAB visible on feed + profile */
  var fab = sfEl('sfFab');
  if (fab) fab.style.display = (normView === 'feed' || normView === 'me') ? 'grid' : 'none';

  if (normView === 'feed') sfRenderTimeline(sfState.currentTab);
  else if (normView === 'search') sfRenderTrends();
  else if (normView === 'dm') sfRenderDMList();
  else if (normView === 'notifications') sfRenderNotifications();
  else if (normView === 'me') sfRenderProfile();
};

var sfSwitchTab = function (tab) {
  sfState.currentTab = tab;
  document.querySelectorAll('.sf-sub-tab').forEach(function (t) {
    t.classList.toggle('active', t.dataset.sfTab === tab);
  });
  sfRenderTimeline(tab);
};

/* ============================================================
 * PART 12 - Followed Roles
 * ============================================================ */

var sfGetAllRoles = function () {
  var allRoles = [];
  try {
    if (typeof config !== 'undefined' && config.characters) {
      allRoles = config.characters.filter(function(r) { return !r.deletedFromWechat; }).map(function (r) {
        return {
          id: r.id || r.name,
          name: r.name,
          prompt: r.persona || r.prompt || '',
          persona: r.persona || r.prompt || '',
          gender: r.gender || '',
          avatar: r.avatar || r.image || null,
          avatarBg: r.avatarBg || '#576B95',
          type: 'character'
        };
      });
    }
    // 添加NPC
    if (typeof config !== 'undefined' && config.npcs) {
      config.npcs.forEach(function (n) {
        allRoles.push({
          id: 'npc-' + n.id,
          name: n.name,
          prompt: n.persona || '',
          persona: n.persona || '',
          gender: n.gender || '',
          avatar: null,
          avatarBg: n.avatarBg || '#FF9500',
          avatarEmoji: n.avatar || n.name.charAt(0),
          type: 'npc'
        });
      });
    }
  } catch (e) {}
  /* 如果设置了参与角色列表，只返回在列表中的角色 */
  if (sfState.activeForumRoleIds && sfState.activeForumRoleIds.length > 0) {
    allRoles = allRoles.filter(function (r) {
      return sfState.activeForumRoleIds.indexOf(r.id) !== -1;
    });
  }
  return allRoles;
};

var sfRenderFollowedRoles = function () {
  var container = sfEl('sfFollowedRoles');
  if (!container) return;
  if (sfState.followedRoles.length === 0) {
    container.innerHTML = '<div class="sf-followed-empty">暂未关注角色，点击下方添加</div>';
  } else {
    var items = sfState.followedRoles.map(function (r, i) {
      var avatarSrc = sfRoleAvatarSrc(r);
      return '<div class="sf-followed-item">'
        + '<img class="sf-followed-avatar" src="' + sfEscapeHtml(avatarSrc) + '"  alt="头像"/>'
        + '<span class="sf-followed-name">' + sfEscapeHtml(r.name || '未命名') + '</span>'
        + '<button class="sf-followed-remove" data-sf-remove-role="' + i + '">&times;</button>'
        + '</div>';
    }).join('');
    container.innerHTML = items;
  }
};

var sfOpenRolePicker = function () {
  var allRoles = sfGetAllRoles();
  var followedIds = sfState.followedRoles.map(function (r) { return r.id; });

  var itemsHtml = allRoles.map(function (r) {
    var isFollowed = followedIds.indexOf(r.id) !== -1;
    var avatarSrc = sfRoleAvatarSrc(r);
    return '<div class="sf-role-picker-item' + (isFollowed ? ' followed' : '') + '" data-sf-pick-role-id="' + sfEscapeHtml(r.id || '') + '" data-sf-pick-role-name="' + sfEscapeHtml(r.name || '') + '">'
      + '<img class="sf-role-picker-avatar" src="' + sfEscapeHtml(avatarSrc) + '"  alt="头像"/>'
      + '<span class="sf-role-picker-name">' + sfEscapeHtml(r.name || '未命名') + '</span>'
      + (isFollowed ? '<span class="sf-role-picker-check">&#10003;</span>' : '')
      + '</div>';
  }).join('');

  var overlay = sfEl('sfRolePickerOverlay');
  if (!overlay) return;
  overlay.innerHTML = '<div class="sf-role-picker-card">'
    + '<div class="sf-role-picker-title">选择角色</div>'
    + '<div class="sf-role-picker-list">' + (itemsHtml || '<div style="color:#888;padding:20px;text-align:center">没有可添加的角色</div>') + '</div>'
    + '<button class="sf-role-picker-close-btn" id="sfRolePickerCloseBtn">关闭</button>'
    + '</div>';
  overlay.classList.add('active');

  var closeBtn = document.getElementById('sfRolePickerCloseBtn');
  if (closeBtn) closeBtn.addEventListener('click', sfCloseRolePicker);

  overlay.querySelectorAll('[data-sf-pick-role-id]').forEach(function (el) {
    el.addEventListener('click', function () {
      var roleId = el.dataset.sfPickRoleId;
      var rid = String(roleId);
      var idx = -1;
      for (var i = 0; i < sfState.followedRoles.length; i++) {
        if (String(sfState.followedRoles[i].id) === rid) { idx = i; break; }
      }
      if (idx !== -1) {
        sfState.followedRoles.splice(idx, 1);
      } else {
        var roleData = allRoles.find(function (r) { return String(r.id) === rid; });
        if (roleData) sfState.followedRoles.push(roleData);
      }
      sfSaveFollowedRoles();
      sfOpenRolePicker();
      sfRenderFollowedRoles();
    });
  });
};

var sfCloseRolePicker = function () {
  var overlay = sfEl('sfRolePickerOverlay');
  if (overlay) overlay.classList.remove('active');
};

/* ---- 参与角色选择弹窗（多选） ---- */
var sfCloseRoleSelectModal = function () {
  var overlay = sfEl('sfRoleSelectOverlay');
  if (overlay) overlay.classList.remove('active');
};

var sfOpenRoleSelectModal = function () {
  /* 获取全部角色和NPC（不受 activeForumRoleIds 过滤影响） */
  var allRoles = [];
  try {
    if (typeof config !== 'undefined' && config.characters) {
      allRoles = config.characters.filter(function(r) { return !r.deletedFromWechat; }).map(function (r) {
        return {
          id: r.id || r.name,
          name: r.name,
          avatar: r.avatar || r.image || null,
          avatarBg: r.avatarBg || '#576B95',
          type: 'character'
        };
      });
    }
    if (typeof config !== 'undefined' && config.npcs) {
      config.npcs.forEach(function (n) {
        allRoles.push({
          id: 'npc-' + n.id,
          name: n.name,
          avatar: null,
          avatarBg: n.avatarBg || '#FF9500',
          avatarEmoji: n.avatar || n.name.charAt(0),
          type: 'npc'
        });
      });
    }
  } catch (e) {}

  var activeIds = sfState.activeForumRoleIds || [];
  var itemsHtml = allRoles.map(function (r) {
    var isSelected = activeIds.indexOf(r.id) !== -1;
    var avatarHtml;
    if (r.type === 'npc') {
      avatarHtml = '<div style="width:36px;height:36px;border-radius:50%;background:' + (r.avatarBg || '#FF9500') + ';display:grid;place-items:center;font-size:16px;color:#fff;flex-shrink:0">' + sfEscapeHtml(r.avatarEmoji || '?') + '</div>';
    } else if (r.avatar) {
      avatarHtml = '<img style="width:36px;height:36px;border-radius:50%;object-fit:cover;flex-shrink:0" src="' + sfEscapeHtml(r.avatar) + '" alt="" />';
    } else {
      avatarHtml = '<div style="width:36px;height:36px;border-radius:50%;background:' + (r.avatarBg || '#576B95') + ';display:grid;place-items:center;font-size:14px;color:#fff;flex-shrink:0">' + sfEscapeHtml(sfInitial(r.name)) + '</div>';
    }
    var typeLabel = r.type === 'npc' ? ' <span style="font-size:10px;color:#FF9500">NPC</span>' : '';
    return '<div class="sf-role-picker-item' + (isSelected ? ' followed' : '') + '" data-sf-roleselect-id="' + sfEscapeHtml(r.id || '') + '" style="cursor:pointer">'
      + avatarHtml
      + '<span class="sf-role-picker-name">' + sfEscapeHtml(r.name || '未命名') + typeLabel + '</span>'
      + '<span class="sf-role-picker-check">' + (isSelected ? '&#10003;' : '&#9744;') + '</span>'
      + '</div>';
  }).join('');

  var selectedCount = activeIds.length;
  var hint = selectedCount > 0 ? ('已选 ' + selectedCount + ' 个角色参与论坛互动') : '未选择时，所有角色和NPC均参与论坛互动';

  var overlay = sfEl('sfRoleSelectOverlay');
  if (!overlay) return;
  overlay.innerHTML = '<div class="sf-role-picker-card" style="max-height:80vh;display:flex;flex-direction:column">'
    + '<div class="sf-role-picker-title">参与角色</div>'
    + '<div style="font-size:11px;color:#999;padding:0 0 8px;text-align:center">' + sfEscapeHtml(hint) + '</div>'
    + '<div class="sf-role-picker-list" style="overflow-y:auto;flex:1">' + (itemsHtml || '<div style="color:#888;padding:20px;text-align:center">没有可选角色</div>') + '</div>'
    + '<div style="display:flex;gap:8px;padding:10px 0 0">'
    + '<button class="sf-role-picker-close-btn" id="sfRoleSelectClearBtn" style="flex:1">全不选</button>'
    + '<button class="sf-role-picker-close-btn" id="sfRoleSelectCloseBtn" style="flex:1">完成</button>'
    + '</div>'
    + '</div>';
  overlay.classList.add('active');

  var closeBtn = document.getElementById('sfRoleSelectCloseBtn');
  if (closeBtn) closeBtn.addEventListener('click', sfCloseRoleSelectModal);
  var clearBtn = document.getElementById('sfRoleSelectClearBtn');
  if (clearBtn) clearBtn.addEventListener('click', function () {
    sfState.activeForumRoleIds = [];
    sfSaveActiveForumRoles();
    sfOpenRoleSelectModal();
    sfToast('已清空，所有角色均可参与');
  });

  overlay.querySelectorAll('[data-sf-roleselect-id]').forEach(function (el) {
    el.addEventListener('click', function () {
      var roleId = el.dataset.sfRoleselectId;
      var idx = sfState.activeForumRoleIds.indexOf(roleId);
      if (idx === -1) {
        sfState.activeForumRoleIds.push(roleId);
      } else {
        sfState.activeForumRoleIds.splice(idx, 1);
      }
      sfSaveActiveForumRoles();
      /* 刷新弹窗显示 */
      sfOpenRoleSelectModal();
    });
  });
};

/* ============================================================
 * PART 13 - Data Loading (uses callApi instead of server endpoints)
 * ============================================================ */

var sfLoadTab = async function (tab) {
  var _sfScope = sfScope(); // 锁定本次加载所属的世界/账号，await 期间切账号也不会存错桶
  sfState.loading[tab] = true;
  sfState.isLoading = true;
  if (sfState.active && sfState.currentView === 'feed' && tab === sfState.currentTab) {
    var tl = sfEl('sfTimeline');
    if (tl && sfState.posts[tab].length === 0) {
      tl.innerHTML = '<div class="sf-loading">正在加载...</div>';
    }
  }

  var role = sfState.currentRole || null;

  /* Gather recent messages from character chat history */
  var recentMessages = [];
  if (role && role.chatHistory) {
    try {
      recentMessages = role.chatHistory.slice(-8).map(function (m) {
        return { role: m.role, content: m.content };
      });
    } catch (e) {}
  }

  /* Gather memories from character */
  var memories = [];
  if (role && role.memories && Array.isArray(role.memories)) {
    memories = role.memories.slice(0, 6);
  }

  try {
    /* Build prompt client-side (same content as server's generateForumPostsCore) */
    var prompt = sfBuildPostsPrompt(tab, sfState.followedRoles, role, recentMessages, memories);

    /* Call AI via existing callApi function */
    var apiMessages = [
      { role: 'system', content: '你是一个虚拟社交论坛的内容生成器。关注页的每条帖子都是虚拟角色以自己本人第一人称发布的，用户是浏览者，绝不能用用户的身份或视角写角色的帖子。请严格按照要求返回JSON格式数据，不要包含任何解释性文字。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages);

    /* Parse JSON from reply */
    var posts = [];
    if (reply) {
      var cleaned = String(reply).replace(/^```json\s*/i, '').replace(/```$/g, '').replace(/^```\s*/, '').trim();
      var jsonMatch = cleaned.match(/\{[\s\S]*\}/);
      var parsed;
      try { parsed = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned); } catch(e) { parsed = null; }
      if (parsed && Array.isArray(parsed.posts)) {
        posts = parsed.posts.slice(0, 12);
      }
    }

    /* Normalize posts */
    posts.forEach(function (p, i) {
      if (!p.id) p.id = tab + '-' + Date.now() + '-' + i;
      if (!p.handle) p.handle = sfHandle(p.authorName);
      if (typeof p.verified !== 'boolean') p.verified = (tab !== 'following' && i < 2);
      if (typeof p.likes !== 'number') p.likes = Math.floor(Math.random() * 5000) + 10;
      if (typeof p.reposts !== 'number') p.reposts = Math.floor(Math.random() * 50);
      if (typeof p.comments !== 'number') p.comments = (p.commentsList || []).length;
      if (typeof p.views !== 'number') p.views = Math.floor(Math.random() * 8000) + 200;
      if (typeof p.avatarIndex !== 'number') p.avatarIndex = i % SF_AVATAR_COUNT;
      p.imageGradient = null;
      if (!p.commentsList) p.commentsList = [];
      p.authorName = String(p.authorName || '匿名').slice(0, 30);
      p.content = String(p.content || '').slice(0, 2000);
      p.time = String(p.time || '刚刚').slice(0, 20);
      /* 解析HTML交互模块字段 */
      if (p.htmlModule && typeof p.htmlModule === 'string') {
        p.htmlModule = String(p.htmlModule).slice(0, 2000);
      } else {
        p.htmlModule = null;
      }

      if (tab === 'following') {
        p.roleAuthored = true;
        p.verified = false;
        if (sfState.followedRoles.length > 0) {
          var matchedRole = sfState.followedRoles.find(function (r) { return r.name === p.authorName; });
          if (matchedRole) {
            p.roleAvatar = sfRoleAvatarSrc(matchedRole);
            p.handle = sfHandle(matchedRole.name);
          }
        } else if (role) {
          p.authorName = role.name;
          p.handle = sfHandle(role.name);
          p.roleAvatar = sfRoleAvatarSrc(role);
        }
      }
    });

    sfState.posts[tab] = posts;
    posts.forEach(function (p) {
      if (!sfState.commentsCache[p.id]) sfState.commentsCache[p.id] = p.commentsList || [];
    });
    /* Persist：用发起时锁定的作用域，防止生成中切账号存错社会 */
    sfStorage.setIn(_sfScope, 'sf_posts_' + tab, JSON.stringify(posts));
  } catch (e) {
    sfState.posts[tab] = [];
    sfToast('生成失败：' + ((e && e.message) ? e.message : '请稍后重试'));
  }

  sfState.loading[tab] = false;
  sfState.isLoading = false;
  if (sfState.active && sfState.currentView === 'feed' && tab === sfState.currentTab) {
    sfRenderTimeline(tab);
  }
};

/* ============================================================
 * PART 14 - Rendering
 * ============================================================ */

var sfFormatPostTime = function (ts) {
  if (!ts) return '刚刚';
  var d = new Date(ts);
  var diff = Date.now() - d;
  if (diff < 0) return '刚刚';
  if (diff < 60000) return '刚刚';
  if (diff < 3600000) return Math.floor(diff / 60000) + '分钟前';
  if (diff < 86400000) return Math.floor(diff / 3600000) + '小时前';
  if (diff < 604800000) return Math.floor(diff / 86400000) + '天前';
  return (d.getMonth() + 1) + '月' + d.getDate() + '日';
};

var sfGetNpcPosts = function (tab) {
  var npcPosts = [];
  try {
    if (typeof config !== 'undefined' && config.npcs) {
      config.npcs.forEach(function(npc) {
        if (npc._deprecated) return;
        if (npc.phone && npc.phone.forum && npc.phone.forum.posts) {
          npc.phone.forum.posts.forEach(function(p) {
            npcPosts.push({
              id: p.id,
              authorName: npc.name,
              handle: sfHandle(npc.name),
              content: p.content,
              time: sfFormatPostTime(p.time),
              timestamp: p.time,
              likes: p.likes || 0,
              reposts: 0,
              comments: (p.comments || []).length,
              views: Math.floor(Math.random() * 3000) + 100,
              commentsList: (p.comments || []).map(function(c) {
                return { id: c.id || ('c' + Math.random()), authorName: c.authorName, content: c.content, time: c.time || '刚刚' };
              }),
              likedBy: p.likedBy || [],
              roleAvatar: null,
              npcAuthored: true,
              npcId: npc.id,
              npcAvatarBg: npc.avatarBg || '#FF9500',
              npcAvatarEmoji: npc.avatar || npc.name.charAt(0),
              verified: false,
              liked: p.liked || false,
              imageGradient: null
            });
            /* Populate caches from NPC post data */
            if (p.comments && p.comments.length > 0 && !sfState.commentsCache[p.id]) {
              sfState.commentsCache[p.id] = (p.comments || []).map(function(c) {
                return { id: c.id || ('c' + Math.random()), authorName: c.authorName, content: c.content, time: c.time || '刚刚', avatarIndex: 0, replyTo: c.replyTo || null, replyToId: c.replyToId || null };
              });
            }
            if (p.likedBy && p.likedBy.length > 0 && !sfState.likesCache[p.id]) {
              sfState.likesCache[p.id] = p.likedBy;
            }
          });
        }
      });
    }
  } catch(e) {
    console.error('sfGetNpcPosts error:', e);
  }
  return npcPosts;
};

var sfGetDisplayPosts = function (tab) {
  var user = sfState.userPosts.filter(function (p) { return p.tab === tab; });
  var ai = sfState.posts[tab] || [];
  /* NPC帖子只在关注页面显示 */
  var npcPosts = (tab === 'following') ? sfGetNpcPosts(tab) : [];
  // NPC帖子排在最前面，按时间倒序
  npcPosts.sort(function(a, b) { return (b.timestamp || 0) - (a.timestamp || 0); });
  return npcPosts.concat(user).concat(ai);
};

var sfFindPost = function (postId) {
  var p = sfState.userPosts.find(function (x) { return x.id === postId; });
  if (p) return p;
  for (var tab in sfState.posts) {
    p = sfState.posts[tab].find(function (x) { return x.id === postId; });
    if (p) return p;
  }
  /* Also search NPC posts */
  var npcPosts = sfGetNpcPosts('following');
  p = npcPosts.find(function (x) { return x.id === postId; });
  if (p) return p;
  return null;
};

/* HTML交互模块安全过滤：移除script标签和事件处理器属性 */
var sfSanitizeHtmlModule = function (html) {
  if (!html || typeof html !== 'string') return '';
  var s = String(html);
  /* 移除<script>...<\/script>（注释中转义避免HTML解析器误关闭script块） */
  s = s.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
  /* 移除onXxx事件处理器属性 */
  s = s.replace(/\son\w+\s*=\s*"[^"]*"/gi, '');
  s = s.replace(/\son\w+\s*=\s*'[^']*'/gi, '');
  s = s.replace(/\son\w+\s*=\s*[^\s>]+/gi, '');
  /* 移除javascript:伪协议 */
  s = s.replace(/javascript:/gi, '');
  return s.trim();
};

var sfRenderPost = function (post) {
  var avatarSrc = post.roleAvatar || sfGetAvatarSrc(post.avatarIndex, post.authorName);
  var commentCount = (sfState.commentsCache[post.id] || post.commentsList || []).length;
  var liked = post.liked ? ' liked' : '';
  /* 匿名帖子不显示认证标识 */
  var verifiedHtml = (post.verified && !post._anonymous) ? '<span class="sf-post-verified">&#10003;</span>' : '';
  var imageGrad = post.imageGradient ? sfGradientCss(post.imageGradient) : '';
  // NPC帖子使用emoji头像
  var avatarHtml;
  if (post._anonymous) {
    /* 匿名帖子：灰色问号头像 */
    avatarHtml = '<div class="sf-post-avatar" style="background:#ccc;display:grid;place-items:center;font-size:20px;color:#fff;border-radius:50%;flex-shrink:0;width:42px;height:42px">?</div>';
  } else if (post.npcAuthored) {
    avatarHtml = '<div class="sf-post-avatar" style="background:' + (post.npcAvatarBg || '#FF9500') + ';display:grid;place-items:center;font-size:18px;color:#fff;border-radius:50%;flex-shrink:0">' + sfEscapeHtml(post.npcAvatarEmoji || '👤') + '</div>';
  } else {
    avatarHtml = '<img class="sf-post-avatar" src="' + sfEscapeHtml(avatarSrc) + '" alt="" />';
  }

  var html = '<div class="sf-post" data-post-id="' + sfEscapeHtml(post.id || '') + '">'
    + '<div class="sf-post-header">'
    + '<div class="sf-post-author-click" data-author-name="' + sfEscapeHtml(post.authorName || '') + '" data-author-npc="' + (post.npcAuthored ? '1' : '0') + '" style="display:flex;align-items:center;gap:10px;flex:1;min-width:0">'
    + avatarHtml
    + '<div class="sf-post-meta">'
    + '<span class="sf-post-name">' + sfEscapeHtml(post.authorName || '匿名') + (post.npcAuthored ? ' <span style="font-size:10px;color:#FF9500">NPC</span>' : '') + (post._anonymous ? ' <span style="font-size:10px;color:#999">匿名</span>' : '') + '</span>'
    + '<span class="sf-post-handle">' + sfEscapeHtml(post.handle || sfHandle(post.authorName)) + '</span>'
    + verifiedHtml
    + '</div>'
    + '</div>'
    + '<span class="sf-post-time">' + sfEscapeHtml(post.time || '刚刚') + '</span>'
    + '</div>';

  var contentText = sfEscapeHtml(post.content || '');
  var typeBadge = sfPostTypeBadgeHtml(post.content);
  html += '<div class="sf-post-content">' + typeBadge + contentText + '</div>';

  /* 渲染HTML交互模块（如果存在） */
  if (post.htmlModule) {
    var safeHtml = sfSanitizeHtmlModule(post.htmlModule);
    if (safeHtml) {
      html += '<div class="sf-post-html-module">'
        + '<div class="sf-post-html-module-title">&#10024; 互动模块</div>'
        + safeHtml + '</div>';
    }
  }

  /* Display post image if available */
  if (post.imageUrl) {
    html += '<img class="sf-post-image" src="' + sfEscapeHtml(post.imageUrl) + '" alt="" />';
  }

  html += '<div class="sf-post-actions">'
    + '<span class="sf-post-action" data-action="comment">&#128172; ' + commentCount + '</span>'
    + '<span class="sf-post-action" data-action="repost">&#8619;&#65039; ' + (post.reposts || 0) + '</span>'
    + '<span class="sf-post-action' + liked + '" data-action="like">&#10084;&#65039; ' + (post.likes || 0) + '</span>'
    + '<span class="sf-post-action" data-action="views">&#128065;&#65039; ' + sfFormatNum(post.views || 0) + '</span>'
    + '</div>';

  /* Show liked-by list (某某赞过) */
  var likesList = sfState.likesCache[post.id] || post.likedBy || [];
  if (post.liked) {
    var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '我';
    if (!likesList.some(function(l) { return l.isUser; })) {
      likesList = [{ name: userName, isUser: true }].concat(likesList);
    }
  }
  if (likesList.length > 0) {
    var displayNames = likesList.slice(0, 3).map(function(l) { return sfEscapeHtml(l.name); });
    var likeText = displayNames.join('、');
    if (likesList.length > 3) {
      likeText += ' 等' + likesList.length + '人';
    }
    html += '<div class="sf-post-likedby" style="padding:4px 12px 8px;font-size:11px;color:#999;line-height:1.5">'
      + '<span style="color:#F5A0B8">&#10084;</span> ' + likeText + '赞过</div>';
  }

  html += '</div>';

  return html;
};

var sfRenderTimeline = function (tab) {
  var timeline = sfEl('sfTimeline');
  if (!timeline) return;

  /* Following page: show followed roles section at top */
  var followedHtml = '';
  if (tab === 'following') {
    followedHtml = '<div class="sf-followed-section">'
      + '<div id="sfFollowedRoles"></div>'
      + '<button class="sf-followed-add-btn" id="sfAddRoleBtn">+ 添加角色</button>'
      + '</div>';
  }

  var posts = sfGetDisplayPosts(tab);
  if (sfState.loading[tab] && posts.length === 0) {
    timeline.innerHTML = followedHtml + '<div class="sf-loading">正在加载...</div>';
    sfAttachFollowedEvents();
    return;
  }
  if (posts.length === 0) {
    timeline.innerHTML = followedHtml + '<div class="sf-empty">'
      + '<div style="margin-bottom:20px;font-size:15px;color:#888">还没有内容哦~</div>'
      + '<button class="sf-generate-btn" data-sf-generate="' + tab + '">'
      + '✨ 生成新动态</button>'
      + '</div>';
    sfAttachFollowedEvents();
    return;
  }
  timeline.innerHTML = followedHtml + posts.map(function (p) { return sfRenderPost(p); }).join('')
    + '<div style="text-align:center;padding:10px 0 20px">'
    + '<button class="sf-refresh-btn" data-sf-refresh="' + tab + '">换一批 ✨</button>'
    + '</div>';

  sfAttachFollowedEvents();

  /* expand behavior for long posts */
  timeline.querySelectorAll('.sf-post-content').forEach(function (el) {
    if (el.scrollHeight > el.clientHeight + 2) {
      el.classList.add('collapsed');
      var btn = document.createElement('span');
      btn.className = 'sf-post-expand';
      btn.textContent = '展开';
      btn.addEventListener('click', function () {
        el.classList.remove('collapsed');
        btn.remove();
      });
      el.parentNode.insertBefore(btn, el.nextSibling);
    }
  });
};

var sfAttachFollowedEvents = function () {
  /* Re-render followed list */
  var followedContainer = sfEl('sfFollowedRoles');
  if (followedContainer) sfRenderFollowedRoles();

  /* Add role button */
  var addBtn = document.getElementById('sfAddRoleBtn');
  if (addBtn) {
    addBtn.addEventListener('click', function () {
      sfOpenRolePicker();
    });
  }

  /* Remove role buttons */
  document.querySelectorAll('[data-sf-remove-role]').forEach(function (btn) {
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      var idx = parseInt(btn.dataset.sfRemoveRole, 10);
      if (!isNaN(idx) && idx >= 0 && idx < sfState.followedRoles.length) {
        sfState.followedRoles.splice(idx, 1);
        sfSaveFollowedRoles();
        sfRenderFollowedRoles();
      }
    });
  });
};

/* ============================================================
 * PART 15 - Like / Save
 * ============================================================ */

var sfToggleLike = function (postId, actionEl) {
  var post = sfFindPost(postId);
  if (!post) return;
  post.liked = !post.liked;
  post.likes = (post.likes || 0) + (post.liked ? 1 : -1);
  
  /* Track user in likedBy list */
  var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '我';
  if (!sfState.likesCache[postId]) sfState.likesCache[postId] = [];
  var likesArr = sfState.likesCache[postId];
  if (post.liked) {
    if (!likesArr.some(function(l) { return l.isUser; })) {
      likesArr.unshift({ name: userName, isUser: true, type: 'user' });
    }
  } else {
    var uIdx = likesArr.findIndex(function(l) { return l.isUser; });
    if (uIdx >= 0) likesArr.splice(uIdx, 1);
  }
  sfSaveLikesCache();
  
  /* Persist NPC post like state back to config */
  if (post.npcAuthored && post.npcId) {
    try {
      var npc = (config.npcs || []).find(function(n) { return String(n.id) === String(post.npcId); });
      if (npc && npc.phone && npc.phone.forum && npc.phone.forum.posts) {
        var origPost = npc.phone.forum.posts.find(function(p) { return p.id === postId; });
        if (origPost) {
          origPost.liked = post.liked;
          origPost.likes = post.likes;
          origPost.likedBy = likesArr;
          Store.set('config', config);
        }
      }
    } catch(e) {}
  }
  if (actionEl) {
    actionEl.classList.toggle('liked', post.liked);
    actionEl.innerHTML = '&#10084;&#65039; ' + post.likes;
  }
  /* Update likes display in detail view */
  if (sfState.currentPostId === postId) {
    sfRenderLikesInDetail(postId);
  }
  /* Update likes display in timeline */
  var likedByEl = document.querySelector('.sf-post[data-post-id="' + postId + '"] .sf-post-likedby');
  if (likedByEl) {
    if (likesArr.length > 0) {
      var displayNames = likesArr.slice(0, 3).map(function(l) { return l.name; });
      var likeText = displayNames.join('、');
      if (likesArr.length > 3) likeText += ' 等' + likesArr.length + '人';
      likedByEl.innerHTML = '<span style="color:#F5A0B8">&#10084;</span> ' + sfEscapeHtml(likeText) + '赞过';
      likedByEl.style.display = 'block';
    } else {
      likedByEl.style.display = 'none';
    }
  }
  if (!sfState.likedPosts) sfState.likedPosts = [];
  if (post.liked) {
    var existIdx = sfState.likedPosts.findIndex(function (p) { return p.id === postId; });
    if (existIdx === -1) {
      var snapshot = JSON.parse(JSON.stringify(post));
      snapshot.liked = true;
      sfState.likedPosts.unshift(snapshot);
      sfSaveLikedPosts();
    }
  } else {
    var remIdx = sfState.likedPosts.findIndex(function (p) { return p.id === postId; });
    if (remIdx !== -1) {
      sfState.likedPosts.splice(remIdx, 1);
      sfSaveLikedPosts();
    }
  }
};

var sfToggleSave = function (postId, actionEl) {
  var post = sfFindPost(postId);
  if (!post) return;
  if (!sfState.savedPosts) sfState.savedPosts = [];
  var existIdx = sfState.savedPosts.findIndex(function (p) { return p.id === postId; });
  if (existIdx === -1) {
    var snapshot = JSON.parse(JSON.stringify(post));
    sfState.savedPosts.unshift(snapshot);
    sfSaveSavedPosts();
    if (actionEl) {
      actionEl.classList.add('saved');
      actionEl.innerHTML = '&#128274; 已收藏';
    }
    sfToast('已收藏');
  } else {
    sfState.savedPosts.splice(existIdx, 1);
    sfSaveSavedPosts();
    if (actionEl) {
      actionEl.classList.remove('saved');
      actionEl.innerHTML = '&#128274; 收藏';
    }
    sfToast('已取消收藏');
  }
};

/* ============================================================
 * PART 16 - Post Detail + Comments
 * ============================================================ */

var sfOpenPostDetail = function (postId) {
  var post = sfFindPost(postId);
  if (!post) return;
  sfState.currentPostId = postId;

  var overlay = sfEl('sfDetailOverlay');
  if (overlay) overlay.classList.add('active');

  var body = sfEl('sfDetailBody');
  if (body) {
    var avatarSrc = post.roleAvatar || sfGetAvatarSrc(post.avatarIndex, post.authorName);
    var commentCount = (sfState.commentsCache[postId] || post.commentsList || []).length;
    /* 匿名帖子不显示认证标识 */
    var verifiedHtml = (post.verified && !post._anonymous) ? '<span class="sf-post-verified">&#10003;</span>' : '';
    var imageGrad = post.imageGradient ? sfGradientCss(post.imageGradient) : '';

    var inner = '<div class="sf-post" style="border:0;cursor:default">'
      + '<div class="sf-post-header">';
    
    /* 匿名帖子使用灰色问号头像，NPC帖子使用emoji头像 */
    if (post._anonymous) {
      inner += '<div class="sf-post-avatar" style="background:#ccc;display:grid;place-items:center;font-size:20px;color:#fff;border-radius:50%;flex-shrink:0;width:42px;height:42px">?</div>';
    } else if (post.npcAuthored) {
      inner += '<div class="sf-post-avatar" style="background:' + (post.npcAvatarBg || '#FF9500') + ';display:grid;place-items:center;font-size:18px;color:#fff;border-radius:50%;flex-shrink:0">' + sfEscapeHtml(post.npcAvatarEmoji || '👤') + '</div>';
    } else {
      inner += '<img class="sf-post-avatar" src="' + sfEscapeHtml(avatarSrc) + '" alt="" />';
    }
    
    inner += '<div class="sf-post-meta">'
      + '<span class="sf-post-name">' + sfEscapeHtml(post.authorName || '匿名') + (post.npcAuthored ? ' <span style="font-size:10px;color:#FF9500">NPC</span>' : '') + (post._anonymous ? ' <span style="font-size:10px;color:#999">匿名</span>' : '') + '</span>'
      + '<span class="sf-post-handle">' + sfEscapeHtml(post.handle || sfHandle(post.authorName)) + '</span>'
      + verifiedHtml
      + '</div>'
      + '<span class="sf-post-time">' + sfEscapeHtml(post.time || '刚刚') + '</span>'
      + '</div>';

    inner += '<div class="sf-post-content">' + sfPostTypeBadgeHtml(post.content) + sfEscapeHtml(post.content || '') + '</div>';

    /* 详情页也渲染HTML交互模块 */
    if (post.htmlModule) {
      var detailSafeHtml = sfSanitizeHtmlModule(post.htmlModule);
      if (detailSafeHtml) {
        inner += '<div class="sf-post-html-module">'
          + '<div class="sf-post-html-module-title">&#10024; 互动模块</div>'
          + detailSafeHtml + '</div>';
      }
    }

    inner += '<div class="sf-post-actions">'
      + '<span class="sf-post-action" data-action="comment">&#128172; ' + commentCount + '</span>'
      + '<span class="sf-post-action" data-action="repost">&#8619;&#65039; ' + (post.reposts || 0) + '</span>'
      + '<span class="sf-post-action' + (post.liked ? ' liked' : '') + '" data-action="like">&#10084;&#65039; ' + (post.likes || 0) + '</span>'
      + '<span class="sf-post-action" data-action="views">&#128065;&#65039; ' + sfFormatNum(post.views || 0) + '</span>'
      + '</div>'
      /* 帖子操作栏后面加删除按钮（仅用户自己的帖子） */
      + (post._user ? '<div style="padding:6px 0 0"><span class="sf-post-action" data-action="delete" style="color:#ff4d4f">&#128465; 删除</span></div>' : '')
      + '</div>'
      + '<div class="sf-detail-likes" style="padding:8px 0 4px;font-size:12px;color:#999;line-height:1.6;display:none"></div>'
      + '<div class="sf-detail-reposts" style="padding:4px 0;display:none"></div>'
      + '<div style="padding:14px 0 4px;color:#999;font-size:13px;font-weight:700">评论</div>'
      + '<div id="sfDetailComments"></div>';

    body.innerHTML = inner;
  }

  sfRenderComments(postId);
  sfRenderLikesInDetail(postId);
  sfRenderRepostsInDetail(postId);
  /* Auto-generate reactions (likes + comments) if not already generated */
  if (!sfState.reactionsGenerated[postId] && !post._commentsLoaded) {
    if (!sfState.commentsCache[postId] || sfState.commentsCache[postId].length === 0) {
      var cc0 = sfEl('sfDetailComments');
      if (cc0) cc0.innerHTML = '<div style="text-align:center;padding:20px;color:#999;font-size:13px">正在生成角色/NPC互动...</div>';
      sfGenerateComments(postId, post);
    }
  } else {
    /* Show regenerate button if already generated */
    sfShowRegenerateBtn(postId, post);
  }
};

var sfShowRegenerateBtn = function (postId, post) {
  var c = sfEl('sfDetailComments');
  if (!c) return;
  var comments = sfState.commentsCache[postId] || [];
  var likes = (sfState.likesCache[postId] || []).length;
  var reposts = (sfState.repostsCache && sfState.repostsCache[postId] || []).length;
  /* Add regenerate button at the bottom of comments */
  var existingBtn = document.getElementById('sfRegenBtn');
  if (existingBtn) existingBtn.remove();
  var btnDiv = document.createElement('div');
  btnDiv.style.cssText = 'text-align:center;padding:12px;';
  btnDiv.innerHTML = '<button id="sfRegenBtn" style="padding:6px 16px;border:1px solid #F5A0B8;border-radius:16px;background:#fff;color:#F5A0B8;font-size:12px;cursor:pointer">✨ 重新生成互动 (' + likes + '赞 ' + comments.length + '评' + (reposts > 0 ? ' ' + reposts + '转' : '') + ')</button>';
  c.appendChild(btnDiv);
  var btn = document.getElementById('sfRegenBtn');
  if (btn) btn.addEventListener('click', function() {
    /* Reset and regenerate */
    sfState.reactionsGenerated[postId] = false;
    sfSaveReactionsGenerated();
    post._commentsLoaded = false;
    post._discussionTriggered = false;
    sfGenerateComments(postId, post);
  });
};

var sfClosePostDetail = function () {
  var d = sfEl('sfDetailOverlay');
  if (d) d.classList.remove('active');
  sfState.currentPostId = null;
  sfClearReplyTo();
};

/* ============================================================
 * 删除帖子：从所有缓存和列表中移除对应帖子
 * ============================================================ */
var sfDeletePost = function (postId) {
  if (!postId) return;
  /* 从用户帖子列表中删除 */
  var upIdx = sfState.userPosts.findIndex(function (p) { return p.id === postId; });
  if (upIdx !== -1) {
    sfState.userPosts.splice(upIdx, 1);
    sfSaveUserPosts();
    /* 更新用户资料发帖数 */
    sfState.userProfile.posts = sfState.userPosts.length;
  }
  /* 从所有tab的时间线帖子中删除 */
  var tabs = ['following', 'recommended', 'gossip'];
  tabs.forEach(function (tab) {
    if (sfState.posts[tab]) {
      var idx = sfState.posts[tab].findIndex(function (p) { return p.id === postId; });
      if (idx !== -1) {
        sfState.posts[tab].splice(idx, 1);
        sfStorage.set('sf_posts_' + tab, JSON.stringify(sfState.posts[tab]));
      }
    }
  });
  /* 从评论缓存中删除 */
  if (sfState.commentsCache[postId]) {
    delete sfState.commentsCache[postId];
    sfSaveCommentsCache();
  }
  /* 从点赞缓存中删除 */
  if (sfState.likesCache[postId]) {
    delete sfState.likesCache[postId];
    sfSaveLikesCache();
  }
  /* 从转发缓存中删除 */
  if (sfState.repostsCache && sfState.repostsCache[postId]) {
    delete sfState.repostsCache[postId];
    sfStorage.set('sf_reposts_cache', JSON.stringify(sfState.repostsCache));
  }
  /* 从互动生成标记中删除 */
  if (sfState.reactionsGenerated[postId]) {
    delete sfState.reactionsGenerated[postId];
    sfSaveReactionsGenerated();
  }
  /* 从已点赞帖子列表中删除 */
  var lpIdx = sfState.likedPosts.findIndex(function (p) { return p.id === postId; });
  if (lpIdx !== -1) {
    sfState.likedPosts.splice(lpIdx, 1);
    sfSaveLikedPosts();
  }
  /* 从已收藏帖子列表中删除 */
  var spIdx = sfState.savedPosts.findIndex(function (p) { return p.id === postId; });
  if (spIdx !== -1) {
    sfState.savedPosts.splice(spIdx, 1);
    sfSaveSavedPosts();
  }
  /* 关闭详情页 */
  sfClosePostDetail();
  /* 重新渲染时间线 */
  sfRenderTimeline(sfState.currentTab);
  sfToast('已删除');
};

/* 容错解析：当AI输出被 max_tokens 截断、JSON不完整时，
   逐个抢救“字段齐全且已闭合”的 reaction / comment，半句对象直接丢弃，保证不显示截断内容 */
function sfUnescapeJsonStr(v) { try { return JSON.parse('"' + v + '"'); } catch (e) { return String(v); } }
function sfLooseParseForumJson(text) {
  var out = { reactions: [], comments: [] };
  try {
    var m;
    var reR = /\{[^{}]*?"name"\s*:\s*"((?:[^"\\]|\\.)*)"[^{}]*?\}/g;
    while ((m = reR.exec(text))) {
      var blk = m[0];
      var am = blk.match(/"action"\s*:\s*"((?:[^"\\]|\\.)*)"/);
      var tm = blk.match(/"text"\s*:\s*"((?:[^"\\]|\\.)*)"/);
      var rm = blk.match(/"replyTo"\s*:\s*"((?:[^"\\]|\\.)*)"/);
      if (am) out.reactions.push({ name: sfUnescapeJsonStr(m[1]), action: sfUnescapeJsonStr(am[1]), text: tm ? sfUnescapeJsonStr(tm[1]) : '', replyTo: rm ? sfUnescapeJsonStr(rm[1]) : null });
    }
    var reC = /\{[^{}]*?"authorName"\s*:\s*"((?:[^"\\]|\\.)*)"[^{}]*?\}/g;
    while ((m = reC.exec(text))) {
      var blk2 = m[0];
      var cm = blk2.match(/"content"\s*:\s*"((?:[^"\\]|\\.)*)"/);
      if (cm) out.comments.push({ authorName: sfUnescapeJsonStr(m[1]), content: sfUnescapeJsonStr(cm[1]), time: '刚刚' });
    }
  } catch (e) {}
  return out;
}

var sfGenerateComments = async function (postId, post) {
  if (!post) return;
  /* Mark reactions as generated to prevent duplicate calls */
  sfState.reactionsGenerated[postId] = true;
  sfSaveReactionsGenerated();
  post._commentsLoaded = true;
  var c = sfEl('sfDetailComments');
  if (c) c.innerHTML = '<div style="text-align:center;padding:20px;color:#999;font-size:13px">正在生成互动...</div>';
  try {
    /* 修复：声明userName变量，避免解析reactions时ReferenceError */
    var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';
    /* Gather character/NPC context data */
    var contextData = sfGatherForumContext(post);
    /* Build comment prompt with context data */
    var prompt = sfBuildCommentsPrompt(post.content, post.authorName, 10, contextData);

    /* Call AI via existing callApi function */
    /* If post has image, include it in the API call for recognition */
    var apiMessages;
    if (post.imageUrl && post.imageUrl.startsWith('data:image')) {
      apiMessages = [
        { role: 'system', content: '你是一个虚拟社交论坛的互动模拟器。角色、NPC和普通论坛用户在浏览帖子，根据人设、帖子内容（包括图片）决定是否点赞、评论或转发。同时生成普通论坛用户评论。只返回JSON，不要解释。' + globalBookSuffix(prompt) },
        { role: 'user', content: [
          { type: 'text', text: prompt + '\n\n【图片内容】这是一条带图片的帖子，请根据图片内容生成互动。' },
          { type: 'image_url', image_url: { url: post.imageUrl, detail: 'low' } }
        ]}
      ];
    } else {
      apiMessages = [
        { role: 'system', content: '你是一个虚拟社交论坛的互动模拟器。角色、NPC和普通论坛用户在浏览帖子，根据人设和帖子内容决定是否点赞、评论或转发。同时生成普通论坛用户评论。只返回JSON，不要解释。' + globalBookSuffix(prompt) },
        { role: 'user', content: prompt }
      ];
    }
    var reply = await callApi(apiMessages, { maxTokens: 6000, temperature: 0.95 });

    var comments = [];
    var likes = [];
    var reposts = [];
    if (reply) {
      var cleaned = String(reply).replace(/^```json\s*/i, '').replace(/```$/g, '').replace(/^```\s*/, '').trim();
      var jsonMatch = cleaned.match(/\{[\s\S]*\}/);
      var parsed;
      try { parsed = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned); } catch(e) { parsed = null; }
      /* JSON 被 max_tokens 截断时容错抢救完整条目（丢弃半句） */
      if (!parsed) {
        try {
          var _loose = sfLooseParseForumJson(cleaned);
          if ((_loose.reactions && _loose.reactions.length) || (_loose.comments && _loose.comments.length)) {
            parsed = _loose;
            console.warn('[sfComments] 评论JSON被截断，已容错抢救 reactions=' + _loose.reactions.length + ' comments=' + _loose.comments.length);
          }
        } catch (_le) {}
      }

      /* Handle reactions format (likes + comments + reposts from characters/NPCs) */
      var rawReactions = [];
      if (parsed && Array.isArray(parsed.reactions)) {
        var allNames = contextData.characters.map(function(c) { return c.name; })
          .concat(contextData.npcs.map(function(n) { return n.name; }));
        parsed.reactions.forEach(function(r, idx) {
          if (!r.name) return;
          var reactionName = String(r.name).trim();
          if (reactionName === post.authorName) return;
          /* 过滤掉AI误把用户名放进reactions的情况 */
          if (reactionName === userName || reactionName.indexOf(userName) >= 0 || userName.indexOf(reactionName) >= 0) return;
          /* Match name with trimming, also try includes for fuzzy match */
          var matchedName = null;
          for (var ni = 0; ni < allNames.length; ni++) {
            /* 只允许精确匹配，杜绝模糊匹配导致的身份混淆 */
            if (allNames[ni] === reactionName) {
              matchedName = allNames[ni];
              break;
            }
          }
          /* 精确匹配失败时，尝试去除前后空格和标点后再匹配 */
          if (!matchedName) {
            var cleanReaction = reactionName.replace(/^[\s\u3000]+|[\s\u3000]+$/g, '').replace(/^[「『\"']+|[」』\"']+$/g, '');
            for (var ni2 = 0; ni2 < allNames.length; ni2++) {
              if (allNames[ni2] === cleanReaction) {
                matchedName = allNames[ni2];
                break;
              }
            }
          }
          if (!matchedName) {
            /* AI把陌生网友评论放在了reactions数组里，作为普通评论保留 */
            if (r.action === 'comment' && r.text) {
              comments.push({
                id: 'c-gen-' + Date.now() + '-' + idx,
                authorName: reactionName.slice(0, 24),
                content: String(r.text),
                time: '刚刚',
                avatarIndex: (idx + 5) % SF_AVATAR_COUNT,
                replyTo: r.replyTo || null
              });
            }
            return;
          }
          /* Store matched name on reaction for memory/proactive use */
          r._matchedName = matchedName;
          rawReactions.push(r);
          if (r.action === 'like') {
            likes.push({ name: matchedName, isUser: false, type: 'character' });
          } else if (r.action === 'comment' && r.text) {
            comments.push({
              id: 'c-ai-' + Date.now() + '-' + idx,
              authorName: matchedName,
              content: String(r.text),
              time: '刚刚',
              avatarIndex: idx % SF_AVATAR_COUNT,
              replyTo: r.replyTo || null
            });
          } else if (r.action === 'repost' && r.text) {
            reposts.push({
              id: 'rp-' + Date.now() + '-' + idx,
              authorName: matchedName,
              content: String(r.text),
              time: '刚刚'
            });
          }
        });
      }
      
      /* Also process generic forum user comments (always, not just as fallback) */
      if (parsed && Array.isArray(parsed.comments)) {
        parsed.comments.forEach(function (cm, idx) {
          var cName = String(cm.authorName || SF_COMMENT_AUTHORS[idx % SF_COMMENT_AUTHORS.length]).slice(0, 24);
          /* Skip if this comment is from a character/NPC (already handled in reactions) */
          var isCharOrNpc = (contextData.characters.some(function(c) { return c.name === cName; }) ||
                             contextData.npcs.some(function(n) { return n.name === cName; }));
          if (isCharOrNpc) return;
          comments.push({
            id: 'c-gen-' + Date.now() + '-' + idx,
            authorName: cName,
            content: String(cm.content || ''),
            time: String(cm.time || '刚刚').slice(0, 20),
            avatarIndex: (idx + Math.floor(Math.random() * 3)) % SF_AVATAR_COUNT
          });
        });
      }
    }

    /* 不再用写死模板评论/点赞冒充AI互动：AI生成多少就显示多少，
       一条都没有时评论区显示"还没有评论，快来抢沙发"空状态，避免千篇一律的默认假评论 */

    /* 为有replyTo但缺replyToId的评论补全ID，构建回复链 */
    comments.forEach(function(cm) {
      if (cm.replyTo && !cm.replyToId) {
        var target = comments.find(function(tc) { return tc.authorName === cm.replyTo && tc.id !== cm.id; });
        if (target) cm.replyToId = target.id;
      }
    });

    sfState.commentsCache[postId] = comments;
    sfSaveCommentsCache();
    sfState.likesCache[postId] = likes;
    sfSaveLikesCache();
    if (!sfState.repostsCache) sfState.repostsCache = {};
    sfState.repostsCache[postId] = reposts;

    /* Add notifications for user's posts */
    if (post._user) {
      likes.forEach(function(l) {
        if (!l.isUser) sfAddNotification('like', { authorName: l.name, postContent: post.content.substring(0, 50) });
      });
      comments.forEach(function(c) {
        var isCharOrNpc = (contextData.characters.some(function(ch) { return ch.name === c.authorName; }) ||
                           contextData.npcs.some(function(np) { return np.name === c.authorName; }));
        if (isCharOrNpc) sfAddNotification('comment', { authorName: c.authorName, content: c.content, postId: postId });
      });
      reposts.forEach(function(r) {
        sfAddNotification('repost', { authorName: r.authorName, content: r.content });
      });
      /* 有角色/NPC评论、点赞或转发时，推送系统级通知 */
      var charLikes = likes.filter(function(l) { return !l.isUser; }).length;
      var charComments = comments.filter(function(c) {
        return contextData.characters.some(function(ch) { return ch.name === c.authorName; }) ||
               contextData.npcs.some(function(np) { return np.name === c.authorName; });
      }).length;
      if (charLikes > 0 || charComments > 0 || reposts.length > 0) {
        var sfSummaries = [];
        if (charLikes > 0) sfSummaries.push(charLikes + '个赞');
        if (charComments > 0) sfSummaries.push(charComments + '条评论');
        if (reposts.length > 0) sfSummaries.push(reposts.length + '次转发');
        sfSendSystemNotification('帖子有新互动', '你的帖子收到了' + sfSummaries.join('、'));
      }
    }
    sfSaveRepostsCache();

    /* Update post counts */
    var userLiked = post.liked;
    post.likes = likes.length + (userLiked ? 1 : 0) + Math.floor(Math.random() * 20) + 5;
    post.likedBy = likes;
    if (userLiked) {
      post.likedBy.unshift({ name: (config.user && config.user.name) || '我', isUser: true, type: 'user' });
    }
    post.reposts = (post.reposts || 0) + reposts.length;
    
    /* Persist to NPC post data if applicable */
    if (post.npcAuthored && post.npcId) {
      try {
        var npc = (config.npcs || []).find(function(n) { return String(n.id) === String(post.npcId); });
        if (npc && npc.phone && npc.phone.forum && npc.phone.forum.posts) {
          var origPost = npc.phone.forum.posts.find(function(p) { return p.id === postId; });
          if (origPost) {
            origPost.likes = post.likes;
            origPost.likedBy = likes;
            origPost.comments = comments.map(function(cm) {
              return { id: cm.id, authorName: cm.authorName, content: cm.content, time: cm.time, replyTo: cm.replyTo || null };
            });
            Store.set('config', config);
          }
        }
      } catch(e) {}
    }
    
    /* Save forum interactions as memories (interaction chain) */
    sfSaveForumMemory(rawReactions, post);
    
    /* Trigger proactive WeChat messages from characters who reposted */
    sfTriggerProactiveWechatMessage(rawReactions, post);
  } catch (e) {
    sfState.commentsCache[postId] = [];
    sfSaveCommentsCache();
    sfState.likesCache[postId] = [];
    sfSaveLikesCache();
    sfToast('互动生成失败：' + ((e && e.message) ? e.message : '可重新打开帖子重试') + '（未使用默认评论）');
  }
  if (sfState.currentPostId === postId) {
    sfRenderComments(postId);
    sfRenderLikesInDetail(postId);
    sfRenderRepostsInDetail(postId);
    /* Show regenerate button after generation completes */
    var curPost = sfFindPost(postId);
    if (curPost) sfShowRegenerateBtn(postId, curPost);
  }
  sfUpdateCommentCount(postId, (sfState.commentsCache[postId] || []).length);
  sfUpdateLikeCount(postId);
  /* Re-render timeline to show updated likes/comments */
  if (sfState.active && sfState.currentView === 'feed') {
    try { sfRenderTimeline(sfState.currentTab); } catch(e) {}
  }

  /* 评论生成后，触发角色间互回复（模拟讨论氛围） */
  if (!post._discussionTriggered) {
    post._discussionTriggered = true;
    setTimeout(function() {
      sfTriggerCommentDiscussion(postId);
    }, 1500 + Math.floor(Math.random() * 2000));
  }
};

/* ============================================================
 * 角色间互回复讨论：AI生成评论后，部分角色评论会被其他角色回复
 * 模拟真实论坛中多人讨论、楼中楼回复的氛围
 * ============================================================ */
var sfTriggerCommentDiscussion = async function (postId) {
  if (!postId) return;
  var post = sfFindPost(postId);
  if (!post) return;
  var comments = sfState.commentsCache[postId] || [];
  if (comments.length < 3) return; /* 评论太少不触发讨论 */

  var allRoles = sfGetAllRoles();
  if (allRoles.length < 2) return; /* 角色太少不触发 */

  /* 从AI生成的评论中，挑选2-3条角色/NPC的评论作为讨论种子 */
  var seedComments = comments.filter(function(cm) {
    return cm.authorName && !cm._typing &&
      allRoles.some(function(r) { return r.name === cm.authorName; });
  });
  if (seedComments.length === 0) return;

  /* 随机选2-3条种子评论 */
  var discussCount = Math.min(seedComments.length, Math.floor(Math.random() * 2) + 2);
  var selectedSeeds = [];
  var seedPool = seedComments.slice();
  for (var s = 0; s < discussCount && seedPool.length > 0; s++) {
    var pickIdx = Math.floor(Math.random() * seedPool.length);
    selectedSeeds.push(seedPool.splice(pickIdx, 1)[0]);
  }

  /* 为每条种子评论生成1-2条角色回复 */
  var totalRepliesGenerated = 0;
  for (var si = 0; si < selectedSeeds.length; si++) {
    var seedComment = selectedSeeds[si];
    /* 排除种子评论作者自己 */
    var availableRoles = allRoles.filter(function(r) { return r.name !== seedComment.authorName; });
    if (availableRoles.length === 0) continue;

    /* 随机选1-2个角色回复 */
    var replyCount = Math.min(availableRoles.length, Math.floor(Math.random() * 2) + 1);
    var repliers = [];
    var rolePool = availableRoles.slice();
    /* 优先选与种子评论作者有关系的角色 */
    for (var ri = 0; ri < replyCount && rolePool.length > 0; ri++) {
      var rPick = Math.floor(Math.random() * rolePool.length);
      repliers.push(rolePool.splice(rPick, 1)[0]);
    }

    /* 为每个回复角色插入占位评论 */
    var prevChainId = seedComment.id;
    var placeholders = [];
    for (var rj = 0; rj < repliers.length; rj++) {
      var role = repliers[rj];
      var phId = 'sc-disc-typing-' + Date.now() + '-' + si + '-' + rj;
      var roleAvatarIdx = allRoles.findIndex(function(r) { return r.name === role.name; });
      if (roleAvatarIdx < 0) roleAvatarIdx = rj;
      roleAvatarIdx = roleAvatarIdx % 10;
      var replyTargetName = rj === 0 ? seedComment.authorName : (repliers[rj - 1] ? repliers[rj - 1].name : seedComment.authorName);
      var replyTargetId = rj === 0 ? seedComment.id : prevChainId;

      placeholders.push({
        id: phId, role: role, roleAvatarIdx: roleAvatarIdx,
        replyTo: replyTargetName, replyToId: replyTargetId,
        seedComment: seedComment
      });

      comments.push({
        id: phId, authorName: role.name,
        content: '正在输入...', time: '',
        avatarIndex: roleAvatarIdx, _typing: true,
        replyTo: replyTargetName, replyToId: replyTargetId
      });
    }
    sfState.commentsCache[postId] = comments;
    sfSaveCommentsCache();
    if (sfState.currentPostId === postId) sfRenderComments(postId);

    /* 逐个生成回复 */
    for (var rk = 0; rk < placeholders.length; rk++) {
      var ph = placeholders[rk];
      var replyRole = ph.role;
      var replyTarget = ph.replyTo;
      try {
        var dPrompt = '你在论坛中看到了一条评论，想以角色身份参与讨论。\n\n';
        dPrompt += '你的身份：角色「' + replyRole.name + '」\n';
        dPrompt += '你的人设：' + (replyRole.persona || replyRole.prompt || '').substring(0, 1500) + '\n\n';
        dPrompt += '帖子内容：' + String(post.content || '').substring(0, 200) + '\n\n';
        dPrompt += '「' + seedComment.authorName + '」的评论：' + String(seedComment.content || '') + '\n';
        if (rk > 0 && placeholders[rk - 1] && placeholders[rk - 1].reply) {
          dPrompt += '「' + placeholders[rk - 1].role.name + '」已经回复了：' + placeholders[rk - 1].reply + '\n';
        }
        dPrompt += '\n请以「' + replyRole.name + '」的身份回复' + (rk === 0 ? '「' + seedComment.authorName + '」的评论' : '上一条回复') + '。\n';
        dPrompt += '要求：\n1. 回复简短自然，1-2句话\n2. 可以带emoji，语气口语化\n3. 可以表达赞同、反对、补充观点等\n4. 只输出回复内容，不要加角色名前缀\n';

        var dApiMessages = [
          { role: 'system', content: '你是一个角色扮演AI，在论坛中以角色身份参与讨论。回复简短自然（1-2句话），符合角色性格。' },
          { role: 'user', content: dPrompt }
        ];
        var dReplyText = await callApi(dApiMessages, { maxTokens: 200, temperature: 0.9 });
        dReplyText = String(dReplyText || '').trim();

        comments = sfState.commentsCache[postId] || [];
        var dPhIdx = comments.findIndex(function(c) { return c.id === ph.id; });
        if (dPhIdx >= 0) {
          if (dReplyText) {
            var dNewId = 'sc-disc-' + Date.now() + '-' + si + '-' + rk;
            comments[dPhIdx] = {
              id: dNewId,
              authorName: replyRole.name,
              content: dReplyText,
              time: '刚刚',
              avatarIndex: ph.roleAvatarIdx,
              replyTo: replyTarget,
              replyToId: ph.replyToId || ''
            };
            ph.reply = dReplyText; /* 供后续prompt引用 */
            prevChainId = dNewId;
            totalRepliesGenerated++;
          } else {
            comments.splice(dPhIdx, 1);
          }
        }
        sfState.commentsCache[postId] = comments;
        sfSaveCommentsCache();
        post.commentsList = comments;
        post.comments = comments.length;
        if (sfState.currentPostId === postId) {
          sfRenderComments(postId);
          sfUpdateCommentCount(postId, comments.length);
        }
        /* 随机延迟 */
        if (rk < placeholders.length - 1) {
          await new Promise(function(r) { setTimeout(r, 1000 + Math.floor(Math.random() * 1500)); });
        }
      } catch (e) {
        comments = sfState.commentsCache[postId] || [];
        var errIdx2 = comments.findIndex(function(c) { return c.id === ph.id; });
        if (errIdx2 >= 0) comments.splice(errIdx2, 1);
        sfState.commentsCache[postId] = comments;
        sfSaveCommentsCache();
        if (sfState.currentPostId === postId) sfRenderComments(postId);
        console.error('sfTriggerCommentDiscussion error:', e);
      }
    }
    /* 种子之间延迟 */
    if (si < selectedSeeds.length - 1) {
      await new Promise(function(r) { setTimeout(r, 800 + Math.floor(Math.random() * 1200)); });
    }
  }

  /* 最终刷新 */
  if (sfState.currentPostId === postId) {
    sfRenderComments(postId);
    sfUpdateCommentCount(postId, (sfState.commentsCache[postId] || []).length);
  }
  sfSaveCommentsCache();
};

/* Render reposts section in post detail */
var sfRenderRepostsInDetail = function (postId) {
  if (!sfState.repostsCache) return;
  var reposts = sfState.repostsCache[postId] || [];
  var repostSection = document.querySelector('#sfDetailBody .sf-detail-reposts');
  if (!repostSection) return;
  if (reposts.length === 0) {
    repostSection.innerHTML = '';
    repostSection.style.display = 'none';
    return;
  }
  repostSection.style.display = 'block';
  var html = reposts.map(function(rp) {
    return '<div class="sf-comment" style="background:#f0f0f0;border-radius:8px;margin-bottom:6px;padding:8px 10px">'
      + '<div class="sf-comment-body">'
      + '<div class="sf-comment-name">' + sfEscapeHtml(rp.authorName || '匿名') + ' <span style="color:#999;font-size:11px">转发了</span></div>'
      + '<div class="sf-comment-text">' + sfEscapeHtml(rp.content || '') + '</div>'
      + '<div class="sf-comment-time">' + sfEscapeHtml(rp.time || '刚刚') + '</div>'
      + '</div></div>';
  }).join('');
  repostSection.innerHTML = '<div style="padding:6px 0 2px;color:#999;font-size:12px;font-weight:600">转发</div>' + html;
};

/* ============================================================
 * Forward post to WeChat (repost card)
 * ============================================================ */
var sfRepostState = { postId: null, selectedChar: null, comment: '' };

var sfForwardToWechat = function (postId) {
  var post = sfFindPost(postId);
  if (!post) return;
  sfRepostState.postId = postId;
  sfRepostState.selectedChar = null;
  sfRepostState.comment = '';

  /* Build character list */
  var chars = (typeof config !== 'undefined' && config.characters) ? config.characters.filter(function(c) { return !c.deletedFromWechat; }) : [];
  var npcChats = (typeof config !== 'undefined' && config.npcChats) ? config.npcChats : [];

  if (chars.length === 0 && npcChats.length === 0) {
    sfToast('没有可转发的聊天对象');
    return;
  }

  var charListHtml = chars.map(function(c, i) {
    var avatarBg = c.avatarBg || '#576B95';
    var avatarHtml;
    if (c.avatar && c.avatar.startsWith('data:')) {
      avatarHtml = '<img src="' + c.avatar + '" style="width:100%;height:100%;object-fit:cover" alt="">';
    } else {
      avatarHtml = sfEscapeHtml(c.avatar || c.name.charAt(0));
    }
    return '<div class="sf-repost-char-item" data-char-idx="' + i + '" data-char-type="character" onclick="sfRepostSelectChar(this)">'
      + '<div class="sf-repost-char-avatar" style="background:' + avatarBg + '">' + avatarHtml + '</div>'
      + '<div class="sf-repost-char-info"><div class="sf-repost-char-name">' + sfEscapeHtml(c.alias || c.name) + '</div>'
      + '<div class="sf-repost-char-desc">' + sfEscapeHtml((c.persona || '').substring(0, 30)) + '</div></div></div>';
  }).join('');

  var npcListHtml = npcChats.map(function(nc, i) {
    var npcBg = nc.npcAvatarBg || '#FF9500';
    var npcAvatarHtml = (nc.npcAvatar && nc.npcAvatar.indexOf('data:') === 0) ? '<img src="' + nc.npcAvatar + '" style="width:100%;height:100%;object-fit:cover" alt="">' : sfEscapeHtml(nc.npcAvatar || nc.npcName.charAt(0));
    return '<div class="sf-repost-char-item" data-char-idx="' + i + '" data-char-type="npc" onclick="sfRepostSelectChar(this)">'
      + '<div class="sf-repost-char-avatar" style="background:' + npcBg + '">' + npcAvatarHtml + '</div>'
      + '<div class="sf-repost-char-info"><div class="sf-repost-char-name">' + sfEscapeHtml(nc.npcName) + ' <span style="font-size:10px;color:#FF9500">NPC</span></div>'
      + '<div class="sf-repost-char-desc">NPC对话</div></div></div>';
  }).join('');

  /* Remove existing overlay */
  var existing = document.getElementById('sfRepostOverlay');
  if (existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'sfRepostOverlay';
  overlay.className = 'sf-repost-overlay';
  overlay.innerHTML = '<div class="sf-repost-sheet">'
    + '<div class="sf-repost-sheet-header">'
    + '<div class="sf-repost-sheet-title">转发到微信</div>'
    + '<div class="sf-repost-sheet-close" onclick="sfCloseRepostSheet()">&times;</div>'
    + '</div>'
    + '<div class="sf-repost-sheet-body" id="sfRepostCharList">' + charListHtml + npcListHtml + '</div>'
    + '<div class="sf-repost-comment-area">'
    + '<textarea id="sfRepostComment" placeholder="说点什么...（可选）" oninput="sfRepostState.comment=this.value"></textarea>'
    + '</div>'
    + '<button class="sf-repost-send-btn" id="sfRepostSendBtn" disabled onclick="sfRepostSend()">发送</button>'
    + '</div>';
  phoneLayer().appendChild(overlay);

  /* Close on backdrop click */
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) sfCloseRepostSheet();
  });
};

var sfRepostSelectChar = function (el) {
  sfRepostState.selectedChar = {
    idx: parseInt(el.dataset.charIdx),
    type: el.dataset.charType
  };
  /* Update visual selection */
  var items = document.querySelectorAll('.sf-repost-char-item');
  items.forEach(function(item) {
    item.style.background = '';
    var check = item.querySelector('.sf-repost-check');
    if (check) check.remove();
  });
  el.style.background = 'rgba(7,193,96,0.1)';
  var check = document.createElement('div');
  check.className = 'sf-repost-check';
  check.style.cssText = 'color:#07C160;font-size:20px;margin-left:auto';
  check.innerHTML = '&#10003;';
  el.appendChild(check);
  /* Enable send button */
  var sendBtn = document.getElementById('sfRepostSendBtn');
  if (sendBtn) sendBtn.disabled = false;
};

var sfCloseRepostSheet = function () {
  var overlay = document.getElementById('sfRepostOverlay');
  if (overlay) overlay.remove();
};

var sfRepostSend = function () {
  if (!sfRepostState.selectedChar || !sfRepostState.postId) return;
  var post = sfFindPost(sfRepostState.postId);
  if (!post) { sfCloseRepostSheet(); return; }

  var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '我';
  var repostData = {
    postId: post.id || '',
    author: post.authorName || '匿名',
    content: String(post.content || '').substring(0, 100),
    comment: sfRepostState.comment || ''
  };
  var msgContent = '[repost]' + JSON.stringify(repostData);

  if (sfRepostState.selectedChar.type === 'character') {
    var char = config.characters[sfRepostState.selectedChar.idx];
    if (!char || char.deletedFromWechat) { sfCloseRepostSheet(); return; }
    char.chatHistory = char.chatHistory || [];
    char.chatHistory.push({
      role: 'user',
      content: msgContent,
      time: Date.now(),
      type: 'repost'
    });
    Store.set('config', config);
    /* Close forum detail and repost sheet */
    sfCloseRepostSheet();
    var detailOverlay = sfEl('sfDetailOverlay');
    if (detailOverlay) detailOverlay.classList.remove('active');
    /* Open the chat */
    openChat(sfRepostState.selectedChar.idx);
    sfToast('已转发给' + (char.alias || char.nickname || char.name));
  } else if (sfRepostState.selectedChar.type === 'npc') {
    var npcChat = config.npcChats[sfRepostState.selectedChar.idx];
    if (!npcChat) { sfCloseRepostSheet(); return; }
    npcChat.messages = npcChat.messages || [];
    npcChat.messages.push({
      role: 'user',
      content: msgContent,
      time: Date.now(),
      type: 'repost'
    });
    Store.set('config', config);
    sfCloseRepostSheet();
    var detailOverlay2 = sfEl('sfDetailOverlay');
    if (detailOverlay2) detailOverlay2.classList.remove('active');
    openNpcChat(sfRepostState.selectedChar.idx);
    sfToast('已转发给' + npcChat.npcName);
  }
};

/* Open original post detail from repost card */
var sfOpenRepostDetail = function (postId) {
  if (!postId) return;
  var post = sfFindPost(postId);
  if (!post) {
    sfToast('原帖已不存在');
    return;
  }
  /* Navigate to forum and open post detail */
  if (typeof openSocialForum === 'function') {
    openSocialForum();
  } else if (typeof openApp === 'function') {
    openApp('social');
  }
  setTimeout(function() {
    sfOpenPostDetail(postId);
  }, 300);
};

/* Fallback reactions generator when API fails */
var sfFallbackReactions = function (contextData, authorName) {
  /* 已禁用写死模板互动（角色点赞/模板评论/随机路人评论），避免假数据；保留空函数兼容旧调用 */
  return { comments: [], likes: [] };
};

/* Render likes section in post detail */
var sfRenderLikesInDetail = function (postId) {
  var post = sfFindPost(postId);
  if (!post) return;
  var likes = sfState.likesCache[postId] || post.likedBy || [];
  /* Add user like if user liked */
  if (post.liked) {
    var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '我';
    if (!likes.some(function(l) { return l.isUser; })) {
      likes = [{ name: userName, isUser: true, type: 'user' }].concat(likes);
    }
  }
  var likeSection = document.querySelector('#sfDetailBody .sf-detail-likes');
  if (!likeSection) return;
  if (likes.length === 0) {
    likeSection.innerHTML = '';
    likeSection.style.display = 'none';
    return;
  }
  likeSection.style.display = 'block';
  var names = likes.map(function(l) { return sfEscapeHtml(l.name); });
  likeSection.innerHTML = '<span style="color:#F5A0B8">&#10084;</span> ' + names.join('、');
};

/* Update like count display */
var sfUpdateLikeCount = function (postId) {
  var post = sfFindPost(postId);
  if (!post) return;
  var likeAction = document.querySelector('#sfDetailBody [data-action="like"]');
  if (likeAction) {
    likeAction.innerHTML = '&#10084;&#65039; ' + (post.likes || 0);
  }
  /* Also update in timeline */
  var timelineAction = document.querySelector('.sf-post[data-post-id="' + postId + '"] [data-action="like"]');
  if (timelineAction) {
    timelineAction.innerHTML = '&#10084;&#65039; ' + (post.likes || 0);
  }
};

var sfRenderComments = function (postId) {
  var c = sfEl('sfDetailComments');
  if (!c) return;
  var comments = sfState.commentsCache[postId] || [];
  var html = '';
  if (comments.length === 0) {
    html = '<div style="text-align:center;padding:24px;color:#999;font-size:13px">还没有评论，快来抢沙发~</div>';
  } else {
    /* 计算每条评论的嵌套层级（基于replyToId链追踪） */
    var nestLevelMap = {};
    comments.forEach(function(cm) {
      var level = 0;
      var curId = cm.replyToId;
      var guard = 0;
      while (curId && guard < 10) {
        var parent = comments.find(function(p) { return p.id === curId; });
        if (!parent) break;
        level++;
        curId = parent.replyToId;
        guard++;
      }
      nestLevelMap[cm.id] = Math.min(level, 3);
    });

    html = comments.map(function (cm, idx) {
      var floorNum = idx + 1;
      var floorLabel = floorNum === 1 ? '沙发' : (floorNum === 2 ? '板凳' : (floorNum === 3 ? '地板' : floorNum + 'F'));
      var nestLevel = nestLevelMap[cm.id] || 0;
      var nestClass = nestLevel > 0 ? ' nested-' + nestLevel : '';
      /* Build reply-to display: 回复者名称可点击跳转 */
      var replyToHtml = '';
      if (cm.replyTo) {
        replyToHtml = '<div class="sf-comment-reply-to"><span class="reply-arrow">↳</span>回复 <span class="reply-target-name" data-scroll-to="' + sfEscapeHtml(cm.replyToId || '') + '">' + sfEscapeHtml(cm.replyTo) + '</span></div>';
      }
      /* 讨论链标记：嵌套层级>=2时显示 */
      var chainBadge = nestLevel >= 2 ? '<span class="sf-comment-chain-badge">&#128172; 讨论</span>' : '';
      var typingAttr = cm._typing ? ' data-typing="1"' : '';
      var timeHtml = cm._typing ? '' : '<div class="sf-comment-time">' + sfEscapeHtml(cm.time || '刚刚') + '</div>';
      var actionsHtml = cm._typing ? '' : '<div class="sf-comment-actions"><span class="sf-comment-reply-btn" data-reply-to="' + sfEscapeHtml(cm.authorName || '匿名') + '" data-reply-id="' + sfEscapeHtml(cm.id || '') + '">回复</span></div>';
      return '<div class="sf-comment has-floor' + nestClass + '" data-comment-id="' + sfEscapeHtml(cm.id || '') + '"' + typingAttr + '>'
        + '<div class="sf-comment-floor">' + floorLabel + '</div>'
        + '<div class="sf-comment-avatar" style="background:' + sfAvatarGradient(cm.avatarIndex || 0) + '">'
        + sfEscapeHtml(sfInitial(cm.authorName)) + '</div>'
        + '<div class="sf-comment-body">'
        + '<div class="sf-comment-name">' + chainBadge + sfEscapeHtml(cm.authorName || '匿名') + '</div>'
        + replyToHtml
        + '<div class="sf-comment-text">' + sfEscapeHtml(cm.content || '') + '</div>'
        + timeHtml
        + actionsHtml
        + '</div></div>';
    }).join('');
  }
  c.innerHTML = html;
  /* Attach reply button click handlers */
  c.querySelectorAll('.sf-comment-reply-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      sfSetReplyTo(btn.getAttribute('data-reply-to'), btn.getAttribute('data-reply-id'));
    });
  });
  /* 点击回复目标名称，滚动到对应评论 */
  c.querySelectorAll('.reply-target-name').forEach(function(el) {
    el.addEventListener('click', function() {
      var targetId = el.getAttribute('data-scroll-to');
      if (!targetId) return;
      var target = c.querySelector('.sf-comment[data-comment-id="' + targetId + '"]');
      if (target) {
        var _cPage = target.closest('.df-page') || target.closest('.sf-comment-list') || target.parentElement;
        if (_cPage) { _cPage.scrollTop = target.offsetTop - _cPage.clientHeight / 2 + target.offsetHeight / 2; }
        target.style.transition = 'background 0.3s';
        target.style.background = 'rgba(245,160,184,0.12)';
        setTimeout(function() { target.style.background = ''; }, 1500);
      }
    });
  });
};

var sfSetReplyTo = function (name, commentId) {
  sfState.replyTo = { name: name, id: commentId };
  var indicator = sfEl('sfReplyIndicator');
  var targetName = sfEl('sfReplyTargetName');
  var input = sfEl('sfCommentInput');
  if (indicator) indicator.classList.add('active');
  if (targetName) targetName.textContent = name;
  if (input) {
    input.placeholder = '回复 ' + name + '...';
    input.focus();
  }
};

var sfClearReplyTo = function () {
  sfState.replyTo = null;
  var indicator = sfEl('sfReplyIndicator');
  var input = sfEl('sfCommentInput');
  if (indicator) indicator.classList.remove('active');
  if (input) input.placeholder = '写条评论...';
};

var sfUpdateCommentCount = function (postId, n) {
  var detailAction = document.querySelector('#sfDetailBody [data-action="comment"]');
  if (detailAction) detailAction.innerHTML = '&#128172; ' + n;
};

var sfSendComment = function () {
  var input = sfEl('sfCommentInput');
  if (!input || !input.value.trim() || !sfState.currentPostId) return;
  var text = input.value.trim();
  input.value = '';
  var comments = sfState.commentsCache[sfState.currentPostId] || [];
  var commenterName = (typeof config !== 'undefined' && config.user && config.user.name) || '我';
  var newComment = {
    id: 'sc-' + Date.now(),
    authorName: commenterName,
    content: text,
    time: '刚刚',
    avatarIndex: 0
  };
  /* Support reply-to: 同时记录replyTo名称和replyToId用于嵌套追踪 */
  if (sfState.replyTo && sfState.replyTo.name) {
    newComment.replyTo = sfState.replyTo.name;
    newComment.replyToId = sfState.replyTo.id || '';
  }
  comments.push(newComment);
  sfState.commentsCache[sfState.currentPostId] = comments;
  sfSaveCommentsCache();
  /* Clear reply state */
  sfClearReplyTo();
  var post = sfFindPost(sfState.currentPostId);
  if (post) {
    post.commentsList = comments;
    post.comments = comments.length;
    /* Persist user comment back to NPC post data */
    if (post.npcAuthored && post.npcId) {
      try {
        var npc = (config.npcs || []).find(function(n) { return String(n.id) === String(post.npcId); });
        if (npc && npc.phone && npc.phone.forum && npc.phone.forum.posts) {
          var origPost = npc.phone.forum.posts.find(function(p) { return p.id === sfState.currentPostId; });
          if (origPost) {
            origPost.comments = origPost.comments || [];
            origPost.comments.push({ id: newComment.id, authorName: commenterName, content: text, time: Date.now(), replyTo: newComment.replyTo || null, replyToId: newComment.replyToId || null });
            Store.set('config', config);
          }
        }
      } catch(e) {}
    }
  }
  sfRenderComments(sfState.currentPostId);
  sfUpdateCommentCount(sfState.currentPostId, comments.length);
  sfToast('评论已发送');

  /* 检测@提及的角色名，触发被@角色自动回复 */
  var mentionedNames = [];
  try {
    var mentionRegex = /@([^\s@]+)/g;
    var match;
    while ((match = mentionRegex.exec(text)) !== null) {
      mentionedNames.push(match[1]);
    }
    if (mentionedNames.length > 0) {
      /* 匹配真实角色/NPC名称 */
      var allRoles = sfGetAllRoles();
      var matchedNames = [];
      mentionedNames.forEach(function (mName) {
        var found = allRoles.find(function (r) {
          return r.name === mName || r.name.indexOf(mName) >= 0 || mName.indexOf(r.name) >= 0;
        });
        if (found && matchedNames.indexOf(found.name) === -1) {
          matchedNames.push(found.name);
        }
      });
      if (matchedNames.length > 0) {
        sfTriggerMentionedReply(sfState.currentPostId, newComment, matchedNames);
      }
    }
  } catch (e) {
    console.error('sfSendComment mention detection error:', e);
  }

  /* 收到回复：无论是否@提及，都触发多人讨论回复 */
  /* @提及时：先让被@角色回复，延迟后再触发其他角色加入讨论 */
  try {
    if (mentionedNames.length > 0) {
      /* 被@角色回复后，延迟触发更多角色加入讨论 */
      setTimeout(function() {
        try { sfTriggerAuthorReply(sfState.currentPostId, newComment); } catch(e) { console.error('delayed author reply error:', e); }
      }, 3000 + mentionedNames.length * 1500);
    } else {
      sfTriggerAuthorReply(sfState.currentPostId, newComment);
    }
  } catch (e) {
    console.error('sfSendComment author reply error:', e);
  }
};

/* ---- @提及自动回复：被@的角色以自身身份生成简短回复 ---- */
var sfTriggerMentionedReply = async function (postId, comment, mentionedNames) {
  if (!postId || !mentionedNames || mentionedNames.length === 0) return;
  var post = sfFindPost(postId);
  if (!post) return;

  var allRoles = sfGetAllRoles();
  var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';

  /* 逐个被@的角色生成回复 */
  for (var i = 0; i < mentionedNames.length; i++) {
    var roleName = mentionedNames[i];
    var role = allRoles.find(function (r) { return r.name === roleName; });
    if (!role) continue;

    try {
      /* 构建AI回复prompt：角色以被@的身份回复，简短自然 */
      var prompt = '你在论坛「论坛」中被' + userName + '@提到了。\n\n';
      prompt += '你的身份：角色「' + role.name + '」\n';
      prompt += '你的人设：' + (role.persona || role.prompt || '').substring(0, 2000) + '\n\n';
      prompt += '帖子内容：' + String(post.content || '').substring(0, 200) + '\n\n';
      prompt += '用户「' + userName + '」的评论：' + String(comment.content || '') + '\n\n';
      prompt += '请以「' + role.name + '」的身份回复这条评论。\n';
      prompt += '要求：\n';
      prompt += '1. 你是被@提到的角色，请以自身身份回复\n';
      prompt += '2. 回复要简短自然，一般1-2句话，像真实社交平台评论\n';
      prompt += '3. 保持角色性格和说话习惯\n';
      prompt += '4. 可以带emoji，语气口语化\n';
      prompt += '5. 只输出回复内容，不要加角色名前缀\n';

      var apiMessages = [
        { role: 'system', content: '你是一个角色扮演AI，在论坛中以被@提到的角色身份回复评论。回复简短自然（1-2句话），符合角色性格。' },
        { role: 'user', content: prompt }
      ];
      var reply = await callApi(apiMessages, { maxTokens: 200, temperature: 0.9 });

      var replyText = String(reply || '').trim();
      if (!replyText) continue;

      /* 将回复添加到评论列表 */
      var comments = sfState.commentsCache[postId] || [];
      var replyComment = {
        id: 'c-mention-' + Date.now() + '-' + i,
        authorName: role.name,
        content: replyText,
        time: '刚刚',
        avatarIndex: i % 10,
        replyTo: comment.authorName,
        replyToId: comment.id || ''
      };
      comments.push(replyComment);
      sfState.commentsCache[postId] = comments;
      sfSaveCommentsCache();

      /* 更新帖子数据 */
      post.commentsList = comments;
      post.comments = comments.length;

      /* 如果当前正在查看该帖子详情，刷新评论显示 */
      if (sfState.currentPostId === postId) {
        sfRenderComments(postId);
        sfUpdateCommentCount(postId, comments.length);
      }
    } catch (e) {
      console.error('sfTriggerMentionedReply error for ' + roleName + ':', e);
    }
  }
};

/* ---- 收到回复：用户评论后，多个角色/NPC 自动回复（类似讨论氛围） ---- */
var sfTriggerAuthorReply = async function (postId, userComment) {
  if (!postId || !userComment) return;
  var post = sfFindPost(postId);
  if (!post) return;

  var allRoles = sfGetAllRoles();
  var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';
  if (allRoles.length === 0) return;

  /* ---- 收集候选回复角色，去重 ---- */
  var candidateRoles = [];

  /* 1. 被 replyTo 指定的角色优先 */
  if (userComment.replyTo) {
    var repliedRole = allRoles.find(function (r) {
      return r.name === userComment.replyTo ||
        r.name.indexOf(userComment.replyTo) >= 0 ||
        userComment.replyTo.indexOf(r.name) >= 0;
    });
    if (repliedRole) candidateRoles.push(repliedRole);
  }

  /* 2. 帖子作者（角色/NPC） */
  if (post.npcAuthored && post.npcId) {
    var authorNpc = allRoles.find(function (r) { return String(r.id) === 'npc-' + String(post.npcId); });
    if (authorNpc && candidateRoles.indexOf(authorNpc) === -1) candidateRoles.push(authorNpc);
  }
  if (post.authorName) {
    var authorRole = allRoles.find(function (r) {
      return r.name === post.authorName ||
        r.name.indexOf(post.authorName) >= 0 ||
        post.authorName.indexOf(r.name) >= 0;
    });
    if (authorRole && candidateRoles.indexOf(authorRole) === -1) candidateRoles.push(authorRole);
  }

  /* 3. 已有评论中的角色 */
  var existingComments = sfState.commentsCache[postId] || [];
  existingComments.forEach(function (ec) {
    if (ec.authorName === userName) return;
    var found = allRoles.find(function (r) { return r.name === ec.authorName; });
    if (found && candidateRoles.indexOf(found) === -1) candidateRoles.push(found);
  });

  /* 4. 从剩余角色中随机补充到 3-4 个 */
  var targetCount = Math.min(allRoles.length, Math.max(3, Math.floor(Math.random() * 2) + 3));
  var remainingRoles = allRoles.filter(function (r) { return candidateRoles.indexOf(r) === -1; });
  /* 打乱 */
  for (var i = remainingRoles.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = remainingRoles[i]; remainingRoles[i] = remainingRoles[j]; remainingRoles[j] = tmp;
  }
  while (candidateRoles.length < targetCount && remainingRoles.length > 0) {
    candidateRoles.push(remainingRoles.shift());
  }
  /* 至少1个，最多4个 */
  if (candidateRoles.length === 0) return;
  candidateRoles = candidateRoles.slice(0, 4);

  /* ---- 为每个角色插入"正在输入..."占位评论 ---- */
  var comments = sfState.commentsCache[postId] || [];
  var placeholders = [];
  /* 记录上一条回复的ID，用于构建回复链 */
  var prevReplyId = userComment.id || '';
  candidateRoles.forEach(function (role, idx) {
    var phId = 'sc-typing-' + Date.now() + '-' + idx;
    var roleAvatarIdx = allRoles.findIndex(function(r) { return r.name === role.name; });
    if (roleAvatarIdx < 0) roleAvatarIdx = idx;
    roleAvatarIdx = roleAvatarIdx % 10;
    /* 第一条回复对准用户，后续对准前一条回复的角色 */
    var replyTargetName = idx === 0 ? userName : (candidateRoles[idx - 1] ? candidateRoles[idx - 1].name : userName);
    var replyTargetId = idx === 0 ? (userComment.id || '') : prevReplyId;
    placeholders.push({
      id: phId,
      role: role,
      roleAvatarIdx: roleAvatarIdx,
      replyTo: replyTargetName,
      replyToId: replyTargetId
    });
    comments.push({
      id: phId,
      authorName: role.name,
      content: '正在输入...',
      time: '',
      avatarIndex: roleAvatarIdx,
      _typing: true,
      replyTo: replyTargetName,
      replyToId: replyTargetId
    });
  });
  sfState.commentsCache[postId] = comments;
  sfSaveCommentsCache();
  if (sfState.currentPostId === postId) sfRenderComments(postId);

  /* ---- 逐个生成回复，每完成一个就替换占位 ---- */
  for (var k = 0; k < placeholders.length; k++) {
    var ph = placeholders[k];
    var role = ph.role;
    var replyTargetName = ph.replyTo;

    try {
      var prompt = '你在论坛中看到了一条评论，请以角色身份回复。\n\n';
      prompt += '你的身份：角色「' + role.name + '」\n';
      prompt += '你的人设：' + (role.persona || role.prompt || '').substring(0, 2000) + '\n\n';
      prompt += '帖子内容：' + String(post.content || '').substring(0, 300) + '\n\n';
      prompt += '用户「' + userName + '」的评论：' + String(userComment.content || '') + '\n\n';
      if (k > 0 && candidateRoles[k - 1]) {
        prompt += '「' + candidateRoles[k - 1].name + '」已经回复了，TA的回复你可以参考：\n';
      }
      prompt += '请以「' + role.name + '」的身份回复，保持角色性格和说话习惯。\n';
      prompt += '要求：\n1. 回复简短自然，1-2句话\n2. 可以带emoji，语气口语化\n3. 只输出回复内容，不要加角色名前缀\n';

      var apiMessages = [
        { role: 'system', content: '你是一个角色扮演AI，在论坛中以角色身份回复评论。回复简短自然（1-2句话），符合角色性格。' },
        { role: 'user', content: prompt }
      ];
      var replyText = await callApi(apiMessages, { maxTokens: 200, temperature: 0.9 });
      replyText = String(replyText || '').trim();

      /* 移除该角色的占位评论 */
      comments = sfState.commentsCache[postId] || [];
      var phIdx = comments.findIndex(function(c) { return c.id === ph.id; });
      if (phIdx >= 0) {
        if (replyText) {
          /* 替换为真实回复 */
          var newReplyId = 'sc-reply-' + Date.now() + '-' + k;
          comments[phIdx] = {
            id: newReplyId,
            authorName: role.name,
            content: replyText,
            time: '刚刚',
            avatarIndex: ph.roleAvatarIdx,
            replyTo: replyTargetName,
            replyToId: ph.replyToId || ''
          };
          /* 更新链ID：后续回复对准这条 */
          prevReplyId = newReplyId;

          /* 持久化到NPC帖子数据 */
          if (post.npcAuthored && post.npcId) {
            try {
              var npc = (config.npcs || []).find(function(n) { return String(n.id) === String(post.npcId); });
              if (npc && npc.phone && npc.phone.forum && npc.phone.forum.posts) {
                var origPost = npc.phone.forum.posts.find(function(p) { return p.id === postId; });
                if (origPost) {
                  origPost.comments = origPost.comments || [];
                  origPost.comments.push({ id: newReplyId, authorName: role.name, content: replyText, time: Date.now(), replyTo: replyTargetName, replyToId: ph.replyToId || null });
                  Store.set('config', config);
                }
              }
            } catch(e) {}
          }

          /* 第一条回复添加通知 */
          if (k === 0) {
            sfAddNotification('reply', {
              authorName: role.name,
              content: replyText,
              postId: postId,
              postContent: (post.content || '').substring(0, 50),
              userComment: (userComment.content || '').substring(0, 50)
            });
            sfSendSystemNotification('收到回复', role.name + ' 等' + candidateRoles.length + '人回复了你的评论');
            sfUpdateNotifBadge();
          }
        } else {
          /* AI 返回空，直接删除占位 */
          comments.splice(phIdx, 1);
        }
      }

      sfState.commentsCache[postId] = comments;
      sfSaveCommentsCache();
      post.commentsList = comments;
      post.comments = comments.length;

      /* 实时刷新评论区 */
      if (sfState.currentPostId === postId) {
        sfRenderComments(postId);
        sfUpdateCommentCount(postId, comments.length);
      }

      /* 随机延迟，模拟真实打字 */
      if (k < placeholders.length - 1) {
        await new Promise(function(r) { setTimeout(r, 800 + Math.floor(Math.random() * 1200)); });
      }
    } catch (e) {
      /* 出错时移除该占位评论 */
      comments = sfState.commentsCache[postId] || [];
      var errIdx = comments.findIndex(function(c) { return c.id === ph.id; });
      if (errIdx >= 0) comments.splice(errIdx, 1);
      sfState.commentsCache[postId] = comments;
      sfSaveCommentsCache();
      if (sfState.currentPostId === postId) sfRenderComments(postId);
      console.error('sfTriggerAuthorReply error for ' + (role.name || '?') + ':', e);
    }
  }

  /* 最终刷新 */
  if (sfState.currentPostId === postId) {
    sfRenderComments(postId);
    sfUpdateCommentCount(postId, (sfState.commentsCache[postId] || []).length);
  }
  sfToast('收到' + candidateRoles.length + '条回复');

  /* 生成陌生网友回复 */
  sfTriggerStrangerReply(postId, post, userComment, userName);
};

/* ---- 陌生网友自动回复：用户评论后，生成2-3条陌生网友回复 ---- */
var sfTriggerStrangerReply = async function (postId, post, userComment, userName) {
  if (!postId || !post || !userComment) return;
  try {
    /* 随机决定生成2-3条陌生网友回复 */
    var strangerCount = 2 + Math.floor(Math.random() * 2);
    var prompt = '你在论坛评论区看到一条' + userName + '的评论，请模拟' + strangerCount + '个不同的陌生网友回复TA。\n\n';
    prompt += '帖子内容：' + String(post.content || '').substring(0, 200) + '\n\n';
    prompt += '用户「' + userName + '」的评论：' + String(userComment.content || '') + '\n\n';
    prompt += '要求：\n';
    prompt += '1. 每条回复使用不同的网名，要有网感（如"路过的猫"、"打工魂"、"甜筒不加糖"等）\n';
    prompt += '2. 回复风格多样：有赞同的、有调侃的、有分享经历的、有玩梗的\n';
    prompt += '3. 1-2句话，口语化，可以带emoji\n';
    prompt += '4. 部分回复可以回复前面的回复者，形成讨论氛围\n';
    prompt += '返回JSON格式：{"replies":[{"authorName":"","content":"","time":"刚刚"}]}\n';
    prompt += '只返回JSON，不要解释。';

    var apiMessages = [
      { role: 'system', content: '你是一个社交论坛评论模拟器，生成陌生网友的真实风格评论。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 900, temperature: 0.9 });
    var cleaned = String(reply || '').replace(/^```json\s*/i, '').replace(/```$/g, '').replace(/^```\s*/, '').trim();
    var jsonMatch = cleaned.match(/\{[\s\S]*\}/);
    var parsed = null;
    try { parsed = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned); } catch(e) {}

    if (!parsed || !parsed.replies || !Array.isArray(parsed.replies)) return;

    var comments = sfState.commentsCache[postId] || [];
    parsed.replies.forEach(function(rp, i) {
      if (!rp.content) return;
      var replyTarget = (i === 0) ? userName : (parsed.replies[i - 1] ? parsed.replies[i - 1].authorName : userName);
      comments.push({
        id: 'c-stranger-' + Date.now() + '-' + i,
        authorName: String(rp.authorName || SF_COMMENT_AUTHORS[Math.floor(Math.random() * SF_COMMENT_AUTHORS.length)]).slice(0, 24),
        content: String(rp.content || ''),
        time: String(rp.time || '刚刚').slice(0, 20),
        avatarIndex: (i + 5) % 10,
        replyTo: replyTarget
      });
    });

    sfState.commentsCache[postId] = comments;
    sfSaveCommentsCache();
    post.commentsList = comments;
    post.comments = comments.length;
    if (sfState.currentPostId === postId) {
      sfRenderComments(postId);
      sfUpdateCommentCount(postId, comments.length);
    }
  } catch(e) {
    console.error('sfTriggerStrangerReply error:', e);
  }
};

/* ---- 通知badge更新 ---- */
var sfUpdateNotifBadge = function () {
  var badge = document.querySelector('.sf-notif-tab-badge');
  if (!badge) return;
  var unread = (sfState.notifList || []).filter(function(n) { return !n.read; }).length;
  if (unread > 0) {
    badge.textContent = unread > 99 ? '99+' : String(unread);
    badge.style.display = 'flex';
  } else {
    badge.style.display = 'none';
  }
};

/* ============================================================
 * PART 17 - Post Creation Modal
 * ============================================================ */

var sfOpenPostModal = function () {
  var m = sfEl('sfPostModal');
  if (m) m.classList.add('active');
  var input = sfEl('sfPostInput');
  if (input) setTimeout(function () { input.focus(); }, 100);
};

var sfClosePostModal = function () {
  var m = sfEl('sfPostModal');
  if (m) m.classList.remove('active');
  var input = sfEl('sfPostInput');
  if (input) input.value = '';
  sfState.tempPostImage = null;
  var preview = sfEl('sfPostImgPreview');
  if (preview) { preview.style.display = 'none'; preview.innerHTML = ''; }
  /* 重置匿名开关 */
  var anonToggle = sfEl('sfAnonymousToggle');
  if (anonToggle) anonToggle.checked = false;
  sfState.isAnonymousPost = false;
};

var sfPublishPost = function () {
  var input = sfEl('sfPostInput');
  if (!input || !input.value.trim()) { sfToast('请输入内容'); return; }
  var text = input.value.trim();
  var userNickname = (typeof config !== 'undefined' && config.user && config.user.name) || '我';

  /* 检查匿名开关状态 */
  var anonToggle = sfEl('sfAnonymousToggle');
  var isAnonymous = anonToggle ? anonToggle.checked : false;

  /* Use user's profile avatar if set */
  var userAvatar = null;
  try {
    var saved = sfStorage.get('sf_user_profile');
    if (saved) {
      var parsed = JSON.parse(saved);
      if (parsed.avatar) userAvatar = parsed.avatar;
    }
  } catch (e) {}
  if (!userAvatar && sfState.userProfile.avatar) userAvatar = sfState.userProfile.avatar;
  if (!userAvatar && typeof config !== 'undefined' && config.user && config.user.avatar) {
    userAvatar = config.user.avatar;
  }

  var post = {
    id: 'sf-user-' + Date.now(),
    authorName: userNickname,
    handle: sfHandle(userNickname),
    verified: false,
    content: text,
    time: '刚刚',
    likes: 0,
    reposts: 0,
    comments: 0,
    views: 0,
    avatarIndex: 0,
    roleAvatar: userAvatar,
    imageGradient: null,
    imageUrl: sfState.tempPostImage || null,
    commentsList: [],
    tab: sfState.currentTab,
    _user: true
  };

  /* 匿名发帖：隐藏真实身份 */
  if (isAnonymous) {
    post.authorName = '匿名用户';
    post.handle = 'anonymous';
    post._anonymous = true;
    post._user = true;
    post.roleAvatar = null;
    post.verified = false;
  }

  sfState.userPosts.unshift(post);
  sfState.userProfile.posts = sfState.userPosts.length;
  sfSaveUserPosts();
  sfClosePostModal();
  sfRenderTimeline(sfState.currentTab);
  sfToast(isAnonymous ? '匿名发布成功' : '发布成功');
  /* 发帖成功后推送系统级通知 */
  sfSendSystemNotification('发布成功', isAnonymous ? '你的匿名帖子已发布到论坛' : '你的帖子已发布到论坛');
  
  /* Auto-generate character/NPC reactions after a short delay */
  setTimeout(function() {
    try {
      var freshPost = sfState.userPosts.find(function(p) { return p.id === post.id; });
      if (freshPost && !sfState.reactionsGenerated[post.id]) {
        sfGenerateComments(post.id, freshPost);
      }
    } catch(e) { console.error('Auto-reaction generation failed:', e); }
  }, 3000);
};

/* ============================================================
 * PART 18 - Side Menu
 * ============================================================ */

var sfOpenSideMenu = function () {
  sfState.sideMenuOpen = true;
  var menu = sfEl('sfSideMenu');
  var ov = sfEl('sfSideOverlay');
  if (menu) menu.classList.add('open');
  if (ov) ov.classList.add('active');
};

var sfCloseSideMenu = function () {
  sfState.sideMenuOpen = false;
  var menu = sfEl('sfSideMenu');
  var ov = sfEl('sfSideOverlay');
  if (menu) menu.classList.remove('open');
  if (ov) ov.classList.remove('active');
};

var sfRenderSideMenu = function () {
  sfLoadProfileMeta();
  var name = sfState.userProfile.displayName ||
    (typeof config !== 'undefined' && config.user && config.user.name) ||
    '体验用户';
  var avatarSrc = sfState.userProfile.avatar ||
    (typeof config !== 'undefined' && config.user && config.user.avatar) ||
    null;
  var header = sfEl('sfMenuHeader');
  if (header) {
    var avatarHtml;
    if (avatarSrc) {
      avatarHtml = '<img src="' + sfEscapeHtml(avatarSrc) + '" style="width:52px;height:52px;border-radius:50%;object-fit:cover" alt="" />';
    } else {
      avatarHtml = sfEscapeHtml(sfInitial(name));
    }
    header.innerHTML = '<div style="display:flex;align-items:center;gap:12px">'
      + '<div style="width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,.25);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:700;color:#fff;overflow:hidden">'
      + avatarHtml + '</div>'
      + '<div><div style="font-size:18px;font-weight:700;color:#fff">' + sfEscapeHtml(name) + '</div>'
      + '<div style="font-size:12px;opacity:.85;color:#fff">@' + sfEscapeHtml(name) + '</div></div></div>';
  }
  var list = sfEl('sfMenuList');
  if (list) {
    var items = [
      { key: 'profile', icon: '&#128100;', label: '个人主页' },
      { key: 'bookmarks', icon: '&#128278;', label: '我的书签' },
      { key: 'drafts', icon: '&#128221;', label: '草稿箱' },
      { key: 'forumRoles', icon: '&#127903;', label: '参与角色' },
      { key: 'worldview', icon: '&#127759;', label: '世界观' },
      { key: 'settings', icon: '&#128221;', label: '论坛规则' },
      { key: 'about', icon: '&#8505;&#65039;', label: '关于论坛' },
      { key: 'close', icon: '&#10005;', label: '退出论坛' }
    ];
    list.innerHTML = items.map(function (it) {
      return '<div class="sf-menu-item" data-menu="' + it.key + '"><span>' + it.icon
        + '</span><span>' + it.label + '</span></div>';
    }).join('');
  }
};

/* ============================================================
 * PART 19 - Search + Trends
 * ============================================================ */

var sfBuildTrends = function () {
  var counts = {};
  var add = function (tag) { tag = String(tag).trim(); if (tag) counts[tag] = (counts[tag] || 0) + 1; };
  for (var tab in sfState.posts) {
    sfState.posts[tab].forEach(function (p) {
      var matches = String(p.content || '').match(/#([^#\s]{1,12})#?/g);
      if (matches) matches.forEach(function (m) { add(m.replace(/#/g, '')); });
    });
  }
  var defaults = ['今日份小确幸', '深夜emo时间', '角色养成计划', '平行世界的我', '天气日记', '读书笔记', '一个人也要好好吃饭'];
  defaults.forEach(function (d) {
    counts[d] = (counts[d] || 0) + Math.floor(Math.random() * 6000) + 800;
  });
  var arr = Object.keys(counts).map(function (k) { return { tag: k, count: counts[k] }; });
  arr.sort(function (a, b) { return b.count - a.count; });
  return arr.slice(0, 8);
};

var sfRenderTrends = function () {
  var c = sfEl('sfTrends');
  if (!c) return;
  var trends = sfBuildTrends();
  var html = '<div class="sf-trend-card"><div class="sf-trend-title">热门话题</div>';
  trends.forEach(function (t, i) {
    html += '<div class="sf-trend-item" data-trend="' + sfEscapeHtml(t.tag) + '">'
      + '<div class="sf-trend-rank">' + (i + 1) + '</div>'
      + '<div class="sf-trend-tag">#' + sfEscapeHtml(t.tag) + '#</div>'
      + '<div class="sf-trend-count">' + t.count + ' 讨论</div>'
      + '</div>';
  });
  html += '</div>';
  c.innerHTML = html;
};

var sfRunSearch = function () {
  var input = sfEl('sfSearchInput');
  var c = sfEl('sfTrends');
  if (!input || !c) return;
  var kw = input.value.trim().toLowerCase();
  if (!kw) { sfRenderTrends(); return; }
  var results = [];
  var seen = {};
  var collect = function (p) {
    if (!p || seen[p.id]) return;
    var t = (p.authorName + ' ' + (p.handle || '') + ' ' + p.content).toLowerCase();
    if (t.indexOf(kw) !== -1) { seen[p.id] = 1; results.push(p); }
  };
  sfState.userPosts.forEach(collect);
  for (var tab in sfState.posts) sfState.posts[tab].forEach(collect);
  if (results.length === 0) {
    c.innerHTML = '<div class="sf-empty">没有找到相关内容</div>';
    return;
  }
  c.innerHTML = '<div style="padding:10px 14px;color:#999;font-size:13px">找到 ' + results.length + ' 条结果</div>'
    + results.map(function (p) { return sfRenderPost(p); }).join('');
};

