/* ============================================================
 * PART 21.5.5 - Stranger DM (陌生人私信系统)
 * ============================================================ */

/* 陌生人私信存储与加载 */
var sfSaveStrangerDMs = function () {
  try {
    sfStorage.set('sf_stranger_dms', JSON.stringify(sfState.strangerDMs || []));
  } catch (e) {}
};

var sfLoadStrangerDMs = function () {
  try {
    var saved = sfStorage.get('sf_stranger_dms');
    if (saved) {
      var parsed = JSON.parse(saved) || [];
      /* 修复：检测并清除旧版本遗留的fallback默认私信缓存（ID全为dm_stranger_sN格式且无真实对话） */
      var isOldFallback = Array.isArray(parsed) && parsed.length > 0 && parsed.every(function(d) {
        return /^dm_stranger_s\d+$/.test(d.id || '') && (!d.messages || d.messages.length === 0);
      });
      if (isOldFallback) {
        console.warn('[sfLoadStrangerDMs] 检测到旧fallback缓存，已清除，将重新AI生成');
        sfStorage.remove('sf_stranger_dms');
        sfState.strangerDMs = [];
      } else {
        sfState.strangerDMs = parsed;
      }
    }
  } catch (e) {}
  /* 如果没有陌生人私信，不在此处自动生成，由渲染列表时触发 */
};

/* 获取用户公开信息（供AI生成陌生人私信时使用，不提供私密信息） */
var sfGetUserPublicInfo = function () {
  var userName = sfState.userProfile.displayName ||
    (typeof config !== 'undefined' && config.user && config.user.name) || '体验用户';
  var userBio = sfState.userProfile.bio || '这个人很神秘，还没有填写简介';
  /* 获取用户最近发帖（最多3条） */
  var recentPosts = (sfState.userPosts || []).slice(0, 3).map(function(p) {
    return String(p.content || '').slice(0, 80);
  }).filter(Boolean);
  /* 获取用户认识的角色名字（供路人问八卦使用） */
  var knownCharNames = [];
  if (typeof config !== 'undefined' && config.characters) {
    config.characters.filter(function(c) { return !c.deletedFromWechat; }).forEach(function(c) {
      knownCharNames.push(c.name);
    });
  }
  if (typeof config !== 'undefined' && config.npcs) {
    config.npcs.forEach(function(n) { knownCharNames.push(n.name); });
  }
  return {
    name: userName,
    bio: userBio,
    recentPosts: recentPosts,
    knownCharNames: knownCharNames
  };
};

/* 调用AI生成15条来自不同陌生网友的私信 */
var sfGenerateStrangerDMs = async function () {
  try {
    var pubInfo = sfGetUserPublicInfo();
    var wvText = sfGetActiveWorldviewText();

    var prompt = '你是一个虚拟社交论坛的陌生人私信生成器。请生成15条来自不同陌生网友的私信，发送给用户「' + pubInfo.name + '」。\n\n';
    prompt += '【用户公开信息】（陌生人只能看到这些信息）\n';
    prompt += '- 昵称：' + pubInfo.name + '\n';
    prompt += '- 简介：' + pubInfo.bio + '\n';
    if (pubInfo.recentPosts.length > 0) {
      prompt += '- 最近发帖：\n';
      pubInfo.recentPosts.forEach(function(p) { prompt += '  · ' + p + '\n'; });
    }
    if (pubInfo.knownCharNames.length > 0) {
      prompt += '\n【绯闻机制】用户在论坛上与以下角色有互动：' + pubInfo.knownCharNames.join('、') + '\n';
      prompt += '部分路人可以根据这些角色名字来问八卦，比如"听说你和XXX关系很好？""你是不是在和XXX谈恋爱？"等。\n';
    }
    if (wvText) prompt += '\n【世界观设定】' + wvText + '\n';
    prompt += '\n【私信类型分布要求】\n';
    prompt += '- 40%友好夸夸：夸赞用户的帖子或昵称，表示关注和支持\n';
    prompt += '- 40%正常交流/八卦：正常聊天、询问问题、讨论话题，或基于绯闻机制问八卦\n';
    prompt += '- 10%奇怪路人/广告：奇怪的搭讪、广告推广、莫名其妙的消息\n';
    prompt += '- 10%负面情绪：抱怨、阴阳怪气、质疑用户等\n\n';
    prompt += '要求：\n';
    prompt += '1. 每条私信来自不同的陌生人，名字要有网感\n';
    prompt += '2. 私信内容简短自然，像真实社交平台的陌生人私信\n';
    prompt += '3. 陌生人只能看到用户的公开信息，不能知道用户的私密信息\n';
    prompt += '4. 返回JSON数组，每条含字段：from(发送者ID，英文随机字符串), name(发送者昵称), avatarEmoji(头像emoji), avatarBg(头像背景色，hex格式), content(私信内容), time(发送时间)\n';
    prompt += '5. 只返回JSON数组，不要解释';

    var apiMessages = [
      { role: 'system', content: '你是一个虚拟社交论坛的陌生人私信生成器。只返回JSON数组，不要包含任何解释性文字。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 4000, temperature: 0.85 });

    var cleaned = String(reply).replace(/^```json\s*/i, '').replace(/```$/g, '').replace(/^```\s*/, '').trim();
    var jsonArrMatch = cleaned.match(/\[[\s\S]*\]/);
    var jsonText = jsonArrMatch ? jsonArrMatch[0] : cleaned;
    var dms = null;
    try { dms = JSON.parse(jsonText); } catch (e1) {
      /* 容错：输出被maxTokens截断、数组未闭合时，截取最后一个完整对象手动补全 */
      try {
        var _lastObj = jsonText.lastIndexOf('}');
        if (jsonText.replace(/\s/g,'').charAt(0) === '[' && _lastObj > 0) {
          dms = JSON.parse(jsonText.substring(0, _lastObj + 1) + ']');
        }
      } catch (e2) { dms = null; }
      if (!Array.isArray(dms)) dms = [];
    }

    if (Array.isArray(dms) && dms.length > 0) {
      /* 保存已有对话记录，以便在新列表中保留同ID的对话 */
      var oldConvMap = {};
      (sfState.strangerDMs || []).forEach(function(s) {
        if (s.id && s.messages && s.messages.length > 0) oldConvMap[s.id] = s.messages;
      });
      sfState.strangerDMs = dms.slice(0, 15).map(function(d, i) {
        var newId = 'dm_stranger_' + (d.from || ('s' + i));
        return {
          id: newId,
          from: d.from || ('s' + i),
          name: String(d.name || '匿名网友').slice(0, 20),
          avatarEmoji: String(d.avatarEmoji || '👤').slice(0, 4),
          avatarBg: String(d.avatarBg || SF_AVATAR_COLORS[i % SF_AVATAR_COLORS.length][0]).slice(0, 20),
          content: String(d.content || '').slice(0, 500),
          time: String(d.time || '刚刚').slice(0, 20),
          messages: oldConvMap[newId] || [],
          lastTime: Date.now() - i * 60000
        };
      });
      sfSaveStrangerDMs();
    } else {
      /* AI返回了非数组或空内容：不使用写死默认私信，显示空状态让用户可点"生成"重试 */
      console.warn('[sfGenerateStrangerDMs] AI返回格式异常，显示空状态供手动重试');
      if (!sfState.strangerDMs || sfState.strangerDMs.length === 0) {
        sfState.strangerDMs = [];
        sfSaveStrangerDMs();
      }
      sfToast('陌生人私信没能生成，可点"生成陌生人私信"重试');
    }
  } catch (e) {
    /* 生成失败：不使用写死默认私信；保留已有列表，首次失败则显示空状态供手动重试 */
    console.warn('[sfGenerateStrangerDMs] 生成失败:', e);
    if (!sfState.strangerDMs || sfState.strangerDMs.length === 0) {
      sfState.strangerDMs = [];
      sfSaveStrangerDMs();
    }
    sfToast('陌生人私信生成失败：' + ((e && e.message) ? e.message : '可点生成按钮重试'));
  }
};

