/* 发送消息给陌生人，AI生成回复（只能看到用户公开信息） */
var sfSendStrangerDM = async function () {
  var input = sfEl('sfDMInput');
  if (!input || !input.value.trim()) return;
  var text = input.value.trim();
  input.value = '';

  var contactId = sfState.currentDMId;
  if (!contactId || contactId.indexOf('dm_stranger_') !== 0) return;

  /* 找到对应的陌生人 */
  var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
  if (!sdm) return;

  var now = new Date();
  var timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  /* 添加用户消息 */
  if (!sdm.messages) sdm.messages = [];
  /* 如果是第一次回复，先把陌生人的初始私信存入对话记录 */
  if (sdm.messages.length === 0 && sdm.content) {
    sdm.messages.push({ me: false, text: sdm.content, time: sdm.time || '刚刚' });
  }
  sdm.messages.push({ me: true, text: text, time: timeStr });
  sdm.lastTime = Date.now();
  sfSaveStrangerDMs();
  sfRenderDMMessages(contactId);

  /* 显示正在输入提示 */
  var body = sfEl('sfDMDetailBody');
  if (body) {
    var typing = document.createElement('div');
    typing.className = 'sf-dm-typing';
    typing.id = 'sfDMTyping';
    typing.textContent = sdm.name + ' 正在输入...';
    body.appendChild(typing);
    body.scrollTop = body.scrollHeight;
  }

  /* 构建AI回复（陌生人只能看到用户公开信息） */
  try {
    var pubInfo = sfGetUserPublicInfo();
    var wvText = sfGetActiveWorldviewText();
    var recentMsgs = sdm.messages.slice(-10).map(function(m) {
      return (m.me ? pubInfo.name : sdm.name) + ': ' + m.text;
    }).join('\n');

    var prompt = '你正在扮演一个论坛上的陌生人「' + sdm.name + '」，在私信中与用户「' + pubInfo.name + '」聊天。\n\n';
    prompt += '【你的身份】你是论坛上一个普通用户，和用户「' + pubInfo.name + '」并不认识。你通过用户的帖子或简介注意到了ta。\n';
    prompt += '【用户公开信息】（你只能看到这些）\n';
    prompt += '- 昵称：' + pubInfo.name + '\n';
    prompt += '- 简介：' + pubInfo.bio + '\n';
    if (wvText) prompt += '【世界观设定】' + wvText + '\n';
    prompt += '\n最近对话:\n' + recentMsgs + '\n\n';
    prompt += '请以「' + sdm.name + '」的身份回复用户最新消息。\n';
    prompt += '要求：\n';
    prompt += '1. 只输出回复内容，不要加角色名前缀\n';
    prompt += '2. 保持口语化、自然，像陌生人私信一样\n';
    prompt += '3. 回复一般1-2句话，不要太长\n';
    prompt += '4. 你是陌生人，不要表现得过于亲密或知道太多用户的信息\n';
    prompt += '5. 可以带emoji\n';

    var apiMessages = [
      { role: 'system', content: '你是一个角色扮演AI，在论坛私信中扮演一个陌生人与用户聊天。保持陌生人之间的距离感，回复简短自然。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 300, temperature: 0.9 });

    var typingEl = document.getElementById('sfDMTyping');
    if (typingEl) typingEl.remove();

    var replyText = String(reply || '...').trim();
    var now2 = new Date();
    var timeStr2 = now2.getHours().toString().padStart(2, '0') + ':' + now2.getMinutes().toString().padStart(2, '0');
    sdm.messages.push({ me: false, text: replyText, time: timeStr2 });
    sdm.lastTime = Date.now();
    sfSaveStrangerDMs();
    sfRenderDMMessages(contactId);
  } catch (e) {
    var typingEl2 = document.getElementById('sfDMTyping');
    if (typingEl2) typingEl2.remove();
    sdm.messages.push({ me: false, text: '（消息发送失败）', time: '' });
    sfSaveStrangerDMs();
    sfRenderDMMessages(contactId);
  }
};

/* v89：论坛私信里，角色也用“自己那颗跨账号大脑”的记忆分段 + 动态称呼（陌生人私信不注入） */
function sfDmRoleContext(contact, userName) {
  try {
    if (!contact || contact.type !== 'character') return '';
    var ch = (config.characters || []).filter(function (c) { return String(c.id) === String(contact.id); })[0];
    if (!ch) return '';
    var curId = (typeof currentAccId === 'function') ? currentAccId() : null;
    var isOwner = (typeof currentAccIsCharOwner === 'function') ? currentAccIsCharOwner(ch) : true;
    var rel = '';
    try { var pp = (typeof waEnsureCharPerson === 'function') ? waEnsureCharPerson(ch, waCurrentAccount ? waCurrentAccount() : null) : null; rel = pp ? (pp.relation || '') : ''; } catch (e) {}
    var out = [];
    var addr = (typeof waDynamicAddressRule === 'function') ? waDynamicAddressRule(userName, rel, isOwner) : '';
    if (addr) out.push(addr);
    if (typeof waBuildCharMemoryBlocks === 'function') out = out.concat(waBuildCharMemoryBlocks(ch, curId, userName, isOwner));
    return out.length ? ('\n' + out.join('\n\n') + '\n') : '';
  } catch (e) { return ''; }
}
var sfGetDMContacts = function () {
  var contacts = [];
  if (typeof config !== 'undefined' && config.characters) {
    config.characters.filter(function(c) { return !c.deletedFromWechat; }).forEach(function(c) {
      contacts.push({
        id: String(c.id || c.name),
        name: c.name,
        persona: c.persona || '',
        avatar: c.avatar || c.image || null,
        avatarBg: c.avatarBg || '#576B95',
        type: 'character'
      });
    });
  }
  if (typeof config !== 'undefined' && config.npcs) {
    config.npcs.filter(function(n) { return !n._deprecated; }).forEach(function(n) {
      contacts.push({
        id: 'npc-' + n.id,
        name: n.name,
        persona: n.persona || '',
        avatar: null,
        avatarBg: n.avatarBg || '#FF9500',
        avatarEmoji: n.avatar || n.name.charAt(0),
        type: 'npc'
      });
    });
  }
  /* 如果设置了参与角色列表，只返回在列表中的联系人 */
  if (sfState.activeForumRoleIds && sfState.activeForumRoleIds.length > 0) {
    contacts = contacts.filter(function (c) {
      return sfState.activeForumRoleIds.indexOf(c.id) !== -1;
    });
    /* 如果过滤后没有联系人了（说明activeForumRoleIds已过期），清除过滤器返回全部 */
    if (contacts.length === 0) {
      sfState.activeForumRoleIds = [];
      sfSaveActiveForumRoles();
      contacts = [];
      if (typeof config !== 'undefined' && config.characters) {
        config.characters.filter(function(c) { return !c.deletedFromWechat; }).forEach(function(c) {
          contacts.push({
            id: String(c.id || c.name),
            name: c.name,
            persona: c.persona || '',
            avatar: c.avatar || c.image || null,
            avatarBg: c.avatarBg || '#576B95',
            type: 'character'
          });
        });
      }
      if (typeof config !== 'undefined' && config.npcs) {
        config.npcs.filter(function(n) { return !n._deprecated; }).forEach(function(n) {
          contacts.push({
            id: 'npc-' + n.id,
            name: n.name,
            persona: n.persona || '',
            avatar: null,
            avatarBg: n.avatarBg || '#FF9500',
            avatarEmoji: n.avatar || n.name.charAt(0),
            type: 'npc'
          });
        });
      }
    }
  }
  return contacts;
};

/* ★ 从角色聊天信息页直接打开论坛私信 */
function openForumDMWithCharacter() {
  var char = config.characters ? config.characters[currentCharIdx] : null;
  if (!char) { showToast('未找到角色数据'); return; }
  var charId = String(char.id || char.name);
  // 打开论坛
  if (typeof openSocialForum !== 'function') { showToast('论坛未加载'); return; }
  openSocialForum();
  // 使用论坛内置视图切换函数
  setTimeout(function() {
    sfState.dmTabType = 'friends';
    if (typeof sfSwitchView === 'function') {
      sfSwitchView('dm');
    }
    // 直接打开该角色的私信对话
    setTimeout(function() {
      sfOpenDMDetail(charId, 'character');
    }, 150);
  }, 300);
}

var sfRenderDMList = function () {
  var container = sfEl('sfDMList');
  if (!container) return;

  /* 顶部好友/陌生人切换标签 */
  var tabType = sfState.dmTabType || 'friends';
  var subTabsHtml = '<div class="sf-dm-sub-tabs">'
    + '<div class="sf-dm-sub-tab ' + (tabType === 'friends' ? 'active' : '') + '" data-dm-tab="friends">好友</div>'
    + '<div class="sf-dm-sub-tab ' + (tabType === 'stranger' ? 'active' : '') + '" data-dm-tab="stranger">陌生人 <span class="sf-dm-stranger-badge">' + (sfState.strangerDMs || []).length + '</span></div>'
    + '</div>';

  if (tabType === 'stranger') {
    /* 陌生人私信列表 */
    if (sfState.strangerDMsLoading) {
      container.innerHTML = subTabsHtml + '<div class="sf-notif-empty">正在刷新陌生人私信…<br><span style="font-size:12px;color:#8E8E93">请稍候</span></div>';
      return;
    }
    var strangers = sfState.strangerDMs || [];
    if (strangers.length === 0) {
      container.innerHTML = subTabsHtml + '<div class="sf-notif-empty" id="sfStrangerEmpty">还没有陌生人私信<br><button class="sf-generate-btn" data-action="gen-stranger-dm" style="padding:10px 24px;font-size:13px">✨ 生成陌生人私信</button></div>';
      return;
    }
    var strangerHtml = '';
    strangers.forEach(function(s) {
      var lastMsg = (s.messages && s.messages.length > 0) ? s.messages[s.messages.length - 1] : null;
      var preview = lastMsg ? (lastMsg.me ? '我: ' + lastMsg.text : lastMsg.text) : s.content;
      strangerHtml += '<div class="sf-dm-item" data-dm-id="' + sfEscapeHtml(s.id) + '" data-dm-type="stranger">'
        + '<div class="sf-dm-avatar" style="background:' + sfEscapeHtml(s.avatarBg || '#FF6B9D') + '">' + sfEscapeHtml(s.avatarEmoji || '👤') + '</div>'
        + '<div class="sf-dm-info">'
        + '<div class="sf-dm-name">' + sfEscapeHtml(s.name) + ' <span style="font-size:10px;color:#F5A0B8">陌生人</span></div>'
        + '<div class="sf-dm-preview">' + sfEscapeHtml(String(preview).substring(0, 40)) + '</div>'
        + '</div>'
        + '<div class="sf-dm-time">' + sfEscapeHtml(lastMsg ? (lastMsg.time || '') : (s.time || '')) + '</div>'
        + '</div>';
    });
    /* 底部刷新按钮 */
    strangerHtml += '<div style="text-align:center;padding:12px"><button class="sf-refresh-btn" data-action="refresh-stranger-dm">换一批陌生人 ✨</button></div>';
    container.innerHTML = subTabsHtml + strangerHtml;
    return;
  }

  /* 好友私信列表（原有逻辑） */
  var contacts = sfGetDMContacts();
  if (contacts.length === 0) {
    container.innerHTML = subTabsHtml + '<div class="sf-notif-empty">暂无可私信的对象<br>请先添加角色或NPC</div>';
    return;
  }
  var html = '';
  contacts.forEach(function(c) {
    var conv = sfState.dmConversations[c.id] || { messages: [], lastTime: 0 };
    var lastMsg = conv.messages.length > 0 ? conv.messages[conv.messages.length - 1] : null;
    var preview = lastMsg ? (lastMsg.me ? '我: ' + lastMsg.text : lastMsg.text) : '点击开始对话';
    var avatarHtml;
    if (c.avatar && (c.avatar.startsWith('data:') || c.avatar.startsWith('http'))) {
      avatarHtml = '<img src="' + c.avatar + '"  alt=""/>';
    } else if (c.type === 'npc') {
      avatarHtml = sfEscapeHtml(c.avatarEmoji || c.name.charAt(0));
    } else {
      avatarHtml = sfEscapeHtml(c.name.charAt(0));
    }
    html += '<div class="sf-dm-item" data-dm-id="' + sfEscapeHtml(c.id) + '" data-dm-type="' + c.type + '">'
      + '<div class="sf-dm-avatar" style="background:' + c.avatarBg + '">' + avatarHtml + '</div>'
      + '<div class="sf-dm-info">'
      + '<div class="sf-dm-name">' + sfEscapeHtml(c.name) + (c.type === 'npc' ? ' <span style="font-size:10px;color:#FF9500">NPC</span>' : '') + '</div>'
      + '<div class="sf-dm-preview">' + sfEscapeHtml(preview.substring(0, 40)) + '</div>'
      + '</div>'
      + '<div class="sf-dm-time">' + (lastMsg ? lastMsg.time || '' : '') + '</div>'
      + '</div>';
  });
  container.innerHTML = subTabsHtml + html;
};

var sfOpenDMDetail = function (contactId, contactType) {
  sfState.currentDMId = contactId;

  /* 陌生人私信（dm_stranger_前缀） */
  if (contactId && contactId.indexOf('dm_stranger_') === 0) {
    var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
    if (!sdm) return;

    var overlay = sfEl('sfDMDetailOverlay');
    if (overlay) overlay.classList.add('active');

    var titleEl = sfEl('sfDMTitle');
    if (titleEl) titleEl.textContent = sdm.name + ' (陌生人)';

    var avatarEl = sfEl('sfDMHeaderAvatar');
    if (avatarEl) {
      avatarEl.textContent = sdm.avatarEmoji || '👤';
      avatarEl.style.background = sdm.avatarBg || '#FF6B9D';
    }

    sfRenderDMMessages(contactId);

    var input = sfEl('sfDMInput');
    if (input) { input.value = ''; setTimeout(function() { input.focus(); }, 200); }
    return;
  }

  /* 好友私信（原有逻辑） */
  var contacts = sfGetDMContacts();
  var contact = contacts.find(function(c) { return c.id === contactId; });
  if (!contact) return;

  overlay = sfEl('sfDMDetailOverlay');
  if (overlay) overlay.classList.add('active');

  titleEl = sfEl('sfDMTitle');
  if (titleEl) titleEl.textContent = contact.name;

  avatarEl = sfEl('sfDMHeaderAvatar');
  if (avatarEl) {
    if (contact.avatar && (contact.avatar.startsWith('data:') || contact.avatar.startsWith('http'))) {
      avatarEl.innerHTML = '<img src="' + contact.avatar + '"  alt=""/>';
    } else {
      avatarEl.textContent = contact.avatarEmoji || contact.name.charAt(0);
    }
    avatarEl.style.background = contact.avatarBg;
  }

  sfRenderDMMessages(contactId);

  input = sfEl('sfDMInput');
  if (input) { input.value = ''; setTimeout(function() { input.focus(); }, 200); }
};

var sfCloseDMDetail = function () {
  var overlay = sfEl('sfDMDetailOverlay');
  if (overlay) overlay.classList.remove('active');
  sfState.currentDMId = null;
};

var sfDMLongPressIdx = -1;
var sfDMLongPressTimer = null;
var sfDMPendingQuote = null;

var sfRenderDMMessages = function (contactId) {
  var body = sfEl('sfDMDetailBody');
  if (!body) return;

  /* 陌生人私信：从strangerDMs获取消息 */
  var conv;
  var isStranger = contactId && contactId.indexOf('dm_stranger_') === 0;
  if (isStranger) {
    var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
    if (!sdm) return;
    conv = { messages: sdm.messages || [] };
    /* 如果还没有对话，显示陌生人的初始私信作为第一条消息 */
    if (conv.messages.length === 0 && sdm.content) {
      conv.messages = [{ me: false, text: sdm.content, time: sdm.time || '刚刚' }];
    }
  } else {
    conv = sfState.dmConversations[contactId] || { messages: [] };
  }

  if (conv.messages.length === 0) {
    body.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#bbb;font-size:13px">还没有消息<br>发条消息开始对话吧~</div>';
    return;
  }
  var html = '';
  conv.messages.forEach(function(m, i) {
    /* 引用块渲染 */
    var _quoteHtml = '';
    if (m.quote) {
      _quoteHtml = '<div style="font-size:12px;color:#999;padding:4px 8px;margin-bottom:4px;background:rgba(0,0,0,.04);border-radius:6px;border-left:2px solid #F5A0B8"><span style="color:#F5A0B8">' + sfEscapeHtml(m.quote.name || '引用') + '：</span>' + sfEscapeHtml((m.quote.text || '').substring(0, 60)) + (m.quote.text && m.quote.text.length > 60 ? '…' : '') + '</div>';
    }
    html += '<div class="sf-dm-bubble ' + (m.me ? 'me' : 'them') + '" data-dm-msg-idx="' + i + '">';
    html += _quoteHtml + sfEscapeHtml(m.text);
    html += '</div>';
    if (i === conv.messages.length - 1 || (i < conv.messages.length - 1 && conv.messages[i + 1].me !== m.me)) {
      html += '<div class="sf-dm-bubble-time">' + sfEscapeHtml(m.time || '') + '</div>';
    }
  });
  body.innerHTML = html;
  body.scrollTop = body.scrollHeight;

  /* ★ 添加长按事件监听 */
  body.querySelectorAll('.sf-dm-bubble[data-dm-msg-idx]').forEach(function(bubble) {
    var idx = parseInt(bubble.dataset.dmMsgIdx);
    if (isNaN(idx)) return;
    bubble.addEventListener('touchstart', function(e) {
      sfDMLongPressTimer = setTimeout(function() {
        sfDMLongPressIdx = idx;
        sfShowDMActionMenu(e);
      }, 500);
    });
    bubble.addEventListener('touchend', function() { clearTimeout(sfDMLongPressTimer); });
    bubble.addEventListener('touchmove', function() { clearTimeout(sfDMLongPressTimer); });
    bubble.addEventListener('contextmenu', function(e) {
      e.preventDefault();
      sfDMLongPressIdx = idx;
      sfShowDMActionMenu(e);
    });
  });
};

function sfShowDMActionMenu(e) {
  var menu = sfEl('sfDMActionMenu');
  if (!menu) return;
  var touch = e.touches ? e.touches[0] : e;
  var x = touch.clientX || e.clientX;
  var y = touch.clientY || e.clientY;
  var phoneRect = document.querySelector('.phone-screen').getBoundingClientRect();
  x = x - phoneRect.left;
  y = y - phoneRect.top;
  if (x > phoneRect.width - 130) x = phoneRect.width - 130;
  if (y > phoneRect.height - 140) y = phoneRect.height - 140;
  menu.style.left = x + 'px';
  menu.style.top = y + 'px';
  menu.classList.add('show');
}

function sfHideDMActionMenu() {
  var menu = sfEl('sfDMActionMenu');
  if (menu) menu.classList.remove('show');
}

/* ★ 论坛私信：删除消息 */
function sfDMDeleteMessage() {
  if (sfDMLongPressIdx < 0) { sfHideDMActionMenu(); return; }
  sfHideDMActionMenu();
  var contactId = sfState.currentDMId;
  if (!contactId) return;
  var conv;
  var isStranger = contactId.indexOf('dm_stranger_') === 0;
  if (isStranger) {
    var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
    if (!sdm) return;
    conv = { messages: sdm.messages || [] };
  } else {
    conv = sfState.dmConversations[contactId] || { messages: [] };
  }
  if (sfDMLongPressIdx >= conv.messages.length) return;
  if (!confirm('确定要删除这条消息吗？')) return;
  conv.messages.splice(sfDMLongPressIdx, 1);
  if (isStranger) {
    sfSaveStrangerDMs();
  } else {
    sfSaveDMConversations();
  }
  sfDMLongPressIdx = -1;
  sfRenderDMMessages(contactId);
}

/* ★ 论坛私信：引用消息 */
function sfDMQuoteMessage() {
  if (sfDMLongPressIdx < 0) { sfHideDMActionMenu(); return; }
  sfHideDMActionMenu();
  var contactId = sfState.currentDMId;
  if (!contactId) return;
  var conv;
  var isStranger = contactId.indexOf('dm_stranger_') === 0;
  if (isStranger) {
    var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
    if (!sdm) return;
    conv = { messages: sdm.messages || [] };
  } else {
    conv = sfState.dmConversations[contactId] || { messages: [] };
  }
  if (sfDMLongPressIdx >= conv.messages.length) return;
  var m = conv.messages[sfDMLongPressIdx];
  var name = m.me ? ((typeof config !== 'undefined' && config.user && config.user.name) || '我') : (sfState.currentDMName || '对方');
  var text = (m.text || '').trim();
  if (!text) { showToast('该消息不支持引用'); return; }
  if (text.length > 80) text = text.substring(0, 80) + '…';
  sfDMPendingQuote = { name: name, text: text };
  var bar = sfEl('sfDMQuoteBar');
  var barText = sfEl('sfDMQuoteText');
  if (bar && barText) {
    barText.textContent = name + '：' + text;
    bar.classList.add('show');
  }
  var input = sfEl('sfDMInput');
  if (input) input.focus();
  sfDMLongPressIdx = -1;
}

function sfCancelDMQuote() {
  sfDMPendingQuote = null;
  var bar = sfEl('sfDMQuoteBar');
  if (bar) bar.classList.remove('show');
}

/* ★ 论坛私信：修改消息（仅自己发的消息） */
function sfDMEditMessage() {
  if (sfDMLongPressIdx < 0) { sfHideDMActionMenu(); return; }
  sfHideDMActionMenu();
  var contactId = sfState.currentDMId;
  if (!contactId) return;
  var conv;
  var isStranger = contactId.indexOf('dm_stranger_') === 0;
  if (isStranger) {
    var sdm = sfState.strangerDMs.find(function(s) { return s.id === contactId; });
    if (!sdm) return;
    conv = { messages: sdm.messages || [] };
  } else {
    conv = sfState.dmConversations[contactId] || { messages: [] };
  }
  if (sfDMLongPressIdx >= conv.messages.length) return;
  var m = conv.messages[sfDMLongPressIdx];
  if (!m.me) { showToast('只能修改自己发的消息'); return; }
  var input = sfEl('sfDMInput');
  if (!input) return;
  input.value = m.text || '';
  input.focus();
  input.dataset.editIdx = String(sfDMLongPressIdx);
  showToast('修改后发送将替换原消息');
  sfDMLongPressIdx = -1;
}

var sfSendDMMessage = async function () {
  var input = sfEl('sfDMInput');
  if (!input || !input.value.trim()) return;
  var text = input.value.trim();

  var contactId = sfState.currentDMId;
  if (!contactId) return;

  /* 陌生人私信路由到专门的发送函数 */
  if (contactId.indexOf('dm_stranger_') === 0) {
    /* 恢复input值供sfSendStrangerDM使用 */
    input.value = text;
    sfSendStrangerDM();
    return;
  }

  /* ★ 编辑模式：替换已有消息 */
  var editIdx = input.dataset.editIdx;
  if (editIdx !== undefined && editIdx !== '') {
    var editIdxInt = parseInt(editIdx, 10);
    if (!sfState.dmConversations[contactId]) sfState.dmConversations[contactId] = { messages: [] };
    var conv = sfState.dmConversations[contactId];
    if (conv.messages[editIdxInt] && conv.messages[editIdxInt].me) {
      conv.messages[editIdxInt].text = text;
      conv.messages[editIdxInt].time = new Date().getHours().toString().padStart(2, '0') + ':' + new Date().getMinutes().toString().padStart(2, '0');
      sfSaveDMConversations();
      sfRenderDMMessages(contactId);
      showToast('消息已修改');
    }
    delete input.dataset.editIdx;
    input.value = '';
    sfCancelDMQuote();
    return;
  }

  input.value = '';

  var contacts = sfGetDMContacts();
  var contact = contacts.find(function(c) { return c.id === contactId; });
  if (!contact) return;

  var now = new Date();
  var timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  if (!sfState.dmConversations[contactId]) sfState.dmConversations[contactId] = { messages: [] };
  /* ★ 带引用的消息 */
  var newMsg = { me: true, text: text, time: timeStr };
  if (sfDMPendingQuote) {
    newMsg.quote = sfDMPendingQuote;
    sfDMPendingQuote = null;
    var bar = sfEl('sfDMQuoteBar');
    if (bar) bar.classList.remove('show');
  }
  sfState.dmConversations[contactId].messages.push(newMsg);
  sfState.dmConversations[contactId].lastTime = Date.now();
  sfSaveDMConversations();
  sfRenderDMMessages(contactId);

  /* Show typing indicator */
  var body = sfEl('sfDMDetailBody');
  if (body) {
    var typing = document.createElement('div');
    typing.className = 'sf-dm-typing';
    typing.id = 'sfDMTyping';
    typing.textContent = contact.name + ' 正在输入...';
    body.appendChild(typing);
    body.scrollTop = body.scrollHeight;
  }

  /* Build AI reply */
  try {
    var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';
    var recentMsgs = sfState.dmConversations[contactId].messages.slice(-10).map(function(m) {
      return (m.me ? userName : contact.name) + ': ' + m.text;
    }).join('\n');

    var activeRuleText = sfGetActiveRuleText();
    var dmWvText = sfGetActiveWorldviewText();
    var prompt = '你正在扮演「' + contact.name + '」在论坛私信中与用户「' + userName + '」聊天。\n\n';
    prompt += '角色人设: ' + (contact.persona || '').substring(0, 2000) + '\n';
    if (dmWvText) prompt += '【世界观设定】: ' + dmWvText + '\n';
    prompt += '\n最近对话:\n' + recentMsgs + '\n\n';
    /* 引用回复上下文 */
    var lastUserMsg = sfState.dmConversations[contactId].messages.filter(function(m){return m.me;}).pop();
    if (lastUserMsg && lastUserMsg.quote) {
      prompt += '【用户引用了「' + lastUserMsg.quote.name + '」的消息】: ' + lastUserMsg.quote.text + '\n请针对这条引用的内容回复。\n\n';
    }
    prompt += sfDmRoleContext(contact, userName);
    prompt += '请以「' + contact.name + '」的身份回复用户最新消息。\n';
    prompt += '要求：\n';
    prompt += '1. 只输出回复内容，不要加角色名前缀\n';
    prompt += '2. 保持口语化、自然，像微信聊天一样简短\n';
    prompt += '3. 回复一般1-2句话，不要太长\n';
    prompt += '4. 符合角色性格和说话习惯\n';
    prompt += '5. 可以带emoji，可以反问、调侃、撒娇等\n';
    prompt += '6. 不要像客服，不要说教，不要用"亲爱的"这种套话\n';

    var apiMessages = [
      { role: 'system', content: '你是一个角色扮演AI，在论坛私信中扮演特定角色与用户聊天。保持角色一致性，回复简短自然（一般1-2句话），像真实的微信聊天。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 300, temperature: 0.9 });

    var typingEl = document.getElementById('sfDMTyping');
    if (typingEl) typingEl.remove();

    var replyText = String(reply || '...').trim();
    var now2 = new Date();
    var timeStr2 = now2.getHours().toString().padStart(2, '0') + ':' + now2.getMinutes().toString().padStart(2, '0');
    sfState.dmConversations[contactId].messages.push({ me: false, text: replyText, time: timeStr2 });
    sfState.dmConversations[contactId].lastTime = Date.now();
    sfSaveDMConversations();
    sfRenderDMMessages(contactId);
  } catch (e) {
    var typingEl2 = document.getElementById('sfDMTyping');
    if (typingEl2) typingEl2.remove();
    sfState.dmConversations[contactId].messages.push({ me: false, text: '（消息发送失败）', time: '' });
    sfRenderDMMessages(contactId);
  }
};

/* 重新生成私信AI回复：删除指定AI回复及之后的消息，重新调用AI生成回复 */
var sfRegenerateDM = async function (contactId, messageIndex) {
  if (!contactId) return;
  var contacts = sfGetDMContacts();
  var contact = contacts.find(function(c) { return c.id === contactId; });
  if (!contact) return;
  if (!sfState.dmConversations[contactId]) return;
  var messages = sfState.dmConversations[contactId].messages;
  if (messageIndex < 0 || messageIndex >= messages.length) return;
  /* 确认目标消息是AI回复（非用户发送） */
  if (messages[messageIndex].me) return;
  /* 删除该条AI回复及之后的所有消息 */
  sfState.dmConversations[contactId].messages = messages.slice(0, messageIndex);
  sfState.dmConversations[contactId].lastTime = Date.now();
  sfSaveDMConversations();
  sfRenderDMMessages(contactId);

  /* 显示正在输入提示 */
  var body = sfEl('sfDMDetailBody');
  if (body) {
    var typing = document.createElement('div');
    typing.className = 'sf-dm-typing';
    typing.id = 'sfDMTyping';
    typing.textContent = contact.name + ' 正在输入...';
    body.appendChild(typing);
    body.scrollTop = body.scrollHeight;
  }

  /* 重新调用AI生成回复 */
  try {
    var userName = (typeof config !== 'undefined' && config.user && config.user.name) || '用户';
    var recentMsgs = sfState.dmConversations[contactId].messages.slice(-10).map(function(m) {
      return (m.me ? userName : contact.name) + ': ' + m.text;
    }).join('\n');

    var activeRuleText = sfGetActiveRuleText();
    var dmWvText = sfGetActiveWorldviewText();
    var prompt = '你正在扮演「' + contact.name + '」在论坛私信中与用户「' + userName + '」聊天。\n\n';
    prompt += '角色人设: ' + (contact.persona || '').substring(0, 2000) + '\n';
    if (dmWvText) prompt += '【世界观设定】: ' + dmWvText + '\n';
    prompt += '\n最近对话:\n' + recentMsgs + '\n\n';
    prompt += sfDmRoleContext(contact, userName);
    prompt += '请以「' + contact.name + '」的身份回复用户最新消息。\n';
    prompt += '要求：\n';
    prompt += '1. 只输出回复内容，不要加角色名前缀\n';
    prompt += '2. 保持口语化、自然，像微信聊天一样简短\n';
    prompt += '3. 回复一般1-2句话，不要太长\n';
    prompt += '4. 符合角色性格和说话习惯\n';
    prompt += '5. 可以带emoji，可以反问、调侃、撒娇等\n';
    prompt += '6. 不要像客服，不要说教，不要用"亲爱的"这种套话\n';

    var apiMessages = [
      { role: 'system', content: '你是一个角色扮演AI，在论坛私信中扮演特定角色与用户聊天。保持角色一致性，回复简短自然（一般1-2句话），像真实的微信聊天。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 300, temperature: 0.9 });

    var typingEl = document.getElementById('sfDMTyping');
    if (typingEl) typingEl.remove();

    var replyText = String(reply || '...').trim();
    var now2 = new Date();
    var timeStr2 = now2.getHours().toString().padStart(2, '0') + ':' + now2.getMinutes().toString().padStart(2, '0');
    sfState.dmConversations[contactId].messages.push({ me: false, text: replyText, time: timeStr2 });
    sfState.dmConversations[contactId].lastTime = Date.now();
    sfSaveDMConversations();
    sfRenderDMMessages(contactId);
    sfToast('已重新生成');
  } catch (e) {
    var typingEl2 = document.getElementById('sfDMTyping');
    if (typingEl2) typingEl2.remove();
    sfState.dmConversations[contactId].messages.push({ me: false, text: '（重新生成失败）', time: '' });
    sfRenderDMMessages(contactId);
    sfToast('重新生成失败：' + ((e && e.message) ? e.message : '请稍后重试'));
  }
};

/* ============================================================
 * PART 21.6 - Forum Rules (自定义论坛规则)
 * ============================================================ */

var sfSaveForumRules = function () {
  try {
    sfStorage.set('sf_forum_rules', JSON.stringify(sfState.forumRules || []));
    sfStorage.set('sf_selected_rule', sfState.selectedRuleId || '');
  } catch (e) {}
};

var sfLoadForumRules = function () {
  try {
    var saved = sfStorage.get('sf_forum_rules');
    if (saved) sfState.forumRules = JSON.parse(saved) || [];
    var selId = sfStorage.get('sf_selected_rule');
    if (selId) sfState.selectedRuleId = selId;
  } catch (e) {}
  /* Add default rule if empty */
  if (sfState.forumRules.length === 0) {
    sfState.forumRules = [
      { id: 'rule-default-1', name: '温馨日常', description: '帖子以日常生活分享为主，风格温馨治愈，评论友善鼓励' }
    ];
    sfState.selectedRuleId = 'rule-default-1';
    sfSaveForumRules();
  }
};

var sfGetActiveRuleText = function () {
  if (!sfState.selectedRuleId) return '';
  var rule = sfState.forumRules.find(function(r) { return r.id === sfState.selectedRuleId; });
  return rule ? (rule.name + ': ' + rule.description) : '';
};

var sfOpenRulesModal = function () {
  sfRenderRulesList();
  var m = sfEl('sfRulesModal');
  if (m) m.classList.add('active');
};

var sfCloseRulesModal = function () {
  var m = sfEl('sfRulesModal');
  if (m) m.classList.remove('active');
};

var sfRenderRulesList = function () {
  var container = sfEl('sfRulesList');
  if (!container) return;
  if (sfState.forumRules.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#999;font-size:13px">暂无规则，点击下方按钮新建</div>';
    return;
  }
  var html = '';
  sfState.forumRules.forEach(function(r) {
    var isActive = r.id === sfState.selectedRuleId;
    html += '<div class="sf-rule-item ' + (isActive ? 'active' : '') + '">'
      + '<div class="sf-rule-info">'
      + '<div class="sf-rule-name">' + sfEscapeHtml(r.name) + (isActive ? ' <span style="font-size:10px;color:#F5A0B8;font-weight:700">● 使用中</span>' : '') + '</div>'
      + '<div class="sf-rule-desc">' + sfEscapeHtml(r.description) + '</div>'
      + '</div>'
      + '<div class="sf-rule-actions">'
      + '<button class="sf-rule-btn select" data-rule-select="' + r.id + '" title="选择">' + (isActive ? '✓' : '○') + '</button>'
      + '<button class="sf-rule-btn" data-rule-edit="' + r.id + '" title="编辑">✎</button>'
      + '<button class="sf-rule-btn del" data-rule-del="' + r.id + '" title="删除">✕</button>'
      + '</div>'
      + '</div>';
  });
  container.innerHTML = html;
};

var sfEditingRuleId = null;

var sfOpenRuleEditor = function (ruleId) {
  sfEditingRuleId = ruleId || null;
  var titleEl = sfEl('sfRuleEditorTitle');
  var nameInput = sfEl('sfRuleNameInput');
  var descInput = sfEl('sfRuleDescInput');
  if (ruleId) {
    var rule = sfState.forumRules.find(function(r) { return r.id === ruleId; });
    if (titleEl) titleEl.textContent = '编辑规则';
    if (nameInput) nameInput.value = rule ? rule.name : '';
    if (descInput) descInput.value = rule ? rule.description : '';
  } else {
    if (titleEl) titleEl.textContent = '新建规则';
    if (nameInput) nameInput.value = '';
    if (descInput) descInput.value = '';
  }
  var editor = sfEl('sfRuleEditor');
  if (editor) editor.classList.add('active');
};

var sfCloseRuleEditor = function () {
  var editor = sfEl('sfRuleEditor');
  if (editor) editor.classList.remove('active');
  sfEditingRuleId = null;
};

var sfSaveRuleFromEditor = function () {
  var nameInput = sfEl('sfRuleNameInput');
  var descInput = sfEl('sfRuleDescInput');
  if (!nameInput || !nameInput.value.trim()) { sfToast('请输入规则名称'); return; }
  var name = nameInput.value.trim();
  var desc = descInput ? descInput.value.trim() : '';

  if (sfEditingRuleId) {
    var rule = sfState.forumRules.find(function(r) { return r.id === sfEditingRuleId; });
    if (rule) { rule.name = name; rule.description = desc; }
  } else {
    var newRule = { id: 'rule-' + Date.now(), name: name, description: desc };
    sfState.forumRules.push(newRule);
    if (!sfState.selectedRuleId) sfState.selectedRuleId = newRule.id;
  }
  sfSaveForumRules();
  sfCloseRuleEditor();
  sfRenderRulesList();
  sfToast('规则已保存');
};

var sfDeleteRule = function (ruleId) {
  sfState.forumRules = sfState.forumRules.filter(function(r) { return r.id !== ruleId; });
  if (sfState.selectedRuleId === ruleId) {
    sfState.selectedRuleId = sfState.forumRules.length > 0 ? sfState.forumRules[0].id : null;
  }
  sfSaveForumRules();
  sfRenderRulesList();
  sfToast('规则已删除');
};

var sfSelectRule = function (ruleId) {
  sfState.selectedRuleId = ruleId;
  sfSaveForumRules();
  sfRenderRulesList();
  sfToast('已切换规则');
};

/* ============================================================
 * PART 21.6.5 - Worldview System (世界观系统)
 * ============================================================ */

/* 世界观存储与加载 */
var sfSaveWorldviews = function () {
  try {
    sfStorage.set('sf_worldviews', JSON.stringify(sfState.worldviews || []));
    sfStorage.set('sf_active_worldview', sfState.activeWorldviewId || '');
  } catch (e) {}
};

var sfLoadWorldviews = function () {
  try {
    var saved = sfStorage.get('sf_worldviews');
    if (saved) sfState.worldviews = JSON.parse(saved) || [];
    var savedActive = sfStorage.get('sf_active_worldview');
    if (savedActive) sfState.activeWorldviewId = savedActive;
  } catch (e) {}
  /* 如果没有世界观，添加默认现代都市世界观 */
  if (sfState.worldviews.length === 0) {
    sfState.worldviews = [
      { id: 'default-modern', name: '现代都市', description: '故事发生在现代都市，角色们过着日常生活' }
    ];
    sfState.activeWorldviewId = 'default-modern';
    sfSaveWorldviews();
  }
  /* 确保有激活的世界观 */
  if (!sfState.activeWorldviewId && sfState.worldviews.length > 0) {
    sfState.activeWorldviewId = sfState.worldviews[0].id;
    sfSaveWorldviews();
  }
};

/* 获取当前激活的世界观对象 */
var sfGetActiveWorldview = function () {
  if (!sfState.activeWorldviewId) return null;
  return sfState.worldviews.find(function(w) { return w.id === sfState.activeWorldviewId; }) || null;
};

/* 获取当前激活的世界观描述文本（用于prompt注入） */
var sfGetActiveWorldviewText = function () {
  var wv = sfGetActiveWorldview();
  if (!wv) return '';
  return wv.name + '：' + wv.description;
};

/* 打开世界观管理弹窗 */
var sfOpenWorldviewModal = function () {
  sfRenderWorldviewList();
  var m = sfEl('sfWorldviewModal');
  if (m) m.classList.add('active');
};

var sfCloseWorldviewModal = function () {
  var m = sfEl('sfWorldviewModal');
  if (m) m.classList.remove('active');
};

/* 渲染世界观列表 */
var sfRenderWorldviewList = function () {
  var container = sfEl('sfWorldviewList');
  if (!container) return;
  if (sfState.worldviews.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:30px;color:#999;font-size:13px">暂无世界观，点击下方按钮新建</div>';
    return;
  }
  var html = '';
  sfState.worldviews.forEach(function(w) {
    var isActive = w.id === sfState.activeWorldviewId;
    html += '<div class="sf-rule-item ' + (isActive ? 'active' : '') + '">'
      + '<div class="sf-rule-info">'
      + '<div class="sf-rule-name">' + sfEscapeHtml(w.name) + (isActive ? ' <span style="font-size:10px;color:#F5A0B8;font-weight:700">● 使用中</span>' : '') + '</div>'
      + '<div class="sf-rule-desc">' + sfEscapeHtml(w.description) + '</div>'
      + '</div>'
      + '<div class="sf-rule-actions">'
      + '<button class="sf-rule-btn select" data-wv-select="' + w.id + '" title="选择">' + (isActive ? '✓' : '○') + '</button>'
      + '<button class="sf-rule-btn" data-wv-edit="' + w.id + '" title="编辑">✎</button>'
      + '<button class="sf-rule-btn del" data-wv-del="' + w.id + '" title="删除">✕</button>'
      + '</div>'
      + '</div>';
  });
  container.innerHTML = html;
};

var sfEditingWorldviewId = null;

/* 打开世界观编辑器 */
var sfOpenWorldviewEditor = function (wvId) {
  sfEditingWorldviewId = wvId || null;
  var titleEl = sfEl('sfWorldviewEditorTitle');
  var nameInput = sfEl('sfWorldviewNameInput');
  var descInput = sfEl('sfWorldviewDescInput');
  if (wvId) {
    var wv = sfState.worldviews.find(function(w) { return w.id === wvId; });
    if (titleEl) titleEl.textContent = '编辑世界观';
    if (nameInput) nameInput.value = wv ? wv.name : '';
    if (descInput) descInput.value = wv ? wv.description : '';
  } else {
    if (titleEl) titleEl.textContent = '新建世界观';
    if (nameInput) nameInput.value = '';
    if (descInput) descInput.value = '';
  }
  var editor = sfEl('sfWorldviewEditor');
  if (editor) editor.classList.add('active');
};

var sfCloseWorldviewEditor = function () {
  var editor = sfEl('sfWorldviewEditor');
  if (editor) editor.classList.remove('active');
  sfEditingWorldviewId = null;
};

/* 从编辑器保存世界观 */
var sfSaveWorldviewFromEditor = function () {
  var nameInput = sfEl('sfWorldviewNameInput');
  var descInput = sfEl('sfWorldviewDescInput');
  if (!nameInput || !nameInput.value.trim()) { sfToast('请输入世界观名称'); return; }
  var name = nameInput.value.trim();
  var desc = descInput ? descInput.value.trim() : '';

  if (sfEditingWorldviewId) {
    var wv = sfState.worldviews.find(function(w) { return w.id === sfEditingWorldviewId; });
    if (wv) { wv.name = name; wv.description = desc; }
  } else {
    var newWv = { id: 'wv-' + Date.now(), name: name, description: desc };
    sfState.worldviews.push(newWv);
    if (!sfState.activeWorldviewId) sfState.activeWorldviewId = newWv.id;
  }
  sfSaveWorldviews();
  sfCloseWorldviewEditor();
  sfRenderWorldviewList();
  sfToast('世界观已保存');
};

/* 删除世界观 */
var sfDeleteWorldview = function (wvId) {
  sfState.worldviews = sfState.worldviews.filter(function(w) { return w.id !== wvId; });
  if (sfState.activeWorldviewId === wvId) {
    sfState.activeWorldviewId = sfState.worldviews.length > 0 ? sfState.worldviews[0].id : null;
  }
  sfSaveWorldviews();
  sfRenderWorldviewList();
  sfToast('世界观已删除');
};

/* 选择激活的世界观 */
var sfSelectWorldview = function (wvId) {
  sfState.activeWorldviewId = wvId;
  sfSaveWorldviews();
  sfRenderWorldviewList();
  sfToast('已切换世界观');
};

/* ============================================================
 * PART 21.7 - Post Image Upload (图片上传)
 * ============================================================ */

var sfHandlePostImage = function (file) {
  if (!file || !file.type.startsWith('image/')) return;
  if (file.size > 5 * 1024 * 1024) { sfToast('图片不能超过5MB'); return; }
  var reader = new FileReader();
  reader.onload = function(e) {
    sfState.tempPostImage = e.target.result;
    var preview = sfEl('sfPostImgPreview');
    if (preview) {
      preview.style.display = 'block';
      preview.className = 'sf-post-img-preview';
      preview.innerHTML = '<img src="' + e.target.result + '"  alt=""/><button class="sf-post-img-remove" id="sfPostImgRemove" type="button">&times;</button>';
      var removeBtn = document.getElementById('sfPostImgRemove');
      if (removeBtn) removeBtn.addEventListener('click', function() {
        sfState.tempPostImage = null;
        preview.style.display = 'none';
        preview.innerHTML = '';
      });
    }
  };
  reader.readAsDataURL(file);
};

/* ============================================================
 * PART 21.8 - Trending Detail (热搜详情页)
 * ============================================================ */

var sfOpenTrendDetail = function (keyword) {
  sfState.currentTrendKeyword = keyword;
  var overlay = sfEl('sfTrendDetailOverlay');
  if (overlay) overlay.classList.add('active');
  var titleEl = sfEl('sfTrendTitle');
  if (titleEl) titleEl.textContent = '#' + keyword + '#';
  var body = sfEl('sfTrendDetailBody');
  if (body) {
    body.innerHTML = '<div class="sf-trend-detail-hero">'
      + '<h2>#' + sfEscapeHtml(keyword) + '#</h2>'
      + '<p>正在生成相关讨论...</p>'
      + '</div>'
      + '<div class="sf-loading">正在加载...</div>';
  }
  sfGenerateTrendPosts(keyword);
};

var sfCloseTrendDetail = function () {
  var overlay = sfEl('sfTrendDetailOverlay');
  if (overlay) overlay.classList.remove('active');
  sfState.currentTrendKeyword = null;
};

var sfGenerateTrendPosts = async function (keyword) {
  var body = sfEl('sfTrendDetailBody');
  if (!body) return;
  try {
    var contextData = sfGatherForumContext({ content: keyword, authorName: '话题讨论' });
    var charNames = contextData.characters.map(function(c) { return c.name; });
    var npcNames = contextData.npcs.map(function(n) { return n.name; });
    var activeRuleText = sfGetActiveRuleText();

    var prompt = '话题「#' + keyword + '#」正在论坛热议。请生成10条不同网友的帖子讨论。\n\n';
    prompt += '可使用的角色: ' + (charNames.concat(npcNames).join('、') || '无') + '\n';
    var trendWvText = sfGetActiveWorldviewText();
    if (trendWvText) prompt += '【世界观设定】: ' + trendWvText + '\n';
    if (activeRuleText) prompt += '论坛规则: ' + activeRuleText + '\n';
    prompt += '\n要求:\n1. 帖子内容围绕话题展开，观点各异\n2. 部分帖子可以由上述角色发布，其余为路人网友\n3. 语气口语化，像真实论坛\n4. 返回JSON数组，每个对象有content和authorName字段';

    var apiMessages = [
      { role: 'system', content: '你是一个论坛内容生成器。只返回JSON数组，不要解释。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 3000 });

    var cleaned = String(reply).replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
    var jsonMatch = cleaned.match(/\[[\s\S]*\]/);
    var posts;
    try { posts = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned); } catch(e) { posts = []; }

    var heroHtml = '<div class="sf-trend-detail-hero">'
      + '<h2>#' + sfEscapeHtml(keyword) + '#</h2>'
      + '<p>' + posts.length + ' 条讨论</p>'
      + '</div>';

    var postsHtml = posts.map(function(p, i) {
      var fakePost = {
        id: 'trend-' + Date.now() + '-' + i,
        authorName: p.authorName || '路人',
        handle: sfHandle(p.authorName || '路人'),
        content: p.content || '',
        time: '刚刚',
        likes: Math.floor(Math.random() * 200) + 10,
        reposts: Math.floor(Math.random() * 50),
        comments: 0,
        views: Math.floor(Math.random() * 5000) + 100,
        avatarIndex: i % SF_AVATAR_COUNT,
        verified: false
      };
      return sfRenderPost(fakePost);
    }).join('');

    body.innerHTML = heroHtml + '<div class="sf-timeline">' + postsHtml + '</div>';
  } catch (e) {
    body.innerHTML = '<div class="sf-trend-detail-hero">'
      + '<h2>#' + sfEscapeHtml(keyword) + '#</h2>'
      + '</div>'
      + '<div class="sf-loading">生成失败，请稍后重试</div>';
  }
};

/* ============================================================
 * PART 21.9 - Character Profile (角色独立主页)
 * ============================================================ */

var sfOpenCharProfile = function (charId, charType) {
  sfState.currentCharProfileId = charId;
  var allRoles = sfGetAllRoles();
  var role = allRoles.find(function(r) { return r.id === charId; });
  if (!role) return;

  var overlay = sfEl('sfCharProfileOverlay');
  if (overlay) overlay.classList.add('active');

  sfRenderCharProfile(role);
};

var sfCloseCharProfile = function () {
  var overlay = sfEl('sfCharProfileOverlay');
  if (overlay) overlay.classList.remove('active');
  sfState.currentCharProfileId = null;
};

var sfRenderCharProfile = function (role) {
  var body = sfEl('sfCharProfileBody');
  if (!body) return;

  var avatarHtml;
  if (role.avatar && (role.avatar.startsWith('data:') || role.avatar.startsWith('http'))) {
    avatarHtml = '<img src="' + role.avatar + '"  alt=""/>';
  } else if (role.type === 'npc') {
    avatarHtml = sfEscapeHtml(role.avatarEmoji || role.name.charAt(0));
  } else {
    avatarHtml = sfEscapeHtml(role.name.charAt(0));
  }

  var avatarBg = role.avatarBg || (role.type === 'npc' ? '#FF9500' : '#576B95');

  /* Find posts by this character */
  var charPosts = [];
  for (var tab in sfState.posts) {
    sfState.posts[tab].forEach(function(p) {
      if (p.authorName === role.name || (p.npcAuthored && role.type === 'npc' && p.authorName === role.name)) {
        charPosts.push(p);
      }
    });
  }

  var profileBio = role._profileBio || role.persona || '这个人很神秘，还没有填写简介';

  var html = '<div class="sf-char-profile-hero">'
    + '<div class="sf-char-profile-avatar" style="background:' + avatarBg + '">' + avatarHtml + '</div>'
    + '<div class="sf-char-profile-name">' + sfEscapeHtml(role.name) + (role.type === 'npc' ? ' <span style="font-size:12px;color:#FF9500">NPC</span>' : '') + '</div>'
    + '<div class="sf-char-profile-handle">@' + sfEscapeHtml(role.name) + '</div>'
    + '<div class="sf-char-profile-bio">' + sfEscapeHtml(profileBio) + '</div>'
    + '<div class="sf-char-profile-stats">'
    + '<div class="sf-char-profile-stat"><div class="num">' + charPosts.length + '</div><div class="label">帖子</div></div>'
    + '<div class="sf-char-profile-stat"><div class="num">' + (role._profileFollowers || Math.floor(Math.random() * 500) + 50) + '</div><div class="label">粉丝</div></div>'
    + '<div class="sf-char-profile-stat"><div class="num">' + (role._profileFollowing || Math.floor(Math.random() * 200) + 10) + '</div><div class="label">关注</div></div>'
    + '</div>'
    + '<div class="sf-char-profile-actions">'
    + '<button class="sf-cp-dm-btn" id="sfCPDMBtn" type="button">&#128172; 私信</button>'
    + '</div>'
    + '</div>'
    + '<div class="sf-char-profile-tabs">'
    + '<div class="sf-char-profile-tab active">帖子</div>'
    + '</div>'
    + '<div class="sf-timeline" id="sfCharProfileTimeline">';

  if (charPosts.length > 0) {
    html += charPosts.map(function(p) { return sfRenderPost(p); }).join('');
  } else {
    html += '<div class="sf-empty">'
      + '<div style="margin-bottom:12px;color:#888">还没有发过帖子</div>'
      + '<button class="sf-generate-btn" id="sfGenCharPostsBtn" style="padding:8px 20px;border:1px solid #F5A0B8;border-radius:16px;background:#fff;color:#F5A0B8;font-size:13px;cursor:pointer">✨ 生成动态</button>'
      + '</div>';
  }
  html += '</div>';

  body.innerHTML = html;

  var genBtn = document.getElementById('sfGenCharPostsBtn');
  if (genBtn) genBtn.addEventListener('click', function() {
    sfGenerateCharPosts(role);
  });
};

var sfGenerateCharPosts = async function (role) {
  var timeline = document.getElementById('sfCharProfileTimeline');
  if (timeline) timeline.innerHTML = '<div class="sf-loading">正在为' + sfEscapeHtml(role.name) + '生成动态...</div>';
  try {
    var activeRuleText = sfGetActiveRuleText();
    var prompt = '请为角色「' + role.name + '」生成5条论坛帖子。\n';
    prompt += '角色人设: ' + (role.persona || '').substring(0, 2000) + '\n';
    var charWvText = sfGetActiveWorldviewText();
    if (charWvText) prompt += '【世界观设定】: ' + charWvText + '\n';
    if (activeRuleText) prompt += '论坛规则: ' + activeRuleText + '\n';
    prompt += '\n要求:\n1. 帖子内容符合角色性格和设定\n2. 语气口语化，像真实社交媒体\n3. 返回JSON数组，每个对象有content和authorName字段（authorName固定为"' + role.name + '"）';

    var apiMessages = [
      { role: 'system', content: '你是一个论坛内容生成器。只返回JSON数组，不要解释。' + globalBookSuffix(prompt) },
      { role: 'user', content: prompt }
    ];
    var reply = await callApi(apiMessages, { maxTokens: 2000 });

    var cleaned = String(reply).replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
    var jsonMatch = cleaned.match(/\[[\s\S]*\]/);
    var posts;
    try { posts = JSON.parse(jsonMatch ? jsonMatch[0] : cleaned); } catch(e) { posts = []; }

    var tab = sfState.currentTab || 'recommended';
    if (!sfState.posts[tab]) sfState.posts[tab] = [];

    posts.forEach(function(p, i) {
      var newPost = {
        id: 'char-' + Date.now() + '-' + i,
        authorName: role.name,
        handle: sfHandle(role.name),
        content: p.content || '',
        time: '刚刚',
        likes: Math.floor(Math.random() * 100),
        reposts: 0,
        comments: 0,
        views: Math.floor(Math.random() * 1000) + 50,
        avatarIndex: i % SF_AVATAR_COUNT,
        verified: false,
        npcAuthored: role.type === 'npc',
        npcAvatarEmoji: role.avatarEmoji,
        npcAvatarBg: role.avatarBg,
        tab: tab
      };
      if (role.type === 'npc') {
        newPost.npcId = role.id.replace('npc-', '');
      }
      sfState.posts[tab].push(newPost);
    });
    sfStorage.set('sf_posts_' + tab, JSON.stringify(sfState.posts[tab]));

    sfRenderCharProfile(role);
    sfToast('已生成' + posts.length + '条动态');
  } catch (e) {
    if (timeline) timeline.innerHTML = '<div class="sf-empty">生成失败，请稍后重试</div>';
  }
};

/* ============================================================
 * PART 21.10 - Enhanced Notifications (增强通知系统)
 * ============================================================ */

var sfAddNotification = function (type, data) {
  var notif = {
    id: 'notif-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
    type: type,
    data: data,
    time: Date.now(),
    read: false
  };
  sfState.notifList.unshift(notif);
  if (sfState.notifList.length > 50) sfState.notifList = sfState.notifList.slice(0, 50);
  try { sfStorage.set('sf_notif_list', JSON.stringify(sfState.notifList)); } catch (e) {}
};

/* 发送浏览器系统级通知：已授权则直接发送，否则请求权限 */
var sfSendSystemNotification = function (title, body) {
  /* 浏览器不支持通知则静默返回 */
  if (!('Notification' in window)) return;
  if (Notification.permission === 'granted') {
    try { new Notification(title, { body: body, icon: 'icon-192.png', badge: 'icon-192.png', tag: 'rua-forum' }); } catch (e) {}
  } else if (Notification.permission !== 'denied') {
    /* 未授权且未拒绝时，请求权限后再发送 */
    Notification.requestPermission().then(function (permission) {
      if (permission === 'granted') {
        try { new Notification(title, { body: body, icon: 'icon-192.png', badge: 'icon-192.png', tag: 'rua-forum' }); } catch (e) {}
      }
    }).catch(function(e) { console.warn('通知权限请求失败:', e); });
  }
};

var sfLoadNotifications = function () {
  try {
    var saved = sfStorage.get('sf_notif_list');
    if (saved) sfState.notifList = JSON.parse(saved) || [];
  } catch (e) {}
};

var sfFormatNotifTime = function (timestamp) {
  var diff = Date.now() - timestamp;
  if (diff < 60000) return '刚刚';
  if (diff < 3600000) return Math.floor(diff / 60000) + '分钟前';
  if (diff < 86400000) return Math.floor(diff / 3600000) + '小时前';
  return Math.floor(diff / 86400000) + '天前';
};

var sfRenderNotifications = function () {
  var container = sfEl('sfNotifList');
  if (!container) return;
  sfLoadNotifications();

  /* Also collect AI activity notifications from posts - only for characters and NPCs, not random strangers */
  var allRoleNames = [];
  if (typeof config !== 'undefined' && config.characters) {
    config.characters.filter(function(c) { return !c.deletedFromWechat; }).forEach(function(c) { allRoleNames.push(c.name); });
  }
  if (typeof config !== 'undefined' && config.npcs) {
    config.npcs.forEach(function(n) { allRoleNames.push(n.name); });
  }
  var aiNotifs = [];
  for (var tab in sfState.posts) {
    sfState.posts[tab].forEach(function(p) {
      /* Only notify for character/NPC posts, not random strangers */
      if (p.npcAuthored || (p.authorName && allRoleNames.indexOf(p.authorName) >= 0)) {
        var existing = sfState.notifList.find(function(n) { return n.data && n.data.postId === p.id; });
        if (!existing) {
          aiNotifs.push({
            id: 'notif-auto-' + p.id,
            type: 'new_post',
            data: { postId: p.id, authorName: p.authorName, content: p.content, npcAuthored: p.npcAuthored },
            time: Date.now() - Math.random() * 3600000,
            read: false
          });
        }
      }
    });
  }
  aiNotifs.forEach(function(n) {
    if (sfState.notifList.length < 50) sfState.notifList.push(n);
  });
  sfState.notifList.sort(function(a, b) { return b.time - a.time; });

  if (sfState.notifList.length === 0) {
    container.innerHTML = '<div class="sf-notif-empty">暂无通知<br>角色和NPC的动态会在这里提醒你</div>';
    return;
  }

  var html = '';
  sfState.notifList.forEach(function(n) {
    var avatarHtml = '';
    var text = '';
    var preview = '';
    var bg = '#576B95';

    if (n.type === 'new_post') {
      var d = n.data || {};
      text = '<span class="name">' + sfEscapeHtml(d.authorName || '某人') + '</span> 发布了新动态';
      preview = (d.content || '').substring(0, 50);
      if (d.npcAuthored) bg = '#FF9500';
    } else if (n.type === 'comment') {
      var d2 = n.data || {};
      text = '<span class="name">' + sfEscapeHtml(d2.authorName || '某人') + '</span> 评论了你的帖子';
      preview = (d2.content || '').substring(0, 50);
    } else if (n.type === 'like') {
      var d3 = n.data || {};
      text = '<span class="name">' + sfEscapeHtml(d3.authorName || '某人') + '</span> 赞了你的帖子';
      preview = (d3.postContent || '').substring(0, 50);
    } else if (n.type === 'repost') {
      var d4 = n.data || {};
      text = '<span class="name">' + sfEscapeHtml(d4.authorName || '某人') + '</span> 转发了你的帖子';
      preview = (d4.content || '').substring(0, 50);
    } else if (n.type === 'reply') {
      var d5 = n.data || {};
      text = '<span class="name">' + sfEscapeHtml(d5.authorName || '某人') + '</span> 回复了你的评论';
      preview = (d5.content || '').substring(0, 50);
      bg = '#7A6FE0';
    }

    html += '<div class="sf-notif-item" data-notif-id="' + sfEscapeHtml(n.id) + '">'
      + '<div class="sf-notif-avatar" style="background:' + bg + '">' + sfEscapeHtml((n.data && n.data.authorName || '?').charAt(0)) + '</div>'
      + '<div class="sf-notif-content">'
      + '<div class="sf-notif-text">' + text + '</div>'
      + (preview ? '<div class="sf-notif-preview">' + sfEscapeHtml(preview) + '</div>' : '')
      + '<div class="sf-notif-time">' + sfFormatNotifTime(n.time) + '</div>'
      + '</div>'
      + '</div>';
  });
  container.innerHTML = html;
  /* 更新badge */
  sfUpdateNotifBadge();
};

/* ============================================================
 * PART 22 - Event Binding
 * ============================================================ */

var sfEventsBound = false;

var sfBindEvents = function () {
  if (sfEventsBound) return;

  /* sub-tabs */
  document.querySelectorAll('.sf-sub-tab').forEach(function (t) {
    t.addEventListener('click', function () { sfSwitchTab(this.dataset.sfTab); });
  });

  /* bottom nav */
  document.querySelectorAll('.sf-bottom-nav .sf-tab').forEach(function (t) {
    t.addEventListener('click', function () { sfSwitchView(this.dataset.sfView); });
  });

  /* nav avatar -> side menu */
  var navAvatar = sfEl('sfNavAvatar');
  if (navAvatar) navAvatar.addEventListener('click', sfOpenSideMenu);

  /* refresh / close */
  var refresh = sfEl('sfRefreshBtn');
  if (refresh) refresh.addEventListener('click', function () {
    /* 私信视图：刷新私信列表（之前只刷新帖子时间线，在私信页点刷新毫无反应） */
    if (sfState.currentView === 'dm') {
      if ((sfState.dmTabType || 'friends') === 'stranger') {
        /* 陌生人标签：重新生成一批 */
        sfState.strangerDMs = [];
        sfState.strangerDMsLoading = true;
        sfSaveStrangerDMs();
        sfRenderDMList();
        sfGenerateStrangerDMs().then(function () {
          sfState.strangerDMsLoading = false;
          sfRenderDMList();
          sfToast('已刷新陌生人私信');
        }).catch(function () {
          sfState.strangerDMsLoading = false;
          sfRenderDMList();
          sfToast('刷新失败，请重试');
        });
      } else {
        /* 好友标签：重新拉取列表 */
        sfRenderDMList();
        sfToast('已刷新私信列表');
      }
      return;
    }
    sfState.posts[sfState.currentTab] = [];
    sfStorage.remove('sf_posts_' + sfState.currentTab);
    sfRenderTimeline(sfState.currentTab);
  });
  var closeBtn = sfEl('sfCloseBtn');
  if (closeBtn) closeBtn.addEventListener('click', closeSocialForum);

  /* fab */
  var fab = sfEl('sfFab');
  if (fab) fab.addEventListener('click', sfOpenPostModal);

  /* timeline delegation */
  var timeline = sfEl('sfTimeline');
  if (timeline) timeline.addEventListener('click', function (e) {
    if (e.target.classList.contains('sf-post-expand')) return;
    var genBtn = e.target.closest('[data-sf-generate]');
    if (genBtn) {
      sfState.posts[genBtn.dataset.sfGenerate] = [];
      sfStorage.remove('sf_posts_' + genBtn.dataset.sfGenerate);
      sfLoadTab(genBtn.dataset.sfGenerate);
      return;
    }
    var refBtn = e.target.closest('[data-sf-refresh]');
    if (refBtn) {
      sfState.posts[refBtn.dataset.sfRefresh] = [];
      sfStorage.remove('sf_posts_' + refBtn.dataset.sfRefresh);
      sfLoadTab(refBtn.dataset.sfRefresh);
      return;
    }
    var action = e.target.closest('[data-action]');
    var authorClick = e.target.closest('[data-author-name]');
    if (authorClick && !action) {
      var authorName = authorClick.dataset.authorName;
      var isNpc = authorClick.dataset.authorNpc === '1';
      if (authorName) {
        var allRoles = sfGetAllRoles();
        var role = allRoles.find(function(r) { return r.name === authorName; });
        if (role) { sfOpenCharProfile(role.id, role.type); return; }
      }
    }
    var post = e.target.closest('[data-post-id]');
    if (!post) return;
    var postId = post.dataset.postId;
    if (action) {
      var act = action.dataset.action;
      if (act === 'like') { sfToggleLike(postId, action); return; }
      if (act === 'save') { sfToggleSave(postId, action); return; }
      if (act === 'repost') { sfForwardToWechat(postId); return; }
      if (act === 'views') return;
      if (act === 'comment') { sfOpenPostDetail(postId); return; }
    }
    sfOpenPostDetail(postId);
  });

  /* detail back + body actions */
  var detailBack = sfEl('sfDetailBack');
  if (detailBack) detailBack.addEventListener('click', sfClosePostDetail);
  var detailBody = sfEl('sfDetailBody');
  if (detailBody) detailBody.addEventListener('click', function (e) {
    var action = e.target.closest('[data-action]');
    if (!action || !sfState.currentPostId) return;
    if (action.dataset.action === 'like') {
      sfToggleLike(sfState.currentPostId, action);
    } else if (action.dataset.action === 'save') {
      sfToggleSave(sfState.currentPostId, action);
    } else if (action.dataset.action === 'repost') {
      sfForwardToWechat(sfState.currentPostId);
    } else if (action.dataset.action === 'share') {
      sfToast('链接已复制到剪贴板');
    } else if (action.dataset.action === 'delete') {
      /* 删除当前帖子 */
      sfDeletePost(sfState.currentPostId);
    }
  });

  /* comments */
  var commentSend = sfEl('sfCommentSend');
  if (commentSend) commentSend.addEventListener('click', sfSendComment);
  var commentInput = sfEl('sfCommentInput');
  if (commentInput) commentInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') sfSendComment();
  });
  /* reply cancel */
  var replyCancel = sfEl('sfReplyCancel');
  if (replyCancel) replyCancel.addEventListener('click', sfClearReplyTo);

  /* post modal */
  var postCancel = sfEl('sfPostCancel');
  if (postCancel) postCancel.addEventListener('click', sfClosePostModal);
  var postPublish = sfEl('sfPostPublish');
  if (postPublish) postPublish.addEventListener('click', sfPublishPost);
  var postModal = sfEl('sfPostModal');
  if (postModal) postModal.addEventListener('click', function (e) {
    if (e.target === this) sfClosePostModal();
  });
  /* 匿名开关事件监听 */
  var anonToggle = sfEl('sfAnonymousToggle');
  if (anonToggle) anonToggle.addEventListener('change', function () {
    sfState.isAnonymousPost = this.checked;
  });

  /* side menu */
  var sideOv = sfEl('sfSideOverlay');
  if (sideOv) sideOv.addEventListener('click', sfCloseSideMenu);
  var menuList = sfEl('sfMenuList');
  if (menuList) menuList.addEventListener('click', function (e) {
    var item = e.target.closest('[data-menu]');
    if (!item) return;
    var key = item.dataset.menu;
    sfCloseSideMenu();
    if (key === 'profile') sfSwitchView('me');
    else if (key === 'bookmarks') sfToast('书签功能开发中');
    else if (key === 'drafts') sfToast('草稿箱是空的');
    else if (key === 'forumRoles') sfOpenRoleSelectModal();
    else if (key === 'worldview') sfOpenWorldviewModal();
    else if (key === 'settings') sfOpenRulesModal();
    else if (key === 'about') sfToast('论坛 v1.0 · 角色陪伴社区');
    else if (key === 'close') closeSocialForum();
  });

  /* search */
  var searchInput = sfEl('sfSearchInput');
  if (searchInput) searchInput.addEventListener('input', sfRunSearch);
  var trends = sfEl('sfTrends');
  if (trends) trends.addEventListener('click', function (e) {
    var item = e.target.closest('[data-trend]');
    if (!item) return;
    sfOpenTrendDetail(item.dataset.trend);
  });

  /* === Forum DM events === */
  var dmList = sfEl('sfDMList');
  if (dmList) dmList.addEventListener('click', function(e) {
    /* 处理 data-action 按钮（生成/刷新陌生人私信） */
    var actionBtn = e.target.closest('[data-action]');
    if (actionBtn) {
      var action = actionBtn.dataset.action;
      if (action === 'gen-stranger-dm') {
        /* 立即显示加载状态 */
        var emptyEl = document.getElementById('sfStrangerEmpty');
        if (emptyEl) emptyEl.innerHTML = '正在生成陌生人私信... <br>请稍候';
        sfGenerateStrangerDMs().then(function() {
          sfRenderDMList();
          sfToast('已生成' + (sfState.strangerDMs || []).length + '条陌生人私信');
        }).catch(function() {
          sfRenderDMList();
          sfToast('生成失败，请重试');
        });
        return;
      }
      if (action === 'refresh-stranger-dm') {
        sfState.strangerDMs = [];
        sfState.strangerDMsLoading = true;
        sfSaveStrangerDMs();
        sfRenderDMList();
        sfGenerateStrangerDMs().then(function() {
          sfState.strangerDMsLoading = false;
          sfRenderDMList();
          sfToast('已刷新陌生人私信');
        }).catch(function() {
          sfState.strangerDMsLoading = false;
          sfRenderDMList();
          sfToast('刷新失败，请重试');
        });
        return;
      }
    }
    /* 好友/陌生人切换标签 */
    var subTab = e.target.closest('[data-dm-tab]');
    if (subTab) {
      sfState.dmTabType = subTab.dataset.dmTab;
      sfRenderDMList();
      /* 切换到陌生人标签且列表为空时自动生成 */
      if (sfState.dmTabType === 'stranger' && sfState.strangerDMs.length === 0) {
        sfGenerateStrangerDMs().then(function() {
          sfRenderDMList();
        }).catch(function(e) { console.warn('陌生人消息生成失败:', e); });
      }
      return;
    }
    var item = e.target.closest('[data-dm-id]');
    if (!item) return;
    sfOpenDMDetail(item.dataset.dmId, item.dataset.dmType);
  });
  var dmBack = sfEl('sfDMBack');
  if (dmBack) dmBack.addEventListener('click', sfCloseDMDetail);
  var dmSend = sfEl('sfDMSend');
  if (dmSend) dmSend.addEventListener('click', sfSendDMMessage);
  var dmInput = sfEl('sfDMInput');
  if (dmInput) dmInput.addEventListener('keydown', function(e) {
    if (e.key === 'Enter') sfSendDMMessage();
  });
  /* DM消息刷新按钮 - 使用事件委托处理动态生成的刷新按钮 */
  var dmDetailBody = sfEl('sfDMDetailBody');
  /* 长按最后一条AI回复来重新生成 */
  if (dmDetailBody) {
    var _dmLongPressTimer = null;
    dmDetailBody.addEventListener('touchstart', function(e) {
      var bubbles = dmDetailBody.querySelectorAll('.sf-dm-bubble.them');
      if (bubbles.length === 0) return;
      var lastBubble = bubbles[bubbles.length - 1];
      if (!lastBubble.contains(e.target) && e.target !== lastBubble) return;
      var contactId = sfState.currentDMId;
      if (!contactId || contactId.indexOf('dm_stranger_') === 0) return;
      var conv = sfState.dmConversations[contactId];
      if (!conv) return;
      var lastIdx = conv.messages.length - 1;
      if (lastIdx < 0 || conv.messages[lastIdx].me) return;
      _dmLongPressTimer = setTimeout(function() {
        sfRegenerateDM(contactId, lastIdx);
      }, 600);
    });
    dmDetailBody.addEventListener('touchend', function() { clearTimeout(_dmLongPressTimer); });
    dmDetailBody.addEventListener('touchmove', function() { clearTimeout(_dmLongPressTimer); });
    dmDetailBody.addEventListener('contextmenu', function(e) {
      var bubbles = dmDetailBody.querySelectorAll('.sf-dm-bubble.them');
      if (bubbles.length === 0) return;
      var lastBubble = bubbles[bubbles.length - 1];
      if (!lastBubble.contains(e.target) && e.target !== lastBubble) return;
      var contactId = sfState.currentDMId;
      if (!contactId || contactId.indexOf('dm_stranger_') === 0) return;
      var conv = sfState.dmConversations[contactId];
      if (!conv) return;
      var lastIdx = conv.messages.length - 1;
      if (lastIdx < 0 || conv.messages[lastIdx].me) return;
      e.preventDefault();
      sfRegenerateDM(contactId, lastIdx);
    });
  }

  /* === Trending detail events === */
  var trendBack = sfEl('sfTrendBack');
  if (trendBack) trendBack.addEventListener('click', sfCloseTrendDetail);
  var trendDetailBody = sfEl('sfTrendDetailBody');
  if (trendDetailBody) trendDetailBody.addEventListener('click', function(e) {
    var authorClick = e.target.closest('[data-author-name]');
    var action = e.target.closest('[data-action]');
    if (authorClick && !action) {
      var authorName = authorClick.dataset.authorName;
      if (authorName) {
        var allRoles = sfGetAllRoles();
        var role = allRoles.find(function(r) { return r.name === authorName; });
        if (role) { sfOpenCharProfile(role.id, role.type); return; }
      }
    }
    var post = e.target.closest('[data-post-id]');
    if (post && !action) sfOpenPostDetail(post.dataset.postId);
  });

  /* === Character profile events === */
  var cpBack = sfEl('sfCPBack');
  if (cpBack) cpBack.addEventListener('click', sfCloseCharProfile);
  var cpRefresh = sfEl('sfCPRefresh');
  if (cpRefresh) cpRefresh.addEventListener('click', function() {
    if (!sfState.currentCharProfileId) return;
    var allRoles = sfGetAllRoles();
    var role = allRoles.find(function(r) { return r.id === sfState.currentCharProfileId; });
    if (role) sfGenerateCharPosts(role);
  });
  /* DM button on character profile - delegate since it's inside dynamically rendered content */
  var cpBody = sfEl('sfCharProfileBody');
  if (cpBody) cpBody.addEventListener('click', function(e) {
    var dmBtn = e.target.closest('#sfCPDMBtn');
    if (!dmBtn) return;
    if (!sfState.currentCharProfileId) return;
    var allRoles = sfGetAllRoles();
    var role = allRoles.find(function(r) { return r.id === sfState.currentCharProfileId; });
    if (!role) return;
    /* sfGetAllRoles already sets NPC id as 'npc-' + n.id, matching sfGetDMContacts */
    var contactId = role.id;
    sfCloseCharProfile();
    sfSwitchView('dm');
    /* Use setTimeout to ensure DM view is rendered before opening detail */
    setTimeout(function() { sfOpenDMDetail(contactId, role.type); }, 100);
  });

  /* === Forum rules events === */
  var rulesClose = sfEl('sfRulesClose');
  if (rulesClose) rulesClose.addEventListener('click', sfCloseRulesModal);
  var rulesSaveBtn = sfEl('sfRulesSaveBtn');
  if (rulesSaveBtn) rulesSaveBtn.addEventListener('click', sfCloseRulesModal);
  var ruleAddBtn = sfEl('sfRuleAddBtn');
  if (ruleAddBtn) ruleAddBtn.addEventListener('click', function() { sfOpenRuleEditor(null); });
  var rulesList = sfEl('sfRulesList');
  if (rulesList) rulesList.addEventListener('click', function(e) {
    var selBtn = e.target.closest('[data-rule-select]');
    var editBtn = e.target.closest('[data-rule-edit]');
    var delBtn = e.target.closest('[data-rule-del]');
    if (selBtn) { sfSelectRule(selBtn.dataset.ruleSelect); return; }
    if (editBtn) { sfOpenRuleEditor(editBtn.dataset.ruleEdit); return; }
    if (delBtn) { sfDeleteRule(delBtn.dataset.ruleDel); return; }
  });
  var ruleEditorCancel = sfEl('sfRuleEditorCancel');
  if (ruleEditorCancel) ruleEditorCancel.addEventListener('click', sfCloseRuleEditor);
  var ruleEditorSave = sfEl('sfRuleEditorSave');
  if (ruleEditorSave) ruleEditorSave.addEventListener('click', sfSaveRuleFromEditor);

  /* === Worldview events (世界观事件) === */
  var wvClose = sfEl('sfWorldviewClose');
  if (wvClose) wvClose.addEventListener('click', sfCloseWorldviewModal);
  var wvSaveBtn = sfEl('sfWorldviewSaveBtn');
  if (wvSaveBtn) wvSaveBtn.addEventListener('click', sfCloseWorldviewModal);
  var wvAddBtn = sfEl('sfWorldviewAddBtn');
  if (wvAddBtn) wvAddBtn.addEventListener('click', function() { sfOpenWorldviewEditor(null); });
  var wvList = sfEl('sfWorldviewList');
  if (wvList) wvList.addEventListener('click', function(e) {
    var selBtn = e.target.closest('[data-wv-select]');
    var editBtn = e.target.closest('[data-wv-edit]');
    var delBtn = e.target.closest('[data-wv-del]');
    if (selBtn) { sfSelectWorldview(selBtn.dataset.wvSelect); return; }
    if (editBtn) { sfOpenWorldviewEditor(editBtn.dataset.wvEdit); return; }
    if (delBtn) { sfDeleteWorldview(delBtn.dataset.wvDel); return; }
  });
  var wvEditorCancel = sfEl('sfWorldviewEditorCancel');
  if (wvEditorCancel) wvEditorCancel.addEventListener('click', sfCloseWorldviewEditor);
  var wvEditorSave = sfEl('sfWorldviewEditorSave');
  if (wvEditorSave) wvEditorSave.addEventListener('click', sfSaveWorldviewFromEditor);

  /* === Post image upload events === */
  var postImgBtn = sfEl('sfPostImgBtn');
  var postImgFile = sfEl('sfPostImgFile');
  if (postImgBtn && postImgFile) {
    postImgBtn.addEventListener('click', function() { postImgFile.click(); });
    postImgFile.addEventListener('change', function() {
      if (this.files && this.files[0]) sfHandlePostImage(this.files[0]);
      this.value = '';
    });
  }

  /* === Notification item click === */
  var notifList = sfEl('sfNotifList');
  if (notifList) notifList.addEventListener('click', function(e) {
    var item = e.target.closest('[data-notif-id]');
    if (!item) return;
    var notifId = item.dataset.notifId;
    var notif = sfState.notifList.find(function(n) { return n.id === notifId; });
    if (notif && notif.data && notif.data.postId) {
      /* 标记为已读 */
      notif.read = true;
      try { sfStorage.set('sf_notif_list', JSON.stringify(sfState.notifList)); } catch(e) {}
      sfUpdateNotifBadge();
      sfOpenPostDetail(notif.data.postId);
    }
  });

  sfEventsBound = true;
};

/* ============================================================
 * PART 23 - Init
 * ============================================================ */

var sfInitialized = false;

var initSocialForum = function () {
  if (sfInitialized) return;
  sfInitialized = true;

  /* Inject CSS */
  var style = document.createElement('style');
  style.setAttribute('data-sf-styles', 'true');
  style.textContent = SF_CSS;
  document.head.appendChild(style);

  /* Inject HTML（挂载到 phoneScreen，使 fixed 覆盖层收进手机框） */
  var container = document.createElement('div');
  container.innerHTML = SF_HTML;
  var sfHost = document.getElementById('phoneScreen') || document.body;
  while (container.firstChild) {
    sfHost.appendChild(container.firstChild);
  }

  /* Load cached data */
  try { sfLoadUserPosts(); } catch (e) {}
  try { sfLoadCommentsCache(); } catch (e) {}

  /* Bind events */
  sfBindEvents();
};

/* ============================================================
 * Export to global scope
 * ============================================================ */

window.SF_CSS = SF_CSS;
