window.sfSetReplyTo = sfSetReplyTo;
window.sfClearReplyTo = sfClearReplyTo;
window.sfDetectPostType = sfDetectPostType;
window.sfPostTypeLabel = sfPostTypeLabel;
window.sfPostTypeBadgeHtml = sfPostTypeBadgeHtml;
window.sfSaveForumMemory = sfSaveForumMemory;
window.sfTriggerProactiveWechatMessage = sfTriggerProactiveWechatMessage;
window.sfOpenPostDetail = sfOpenPostDetail;
window.sfClosePostDetail = sfClosePostDetail;
