window.sfCloseSideMenu = sfCloseSideMenu;
window.sfOpenRolePicker = sfOpenRolePicker;
window.sfCloseRolePicker = sfCloseRolePicker;
window.sfOpenRoleSelectModal = sfOpenRoleSelectModal;
window.sfCloseRoleSelectModal = sfCloseRoleSelectModal;
window.sfSaveActiveForumRoles = sfSaveActiveForumRoles;
window.sfLoadActiveForumRoles = sfLoadActiveForumRoles;
window.sfTriggerMentionedReply = sfTriggerMentionedReply;
window.sfTriggerAuthorReply = sfTriggerAuthorReply;
window.sfTriggerStrangerReply = sfTriggerStrangerReply;
window.sfTriggerCommentDiscussion = sfTriggerCommentDiscussion;
window.sfUpdateNotifBadge = sfUpdateNotifBadge;
window.sfToggleLike = sfToggleLike;
window.sfToggleSave = sfToggleSave;
window.sfBindEvents = sfBindEvents;
window.initSocialForum = initSocialForum;
