/* ===== Utility helpers ===== */

/* Store wrapper — uses host Store if available, falls back to localStorage */
var _dfStore = {
  get: function (key, def) {
    try {
      if (typeof Store !== 'undefined' && Store && Store.get) {
        var v = Store.get(key, def);
        if (typeof v === 'string' && v !== def) {
          try { return JSON.parse(v); } catch (e) { return v; }
        }
        return v;
      }
      var raw = localStorage.getItem(key);
      if (raw === null || raw === undefined) return def;
      return JSON.parse(raw);
    } catch (e) { return def; }
  },
  set: function (key, val) {
    try {
      if (typeof Store !== 'undefined' && Store && Store.set) {
        Store.set(key, val);
        return;
      }
      localStorage.setItem(key, typeof val === 'string' ? val : JSON.stringify(val));
    } catch (e) {}
  },
  remove: function (key) {
    try {
      if (typeof Store !== 'undefined' && Store && Store.remove) { Store.remove(key); return; }
      localStorage.removeItem(key);
    } catch (e) {}
  }
};

/* ===== API 响应内容提取工具函数 ===== */
/* 统一处理三种情况：
   1. content 是字符串 → 直接返回
   2. content 是数组（Gemini 格式 [{type:"text",text:"..."}]）→ 提取文本
   3. content 为空但 reasoning_content 存在（DeepSeek-R1/QwQ 推理模型）→ 跳过，返回空字符串（防止思维链泄露）
*/
var _extractContent = function (content, reasoningContent) {
  /* 情况1：字符串 */
  if (typeof content === 'string') return content;
  /* 情况2：数组（Gemini 格式） */
  if (Array.isArray(content)) {
    var parts = [];
    for (var i = 0; i < content.length; i++) {
      if (content[i] && content[i].type === 'text' && content[i].text) {
        parts.push(content[i].text);
      }
    }
    return parts.join('');
  }
  /* 情况3：content 为空/null/undefined，但有 reasoning_content（推理模型）
     不返回 reasoning_content，避免推理模型原生思维链泄露到正文/fullText中。
     推理模型的思维链是其内部思考过程，不应展示给用户或混入回复。 */
  /* 返回空字符串：流式时跳过推理阶段delta，非流式时触发重试/兜底逻辑 */
  return '';
};

/* 从 message 对象提取内容（非流式响应） */
var _extractMsgContent = function (message) {
  if (!message) return '';
  return _extractContent(message.content, message.reasoning_content);
};

/* 从 delta 对象提取内容（流式响应） */
var _extractDeltaContent = function (delta) {
  if (!delta) return '';
  return _extractContent(delta.content, delta.reasoning_content);
};

/* ===== SSE 格式通用解析器 ===== */
/* 某些API即使请求 stream:false，或 content-type 标记为 JSON，
   实际返回的仍是 SSE 格式（data: {...}\n\ndata: {...}\n\ndata: [DONE]）。
   此函数自动检测并解析，返回提取的文本内容或 null。 */
var _parseSseOrJson = function (rawText) {
  if (!rawText || !rawText.trim()) return null;
  
  /* 检测是否为 SSE 格式：包含 data: 行 */
  var hasSseData = rawText.indexOf('data:') !== -1;
  
  if (hasSseData) {
    /* SSE 格式：逐行解析 data: 行 */
    var lines = rawText.split('\n');
    var fullContent = '';
    var hasAnyValidChunk = false;
    for (var i = 0; i < lines.length; i++) {
      var trimmed = lines[i].trim();
      if (!trimmed || !trimmed.startsWith('data:')) continue;
      var dataStr = trimmed.slice(5).trim();
      if (dataStr === '[DONE]') continue;
      try {
        var json = JSON.parse(dataStr);
        /* 优先从 delta 提取（流式格式），其次从 message 提取（非流式格式） */
        if (json.choices && json.choices[0]) {
          if (json.choices[0].delta) {
            var deltaContent = _extractDeltaContent(json.choices[0].delta);
            if (deltaContent) { fullContent += deltaContent; hasAnyValidChunk = true; }
          } else if (json.choices[0].message) {
            var msgContent = _extractMsgContent(json.choices[0].message);
            if (msgContent) { fullContent += msgContent; hasAnyValidChunk = true; }
          }
        }
      } catch(e) {}
    }
    if (hasAnyValidChunk && fullContent.trim()) return fullContent;
  }
  
  /* 非 SSE：尝试直接 JSON.parse */
  try {
    var data = JSON.parse(rawText);
    if (data.choices && data.choices[0] && data.choices[0].message) {
      var content = _extractMsgContent(data.choices[0].message);
      if (content && content.trim()) return content;
    }
    /* 可能是错误响应 */
    if (data.error && data.error.message) throw new Error(data.error.message);
  } catch(e) {
    if (e.message && e.message.indexOf('Error:') === 0) throw e;
  }
  
  return null;
};

var _escapeHtml = (typeof escapeHtml === 'function') ? escapeHtml : function (text) {
  return String(text == null ? '' : text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

var _showToast = (typeof showToast === 'function') ? showToast : function (msg) {
  if (typeof toast === 'function') { toast(msg); return; }
};

