/* 当前世界下的全部用户人设账号（供同人文选择“故事里的我”） */
var dfCurrentWorldUserAccs = function () {
  try {
    var wid = (config.waSession && config.waSession.worldId) || 'default';
    var w = (config.worlds || []).filter(function (x) { return (x.id || 'default') === wid; })[0];
    return (w && Array.isArray(w.users)) ? w.users.slice() : [];
  } catch (e) { return []; }
};
var dfFindUserAcc = function (accId) {
  try {
    var out = null;
    (config.worlds || []).forEach(function (w) { (w.users || []).forEach(function (u) { if (String(u.id) === String(accId)) out = u; }); });
    return out;
  } catch (e) { return null; }
};
/* 选中的人设账号必须属于当前世界；跨世界（如切换世界后）视为无效，回退当前账号 */
var dfResolveSelectedAcc = function () {
  try {
    if (!dfState.selectedUserAccId) return null;
    var inWorld = dfCurrentWorldUserAccs().filter(function (u) { return String(u.id) === String(dfState.selectedUserAccId); })[0];
    return inWorld || null;
  } catch (e) { return null; }
};

/* ===== Save/Load ===== */
var dfSaveFormState = function () {
  try {
    _dfStore.set('df_form_state', {
      selectedCharacter: dfState.selectedCharacter,
      selectedUserAccId: dfState.selectedUserAccId,
      selectedTags: dfState.selectedTags,
      selectedTropes: dfState.selectedTropes,
      wordCount: dfState.wordCount,
      style: dfState.style,
      customRequest: dfState.customRequest,
      area: dfState.area,
      workType: dfState.workType
    });
  } catch (e) {}
};

var dfLoadFormState = function () {
  try {
    var fs = _dfStore.get('df_form_state', null);
    if (!fs) return;
    if (fs.selectedCharacter !== undefined) dfState.selectedCharacter = fs.selectedCharacter;
    if (fs.selectedUserAccId !== undefined) dfState.selectedUserAccId = fs.selectedUserAccId;
    if (fs.selectedTags) dfState.selectedTags = fs.selectedTags;
    if (fs.selectedTropes) dfState.selectedTropes = fs.selectedTropes;
    if (fs.wordCount) dfState.wordCount = fs.wordCount;
    if (fs.style) dfState.style = fs.style;
    if (fs.customRequest !== undefined) dfState.customRequest = fs.customRequest;
    if (fs.area) dfState.area = fs.area;
    if (fs.workType) dfState.workType = fs.workType;
  } catch (e) {}
};

var dfIsNovelMode = function () {
  var role = dfState.role || null;
  return !!(role && role.source === 'novel-game');
};

var dfLoadUserWorksOnly = function () {
  try {
    dfState.userWorks = _dfStore.get('df_user_works', []) || [];
  } catch (e) {}
  try {
    dfState.collectedWorks = _dfStore.get('df_collected_works', []) || [];
  } catch (e) {}
  try {
    dfState.novelUserWorks = _dfStore.get('df_novel_user_works', []) || [];
  } catch (e) {}
  try {
    dfState.novelCollectedWorks = _dfStore.get('df_novel_collected_works', []) || [];
  } catch (e) {}
};

var dfLoadTropeData = function () {
  try {
    var presets = _dfStore.get('df_trope_presets', null);
    if (presets) dfState.tropePresets = presets;
  } catch (e) {}
  try {
    var customs = _dfStore.get('df_custom_tropes', null);
    if (customs) {
      dfState.customTropes = (customs || []).map(function (t) {
        if (typeof t === 'string') return { name: t, content: '' };
        return t;
      });
    }
  } catch (e) {}
  try {
    var tags = _dfStore.get('df_custom_tags', null);
    if (tags) dfState.customTags = tags || [];
  } catch (e) {}
  try {
    var delTags = _dfStore.get('df_deleted_preset_tags', null);
    if (delTags) dfState.deletedPresetTags = delTags || [];
  } catch (e) {}
  try {
    var bmKey = dfIsNovelMode() ? 'df_novel_bookmarks' : 'df_bookmarks';
    var bm = _dfStore.get(bmKey, null);
    dfState.bookmarks = bm ? (bm || []) : [];
    /* 迁移：旧书签可能缺少 workType，从内容推断并补上 */
    if (dfState.bookmarks && dfState.bookmarks.length) {
      var _migrated = false;
      dfState.bookmarks.forEach(function (b) {
        if (b && b.work && !b.work.workType) {
          var _sample = '';
          if (b.chapters && b.chapters.length) {
            _sample = b.chapters[b.chapters.length - 1].content || b.work.content || b.work.excerpt || '';
          } else {
            _sample = b.work.content || b.work.excerpt || '';
          }
          b.work.workType = dfInferWorkType(_sample);
          _migrated = true;
        }
      });
      if (_migrated) {
        try { _dfStore.set(bmKey, dfState.bookmarks); } catch (e) {}
      }
    }
  } catch (e) {}
};

var dfSaveTropeData = function () {
  try { _dfStore.set('df_trope_presets', dfState.tropePresets); } catch (e) {}
  try { _dfStore.set('df_custom_tropes', dfState.customTropes); } catch (e) {}
};

var dfSaveCustomTags = function () {
  try { _dfStore.set('df_custom_tags', dfState.customTags); } catch (e) {}
  try { _dfStore.set('df_deleted_preset_tags', dfState.deletedPresetTags); } catch (e) {}
};

var dfSaveBookmarks = function () {
  try {
    var bmKey = dfIsNovelMode() ? 'df_novel_bookmarks' : 'df_bookmarks';
    _dfStore.set(bmKey, dfState.bookmarks);
  } catch (e) {}
};

