// ---- 加密保险箱 ----
function pcRenderVault(data) {
  if (!data || typeof data !== 'object') return pcShowEmpty('保险箱为空');
  var html = '<div style="padding:12px;background:#0d0d0d;min-height:100%;color:#ccc;">';
  if (data.secretStash && data.secretStash.length) {
    html += '<div style="margin-bottom:20px;">';
    html += '<div style="font-size:13px;color:#666;margin-bottom:10px;border-bottom:1px solid #222;padding-bottom:6px;">🔒 私密收藏</div>';
    for (var i = 0; i < data.secretStash.length; i++) {
      var s = data.secretStash[i];
      html += '<div style="background:#1a1a1a;border-radius:8px;padding:12px;margin-bottom:8px;border:1px solid #222;">';
      html += '<div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:6px;">';
      html += '<div style="font-size:14px;color:#e0e0e0;font-weight:500;">' + pcEsc(s.title || '') + '</div>';
      if (s.viewCount) html += '<span style="font-size:10px;color:#555;white-space:nowrap;">👁 ' + pcEsc(String(s.viewCount)) + '次</span>';
      html += '</div>';
      if (s.privateNote) html += '<div style="font-size:12px;color:#777;margin-bottom:4px;font-style:italic;">"' + pcEsc(s.privateNote) + '"</div>';
      html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
      if (s.tags && Array.isArray(s.tags)) {
        html += '<div style="font-size:10px;">' + s.tags.map(function(t) { return '<span style="background:#2a2a2a;padding:2px 6px;border-radius:3px;margin-right:4px;color:#888;">' + pcEsc(t) + '</span>'; }).join('') + '</div>';
      }
      if (s.lastViewed) html += '<span style="font-size:10px;color:#444;">最后查看: ' + pcEsc(s.lastViewed) + '</span>';
      html += '</div></div>';
    }
    html += '</div>';
  }
  if (data.hiddenSearches && data.hiddenSearches.length) {
    html += '<div style="margin-bottom:20px;">';
    html += '<div style="font-size:13px;color:#666;margin-bottom:10px;border-bottom:1px solid #222;padding-bottom:6px;">🌙 深夜搜索</div>';
    for (var i2 = 0; i2 < data.hiddenSearches.length; i2++) {
      var h = data.hiddenSearches[i2];
      html += '<div style="background:#1a1a1a;border-radius:8px;padding:10px 12px;margin-bottom:6px;border:1px solid #1f1f1f;">';
      html += '<div style="font-size:13px;color:#bbb;margin-bottom:4px;">🔍 ' + pcEsc(h.query || '') + '</div>';
      html += '<div style="display:flex;justify-content:space-between;align-items:center;">';
      if (h.searchTime) html += '<span style="font-size:10px;color:#555;">' + pcEsc(h.searchTime) + '</span>';
      if (h.resultSummary) html += '<span style="font-size:10px;color:#444;max-width:60%;text-align:right;">' + pcEsc(h.resultSummary) + '</span>';
      html += '</div></div>';
    }
    html += '</div>';
  }
  if (data.encryptedNotes && data.encryptedNotes.length) {
    html += '<div style="margin-bottom:20px;">';
    html += '<div style="font-size:13px;color:#666;margin-bottom:10px;border-bottom:1px solid #222;padding-bottom:6px;">🔏 加密日记</div>';
    for (var i3 = 0; i3 < data.encryptedNotes.length; i3++) {
      var n = data.encryptedNotes[i3];
      html += '<div style="background:#1a1a1a;border-radius:8px;padding:12px;margin-bottom:8px;border:1px solid #222;">';
      if (n.datetime) html += '<div style="font-size:10px;color:#555;margin-bottom:6px;">' + pcEsc(n.datetime) + '</div>';
      if (n.locked) {
        html += '<div style="font-size:13px;color:#666;font-style:italic;">🔒 ' + pcEsc(n.content || '已加密') + '</div>';
      } else {
        html += '<div style="font-size:13px;color:#aaa;line-height:1.5;">' + pcEsc(n.content || '') + '</div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }
  if (data.savedSecrets && data.savedSecrets.length) {
    html += '<div style="margin-bottom:20px;">';
    html += '<div style="font-size:13px;color:#666;margin-bottom:10px;border-bottom:1px solid #222;padding-bottom:6px;">👁‍🗨 私密书签</div>';
    for (var i4 = 0; i4 < data.savedSecrets.length; i4++) {
      var sp = data.savedSecrets[i4];
      html += '<div style="background:#1a1a1a;border-radius:8px;padding:10px 12px;margin-bottom:6px;border:1px solid #1f1f1f;">';
      html += '<div style="font-size:13px;color:#bbb;margin-bottom:4px;">' + pcEsc(sp.title || '') + '</div>';
      if (sp.savedReason) html += '<div style="font-size:11px;color:#666;font-style:italic;">"' + pcEsc(sp.savedReason) + '"</div>';
      html += '</div>';
    }
    html += '</div>';
  }
  html += '</div>';
  return html;
}

