// ---- 音乐 ----
function pcRenderMusic(data) {
  if (!data || typeof data !== 'object') return pcShowEmpty('暂无歌曲');
  var html = '<div class="pc-music-container">';
  if (data.weekStats) {
    var ws = data.weekStats;
    html += '<div class="pc-music-stats">';
    if (ws.topSong) html += '<div class="pc-music-stats-top">🎵 本周最常听: ' + pcEsc(ws.topSong.title || '') + ' - ' + pcEsc(ws.topSong.artist || '') + '</div>';
    if (ws.totalMinutes) html += '<div class="pc-music-stats-total">⏱ 本周听了 ' + pcEsc(String(ws.totalMinutes)) + ' 分钟</div>';
    if (ws.peakPeriodLabel) html += '<div class="pc-music-stats-peak">🌙 高峰时段: ' + pcEsc(ws.peakPeriodLabel) + '</div>';
    html += '</div>';
  }
  var playlists = data.playlists || data.songs || data;
  if (!Array.isArray(playlists) && data.playlists) playlists = data.playlists;
  if (Array.isArray(playlists)) {
    for (var p = 0; p < playlists.length; p++) {
      var pl = playlists[p];
      if (pl.tracks && Array.isArray(pl.tracks)) {
        html += '<div class="pc-music-playlist-header">🎵 ' + pcEsc(pl.title || '') + (pl.subtitle ? ' - ' + pcEsc(pl.subtitle) : '') + '</div>';
        html += '<div class="pc-music-list">';
        for (var i = 0; i < pl.tracks.length; i++) {
          var m = pl.tracks[i];
          html += '<div class="pc-music-item">';
          html += '<div class="pc-music-cover">' + pcThumbHtml(null, i) + '</div>';
          html += '<div class="pc-music-info">';
          html += '<div class="pc-music-title">' + pcEsc(m.title || '') + '</div>';
          html += '<div class="pc-music-artist">' + pcEsc(m.artist || '') + '</div>';
          html += '</div></div>';
        }
        html += '</div>';
      } else {
        html += '<div class="pc-music-list"><div class="pc-music-item">';
        html += '<div class="pc-music-cover">' + pcThumbHtml(null, p) + '</div>';
        html += '<div class="pc-music-info">';
        html += '<div class="pc-music-title">' + pcEsc(pl.title || '') + '</div>';
        html += '<div class="pc-music-artist">' + pcEsc(pl.artist || '') + (pl.album ? ' - ' + pcEsc(pl.album) : '') + '</div>';
        html += '</div><div class="pc-music-duration">' + pcEsc(pl.duration || '') + '</div>';
        html += '</div></div>';
      }
    }
  }
  html += '</div></div>';
  return html;
}

// ---- 浏览器 ----
function pcRenderBrowser(data) {
  if (!data || typeof data !== 'object') return pcShowEmpty('暂无浏览数据');
  var html = '<div class="pc-browser">';
  if (data.tagline) {
    html += '<div class="pc-browser-tagline" style="font-size:13px;color:var(--color-muted);padding:8px 12px;background:var(--color-surface);border-radius:10px;margin-bottom:10px;">' + pcEsc(data.tagline) + '</div>';
  }
  if (data.searches && data.searches.length) {
    html += '<div class="pc-browser-section"><h3>🔍 搜索记录</h3><div class="pc-browser-list">';
    for (var s = 0; s < data.searches.length; s++) {
      var sr = data.searches[s];
      html += '<div class="pc-browser-item"><div class="pc-browser-item-title">' + pcEsc(sr.query || '') + '</div>';
      html += '<div class="pc-browser-item-time">' + pcEsc(sr.time || sr.when || '') + '</div></div>';
    }
    html += '</div></div>';
  }
  if (data.openTabs && data.openTabs.length) {
    html += '<div class="pc-browser-section"><h3>📂 打开的标签</h3><div class="pc-browser-list">';
    for (var t = 0; t < data.openTabs.length; t++) {
      var tab = data.openTabs[t];
      html += '<div class="pc-browser-item"><div class="pc-browser-item-title">' + pcEsc(tab.title || '') + '</div>';
      html += '<div class="pc-browser-item-url">' + pcEsc(tab.url || tab.domain || '') + '</div></div>';
    }
    html += '</div></div>';
  }
  html += '<div class="pc-browser-section"><h3>📜 浏览历史</h3>';
  if (data.history && data.history.length) {
    html += '<div class="pc-browser-list">';
    for (var i = 0; i < data.history.length; i++) {
      var h = data.history[i];
      html += '<div class="pc-browser-item"><div class="pc-browser-item-title">' + pcEsc(h.title || '') + '</div>';
      html += '<div class="pc-browser-item-url">' + pcEsc(h.url || '') + '</div>';
      html += '<div class="pc-browser-item-time">' + pcEsc(h.visitedAt || h.time || '') + '</div></div>';
    }
    html += '</div>';
  } else {
    html += '<p class="pc-empty-text">暂无浏览记录</p>';
  }
  html += '</div>';
  html += '<div class="pc-browser-section"><h3>⭐ 书签收藏</h3>';
  if (data.bookmarks && data.bookmarks.length) {
    html += '<div class="pc-browser-list">';
    for (var j = 0; j < data.bookmarks.length; j++) {
      var b = data.bookmarks[j];
      html += '<div class="pc-browser-item"><div class="pc-browser-item-title">' + pcEsc(b.title || '') + '</div>';
      html += '<div class="pc-browser-item-url">' + pcEsc(b.url || '') + '</div></div>';
    }
    html += '</div>';
  } else {
    html += '<p class="pc-empty-text">暂无书签</p>';
  }
  html += '</div></div>';
  return html;
}

// ---- 购物 ----
function pcRenderShop(data) {
  if (data && !Array.isArray(data) && typeof data === 'object' && data.orders) {
    data = data.orders;
  }
  if (!data || !Array.isArray(data) || data.length === 0) return pcShowEmpty('暂无购物订单');
  var statusMap = { '已完成': 'pc-order-done', '配送中': 'pc-order-delivering', '待付款': 'pc-order-pending', '已取消': 'pc-order-cancelled' };
  var _roleName = pcState.roleName || '角色';
  var _userName = '你';
  try { if (typeof config !== 'undefined' && config && config.user && config.user.name) _userName = config.user.name; } catch(e) {}
  var recipientLabel = { self: _roleName, you: _userName, both: _roleName + ' & ' + _userName };
  var recipientColor = { self: '#aaa', you: '#e8749b', both: '#7b9be8' };
  var html = '<div class="pc-order-list">';
  for (var i = 0; i < data.length; i++) {
    var o = data[i];
    var cls = statusMap[o.status] || 'pc-order-done';
    var rcp = o.recipient || 'self';
    var rcpStyle = 'font-size:11px;color:' + (recipientColor[rcp] || '#aaa') + ';margin-bottom:2px;';
    html += '<div class="pc-order-card">';
    html += '<div class="pc-order-top">';
    html += '<span class="pc-order-no">' + pcEsc(o.orderNo || '') + '</span>';
    html += '<span class="pc-order-status ' + cls + '">' + pcEsc(o.status || '') + '</span>';
    html += '</div>';
    html += '<span style="' + rcpStyle + '">' + (recipientLabel[rcp] || _roleName) + '</span>';
    html += '<div class="pc-order-item-name">' + pcEsc(o.item || '') + '</div>';
    if (o.browsingNote) {
      html += '<div style="margin:4px 0;padding:4px 8px;background:#fffbe6;border-left:2px solid #f0c040;border-radius:0 4px 4px 0;font-size:11px;color:#996;font-style:italic;">💭 ' + pcEsc(o.browsingNote) + '</div>';
    }
    html += '<div class="pc-order-bottom">';
    html += '<span class="pc-order-date">' + pcEsc(o.date || '') + '</span>';
    html += '<span class="pc-order-price">¥' + pcFormatPrice(o.price) + '</span>';
    html += '</div></div>';
  }
  html += '</div>';
  return html;
}

// ---- 外卖 ----
function pcRenderFood(data) {
  if (data && !Array.isArray(data) && typeof data === 'object' && data.orders) {
    data = data.orders;
  }
  if (!data || !Array.isArray(data) || data.length === 0) return pcShowEmpty('暂无外卖订单');
  var statusMap = { '已完成': 'pc-order-done', '配送中': 'pc-order-delivering', '已取消': 'pc-order-cancelled' };
  var _roleName = pcState.roleName || '角色';
  var _userName = '你';
  try { if (typeof config !== 'undefined' && config && config.user && config.user.name) _userName = config.user.name; } catch(e) {}
  var recipientLabel = { self: _roleName, you: _userName, both: _roleName + ' & ' + _userName };
  var recipientColor = { self: '#aaa', you: '#e8749b', both: '#7b9be8' };
  var html = '<div class="pc-order-list">';
  for (var i = 0; i < data.length; i++) {
    var o = data[i];
    var cls = statusMap[o.status] || 'pc-order-done';
    var itemsText = '';
    if (o.items && o.items.length) itemsText = o.items.join('、');
    var rcp = o.recipient || 'self';
    var rcpStyle = 'font-size:11px;color:' + (recipientColor[rcp] || '#aaa') + ';margin-bottom:2px;';
    html += '<div class="pc-order-card">';
    html += '<div class="pc-order-top">';
    html += '<span class="pc-order-no">' + pcEsc(o.orderNo || '') + '</span>';
    html += '<span class="pc-order-status ' + cls + '">' + pcEsc(o.status || '') + '</span>';
    html += '</div>';
    html += '<span style="' + rcpStyle + '">' + (recipientLabel[rcp] || _roleName) + '</span>';
    html += '<div class="pc-order-restaurant">' + pcEsc(o.restaurant || '') + '</div>';
    if (itemsText) html += '<div class="pc-order-items">' + pcEsc(itemsText) + '</div>';
    if (o.isImpulse) html += '<div style="font-size:10px;color:#e8749b;margin:2px 0;">🔎 冲动下单 · ' + pcEsc(o.orderTime || '') + '</div>';
    html += '<div class="pc-order-bottom">';
    html += '<span class="pc-order-date">' + pcEsc(o.date || '') + '</span>';
    html += '<span class="pc-order-price">¥' + pcFormatPrice(o.price) + '</span>';
    html += '</div></div>';
  }
  html += '</div>';
  return html;
}

// ---- 情趣好物 ----
function pcRenderIntShop(data) {
  if (!data || typeof data !== 'object') return pcShowEmpty('暂无情趣好物数据');
  var html = '<div class="pc-intshop">';
  if (data.orders && data.orders.length) {
    var statusMap = { '已完成': 'pc-order-done', '配送中': 'pc-order-delivering', '待付款': 'pc-order-pending', '已取消': 'pc-order-cancelled' };
    html += '<div class="pc-intshop-section"><h3>🛒 订单记录</h3><div class="pc-order-list">';
    for (var i = 0; i < data.orders.length; i++) {
      var o = data.orders[i];
      var cls = statusMap[o.status] || 'pc-order-done';
      html += '<div class="pc-order-card"><div class="pc-order-top">';
      html += '<span class="pc-order-no">' + pcEsc(o.orderNo || '') + '</span>';
      html += '<span class="pc-order-status ' + cls + '">' + pcEsc(o.status || '') + '</span>';
      html += '</div>';
      var _roleName = pcState.roleName || '角色';
      var _userName = '你';
      try { if (typeof config !== 'undefined' && config && config.user && config.user.name) _userName = config.user.name; } catch(e) {}
      var recipientLabel = { self: _roleName, you: _userName, both: _roleName + ' & ' + _userName };
      var recipientColor = { self: '#aaa', you: '#e8749b', both: '#7b9be8' };
      var rcp = o.recipient || 'self';
      var rcpStyle = 'font-size:11px;color:' + (recipientColor[rcp] || '#aaa') + ';margin-bottom:2px;';
      html += '<span style="' + rcpStyle + '">' + (recipientLabel[rcp] || _roleName) + '</span>';
      html += '<div class="pc-order-item-name">' + pcEsc(o.product || '') + '</div>';
      if (o.brand) html += '<div class="pc-order-items">品牌：' + pcEsc(o.brand) + '</div>';
      if (o.isPrivate) html += '<div class="pc-intshop-private">🔒 隐私发货 · ' + pcEsc(o.pickupPoint || '代收点') + '</div>';
      if (o.reviewNote) html += '<div class="pc-intshop-review">💭 ' + pcEsc(o.reviewNote) + '</div>';
      if (o.repurchase) html += '<div class="pc-intshop-repurchase">🔁 已回购</div>';
      html += '<div class="pc-order-bottom">';
      html += '<span class="pc-order-date">' + pcEsc(o.orderDate || '') + '</span>';
      html += '<span class="pc-order-price">¥' + pcFormatPrice(o.price) + '</span>';
      html += '</div></div>';
    }
    html += '</div></div>';
  }
  if (data.wishlist && data.wishlist.length) {
    html += '<div class="pc-intshop-section"><h3>💝 心愿单</h3><div class="pc-intshop-wishlist">';
    for (var j = 0; j < data.wishlist.length; j++) {
      var w = data.wishlist[j];
      html += '<div class="pc-intshop-wish-item">';
      html += '<div class="pc-intshop-wish-product">' + pcEsc(w.product || '') + '</div>';
      if (w.brand) html += '<div class="pc-intshop-wish-brand">' + pcEsc(w.brand) + '</div>';
      html += '<div class="pc-intshop-wish-bottom">';
      html += '<span class="pc-order-price">¥' + pcFormatPrice(w.price) + '</span>';
      html += '<span class="pc-order-date">' + pcEsc(w.addedDate || '') + '</span>';
      html += '</div>';
      if (w.hesitationReason) html += '<div class="pc-intshop-hesitation">💭 ' + pcEsc(w.hesitationReason) + '</div>';
      html += '</div>';
    }
    html += '</div></div>';
  }
  if (data.browsingHistory && data.browsingHistory.length) {
    html += '<div class="pc-intshop-section"><h3>👁 浏览记录</h3><div class="pc-intshop-browsing">';
    for (var k = 0; k < data.browsingHistory.length; k++) {
      var b = data.browsingHistory[k];
      html += '<div class="pc-intshop-browse-item' + (b.lateNight ? ' pc-intshop-late-night' : '') + '">';
      html += '<div class="pc-intshop-browse-product">' + pcEsc(b.product || '') + '</div>';
      html += '<div class="pc-intshop-browse-meta">';
      html += '<span>浏览 ' + pcEsc(String(b.viewCount || 0)) + ' 次</span>';
      html += '<span class="pc-order-date">' + pcEsc(b.lastViewed || '') + '</span>';
      if (b.lateNight) html += '<span class="pc-intshop-night-tag">🌙 深夜</span>';
      html += '</div></div>';
    }
    html += '</div></div>';
  }
  html += '</div>';
  return html;
}

// ---- 资产 ----
function pcRenderAssets(data) {
  if (!data || typeof data !== 'object') return pcShowEmpty('暂无资产数据');
  var html = '<div class="pc-assets">';
  html += '<div class="pc-assets-hero">';
  html += '<div class="pc-assets-balance-label">账户余额</div>';
  html += '<div class="pc-assets-balance">¥' + pcFormatPrice(data.balance) + '</div>';
  html += '</div>';
  if (data.income && data.income.length) {
    html += '<div class="pc-assets-section"><h3>💎 收入明细</h3>';
    for (var i = 0; i < data.income.length; i++) {
      var inc = data.income[i];
      html += '<div class="pc-assets-item"><div><div class="pc-assets-item-name">' + pcEsc(inc.source || '') + '</div>';
      html += '<div class="pc-assets-item-date">' + pcEsc(inc.date || '') + '</div></div>';
      html += '<div class="pc-assets-item-amount pc-assets-income">+' + pcFormatPrice(inc.amount) + '</div></div>';
    }
    html += '</div>';
  }
  if (data.expenses && data.expenses.length) {
    html += '<div class="pc-assets-section"><h3>💸 支出明细</h3>';
    for (var j = 0; j < data.expenses.length; j++) {
      var exp = data.expenses[j];
      html += '<div class="pc-assets-item"><div><div class="pc-assets-item-name">' + pcEsc(exp.item || '') + '</div>';
      html += '<div class="pc-assets-item-date">' + pcEsc(exp.date || '') + '</div></div>';
      html += '<div class="pc-assets-item-amount pc-assets-expense">-' + pcFormatPrice(exp.amount) + '</div></div>';
    }
    html += '</div>';
  }
  html += '</div>';
  return html;
}

// ============================================================
// 14. Events
// ============================================================
function pcBindEvents() {
  if (pcEventBound) return;
  pcEventBound = true;
  pcUpdateClock();
  setInterval(pcUpdateClock, 30000);
  var closeBtn = document.getElementById('pcCloseBtn');
  if (closeBtn) closeBtn.addEventListener('click', closePhoneCheck);
  var deskBack = document.getElementById('pcDeskBack');
  if (deskBack) deskBack.addEventListener('click', function() {
    document.getElementById('pcDesktop').style.display = 'none';
    document.getElementById('pcViewer').style.display = 'none';
    document.getElementById('pcRolePicker').style.display = '';
  });
  var viewerBack = document.getElementById('pcViewerBack');
  if (viewerBack) viewerBack.addEventListener('click', pcViewerBackHandler);
  var refreshBtn = document.getElementById('pcRefreshBtn');
  if (refreshBtn) refreshBtn.addEventListener('click', pcRefreshApp);
  var overlay = document.getElementById('pcOverlay');
  if (overlay) overlay.addEventListener('click', function(e) {
    if (e.target === overlay) closePhoneCheck();
  });
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape' && pcState.open) {
      var viewer = document.getElementById('pcViewer');
      var desktop = document.getElementById('pcDesktop');
      if (viewer && viewer.style.display !== 'none') {
        if (pcSubView === 'detail') { pcBackToList(); }
        else { pcCloseApp(); }
      } else if (desktop && desktop.style.display !== 'none') {
        desktop.style.display = 'none';
        document.getElementById('pcRolePicker').style.display = '';
      } else {
        closePhoneCheck();
      }
    }
  });
}

// ============================================================
// 15. Initialization
// ============================================================
function initPhoneCheck() {
  // Inject CSS if not already present
  if (!document.getElementById('pcStyleTag')) {
    var styleEl = document.createElement('style');
    styleEl.id = 'pcStyleTag';
    styleEl.textContent = PC_CSS;
    document.head.appendChild(styleEl);
  }
  // Inject HTML if not already present
  if (!document.getElementById('pcOverlay')) {
    var container = document.createElement('div');
    container.innerHTML = PC_HTML;
    var pcHost = document.getElementById('phoneScreen') || document.body;
    while (container.firstChild) {
      pcHost.appendChild(container.firstChild);
    }
  }
  // Bind events
  pcBindEvents();
}

// Expose key functions globally
if (typeof window !== 'undefined') {
  window.openPhoneCheck = openPhoneCheck;
  window.initPhoneCheck = initPhoneCheck;
  window.pcSelectRoleById = pcSelectRoleById;
  window.pcOpenApp = pcOpenApp;
  window.pcRefreshApp = pcRefreshApp;
  window.pcOpenChatDetail = pcOpenChatDetail;
  window.pcOpenSmsDetail = pcOpenSmsDetail;
  window.pcOpenAlbumDetail = pcOpenAlbumDetail;
  window.pcOpenNoteDetail = pcOpenNoteDetail;
  window.pcBackToList = pcBackToList;
}

